/* Newly authored study translations and phrase notes; original English is unchanged. */
window.BOOK34_LANGUAGE_SUPPORT={"version":1,"label":"自编中文译文（非教材官方译文）","reviewStatus":"self-reviewed","status":{"3":{"lessons":60,"sentences":1301,"expressions":326},"4":{"lessons":48,"sentences":754,"expressions":243}},"lessons":[{"lessonId":"nce-b3-fa4874-l001","book":3,"number":1,"title":"A puma at large","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Pumas are large, cat-like animals which are found in America.","zh":"美洲狮是一种体型较大、外形像猫的动物，生活在美洲。","kind":"narration","speaker":"旁白"},{"en":"When reports came into London Zoo that a wild puma had been spotted forty-five miles south of London, they were not taken seriously.","zh":"伦敦动物园接到报告，说有人在伦敦以南四十五英里的地方发现了一只野生美洲狮，可这些报告起初并未受到重视。","kind":"narration","speaker":"旁白"},{"en":"However, as the evidence began to accumulate, experts from the Zoo felt obliged to investigate, for the descriptions given by people who claimed to have seen the puma were extraordinarily similar.","zh":"然而，随着证据逐渐增多，动物园的专家觉得有必要展开调查，因为那些声称见过美洲狮的人所作的描述极为相似。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"The hunt for the puma began in a small village where a woman picking blackberries saw ‘a large cat’ only five yards away from her.","zh":"搜寻美洲狮的行动始于一个小村庄，那里一位正在采摘黑莓的妇女看见一只“大猫”，离她只有五码远。","kind":"narration","speaker":"旁白"},{"en":"It immediately ran away when she saw it, and experts confirmed that a puma will not attack a human being unless it is cornered.","zh":"她一看见它，它就立刻跑开了；专家证实，美洲狮除非被逼得走投无路，否则不会攻击人。","kind":"narration","speaker":"旁白"},{"en":"The search proved difficult, for the puma was often observed at one place in the morning and at another place twenty miles away in the evening.","zh":"搜寻工作十分困难，因为人们常常早晨在一个地方看见它，晚上又在二十英里以外的另一个地方发现它。","kind":"narration","speaker":"旁白"},{"en":"Wherever it went, it left behind it a trail of dead deer and small animals like rabbits.","zh":"它无论走到哪里，沿途总会留下死鹿以及兔子等小动物的尸体。","kind":"narration","speaker":"旁白"},{"en":"Paw prints were seen in a number of places and puma fur was found clinging to bushes.","zh":"好几个地方都发现了爪印，灌木丛上也找到了挂着的美洲狮毛。","kind":"narration","speaker":"旁白"},{"en":"Several people complained of ‘cat-like noises’ at night and a businessman on a fishing trip saw the puma up a tree.","zh":"有几个人抱怨夜里听见“像猫叫一样的声音”，还有一位出门钓鱼的商人看见那只美洲狮在树上。","kind":"narration","speaker":"旁白"},{"en":"The experts were now fully convinced that the animal was a puma, but where had it come from?","zh":"专家这时完全确信那动物是一只美洲狮，可它究竟是从哪里来的呢？","kind":"narration","speaker":"旁白"},{"en":"As no pumas had been reported missing from any zoo in the country, this one must have been in the possession of a private collector and somehow managed to escape.","zh":"国内没有一家动物园报告有美洲狮失踪，所以这只美洲狮一定曾由私人收藏者饲养，不知怎样设法逃了出来。","kind":"narration","speaker":"旁白"},{"en":"The hunt went on for several weeks, but the puma was not caught.","zh":"搜寻持续了好几个星期，却始终没有抓到那只美洲狮。","kind":"narration","speaker":"旁白"},{"en":"It is disturbing to think that a dangerous wild animal is still at large in the quiet countryside.","zh":"想到一只危险的野兽还在宁静的乡间四处游荡，实在令人不安。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"take seriously","matchedForm":"taken seriously","meaning":"认真对待","note":"常用 take somebody/something seriously；被动形式为 be taken seriously。","example":"When reports came into London Zoo that a wild puma had been spotted forty-five miles south of London, they were not taken seriously.","exampleZh":"伦敦动物园接到报告，说有人在伦敦以南四十五英里的地方发现了一只野生美洲狮，可这些报告起初并未受到重视。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"feel obliged to do something","matchedForm":"felt obliged to","meaning":"觉得有责任或有必要做某事","note":"obliged 表示受到责任或情势的推动，后接 to 加动词原形。","example":"However, as the evidence began to accumulate, experts from the Zoo felt obliged to investigate, for the descriptions given by people who claimed to have seen the puma were extraordinarily similar.","exampleZh":"然而，随着证据逐渐增多，动物园的专家觉得有必要展开调查，因为那些声称见过美洲狮的人所作的描述极为相似。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"leave behind","matchedForm":"left behind","meaning":"留下","note":"可指离去后留下的痕迹、物品或后果；本文代词 it 指美洲狮。","example":"Wherever it went, it left behind it a trail of dead deer and small animals like rabbits.","exampleZh":"它无论走到哪里，沿途总会留下死鹿以及兔子等小动物的尸体。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"in the possession of","matchedForm":"in the possession of","meaning":"由某人拥有或保管","note":"in the possession of somebody 表示东西归某人所有；in possession of 则以拥有者为主语。","example":"As no pumas had been reported missing from any zoo in the country, this one must have been in the possession of a private collector and somehow managed to escape.","exampleZh":"国内没有一家动物园报告有美洲狮失踪，所以这只美洲狮一定曾由私人收藏者饲养，不知怎样设法逃了出来。","sourceParagraphIndex":1,"sourceSentenceIndex":7,"sourceType":"textbook-passage"},{"phrase":"at large","matchedForm":"at large","meaning":"未被捕获，仍在外游荡","note":"用于逃犯或危险动物时，表示尚未受到拘捕或控制。","example":"It is disturbing to think that a dangerous wild animal is still at large in the quiet countryside.","exampleZh":"想到一只危险的野兽还在宁静的乡间四处游荡，实在令人不安。","sourceParagraphIndex":1,"sourceSentenceIndex":9,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l002","book":3,"number":2,"title":"Thirteen equals one","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Our vicar is always raising money for one cause or another, but he has never managed to get enough money to have the church clock repaired.","zh":"我们教区的牧师总在为这样那样的事情筹款，可他始终没能筹到足够的钱来修理教堂的大钟。","kind":"narration","speaker":"旁白"},{"en":"The big clock which used to strike the hours day and night was damaged many years ago and has been silent ever since.","zh":"那座大钟从前昼夜报时，多年前损坏之后，就一直没有再响过。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"One night, however, our vicar woke up with a start: the clock was striking the hours!","zh":"然而，一天夜里，我们的牧师突然惊醒了：大钟竟然在报时！","kind":"narration","speaker":"旁白"},{"en":"Looking at his watch, he saw that it was one o’clock, but the bell struck thirteen times before it stopped.","zh":"他看了看表，发现当时是一点，可钟声响了十三下才停。","kind":"narration","speaker":"旁白"},{"en":"Armed with a torch, the vicar went up into the clock tower to see what was going on.","zh":"牧师拿着手电筒，走上钟楼，想看看究竟出了什么事。","kind":"narration","speaker":"旁白"},{"en":"In the torchlight, he caught sight of a figure whom he immediately recognized as Bill Wilkins, our local grocer.","zh":"手电筒的光照出一个人影，他立刻认出那是本地的杂货店老板比尔·威尔金斯。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"‘Whatever are you doing up here Bill?’ asked the vicar in surprise.","zh":"“比尔，你到底在这上头干什么？”牧师惊讶地问。","kind":"speech","speaker":"牧师"}]},{"index":3,"rows":[{"en":"‘I’m trying to repair the bell,’ answered Bill.","zh":"“我在试着修钟，”比尔答道。","kind":"speech","speaker":"比尔·威尔金斯"},{"en":"‘I've been coming up here night after night for weeks now.","zh":"“这几个星期，我每天晚上都上这儿来。","kind":"speech","speaker":"比尔·威尔金斯"},{"en":"You see, I was hoping to give you a surprise.’","zh":"你知道，我原本想给您一个惊喜。”","kind":"speech","speaker":"比尔·威尔金斯"}]},{"index":4,"rows":[{"en":"‘You certainly did give me a surprise!’ said the vicar.","zh":"“你可真让我大吃了一惊！”牧师说。","kind":"speech","speaker":"牧师"},{"en":"‘You've probably woken up everyone in the village as well.","zh":"“你大概也把全村人都吵醒了。","kind":"speech","speaker":"牧师"},{"en":"Still, I'm glad the bell is working again.’","zh":"不过，钟又能响了，我还是很高兴。”","kind":"speech","speaker":"牧师"}]},{"index":5,"rows":[{"en":"‘That's the trouble, vicar,’ answered Bill.","zh":"“麻烦就在这儿，牧师，”比尔回答。","kind":"speech","speaker":"比尔·威尔金斯"},{"en":"‘It’s working all right, but I'm afraid that at one o’clock it will strike thirteen times and there’s nothing I can do about it.’","zh":"“钟倒是能响了，可恐怕到了一点它就要敲十三下，这一点我实在无能为力。”","kind":"speech","speaker":"比尔·威尔金斯"}]},{"index":6,"rows":[{"en":"‘We'll get used to that, Bill,’ said the vicar.","zh":"“我们会习惯的，比尔，”牧师说。","kind":"speech","speaker":"牧师"},{"en":"‘Thirteen is not as good as one, but it's better than nothing.","zh":"“十三下虽然不如一下好，可总比一下都不响强。","kind":"speech","speaker":"牧师"},{"en":"Now let’s go downstairs and have a cup of tea.’","zh":"现在咱们下楼喝杯茶吧。”","kind":"speech","speaker":"牧师"}]}],"usage":[{"phrase":"one ... or another","matchedForm":"one cause or another","meaning":"这样或那样的某件事","note":"one 后的名词可替换，表示种类不一且未具体指明的事物。","example":"Our vicar is always raising money for one cause or another, but he has never managed to get enough money to have the church clock repaired.","exampleZh":"我们教区的牧师总在为这样那样的事情筹款，可他始终没能筹到足够的钱来修理教堂的大钟。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"day and night","matchedForm":"day and night","meaning":"日日夜夜，昼夜不停","note":"可直接作时间状语，强调白天和夜间都如此。","example":"The big clock which used to strike the hours day and night was damaged many years ago and has been silent ever since.","exampleZh":"那座大钟从前昼夜报时，多年前损坏之后，就一直没有再响过。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"with a start","matchedForm":"with a start","meaning":"猛地一惊","note":"常与 wake up 搭配，表示突然受惊而醒。","example":"One night, however, our vicar woke up with a start: the clock was striking the hours!","exampleZh":"然而，一天夜里，我们的牧师突然惊醒了：大钟竟然在报时！","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"catch sight of","matchedForm":"caught sight of","meaning":"突然看见","note":"强调某人或某物进入视野；不要与表示持续观察的 watch 混淆。","example":"In the torchlight, he caught sight of a figure whom he immediately recognized as Bill Wilkins, our local grocer.","exampleZh":"手电筒的光照出一个人影，他立刻认出那是本地的杂货店老板比尔·威尔金斯。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"night after night","matchedForm":"night after night","meaning":"一夜又一夜，连续每晚","note":"名词重复搭配 after，突出反复持续，如 day after day。","example":"‘I've been coming up here night after night for weeks now.","exampleZh":"“这几个星期，我每天晚上都上这儿来。","sourceParagraphIndex":3,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"get used to","matchedForm":"get used to","meaning":"逐渐习惯","note":"to 是介词，后接名词、代词或动名词，不能直接接动词原形。","example":"‘We'll get used to that, Bill,’ said the vicar.","exampleZh":"“我们会习惯的，比尔，”牧师说。","sourceParagraphIndex":6,"sourceSentenceIndex":0,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l003","book":3,"number":3,"title":"An unknown goddess","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Some time ago, an interesting discovery was made by archaeologists on the Aegean island of Kea.","zh":"前些时候，考古学家在爱琴海的凯阿岛上有了一项有趣的发现。","kind":"narration","speaker":"旁白"},{"en":"An American team explored a temple which stands in an ancient city on the promontory of Ayia Irini.","zh":"一支美国考古队考察了一座神庙，它位于阿伊亚伊里尼海角的一座古城里。","kind":"narration","speaker":"旁白"},{"en":"The city at one time must have been prosperous, for it enjoyed a high level of civilization.","zh":"这座城市一度一定十分繁荣，因为它曾拥有高度发达的文明。","kind":"narration","speaker":"旁白"},{"en":"Houses — often three storeys high — were built of stone.","zh":"房屋用石头建成，往往高达三层。","kind":"narration","speaker":"旁白"},{"en":"They had large rooms with beautifully decorated walls.","zh":"屋内的房间宽敞，墙壁装饰精美。","kind":"narration","speaker":"旁白"},{"en":"The city was even equipped with a drainage system, for a great many clay pipes were found beneath the narrow streets.","zh":"这座城市甚至配备了排水系统，因为在狭窄的街道下面发现了大量陶制管道。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"The temple which the archaeologists explored was used as a place of worship from the fifteenth century B.C. until Roman times.","zh":"考古学家考察的这座神庙，从公元前十五世纪一直到古罗马时期都被用作礼拜场所。","kind":"narration","speaker":"旁白"},{"en":"In the most sacred room of the temple, clay fragments of fifteen statues were found.","zh":"在神庙最神圣的房间里，发现了十五尊雕像的陶制碎片。","kind":"narration","speaker":"旁白"},{"en":"Each of these represented a goddess and had, at one time, been painted.","zh":"每尊雕像表现的都是一位女神，而且都曾经上过色。","kind":"narration","speaker":"旁白"},{"en":"The body of one statue was found among remains dating from the fifteenth century B.C.","zh":"其中一尊雕像的躯干是在公元前十五世纪的遗存中发现的。","kind":"narration","speaker":"旁白"},{"en":"Its missing head happened to be among remains of the fifth century B.C.","zh":"它缺失的头部恰好出现在公元前五世纪的遗存中。","kind":"narration","speaker":"旁白"},{"en":"This head must have been found in Classical times and carefully preserved.","zh":"这颗头像一定是在古典时代被发现，随后得到了精心保存。","kind":"narration","speaker":"旁白"},{"en":"It was very old and precious even then.","zh":"即使在当时，它也已经十分古老而珍贵了。","kind":"narration","speaker":"旁白"},{"en":"When the archaeologists reconstructed the fragments, they were amazed to find that the goddess turned out to be a very modern-looking woman.","zh":"考古学家把碎片重新拼合起来后，惊讶地发现，这位女神竟是一位相貌十分现代的女子。","kind":"narration","speaker":"旁白"},{"en":"She stood three feet high and her hands rested on her hips.","zh":"她高三英尺，双手叉在腰间。","kind":"narration","speaker":"旁白"},{"en":"She was wearing a full-length skirt which swept the ground.","zh":"她穿着一条曳地的长裙。","kind":"narration","speaker":"旁白"},{"en":"Despite her great age, she was very graceful indeed, but, so far, the archaeologists have been unable to discover her identity.","zh":"虽然年代久远，她的姿态确实依旧十分优雅；不过，考古学家至今还未能查明她的身份。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"at one time","matchedForm":"at one time","meaning":"曾经，一度","note":"这里指过去某一时期，不是“同时”；表示同时通常用 at the same time。","example":"The city at one time must have been prosperous, for it enjoyed a high level of civilization.","exampleZh":"这座城市一度一定十分繁荣，因为它曾拥有高度发达的文明。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"be equipped with","matchedForm":"equipped with","meaning":"配备有","note":"equipment 为不可数名词；be equipped with 后接配备的设施或设备。","example":"The city was even equipped with a drainage system, for a great many clay pipes were found beneath the narrow streets.","exampleZh":"这座城市甚至配备了排水系统，因为在狭窄的街道下面发现了大量陶制管道。","sourceParagraphIndex":0,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"date from","matchedForm":"dating from","meaning":"始于某年代，可追溯到","note":"date from 后接起始时间，本文分词短语修饰 remains。","example":"The body of one statue was found among remains dating from the fifteenth century B.C.","exampleZh":"其中一尊雕像的躯干是在公元前十五世纪的遗存中发现的。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"turn out to be","matchedForm":"turned out to be","meaning":"结果发现是","note":"常用于最终结果出乎预料的情形，后接名词或形容词。","example":"When the archaeologists reconstructed the fragments, they were amazed to find that the goddess turned out to be a very modern-looking woman.","exampleZh":"考古学家把碎片重新拼合起来后，惊讶地发现，这位女神竟是一位相貌十分现代的女子。","sourceParagraphIndex":1,"sourceSentenceIndex":7,"sourceType":"textbook-passage"},{"phrase":"so far","matchedForm":"so far","meaning":"到目前为止","note":"强调从过去延续到现在的情况，常与现在完成时连用。","example":"Despite her great age, she was very graceful indeed, but, so far, the archaeologists have been unable to discover her identity.","exampleZh":"虽然年代久远，她的姿态确实依旧十分优雅；不过，考古学家至今还未能查明她的身份。","sourceParagraphIndex":1,"sourceSentenceIndex":10,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l004","book":3,"number":4,"title":"The double life of Alfred Bloggs","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"These days, people who do manual work often receive far more money than people who work in offices.","zh":"如今，从事体力劳动的人，收入往往比坐办公室的人高得多。","kind":"narration","speaker":"旁白"},{"en":"People who work in offices are frequently referred to as ‘white-collar workers’ for the simple reason that they usually wear a collar and tie to go to work.","zh":"办公室工作人员常被称为“白领”，原因很简单：他们上班通常穿有领衬衫、打领带。","kind":"narration","speaker":"旁白"},{"en":"Such is human nature, that a great many people are often willing to sacrifice higher pay for the privilege of becoming white-collar workers.","zh":"人性就是如此，许多人往往情愿放弃较高的薪水，以换取成为白领的那份体面。","kind":"narration","speaker":"旁白"},{"en":"This can give rise to curious situations, as it did in the case of Alfred Bloggs who worked as a dustman for the Ellesmere Corporation.","zh":"这会造成一些奇特的情况，埃尔斯米尔市政机构的清洁工阿尔弗雷德·布洛格斯就是一例。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"When he got married, Alf was too embarrassed to say anything to his wife about his job.","zh":"阿尔弗结婚时，不好意思向妻子提起自己的工作。","kind":"narration","speaker":"旁白"},{"en":"He simply told her that he worked for the Corporation.","zh":"他只告诉她，自己在市政机构工作。","kind":"narration","speaker":"旁白"},{"en":"Every morning, he left home dressed in a smart black suit.","zh":"每天早上，他都穿着一套挺括的黑西装离家。","kind":"narration","speaker":"旁白"},{"en":"He then changed into overalls and spent the next eight hours as a dustman.","zh":"然后，他换上工作服，接下来的八小时就当清洁工。","kind":"narration","speaker":"旁白"},{"en":"Before returning home at night, he took a shower and changed back into his suit.","zh":"晚上回家前，他先洗个澡，再换回西装。","kind":"narration","speaker":"旁白"},{"en":"Alf did this for over two years and his fellow dustmen kept his secret.","zh":"阿尔弗这样做了两年多，清洁工同事们也一直替他保守秘密。","kind":"narration","speaker":"旁白"},{"en":"Alf’s wife has never discovered that she married a dustman and she never will, for Alf has just found another job.","zh":"阿尔弗的妻子始终没有发现自己嫁给了一名清洁工，而且以后也永远不会发现，因为阿尔弗刚找到了一份新工作。","kind":"narration","speaker":"旁白"},{"en":"He will soon be working in an office.","zh":"他很快就要到办公室工作了。","kind":"narration","speaker":"旁白"},{"en":"He will be earning only half as much as he used to, but he feels that his rise in status is well worth the loss of money.","zh":"他的收入将只有过去的一半，但他觉得，地位的提高完全值得这笔金钱上的损失。","kind":"narration","speaker":"旁白"},{"en":"From now on, he will wear a suit all day and others will call him ‘Mr. Bloggs’, not ‘Alf’.","zh":"从今以后，他将整天穿着西装，别人也会称呼他“布洛格斯先生”，而不再叫他“阿尔弗”。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"do manual work","matchedForm":"do manual work","meaning":"从事体力劳动","note":"manual 在此指依靠体力或双手完成的工作；work 为不可数名词。","example":"These days, people who do manual work often receive far more money than people who work in offices.","exampleZh":"如今，从事体力劳动的人，收入往往比坐办公室的人高得多。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"refer to ... as","matchedForm":"referred to as","meaning":"把……称为……","note":"常见被动结构 be referred to as；as 后接名称或称谓。","example":"People who work in offices are frequently referred to as ‘white-collar workers’ for the simple reason that they usually wear a collar and tie to go to work.","exampleZh":"办公室工作人员常被称为“白领”，原因很简单：他们上班通常穿有领衬衫、打领带。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"give rise to","matchedForm":"give rise to","meaning":"引发，导致","note":"后接结果、问题或情况，语气较正式。","example":"This can give rise to curious situations, as it did in the case of Alfred Bloggs who worked as a dustman for the Ellesmere Corporation.","exampleZh":"这会造成一些奇特的情况，埃尔斯米尔市政机构的清洁工阿尔弗雷德·布洛格斯就是一例。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"change into","matchedForm":"changed into","meaning":"换上","note":"表示换穿某种衣物；change back into 表示换回原来的衣服。","example":"He then changed into overalls and spent the next eight hours as a dustman.","exampleZh":"然后，他换上工作服，接下来的八小时就当清洁工。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"be well worth","matchedForm":"well worth","meaning":"很值得","note":"worth 后接名词或动名词，well 可加强语气，不用 very 修饰 worth。","example":"He will be earning only half as much as he used to, but he feels that his rise in status is well worth the loss of money.","exampleZh":"他的收入将只有过去的一半，但他觉得，地位的提高完全值得这笔金钱上的损失。","sourceParagraphIndex":1,"sourceSentenceIndex":8,"sourceType":"textbook-passage"},{"phrase":"from now on","matchedForm":"From now on","meaning":"从现在起","note":"强调某一做法或状态从说话所指的现在开始持续。","example":"From now on, he will wear a suit all day and others will call him ‘Mr. Bloggs’, not ‘Alf’.","exampleZh":"从今以后，他将整天穿着西装，别人也会称呼他“布洛格斯先生”，而不再叫他“阿尔弗”。","sourceParagraphIndex":1,"sourceSentenceIndex":9,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l005","book":3,"number":5,"title":"The facts","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Editors of newspapers and magazines often go to extremes to provide their readers with unimportant facts and statistics.","zh":"报刊编辑为了向读者提供一些无关紧要的事实和统计数字，常常不惜走极端。","kind":"narration","speaker":"旁白"},{"en":"Last year a journalist had been instructed by a well-known magazine to write an article on the president’s palace in a new African republic.","zh":"去年，一家知名杂志要求一名记者写一篇文章，介绍非洲一个新成立的共和国的总统府。","kind":"narration","speaker":"旁白"},{"en":"When the article arrived, the editor read the first sentence and then refused to publish it.","zh":"稿子送到后，编辑读了第一句话，就拒绝刊登。","kind":"narration","speaker":"旁白"},{"en":"The article began: ‘Hundreds of steps lead to the high wall which surrounds the president's palace.’","zh":"文章开头写道：“数百级台阶通向环绕总统府的高墙。”","kind":"note","speaker":"记者（文章原文）"},{"en":"The editor at once sent the journalist a fax instructing him to find out the exact number of steps and the height of the wall.","zh":"编辑立即给记者发了一份传真，要求他查清台阶的准确级数以及围墙的高度。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"The journalist immediately set out to obtain these important facts, but he took a long time to send them.","zh":"记者立刻着手获取这些重要事实，可是过了很久也没把它们发回来。","kind":"narration","speaker":"旁白"},{"en":"Meanwhile, the editor was getting impatient, for the magazine would soon go to press.","zh":"与此同时，编辑越来越不耐烦，因为杂志很快就要付印了。","kind":"narration","speaker":"旁白"},{"en":"He sent the journalist two more faxes, but received no reply.","zh":"他又给记者发了两份传真，却没有收到答复。","kind":"narration","speaker":"旁白"},{"en":"He sent yet another fax informing the journalist that if he did not reply soon he would be fired.","zh":"他再发了一份传真，告诉记者，要是不尽快答复，就会被解雇。","kind":"narration","speaker":"旁白"},{"en":"When the journalist again failed to reply, the editor reluctantly published the article as it had originally been written.","zh":"记者仍然没有回复，编辑只好不情愿地照原稿刊登了文章。","kind":"narration","speaker":"旁白"},{"en":"A week later, the editor at last received a fax from the journalist.","zh":"一周后，编辑终于收到了记者的传真。","kind":"narration","speaker":"旁白"},{"en":"Not only had the poor man been arrested, but he had been sent to prison as well.","zh":"原来，这个可怜的人不仅被逮捕了，还被关进了监狱。","kind":"narration","speaker":"旁白"},{"en":"However, he had at last been allowed to send a fax in which he informed the editor that he had been arrested while counting the 1,084 steps leading to the fifteen-foot wall which surrounded the president’s palace.","zh":"不过，他终于获准发一份传真，在传真中告诉编辑：他是在数通往总统府十五英尺高围墙的那一千零八十四级台阶时被逮捕的。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"go to extremes","matchedForm":"go to extremes","meaning":"走极端，采取过火的做法","note":"常接 to do something，说明为了什么而做得过头。","example":"Editors of newspapers and magazines often go to extremes to provide their readers with unimportant facts and statistics.","exampleZh":"报刊编辑为了向读者提供一些无关紧要的事实和统计数字，常常不惜走极端。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"find out","matchedForm":"find out","meaning":"查明，弄清","note":"强调通过调查或询问获知事实，后可接名词或疑问词引导的从句。","example":"The editor at once sent the journalist a fax instructing him to find out the exact number of steps and the height of the wall.","exampleZh":"编辑立即给记者发了一份传真，要求他查清台阶的准确级数以及围墙的高度。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"set out to do something","matchedForm":"set out to","meaning":"着手做某事","note":"set out to 加动词原形表示开始执行一项有目的的行动。","example":"The journalist immediately set out to obtain these important facts, but he took a long time to send them.","exampleZh":"记者立刻着手获取这些重要事实，可是过了很久也没把它们发回来。","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"go to press","matchedForm":"go to press","meaning":"付印","note":"用于报刊书籍进入印刷阶段；press 在这一固定搭配中不加冠词。","example":"Meanwhile, the editor was getting impatient, for the magazine would soon go to press.","exampleZh":"与此同时，编辑越来越不耐烦，因为杂志很快就要付印了。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"as well","matchedForm":"as well","meaning":"也，同样","note":"通常放在句末；本句与 not only ... but ... 连用，补充被送进监狱这一遭遇。","example":"Not only had the poor man been arrested, but he had been sent to prison as well.","exampleZh":"原来，这个可怜的人不仅被逮捕了，还被关进了监狱。","sourceParagraphIndex":1,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"at last","matchedForm":"at last","meaning":"终于","note":"强调等候或拖延之后某件事终于发生，常带如释重负或不耐的语气。","example":"A week later, the editor at last received a fax from the journalist.","exampleZh":"一周后，编辑终于收到了记者的传真。","sourceParagraphIndex":1,"sourceSentenceIndex":5,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l006","book":3,"number":6,"title":"Smash-and-grab","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"The expensive shops in a famous arcade near Piccadilly were just opening.","zh":"皮卡迪利附近一条著名购物廊里的高档商店刚刚开门营业。","kind":"narration","speaker":"旁白"},{"en":"At this time of the morning, the arcade was almost empty.","zh":"早晨这个时候，购物廊里几乎没有人。","kind":"narration","speaker":"旁白"},{"en":"Mr. Taylor, the owner of a jewellery shop was admiring a new window display.","zh":"一家珠宝店的店主泰勒先生，正在欣赏新布置的橱窗。","kind":"narration","speaker":"旁白"},{"en":"Two of his assistants had been working busily since eight o’clock and had only just finished.","zh":"他的两名店员从八点起就一直忙着布置，刚刚才完工。","kind":"narration","speaker":"旁白"},{"en":"Diamond necklaces and rings had been beautifully arranged on a background of black velvet.","zh":"钻石项链和戒指以黑色天鹅绒为衬底，摆放得十分漂亮。","kind":"narration","speaker":"旁白"},{"en":"After gazing at the display for several minutes, Mr. Taylor went back into his shop.","zh":"泰勒先生凝视了这番陈列几分钟后，回到了店里。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"The silence was suddenly broken when a large car, with its headlights on and its horn blaring, roared down the arcade.","zh":"突然，一辆大汽车亮着前灯、鸣着喇叭，沿购物廊呼啸驶来，打破了寂静。","kind":"narration","speaker":"旁白"},{"en":"It came to a stop outside the jeweller’s.","zh":"车停在了珠宝店外。","kind":"narration","speaker":"旁白"},{"en":"One man stayed at the wheel while two others with black stockings over their faces jumped out and smashed the window of the shop with iron bars.","zh":"一个人留在驾驶座上，另外两个人脸上套着黑色长袜，跳下车来，用铁棒砸碎了商店的橱窗。","kind":"narration","speaker":"旁白"},{"en":"While this was going on, Mr. Taylor was upstairs.","zh":"这一切发生的时候，泰勒先生正在楼上。","kind":"narration","speaker":"旁白"},{"en":"He and his staff began throwing furniture out of the window.","zh":"他和店员开始把家具从窗口往外扔。","kind":"narration","speaker":"旁白"},{"en":"Chairs and tables went flying into the arcade.","zh":"椅子和桌子纷纷飞进购物廊。","kind":"narration","speaker":"旁白"},{"en":"One of the thieves was struck by a heavy statue, but he was too busy helping himself to diamonds to notice any pain.","zh":"一尊沉重的雕像砸中了一个窃贼，可他正忙着大把拿钻石，根本顾不上疼。","kind":"narration","speaker":"旁白"},{"en":"The raid was all over in three minutes, for the men scrambled back into the car and it moved off at a fantastic speed.","zh":"整个抢劫过程三分钟就结束了，那几个人仓促爬回车里，车以惊人的速度开走了。","kind":"narration","speaker":"旁白"},{"en":"Just as it was leaving, Mr. Taylor rushed out and ran after it throwing ashtrays and vases, but it was impossible to stop the thieves.","zh":"就在车开走时，泰勒先生冲了出来，追着汽车扔烟灰缸和花瓶，可已经无法拦住那些窃贼。","kind":"narration","speaker":"旁白"},{"en":"They had got away with thousands of pounds worth of diamonds.","zh":"他们带着价值数千英镑的钻石逃掉了。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"gaze at","matchedForm":"gazing at","meaning":"凝视，仔细看","note":"表示目光停留较久；at 后接注视的对象。","example":"After gazing at the display for several minutes, Mr. Taylor went back into his shop.","exampleZh":"泰勒先生凝视了这番陈列几分钟后，回到了店里。","sourceParagraphIndex":0,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"come to a stop","matchedForm":"came to a stop","meaning":"停下来","note":"描述从移动到停止的过程，stop 在这里是名词。","example":"It came to a stop outside the jeweller’s.","exampleZh":"车停在了珠宝店外。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"at the wheel","matchedForm":"at the wheel","meaning":"在驾驶，在方向盘后","note":"wheel 在这一搭配中指汽车方向盘，常暗示某人正负责驾驶。","example":"One man stayed at the wheel while two others with black stockings over their faces jumped out and smashed the window of the shop with iron bars.","exampleZh":"一个人留在驾驶座上，另外两个人脸上套着黑色长袜，跳下车来，用铁棒砸碎了商店的橱窗。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"help oneself to","matchedForm":"helping himself to","meaning":"自行取用；此处指大肆拿走","note":"通常用于招呼人自行取食，文中带讽刺意味，指窃贼擅自拿取珠宝。","example":"One of the thieves was struck by a heavy statue, but he was too busy helping himself to diamonds to notice any pain.","exampleZh":"一尊沉重的雕像砸中了一个窃贼，可他正忙着大把拿钻石，根本顾不上疼。","sourceParagraphIndex":1,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"get away with","matchedForm":"got away with","meaning":"携带赃物逃走","note":"这里 with 后接偷走的物品；也可用于表示做坏事而未受惩罚，需按语境区分。","example":"They had got away with thousands of pounds worth of diamonds.","exampleZh":"他们带着价值数千英镑的钻石逃掉了。","sourceParagraphIndex":1,"sourceSentenceIndex":9,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l007","book":3,"number":7,"title":"Mutilated ladies","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Has it ever happened to you?","zh":"你碰到过这种事吗？","kind":"narration","speaker":"旁白"},{"en":"Have you ever put your trousers in the washing machine and then remembered there was a large bank note in your back pocket?","zh":"你有没有把裤子放进洗衣机后，才想起后裤袋里还有一张大面额钞票？","kind":"narration","speaker":"旁白"},{"en":"When you rescued your trousers, did you find the note was whiter than white?","zh":"等你把裤子抢救出来时，有没有发现钞票已经洗得白得不能再白了？","kind":"narration","speaker":"旁白"},{"en":"People who live in Britain needn’t despair when they make mistakes like this (and a lot of people do)!","zh":"住在英国的人犯下这种错误时不必绝望，而犯这种错误的人还真不少！","kind":"narration","speaker":"旁白"},{"en":"Fortunately for them, the Bank of England has a team called Mutilated Ladies which deals with claims from people who fed their money to a machine or to their dog.","zh":"对他们来说，幸运的是，英格兰银行有一个名叫“残损纸币处理小组”（Mutilated Ladies）的团队，负责处理那些把钞票送进机器或狗嘴的人提出的兑换申请。","kind":"narration","speaker":"旁白"},{"en":"Dogs, it seems, love to chew up money!","zh":"狗似乎特别喜欢把钞票嚼得粉碎！","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"A recent case concerns Jane Butlin whose fiancé, John, runs a successful furniture business.","zh":"最近的一桩案例与简·巴特林有关，她的未婚夫约翰经营着一家生意兴隆的家具公司。","kind":"narration","speaker":"旁白"},{"en":"John had a very good day and put his wallet containing £ 3,000 into the microwave oven for safekeeping.","zh":"约翰那天生意特别好，为了安全起见，他把装着三千英镑的钱包放进了微波炉。","kind":"narration","speaker":"旁白"},{"en":"Then he and Jane went horse-riding.","zh":"随后，他和简骑马去了。","kind":"narration","speaker":"旁白"},{"en":"When they got home, Jane cooked their dinner in the microwave oven and without realizing it, cooked her fiancé’s wallet as well.","zh":"回家后，简用微波炉做晚饭，无意之中也把未婚夫的钱包一块儿烤了。","kind":"narration","speaker":"旁白"},{"en":"Imagine their dismay when they found a beautifully-cooked wallet and notes turned to ash!","zh":"想象一下，他们发现钱包“烤得恰到好处”、钞票却化成灰烬时，会多么沮丧！","kind":"narration","speaker":"旁白"},{"en":"John went to see his bank manager who sent the remains of wallet and the money to the special department of the Bank of England in Newcastle: the Mutilated Ladies!","zh":"约翰去找银行经理，经理把钱包和钞票的残骸送到了英格兰银行设在纽卡斯尔的那个特别部门——残损纸币处理小组！","kind":"narration","speaker":"旁白"},{"en":"They examined the remains and John got all his money back.","zh":"他们检查了这些残骸，约翰便拿回了全部款项。","kind":"narration","speaker":"旁白"},{"en":"‘So long as there’s something to identify, we will give people their money back,’ said a spokeswoman for the Bank.","zh":"银行的一位女发言人说：“只要还剩下可以辨认的东西，我们就会把钱退还给人们。”","kind":"speech","speaker":"英格兰银行女发言人"},{"en":"‘Last year, we paid £1.5m on 21,000 claims.’","zh":"“去年，我们受理了两万一千宗申请，兑付了一百五十万英镑。”","kind":"speech","speaker":"英格兰银行女发言人"}]}],"usage":[{"phrase":"deal with","matchedForm":"deals with","meaning":"处理申请","note":"deal with 后接需要处理的人或事；本文 claims 指残损钞票的兑付申请。","example":"Fortunately for them, the Bank of England has a team called Mutilated Ladies which deals with claims from people who fed their money to a machine or to their dog.","exampleZh":"对他们来说，幸运的是，英格兰银行有一个名叫“残损纸币处理小组”（Mutilated Ladies）的团队，负责处理那些把钞票送进机器或狗嘴的人提出的兑换申请。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"chew up","matchedForm":"chew up","meaning":"嚼碎","note":"up 强调嚼得破碎或彻底，money 在此具体指纸币。","example":"Dogs, it seems, love to chew up money!","exampleZh":"狗似乎特别喜欢把钞票嚼得粉碎！","sourceParagraphIndex":0,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"for safekeeping","matchedForm":"for safekeeping","meaning":"为了妥善保管","note":"常用于将钱或贵重物品放置、交托到某处，表示保管目的。","example":"John had a very good day and put his wallet containing £ 3,000 into the microwave oven for safekeeping.","exampleZh":"约翰那天生意特别好，为了安全起见，他把装着三千英镑的钱包放进了微波炉。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"without realizing it","matchedForm":"without realizing it","meaning":"没有意识到，浑然不觉","note":"without 为介词，后接动名词；it 指当事人未察觉的情况。","example":"When they got home, Jane cooked their dinner in the microwave oven and without realizing it, cooked her fiancé’s wallet as well.","exampleZh":"回家后，简用微波炉做晚饭，无意之中也把未婚夫的钱包一块儿烤了。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"so long as","matchedForm":"So long as","meaning":"只要","note":"引导条件从句，与 as long as 在这一用法中相近，不是比较持续时间。","example":"‘So long as there’s something to identify, we will give people their money back,’ said a spokeswoman for the Bank.","exampleZh":"银行的一位女发言人说：“只要还剩下可以辨认的东西，我们就会把钱退还给人们。”","sourceParagraphIndex":1,"sourceSentenceIndex":7,"sourceType":"textbook-passage"}],"translationNotes":["Mutilated Ladies 是原文对银行残损钞票处理团队的诙谐称呼；译文按其职能译为“残损纸币处理小组”，同时保留英文名称。"]},{"lessonId":"nce-b3-fa4874-l008","book":3,"number":8,"title":"A famous monastery","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"The Great St. Bernard Pass connects Switzerland to Italy.","zh":"大圣伯纳德山口连接着瑞士和意大利。","kind":"narration","speaker":"旁白"},{"en":"At 2,473 metres, it is the highest mountain pass in Europe.","zh":"它海拔两千四百七十三米，是欧洲最高的山口。","kind":"narration","speaker":"旁白"},{"en":"The famous monastery of St. Bernard, which was founded in the eleventh century, lies about a mile away.","zh":"著名的圣伯纳德修道院创建于十一世纪，位于大约一英里之外。","kind":"narration","speaker":"旁白"},{"en":"For hundreds of years, St. Bernard dogs have saved the lives of travellers crossing the dangerous Pass.","zh":"几百年来，圣伯纳德犬救过许多穿越这处险峻山口的旅行者的性命。","kind":"narration","speaker":"旁白"},{"en":"These friendly dogs, which were first brought from Asia, were used as watchdogs even in Roman times.","zh":"这些友善的狗最初从亚洲引进，早在古罗马时期就被用来看家护院。","kind":"narration","speaker":"旁白"},{"en":"Now that a tunnel has been built through the mountains, the Pass is less dangerous, but each year, the dogs are still sent out into the snow whenever a traveller is in difficulty.","zh":"如今，穿山隧道已经建成，山口的危险性有所降低，但每年只要有旅行者遇险，这些狗仍会被派到雪地里救援。","kind":"narration","speaker":"旁白"},{"en":"Despite the new tunnel, there are still a few people who rashly attempt to cross the Pass on foot.","zh":"尽管有了新隧道，仍有少数人冒失地试图徒步穿越山口。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"During the summer months, the monastery is very busy, for it is visited by thousands of people who cross the Pass in cars.","zh":"夏季的几个月里，修道院非常热闹，因为有成千上万开车经过山口的人来参观。","kind":"narration","speaker":"旁白"},{"en":"As there are so many people about, the dogs have to be kept in a special enclosure.","zh":"由于周围人太多，这些狗只得关在专门的围栏内。","kind":"narration","speaker":"旁白"},{"en":"In winter, however, life at the monastery is quite different.","zh":"然而到了冬天，修道院里的生活就大不一样了。","kind":"narration","speaker":"旁白"},{"en":"The temperature drops to -30° and very few people attempt to cross the Pass.","zh":"气温降到零下三十度，极少有人尝试穿越山口。","kind":"narration","speaker":"旁白"},{"en":"The monks prefer winter to summer for they have more privacy.","zh":"修士们更喜欢冬天，而不喜欢夏天，因为冬天他们能有更多不受打扰的私人空间。","kind":"narration","speaker":"旁白"},{"en":"The dogs have greater freedom, too, for they are allowed to wander outside their enclosure.","zh":"狗也有了更大的自由，因为它们获准在围栏外四处走动。","kind":"narration","speaker":"旁白"},{"en":"The only regular visitors to the monastery in winter are parties of skiers who go there at Christmas and Easter.","zh":"冬天定期造访修道院的，只有在圣诞节和复活节前来的一群群滑雪者。","kind":"narration","speaker":"旁白"},{"en":"These young people, who love the peace of the mountains, always receive a warm welcome at St. Bernard's monastery.","zh":"这些热爱山中宁静的年轻人，在圣伯纳德修道院总会受到热情欢迎。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"connect ... to","matchedForm":"connects Switzerland to Italy","meaning":"连接两地","note":"connect A to B 表示把 A 与 B 相连；此处主语是连接两地的山口。","example":"The Great St. Bernard Pass connects Switzerland to Italy.","exampleZh":"大圣伯纳德山口连接着瑞士和意大利。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"now that","matchedForm":"Now that","meaning":"既然，由于现在已经","note":"引导原因从句，强调新的情况已经出现，从而带来后面的结果。","example":"Now that a tunnel has been built through the mountains, the Pass is less dangerous, but each year, the dogs are still sent out into the snow whenever a traveller is in difficulty.","exampleZh":"如今，穿山隧道已经建成，山口的危险性有所降低，但每年只要有旅行者遇险，这些狗仍会被派到雪地里救援。","sourceParagraphIndex":0,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"in difficulty","matchedForm":"in difficulty","meaning":"处于困境，遇到困难","note":"本文指旅行者遇险；也可用于一般生活或工作上的困难。","example":"Now that a tunnel has been built through the mountains, the Pass is less dangerous, but each year, the dogs are still sent out into the snow whenever a traveller is in difficulty.","exampleZh":"如今，穿山隧道已经建成，山口的危险性有所降低，但每年只要有旅行者遇险，这些狗仍会被派到雪地里救援。","sourceParagraphIndex":0,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"on foot","matchedForm":"on foot","meaning":"步行","note":"固定搭配不加冠词，也不用复数 feet。","example":"Despite the new tunnel, there are still a few people who rashly attempt to cross the Pass on foot.","exampleZh":"尽管有了新隧道，仍有少数人冒失地试图徒步穿越山口。","sourceParagraphIndex":0,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"prefer ... to","matchedForm":"prefer winter to summer","meaning":"比起……更喜欢……","note":"prefer A to B 中 A 是更喜欢的对象，to 是介词。","example":"The monks prefer winter to summer for they have more privacy.","exampleZh":"修士们更喜欢冬天，而不喜欢夏天，因为冬天他们能有更多不受打扰的私人空间。","sourceParagraphIndex":1,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"receive a warm welcome","matchedForm":"receive a warm welcome","meaning":"受到热情欢迎","note":"welcome 在此为可数名词；give somebody a warm welcome 表示热情欢迎某人。","example":"These young people, who love the peace of the mountains, always receive a warm welcome at St. Bernard's monastery.","exampleZh":"这些热爱山中宁静的年轻人，在圣伯纳德修道院总会受到热情欢迎。","sourceParagraphIndex":1,"sourceSentenceIndex":7,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l009","book":3,"number":9,"title":"Flying cats","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Cats never fail to fascinate human beings.","zh":"猫总能让人着迷。","kind":"narration","speaker":"旁白"},{"en":"They can be friendly and affectionate towards humans, but they lead mysterious lives of their own as well.","zh":"它们可以对人友善而亲昵，但也过着自己神秘的生活。","kind":"narration","speaker":"旁白"},{"en":"They never become submissive like dogs and horses.","zh":"它们从不像狗和马那样变得顺从。","kind":"narration","speaker":"旁白"},{"en":"As a result, humans have learned to respect feline independence.","zh":"因此，人类已学会尊重猫的独立性。","kind":"narration","speaker":"旁白"},{"en":"Most cats remain suspicious of humans all their lives.","zh":"大多数猫终其一生都对人类保持戒心。","kind":"narration","speaker":"旁白"},{"en":"One of the things that fascinates us most about cats is the popular belief that they have nine lives.","zh":"猫最让我们着迷的地方之一，就是人们普遍相信它们有九条命。","kind":"narration","speaker":"旁白"},{"en":"Apparently, there is a good deal of truth in this idea.","zh":"看来，这种说法还真有不少道理。","kind":"narration","speaker":"旁白"},{"en":"A cat’s ability to survive falls is based on fact.","zh":"猫能够从高处坠落后生还，是有事实依据的。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Recently the New York Animal Medical Centre made a study of 132 cats over a period of five months.","zh":"最近，纽约动物医疗中心在五个月里对一百三十二只猫进行了研究。","kind":"narration","speaker":"旁白"},{"en":"All these cats had one experience in common: they had fallen off high buildings, yet only eight of them died from shock or injuries.","zh":"这些猫都有一个共同经历：从高楼坠落过，然而其中只有八只因休克或伤势而死亡。","kind":"narration","speaker":"旁白"},{"en":"Of course, New York is the ideal place for such an interesting study, because there is no shortage of tall buildings.","zh":"当然，纽约是开展这种有趣研究的理想地点，因为那里不缺高楼。","kind":"narration","speaker":"旁白"},{"en":"There are plenty of high-rise windowsills to fall from!","zh":"有的是可供猫跌落的高层窗台！","kind":"narration","speaker":"旁白"},{"en":"One cat, Sabrina, fell 32 storeys, yet only suffered from a broken tooth.","zh":"一只名叫萨布丽娜的猫从三十二层楼的高度跌落，却只摔断了一颗牙。","kind":"narration","speaker":"旁白"},{"en":"‘Cats behave like well-trained paratroopers,’ a doctor said.","zh":"一位医生说：“猫的表现就像训练有素的伞兵。”","kind":"speech","speaker":"一位医生"},{"en":"It seems that the further cats fall, the less they are likely to injure themselves.","zh":"看起来，猫下落的距离越长，受伤的可能性反而越小。","kind":"narration","speaker":"旁白"},{"en":"In a long drop, they reach speeds of 60 miles an hour and more.","zh":"长距离坠落时，它们的速度会达到每小时六十英里，甚至更快。","kind":"narration","speaker":"旁白"},{"en":"At high speeds, falling cats have time to relax.","zh":"下落速度很高时，猫有时间放松身体。","kind":"narration","speaker":"旁白"},{"en":"They stretch out their legs like flying squirrels.","zh":"它们像鼯鼠一样伸展开四肢。","kind":"narration","speaker":"旁白"},{"en":"This increases their air-resistance and reduces the shock of impact when they hit the ground.","zh":"这样会增加空气阻力，减轻落地瞬间的冲击。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"never fail to","matchedForm":"never fail to","meaning":"总会，必定会","note":"字面为从不未能做到，实际强调每次都能产生某种效果，注意双重否定。","example":"Cats never fail to fascinate human beings.","exampleZh":"猫总能让人着迷。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"as a result","matchedForm":"As a result","meaning":"因此，结果","note":"作连接性状语时可单独使用；as a result of 后要接原因。","example":"As a result, humans have learned to respect feline independence.","exampleZh":"因此，人类已学会尊重猫的独立性。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"remain suspicious of","matchedForm":"remain suspicious of","meaning":"始终对……存有戒心","note":"suspicious of 表示不信任或有疑心，不等于令人怀疑的 suspicious 人或行为。","example":"Most cats remain suspicious of humans all their lives.","exampleZh":"大多数猫终其一生都对人类保持戒心。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"have ... in common","matchedForm":"had one experience in common","meaning":"有共同之处","note":"have something in common 表示具有相同特征或经历。","example":"All these cats had one experience in common: they had fallen off high buildings, yet only eight of them died from shock or injuries.","exampleZh":"这些猫都有一个共同经历：从高楼坠落过，然而其中只有八只因休克或伤势而死亡。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"no shortage of","matchedForm":"no shortage of","meaning":"不缺，大量存在","note":"shortage 指短缺，no shortage of 常委婉地表示数量相当充足。","example":"Of course, New York is the ideal place for such an interesting study, because there is no shortage of tall buildings.","exampleZh":"当然，纽约是开展这种有趣研究的理想地点，因为那里不缺高楼。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"stretch out","matchedForm":"stretch out","meaning":"伸展，伸开","note":"out 表示向外展开，常用于四肢或身体。","example":"They stretch out their legs like flying squirrels.","exampleZh":"它们像鼯鼠一样伸展开四肢。","sourceParagraphIndex":1,"sourceSentenceIndex":9,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l010","book":3,"number":10,"title":"The loss of the Titanic","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"The great ship, Titanic, sailed for New York from Southampton on April 10th, 1912.","zh":"巨轮“泰坦尼克号”于一九一二年四月十日从南安普敦起航，驶往纽约。","kind":"narration","speaker":"旁白"},{"en":"She was carrying 1,316 passengers and a crew of 891.","zh":"船上载有一千三百一十六名乘客和八百九十一名船员。","kind":"narration","speaker":"旁白"},{"en":"Even by modern standards, the 46,000 ton Titanic was a colossal ship.","zh":"即使按现代标准衡量，这艘四万六千吨的“泰坦尼克号”也称得上巨轮。","kind":"narration","speaker":"旁白"},{"en":"At that time, however, she was not only the largest ship that had ever been built, but was regarded as unsinkable, for she had sixteen watertight compartments.","zh":"而在当时，它不仅是有史以来建造的最大船只，还被认为永不沉没，因为船上设有十六个水密舱。","kind":"narration","speaker":"旁白"},{"en":"Even if two of these were flooded, she would still be able to float.","zh":"即使其中两个进水，船仍然能够漂浮。","kind":"narration","speaker":"旁白"},{"en":"The tragic sinking of this great liner will always be remembered, for she went down on her first voyage with heavy loss of life.","zh":"这艘巨型客轮悲惨沉没的事件将永远被人铭记，因为它在首次航行中就沉入海底，造成大量人员丧生。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Four days after setting out, while the Titanic was sailing across the icy waters of the North Atlantic, a huge iceberg was suddenly spotted by a lookout.","zh":"起航四天后，“泰坦尼克号”正在北大西洋冰冷的海域航行，一名瞭望员突然发现了一座巨大的冰山。","kind":"narration","speaker":"旁白"},{"en":"After the alarm had been given, the great ship turned sharply to avoid a direct collision.","zh":"警报发出后，巨轮猛地转向，以避免正面相撞。","kind":"narration","speaker":"旁白"},{"en":"The Titanic turned just in time, narrowly missing the immense wall of ice which rose over 100 feet out of the water beside her.","zh":"“泰坦尼克号”及时转了向，险些撞上身旁那堵高出水面一百多英尺的巨大冰墙。","kind":"narration","speaker":"旁白"},{"en":"Suddenly, there was a slight trembling sound from below, and the captain went down to see what had happened.","zh":"突然，船底下传来轻微的颤动声，船长便下去查看出了什么事。","kind":"narration","speaker":"旁白"},{"en":"The noise had been so faint that no one thought that the ship had been damaged.","zh":"那声音微弱得没有人想到船已经受损。","kind":"narration","speaker":"旁白"},{"en":"Below, the captain realized to his horror that the Titanic was sinking rapidly, for five of her sixteen watertight compartments had already been flooded!","zh":"到了船舱下面，船长惊恐地发现，“泰坦尼克号”正在迅速下沉，因为十六个水密舱中已有五个进水了！","kind":"narration","speaker":"旁白"},{"en":"The order to abandon ship was given and hundreds of people plunged into the icy water.","zh":"弃船的命令下达后，数百人跳进了冰冷的海水。","kind":"narration","speaker":"旁白"},{"en":"As there were not enough lifeboats for everybody, 1,500 lives were lost.","zh":"由于救生艇不够全体人员使用，一千五百人丧生了。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"sail for","matchedForm":"sailed for","meaning":"乘船驶往","note":"for 后接目的地；from 后接出发地，两个介词方向不同。","example":"The great ship, Titanic, sailed for New York from Southampton on April 10th, 1912.","exampleZh":"巨轮“泰坦尼克号”于一九一二年四月十日从南安普敦起航，驶往纽约。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"by ... standards","matchedForm":"by modern standards","meaning":"按……标准衡量","note":"by 在此表示衡量或判断的依据。","example":"Even by modern standards, the 46,000 ton Titanic was a colossal ship.","exampleZh":"即使按现代标准衡量，这艘四万六千吨的“泰坦尼克号”也称得上巨轮。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"be regarded as","matchedForm":"regarded as","meaning":"被认为是","note":"as 后可接名词或形容词，说明人们赋予的身份或判断。","example":"At that time, however, she was not only the largest ship that had ever been built, but was regarded as unsinkable, for she had sixteen watertight compartments.","exampleZh":"而在当时，它不仅是有史以来建造的最大船只，还被认为永不沉没，因为船上设有十六个水密舱。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"just in time","matchedForm":"just in time","meaning":"恰好及时","note":"强调赶在为时已晚之前；on time 通常指准时。","example":"The Titanic turned just in time, narrowly missing the immense wall of ice which rose over 100 feet out of the water beside her.","exampleZh":"“泰坦尼克号”及时转了向，险些撞上身旁那堵高出水面一百多英尺的巨大冰墙。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"to one’s horror","matchedForm":"to his horror","meaning":"使某人惊恐的是","note":"to 加物主代词和情绪名词，说明事情给某人造成的感受。","example":"Below, the captain realized to his horror that the Titanic was sinking rapidly, for five of her sixteen watertight compartments had already been flooded!","exampleZh":"到了船舱下面，船长惊恐地发现，“泰坦尼克号”正在迅速下沉，因为十六个水密舱中已有五个进水了！","sourceParagraphIndex":1,"sourceSentenceIndex":5,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l011","book":3,"number":11,"title":"Not guilty","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Customs Officers are quite tolerant these days, but they can still stop you when you are going through the Green Channel and have nothing to declare.","zh":"如今海关人员相当宽容，不过即使你走绿色通道、没有需要申报的物品，他们仍可能拦住你。","kind":"narration","speaker":"旁白"},{"en":"Even really honest people are often made to feel guilty.","zh":"就连真正诚实的人，也常被弄得觉得自己像做了错事。","kind":"narration","speaker":"旁白"},{"en":"The hardened professional smuggler, on the other hand, is never troubled by such feelings, even if he has five hundred gold watches hidden in his suitcase.","zh":"反倒是老练的职业走私者，从不受这种感觉困扰，哪怕手提箱里藏着五百只金表也是如此。","kind":"narration","speaker":"旁白"},{"en":"When I returned from abroad recently, a particularly officious young Customs Officer clearly regarded me as a smuggler.","zh":"最近我从国外回来时，一名格外爱摆官架子的年轻海关人员，显然把我当成了走私者。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"‘Have you anything to declare?’ he asked, looking me in the eye.","zh":"“你有什么物品要申报吗？”他直视着我的眼睛问。","kind":"speech","speaker":"年轻海关人员"}]},{"index":2,"rows":[{"en":"‘No,’ I answered confidently.","zh":"“没有，”我自信地回答。","kind":"speech","speaker":"我"}]},{"index":3,"rows":[{"en":"‘Would you mind unlocking this suitcase please?’","zh":"“请把这只手提箱打开，可以吗？”","kind":"speech","speaker":"年轻海关人员"}]},{"index":4,"rows":[{"en":"‘Not at all,’ I answered.","zh":"“当然可以，”我答道。","kind":"speech","speaker":"我"}]},{"index":5,"rows":[{"en":"The Officer went through the case with great care.","zh":"那位海关人员十分仔细地检查了箱子。","kind":"narration","speaker":"旁白"},{"en":"All the things I had packed so carefully were soon in a dreadful mess.","zh":"我原本精心收好的东西，很快就被翻得乱七八糟。","kind":"narration","speaker":"旁白"},{"en":"I felt sure I would never be able to close the case again.","zh":"我确信自己再也没法把箱子合上了。","kind":"narration","speaker":"旁白"},{"en":"Suddenly, I saw the Officer's face light up.","zh":"突然，我看见那位海关人员脸上露出了喜色。","kind":"narration","speaker":"旁白"},{"en":"He had spotted a tiny bottle at the bottom of my case and he pounced on it with delight.","zh":"他发现箱子底部有一个小瓶子，便高兴地一把抓住它。","kind":"narration","speaker":"旁白"}]},{"index":6,"rows":[{"en":"‘Perfume, eh?’ he asked sarcastically.","zh":"“香水，嗯？”他讥讽地问。","kind":"speech","speaker":"年轻海关人员"},{"en":"‘You should have declared that.","zh":"“这东西你本来应该申报。","kind":"speech","speaker":"年轻海关人员"},{"en":"Perfume is not exempt from import duty.’","zh":"香水可不能免交进口税。”","kind":"speech","speaker":"年轻海关人员"}]},{"index":7,"rows":[{"en":"‘But it isn’t perfume,’ I said.","zh":"“可这不是香水，”我说。","kind":"speech","speaker":"我"},{"en":"‘It’s hair gel.’ Then I added with a smile, ‘It’s a strange mixture I make myself.’","zh":"“这是发胶。”随后我又笑着补充说：“是我自己调配的一种奇特混合物。”","kind":"speech","speaker":"我"}]},{"index":8,"rows":[{"en":"As I expected, he did not believe me.","zh":"正如我所料，他并不相信我的话。","kind":"narration","speaker":"旁白"}]},{"index":9,"rows":[{"en":"‘Try it!’ I said encouragingly.","zh":"“试试看！”我鼓励他说。","kind":"speech","speaker":"我"}]},{"index":10,"rows":[{"en":"The Officer unscrewed the cap and put the bottle to his nostrils.","zh":"那位海关人员拧开瓶盖，把瓶子凑到鼻孔前。","kind":"narration","speaker":"旁白"},{"en":"He was greeted by an unpleasant smell which convinced him that I was telling the truth.","zh":"一股难闻的气味扑鼻而来，使他相信我说的是实话。","kind":"narration","speaker":"旁白"},{"en":"A few minutes later, I was able to hurry away with precious chalk marks on my baggage.","zh":"几分钟后，我的行李上有了那宝贵的粉笔放行记号，我得以匆匆离开。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"have nothing to declare","matchedForm":"have nothing to declare","meaning":"没有需要向海关申报的物品","note":"declare 在海关语境中指依法申报携带的物品，不能简单理解为公开宣布。","example":"Customs Officers are quite tolerant these days, but they can still stop you when you are going through the Green Channel and have nothing to declare.","exampleZh":"如今海关人员相当宽容，不过即使你走绿色通道、没有需要申报的物品，他们仍可能拦住你。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"on the other hand","matchedForm":"on the other hand","meaning":"另一方面，反过来看","note":"引出与前述情况不同或相反的一面，不一定必须先出现 on the one hand。","example":"The hardened professional smuggler, on the other hand, is never troubled by such feelings, even if he has five hundred gold watches hidden in his suitcase.","exampleZh":"反倒是老练的职业走私者，从不受这种感觉困扰，哪怕手提箱里藏着五百只金表也是如此。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"look somebody in the eye","matchedForm":"looking me in the eye","meaning":"直视某人的眼睛","note":"eye 常用单数；宾语放在 look 与 in 之间。","example":"‘Have you anything to declare?’ he asked, looking me in the eye.","exampleZh":"“你有什么物品要申报吗？”他直视着我的眼睛问。","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"in a mess","matchedForm":"in a dreadful mess","meaning":"乱成一团","note":"mess 前可加形容词强调程度；in a mess 也可形容处境混乱。","example":"All the things I had packed so carefully were soon in a dreadful mess.","exampleZh":"我原本精心收好的东西，很快就被翻得乱七八糟。","sourceParagraphIndex":5,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"light up","matchedForm":"light up","meaning":"面露喜色","note":"以 face 或 eyes 为主语时，表示神情因喜悦或兴奋而明亮起来。","example":"Suddenly, I saw the Officer's face light up.","exampleZh":"突然，我看见那位海关人员脸上露出了喜色。","sourceParagraphIndex":5,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"be exempt from","matchedForm":"exempt from","meaning":"免于，获豁免","note":"from 后接税款、责任或义务；本句有 not，意思是不能免税。","example":"Perfume is not exempt from import duty.’","exampleZh":"香水可不能免交进口税。”","sourceParagraphIndex":6,"sourceSentenceIndex":2,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l012","book":3,"number":12,"title":"Life on a desert island","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Most of us have formed an unrealistic picture of life on a desert island.","zh":"我们大多数人对荒岛生活形成了一种不切实际的想象。","kind":"narration","speaker":"旁白"},{"en":"We sometimes imagine a desert island to be a sort of paradise where the sun always shines.","zh":"有时，我们把荒岛想象成某种阳光永远普照的乐园。","kind":"narration","speaker":"旁白"},{"en":"Life there is simple and good.","zh":"那里的生活简单又美好。","kind":"narration","speaker":"旁白"},{"en":"Ripe fruit falls from the trees and you never have to work.","zh":"成熟的果实从树上掉下来，人根本不用干活。","kind":"narration","speaker":"旁白"},{"en":"The other side of the picture is quite the opposite.","zh":"另一种想象则完全相反。","kind":"narration","speaker":"旁白"},{"en":"Life on a desert island is wretched.","zh":"荒岛上的生活凄苦不堪。","kind":"narration","speaker":"旁白"},{"en":"You either starve to death or live like Robinson Crusoe, waiting for a boat which never comes.","zh":"你要么饿死，要么像鲁滨孙·克鲁索那样生活，苦等一艘永远不会出现的船。","kind":"narration","speaker":"旁白"},{"en":"Perhaps there is an element of truth in both these pictures, but few of us have had the opportunity to find out.","zh":"这两种想象也许都多少有些道理，但我们中很少有人有机会去验证。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Two men who recently spent five days on a coral island wished they had stayed there longer.","zh":"最近，有两个人在一座珊瑚岛上待了五天，他们却希望当时能在那儿多待些日子。","kind":"narration","speaker":"旁白"},{"en":"They were taking a badly damaged boat from the Virgin Islands to Miami to have it repaired.","zh":"他们正把一艘严重受损的船从维尔京群岛开往迈阿密去修理。","kind":"narration","speaker":"旁白"},{"en":"During the journey, their boat began to sink.","zh":"途中，他们的船开始下沉。","kind":"narration","speaker":"旁白"},{"en":"They quickly loaded a small rubber dinghy with food, matches, and cans of beer and rowed for a few miles across the Caribbean until they arrived at a tiny coral island.","zh":"他们迅速把食物、火柴和罐装啤酒装进一只小橡皮艇，在加勒比海上划了几英里，来到一座小小的珊瑚岛。","kind":"narration","speaker":"旁白"},{"en":"There were hardly any trees on the island and there was no water, but this did not prove to be a problem.","zh":"岛上几乎没有树，也没有水，但事实证明，这并未成为问题。","kind":"narration","speaker":"旁白"},{"en":"The men collected rainwater in the rubber dinghy.","zh":"他们用橡皮艇收集雨水。","kind":"narration","speaker":"旁白"},{"en":"As they had brought a spear gun with them, they had plenty to eat.","zh":"由于带了鱼枪，他们有充足的食物。","kind":"narration","speaker":"旁白"},{"en":"They caught lobster and fish every day, and, as one of them put it ‘ate like kings’.","zh":"他们每天捕龙虾和鱼，用其中一人的话说，吃得“像国王一样”。","kind":"narration","speaker":"旁白"},{"en":"When a passing tanker rescued them five days later, both men were genuinely sorry that they had to leave.","zh":"五天后，一艘路过的油轮救起了他们，两人对不得不离开这里都真心感到遗憾。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"form a picture of","matchedForm":"formed an unrealistic picture of","meaning":"形成对……的印象或想象","note":"picture 在这里指脑海中的认识，并非实际画出的图画。","example":"Most of us have formed an unrealistic picture of life on a desert island.","exampleZh":"我们大多数人对荒岛生活形成了一种不切实际的想象。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"starve to death","matchedForm":"starve to death","meaning":"饿死","note":"to death 表示最终达到死亡的结果，也见于 freeze to death。","example":"You either starve to death or live like Robinson Crusoe, waiting for a boat which never comes.","exampleZh":"你要么饿死，要么像鲁滨孙·克鲁索那样生活，苦等一艘永远不会出现的船。","sourceParagraphIndex":0,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"an element of truth","matchedForm":"an element of truth","meaning":"几分真实性","note":"element 在此指某种成分或程度，表示并非全然不实，也非完全正确。","example":"Perhaps there is an element of truth in both these pictures, but few of us have had the opportunity to find out.","exampleZh":"这两种想象也许都多少有些道理，但我们中很少有人有机会去验证。","sourceParagraphIndex":0,"sourceSentenceIndex":7,"sourceType":"textbook-passage"},{"phrase":"load ... with","matchedForm":"loaded a small rubber dinghy with","meaning":"把……装上……","note":"load 容器 with 物品；另一结构为 load 物品 into 容器。","example":"They quickly loaded a small rubber dinghy with food, matches, and cans of beer and rowed for a few miles across the Caribbean until they arrived at a tiny coral island.","exampleZh":"他们迅速把食物、火柴和罐装啤酒装进一只小橡皮艇，在加勒比海上划了几英里，来到一座小小的珊瑚岛。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"as somebody puts it","matchedForm":"as one of them put it","meaning":"用某人的话说","note":"put 在此表示表达、措辞；过去时 put 的拼写不变。","example":"They caught lobster and fish every day, and, as one of them put it ‘ate like kings’.","exampleZh":"他们每天捕龙虾和鱼，用其中一人的话说，吃得“像国王一样”。","sourceParagraphIndex":1,"sourceSentenceIndex":7,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l013","book":3,"number":13,"title":"‘It’s only me’","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"After her husband had gone to work, Mrs. Richards sent her children to school and went upstairs to her bedroom.","zh":"丈夫上班后，理查兹太太送孩子们去上学，随后上楼进了自己的卧室。","kind":"narration","speaker":"旁白"},{"en":"She was too excited to do any housework that morning, for in the evening she would be going to a fancy-dress party with her husband.","zh":"那天早晨，她兴奋得什么家务都做不下去，因为当晚她要和丈夫一起参加化装舞会。","kind":"narration","speaker":"旁白"},{"en":"She intended to dress up as a ghost and as she had made her costume the night before, she was impatient to try it on.","zh":"她打算装扮成鬼；服装已在前一天晚上做好，她迫不及待地想试穿一下。","kind":"narration","speaker":"旁白"},{"en":"Though the costume consisted only of a sheet, it was very effective.","zh":"尽管这套服装只有一条床单，效果却很好。","kind":"narration","speaker":"旁白"},{"en":"After putting it on, Mrs. Richards went downstairs.","zh":"理查兹太太穿上它后，下了楼。","kind":"narration","speaker":"旁白"},{"en":"She wanted to find out whether it would be comfortable to wear.","zh":"她想看看穿着它是否舒服。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Just as Mrs. Richards was entering the dining room, there was a knock on the front door.","zh":"理查兹太太刚要走进餐厅，前门就传来了敲门声。","kind":"narration","speaker":"旁白"},{"en":"She knew that it must be the baker.","zh":"她知道，来的一定是送面包的人。","kind":"narration","speaker":"旁白"},{"en":"She had told him to come straight in if ever she failed to open the door and to leave the bread on the kitchen table.","zh":"她曾告诉他，如果有时她没来开门，就直接进来，把面包放在厨房桌上。","kind":"narration","speaker":"旁白"},{"en":"Not wanting to frighten the poor man, Mrs. Richards quickly hid in the small storeroom under the stairs.","zh":"理查兹太太不想吓着这可怜的人，便赶紧躲进楼梯下的小储藏室。","kind":"narration","speaker":"旁白"},{"en":"She heard the front door open and heavy footsteps in the hall.","zh":"她听见前门开了，门厅里响起沉重的脚步声。","kind":"narration","speaker":"旁白"},{"en":"Suddenly the door of the storeroom was opened and a man entered.","zh":"突然，储藏室的门打开了，一个男人走了进来。","kind":"narration","speaker":"旁白"},{"en":"Mrs. Richards realized that it must be the man from the Electricity Board who had come to read the meter.","zh":"理查兹太太这才明白，来的一定是供电局查电表的人。","kind":"narration","speaker":"旁白"},{"en":"She tried to explain the situation, saying ‘It’s only me’, but it was too late.","zh":"她想解释情况，说“是我呀”，可已经太晚了。","kind":"speech","speaker":"理查兹太太"},{"en":"The man let out a cry and jumped back several paces.","zh":"那人惊叫一声，向后跳了好几步。","kind":"narration","speaker":"旁白"},{"en":"When Mrs. Richards walked towards him, he fled, slamming the door behind him.","zh":"理查兹太太朝他走去时，他逃了出去，砰地关上了身后的门。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"dress up as","matchedForm":"dress up as","meaning":"装扮成","note":"dress up 表示穿特别服装，as 后说明扮演的角色。","example":"She intended to dress up as a ghost and as she had made her costume the night before, she was impatient to try it on.","exampleZh":"她打算装扮成鬼；服装已在前一天晚上做好，她迫不及待地想试穿一下。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"be impatient to do something","matchedForm":"impatient to","meaning":"迫不及待地想做某事","note":"这里是急切期待，不是对人发脾气；try it on 中代词须放在 try 与 on 之间。","example":"She intended to dress up as a ghost and as she had made her costume the night before, she was impatient to try it on.","exampleZh":"她打算装扮成鬼；服装已在前一天晚上做好，她迫不及待地想试穿一下。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"consist of","matchedForm":"consisted only of","meaning":"仅由……组成","note":"consist of 通常不用被动语态；本句 only 插在动词与 of 之间，强调服装只有一条床单。","example":"Though the costume consisted only of a sheet, it was very effective.","exampleZh":"尽管这套服装只有一条床单，效果却很好。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"come straight in","matchedForm":"come straight in","meaning":"直接进来","note":"straight 在此为副词，表示不耽搁、不绕道，不能换成形容词 straight 的其他义项。","example":"She had told him to come straight in if ever she failed to open the door and to leave the bread on the kitchen table.","exampleZh":"她曾告诉他，如果有时她没来开门，就直接进来，把面包放在厨房桌上。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"let out a cry","matchedForm":"let out a cry","meaning":"发出一声叫喊","note":"let out 可表示发出声音，如 let out a sigh；let 的过去式仍为 let。","example":"The man let out a cry and jumped back several paces.","exampleZh":"那人惊叫一声，向后跳了好几步。","sourceParagraphIndex":1,"sourceSentenceIndex":8,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l014","book":3,"number":14,"title":"A noble gangster","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"There was a time when the owners of shops and businesses in Chicago had to pay large sums of money to gangsters in return for ‘protection’.","zh":"曾经有一个时期，芝加哥的商店和企业主必须向黑帮缴纳大笔金钱，以换取所谓的“保护”。","kind":"narration","speaker":"旁白"},{"en":"If the money was not paid promptly, the gangsters would quickly put a man out of business by destroying his shop.","zh":"如果钱没及时交上，黑帮很快就会毁掉店铺，让店主无法继续营业。","kind":"narration","speaker":"旁白"},{"en":"Obtaining ‘protection money’ is not a modern crime.","zh":"收取“保护费”并不是现代才出现的罪行。","kind":"narration","speaker":"旁白"},{"en":"As long ago as the fourteenth century, an Englishman, Sir John Hawkwood, made the remarkable discovery that people would rather pay large sums of money than have their life work destroyed by gangsters.","zh":"早在十四世纪，英国人约翰·霍克伍德爵士就有了一个惊人的发现：人们宁可付出大笔金钱，也不愿让黑帮毁掉自己一生的心血。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Six hundred years ago, Sir John Hawkwood arrived in Italy with a band of soldiers and settled near Florence.","zh":"六百年前，约翰·霍克伍德爵士带着一队士兵来到意大利，在佛罗伦萨附近驻扎下来。","kind":"narration","speaker":"旁白"},{"en":"He soon made a name for himself and came to be known to the Italians as Giovanni Acuto.","zh":"他很快闯出了名声，意大利人逐渐把他称为乔瓦尼·阿库托。","kind":"narration","speaker":"旁白"},{"en":"Whenever the Italian city-states were at war with each other, Hawkwood used to hire his soldiers to princes who were willing to pay the high price he demanded.","zh":"每当意大利各城邦交战时，霍克伍德就把手下的士兵出租给愿意支付他所索高价的王公。","kind":"narration","speaker":"旁白"},{"en":"In times of peace, when business was bad, Hawkwood and his men would march into a city-state and, after burning down a few farms, would offer to go away if protection money was paid to them.","zh":"和平时期生意清淡，霍克伍德和手下便开进某个城邦，烧掉几座农场，然后提出，只要付给他们保护费，他们就离开。","kind":"narration","speaker":"旁白"},{"en":"Hawkwood made large sums of money in this way.","zh":"霍克伍德用这种办法赚到了大笔钱财。","kind":"narration","speaker":"旁白"},{"en":"In spite of this, the Italians regarded him as a sort of hero.","zh":"尽管如此，意大利人却把他视为某种英雄。","kind":"narration","speaker":"旁白"},{"en":"When he died at the age of eighty, the Florentines gave him a state funeral and had a picture painted which was dedicated to the memory of ‘the most valiant soldier and most notable leader, Signor Giovanni Haukodue’.","zh":"他八十岁去世时，佛罗伦萨人为他举行了国葬，并请人画了一幅画像，以纪念“最英勇的战士、最卓越的领袖乔瓦尼·霍科杜埃先生”。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"in return for","matchedForm":"in return for","meaning":"作为……的交换或回报","note":"for 后说明对方给予的事物；本课所谓保护实际是黑帮敲诈的名目。","example":"There was a time when the owners of shops and businesses in Chicago had to pay large sums of money to gangsters in return for ‘protection’.","exampleZh":"曾经有一个时期，芝加哥的商店和企业主必须向黑帮缴纳大笔金钱，以换取所谓的“保护”。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"put somebody out of business","matchedForm":"put a man out of business","meaning":"使某人停业或破产","note":"out of business 表示不再经营，不是因公外出。","example":"If the money was not paid promptly, the gangsters would quickly put a man out of business by destroying his shop.","exampleZh":"如果钱没及时交上，黑帮很快就会毁掉店铺，让店主无法继续营业。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"as long ago as","matchedForm":"As long ago as","meaning":"早在……的时候","note":"强调时间之久，与表示条件的 as long as 用法不同。","example":"As long ago as the fourteenth century, an Englishman, Sir John Hawkwood, made the remarkable discovery that people would rather pay large sums of money than have their life work destroyed by gangsters.","exampleZh":"早在十四世纪，英国人约翰·霍克伍德爵士就有了一个惊人的发现：人们宁可付出大笔金钱，也不愿让黑帮毁掉自己一生的心血。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"make a name for oneself","matchedForm":"made a name for himself","meaning":"成名，闯出名声","note":"表示因成就、表现或活动而被人熟知，未必一定是好名声。","example":"He soon made a name for himself and came to be known to the Italians as Giovanni Acuto.","exampleZh":"他很快闯出了名声，意大利人逐渐把他称为乔瓦尼·阿库托。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"in spite of","matchedForm":"In spite of","meaning":"尽管","note":"of 后接名词、代词或动名词；若接完整从句，通常用 in spite of the fact that。","example":"In spite of this, the Italians regarded him as a sort of hero.","exampleZh":"尽管如此，意大利人却把他视为某种英雄。","sourceParagraphIndex":1,"sourceSentenceIndex":5,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l015","book":3,"number":15,"title":"Fifty pence worth of trouble","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Children always appreciate small gifts of money.","zh":"孩子们总喜欢得到一点小额的零用钱。","kind":"narration","speaker":"旁白"},{"en":"Mum or dad, of course, provide a regular supply of pocket money, but uncles and aunts are always a source of extra income.","zh":"当然，爸爸妈妈会定期给零花钱，但叔伯姑姨总是额外收入的来源。","kind":"narration","speaker":"旁白"},{"en":"With some children, small sums go a long way.","zh":"对有些孩子来说，一点钱也能花上很久。","kind":"narration","speaker":"旁白"},{"en":"If fifty pence pieces are not exchanged for sweets, they rattle for months inside money boxes.","zh":"如果五十便士的硬币没有被拿去买糖果，就会在储蓄罐里叮当作响地待上几个月。","kind":"narration","speaker":"旁白"},{"en":"Only very thrifty children manage to fill up a money box.","zh":"只有非常节俭的孩子才能把储蓄罐装满。","kind":"narration","speaker":"旁白"},{"en":"For most of them, fifty pence is a small price to pay for a nice big bar of chocolate.","zh":"对大多数孩子来说，花五十便士买一大块好吃的巧克力，是很划算的。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"My nephew, George, has a money box but it is always empty.","zh":"我的侄子乔治有个储蓄罐，可里面总是空的。","kind":"narration","speaker":"旁白"},{"en":"Very few of the fifty pence pieces and pound coins I have given him have found their way there.","zh":"我给他的五十便士和一英镑硬币，几乎没几枚进过那个罐子。","kind":"narration","speaker":"旁白"},{"en":"I gave him fifty pence yesterday and advised him to save it.","zh":"昨天，我给了他五十便士，劝他存起来。","kind":"narration","speaker":"旁白"},{"en":"Instead he bought himself fifty pence worth of trouble.","zh":"可他却用这五十便士给自己买来了麻烦。","kind":"narration","speaker":"旁白"},{"en":"On his way to the sweet shop, he dropped his fifty pence and it bounced along the pavement and then disappeared down a drain.","zh":"去糖果店的路上，他把五十便士硬币掉到了地上；硬币沿人行道弹跳着，接着落进排水沟，不见了。","kind":"narration","speaker":"旁白"},{"en":"George took off his jacket, rolled up his sleeves and pushed his right arm through the drain cover.","zh":"乔治脱下外套，卷起袖子，把右胳膊伸进排水沟盖的缝隙。","kind":"narration","speaker":"旁白"},{"en":"He could not find his fifty pence piece anywhere, and what is more, he could not get his arm out.","zh":"他怎么也找不到那枚五十便士硬币，而且更糟的是，他的胳膊也拔不出来了。","kind":"narration","speaker":"旁白"},{"en":"A crowd of people gathered round him and a lady rubbed his arm with soap and butter, but George was firmly stuck.","zh":"一群人围了过来，一位女士用肥皂和黄油涂抹他的胳膊，可乔治还是卡得紧紧的。","kind":"narration","speaker":"旁白"},{"en":"The fire brigade was called and two fire fighters freed George using a special type of grease.","zh":"有人叫来了消防队，两名消防员用一种特殊的润滑油脂，才把乔治解救出来。","kind":"narration","speaker":"旁白"},{"en":"George was not too upset by his experience because the lady who owns the sweet shop heard about his troubles and rewarded him with a large box of chocolates.","zh":"乔治倒没有因为这番经历太难过，因为糖果店的女店主听说他的麻烦后，奖给了他一大盒巧克力。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"go a long way","matchedForm":"go a long way","meaning":"能用很久，能起很大作用","note":"谈钱或物资时指少量也很经用、很有帮助，并非走很远的路。","example":"With some children, small sums go a long way.","exampleZh":"对有些孩子来说，一点钱也能花上很久。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"fill up","matchedForm":"fill up","meaning":"装满","note":"up 强调达到满的状态；名词宾语可放后面，代词宾语须置于 fill 与 up 之间。","example":"Only very thrifty children manage to fill up a money box.","exampleZh":"只有非常节俭的孩子才能把储蓄罐装满。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"find one’s way","matchedForm":"found their way","meaning":"最终来到，进入某处","note":"可用物作主语，表示物品辗转到达；本文否定语境说硬币几乎没有存进去。","example":"Very few of the fifty pence pieces and pound coins I have given him have found their way there.","exampleZh":"我给他的五十便士和一英镑硬币，几乎没几枚进过那个罐子。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"roll up one’s sleeves","matchedForm":"rolled up his sleeves","meaning":"卷起袖子","note":"既可表示实际动作，也可比喻准备认真动手工作；本文是字面动作。","example":"George took off his jacket, rolled up his sleeves and pushed his right arm through the drain cover.","exampleZh":"乔治脱下外套，卷起袖子，把右胳膊伸进排水沟盖的缝隙。","sourceParagraphIndex":1,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"what is more","matchedForm":"what is more","meaning":"而且，此外","note":"补充更进一步的信息；本课加入的是更糟糕的情况。","example":"He could not find his fifty pence piece anywhere, and what is more, he could not get his arm out.","exampleZh":"他怎么也找不到那枚五十便士硬币，而且更糟的是，他的胳膊也拔不出来了。","sourceParagraphIndex":1,"sourceSentenceIndex":6,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l016","book":3,"number":16,"title":"Mary had a little lamb","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Mary and her husband Dimitri lived in the tiny village of Perachora in southern Greece.","zh":"玛丽和丈夫迪米特里住在希腊南部的小村庄佩拉霍拉。","kind":"narration","speaker":"旁白"},{"en":"One of Mary's prize possessions was a little white lamb which her husband had given her.","zh":"玛丽最珍爱的东西之一，是丈夫送给她的一只小白羊。","kind":"narration","speaker":"旁白"},{"en":"She kept it tied to a tree in a field during the day and went to fetch it every evening.","zh":"白天，她把小羊拴在田里的一棵树上，每天晚上再去把它牵回来。","kind":"narration","speaker":"旁白"},{"en":"One evening, however, the lamb was missing.","zh":"然而，一天傍晚，小羊不见了。","kind":"narration","speaker":"旁白"},{"en":"The rope had been cut, so it was obvious that the lamb had been stolen.","zh":"绳子被割断了，显然小羊是被人偷走的。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"When Dimitri came in from the fields, his wife told him what had happened.","zh":"迪米特里从田里回来时，妻子把发生的事告诉了他。","kind":"narration","speaker":"旁白"},{"en":"Dimitri at once set out to find the thief.","zh":"迪米特里立刻动身去找小偷。","kind":"narration","speaker":"旁白"},{"en":"He knew it would not prove difficult in such a small village.","zh":"他知道，在这么小的村庄里，找到小偷不会太难。","kind":"narration","speaker":"旁白"},{"en":"After telling several of his friends about the theft, Dimitri found out that his neighbour, Aleko, had suddenly acquired a new lamb.","zh":"迪米特里向几个朋友说起失窃的事后，得知邻居阿莱科突然多了一只新羊羔。","kind":"narration","speaker":"旁白"},{"en":"Dimitri immediately went to Aleko’s house and angrily accused him of stealing the lamb.","zh":"迪米特里马上来到阿莱科家，愤怒地指责他偷了小羊。","kind":"narration","speaker":"旁白"},{"en":"He told him he had better return it or he would call the police.","zh":"他告诉阿莱科，最好把羊还回来，否则他就报警。","kind":"narration","speaker":"旁白"},{"en":"Aleko denied taking it and led Dimitri into his backyard.","zh":"阿莱科否认偷羊，领着迪米特里来到后院。","kind":"narration","speaker":"旁白"},{"en":"It was true that he had just bought a lamb, he explained, but his lamb was black.","zh":"他解释说，自己确实刚买了一只羊羔，不过他的羊是黑色的。","kind":"narration","speaker":"旁白"},{"en":"Ashamed of having acted so rashly, Dimitri apologized to Aleko for having accused him.","zh":"迪米特里为自己的鲁莽感到羞愧，因而为错怪阿莱科向他道歉。","kind":"narration","speaker":"旁白"},{"en":"While they were talking it began to rain and Dimitri stayed in Aleko’s house until the rain stopped.","zh":"他们谈话时下起了雨，迪米特里就在阿莱科家待到雨停。","kind":"narration","speaker":"旁白"},{"en":"When he went outside half an hour later, he was astonished to find that the little black lamb was almost white.","zh":"半小时后，他走到外面，惊讶地发现那只小黑羊几乎变成白色的了。","kind":"narration","speaker":"旁白"},{"en":"Its wool, which had been dyed black, had been washed clean by the rain!","zh":"原来，羊毛是染黑的，雨水已经把染料冲洗干净了！","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"prize possession","matchedForm":"prize possessions","meaning":"珍爱的财物","note":"prize 在此作定语，表示极珍贵、令人自豪，并非一定指获奖得到的物品。","example":"One of Mary's prize possessions was a little white lamb which her husband had given her.","exampleZh":"玛丽最珍爱的东西之一，是丈夫送给她的一只小白羊。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"set out to","matchedForm":"set out to","meaning":"动身去，着手去","note":"后接动词原形，强调有明确目的地开始行动。","example":"Dimitri at once set out to find the thief.","exampleZh":"迪米特里立刻动身去找小偷。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"accuse somebody of","matchedForm":"accused him of","meaning":"指控或指责某人做了某事","note":"of 后接名词或动名词；不要与 blame somebody for 的介词混淆。","example":"Dimitri immediately went to Aleko’s house and angrily accused him of stealing the lamb.","exampleZh":"迪米特里马上来到阿莱科家，愤怒地指责他偷了小羊。","sourceParagraphIndex":1,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"had better","matchedForm":"had better","meaning":"最好做某事","note":"后接动词原形，常包含劝告或警告意味；否定为 had better not do。","example":"He told him he had better return it or he would call the police.","exampleZh":"他告诉阿莱科，最好把羊还回来，否则他就报警。","sourceParagraphIndex":1,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"apologize to ... for","matchedForm":"apologized to Aleko for","meaning":"为某事向某人道歉","note":"to 引出道歉对象，for 引出原因；having done 强调行为先于道歉发生。","example":"Ashamed of having acted so rashly, Dimitri apologized to Aleko for having accused him.","exampleZh":"迪米特里为自己的鲁莽感到羞愧，因而为错怪阿莱科向他道歉。","sourceParagraphIndex":1,"sourceSentenceIndex":8,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l017","book":3,"number":17,"title":"The longest suspension bridge in the world","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Verrazano, an Italian about whom little is known, sailed into New York Harbour in 1524 and named it Angoulême.","zh":"一五二四年，一位名叫韦拉扎诺、身世鲜为人知的意大利人驶入纽约港，并把它命名为昂古莱姆。","kind":"narration","speaker":"旁白"},{"en":"He described it as ‘a very agreeable situation located within two small hills in the midst of which flowed a great river.’","zh":"他把这里描述为“一个十分宜人的地方，位于两座小山之间，一条大河从中流过”。","kind":"narration","speaker":"旁白"},{"en":"Though Verrazano is by no means considered to be a great explorer, his name will probably remain immortal, for on November 21st, 1964, the longest suspension bridge in the world was named after him.","zh":"尽管韦拉扎诺绝不能算作伟大的探险家，他的名字却可能永垂不朽，因为一九六四年十一月二十一日，当时世界上最长的悬索桥以他的名字命名。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"The Verrazano Bridge, which was designed by Othmar Ammann, joins Brooklyn to Staten Island.","zh":"韦拉扎诺大桥由奥特马尔·阿曼设计，连接布鲁克林和斯塔滕岛。","kind":"narration","speaker":"旁白"},{"en":"It has a span of 4,260 feet.","zh":"它的跨度为四千二百六十英尺。","kind":"narration","speaker":"旁白"},{"en":"The bridge is so long that the shape of the earth had to be taken into account by its designer.","zh":"桥身长到设计者不得不把地球的形状考虑在内。","kind":"narration","speaker":"旁白"},{"en":"Two great towers support four huge cables.","zh":"两座巨塔支撑着四根巨大的钢缆。","kind":"narration","speaker":"旁白"},{"en":"The towers are built on immense underwater platforms made of steel and concrete.","zh":"桥塔建在巨大的水下平台上，平台由钢材和混凝土建成。","kind":"narration","speaker":"旁白"},{"en":"The platforms extend to a depth of over 100 feet under the sea.","zh":"这些平台伸至海面下一百多英尺的深处。","kind":"narration","speaker":"旁白"},{"en":"These alone took sixteen months to build.","zh":"仅建造这些平台就花了十六个月。","kind":"narration","speaker":"旁白"},{"en":"Above the surface of the water, the towers rise to a height of nearly 700 feet.","zh":"桥塔在水面以上高耸近七百英尺。","kind":"narration","speaker":"旁白"},{"en":"They support the cables from which the bridge has been suspended.","zh":"它们支撑着钢缆，桥身就悬吊在这些钢缆上。","kind":"narration","speaker":"旁白"},{"en":"Each of the four cables contains 26,108 lengths of wire.","zh":"四根钢缆中的每一根都包含两万六千一百零八根钢丝。","kind":"narration","speaker":"旁白"},{"en":"It has been estimated that if the bridge were packed with cars, it would still only be carrying a third of its total capacity.","zh":"据估计，即使桥上挤满汽车，承受的重量也仅为其总承载能力的三分之一。","kind":"narration","speaker":"旁白"},{"en":"However, size and strength are not the only important things about this bridge.","zh":"不过，规模和强度并不是这座桥仅有的重要特点。","kind":"narration","speaker":"旁白"},{"en":"Despite its immensity, it is both simple and elegant, fulfilling its designer’s dream to create ‘an enormous object drawn as faintly as possible’.","zh":"它虽然庞大，却既简洁又优美，实现了设计者的梦想：创造“一个用尽可能轻淡的线条勾勒出来的庞然大物”。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"by no means","matchedForm":"by no means","meaning":"绝不，决非","note":"语气强烈的否定；若放在句首修饰整句，通常需用部分倒装。","example":"Though Verrazano is by no means considered to be a great explorer, his name will probably remain immortal, for on November 21st, 1964, the longest suspension bridge in the world was named after him.","exampleZh":"尽管韦拉扎诺绝不能算作伟大的探险家，他的名字却可能永垂不朽，因为一九六四年十一月二十一日，当时世界上最长的悬索桥以他的名字命名。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"name after","matchedForm":"named after","meaning":"以某人的名字命名","note":"be named after somebody 表示名称取自某人，以示纪念或关联。","example":"Though Verrazano is by no means considered to be a great explorer, his name will probably remain immortal, for on November 21st, 1964, the longest suspension bridge in the world was named after him.","exampleZh":"尽管韦拉扎诺绝不能算作伟大的探险家，他的名字却可能永垂不朽，因为一九六四年十一月二十一日，当时世界上最长的悬索桥以他的名字命名。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"take into account","matchedForm":"taken into account","meaning":"把……考虑进去","note":"宾语可置于 take 与 into account 之间；被动形式为 be taken into account。","example":"The bridge is so long that the shape of the earth had to be taken into account by its designer.","exampleZh":"桥身长到设计者不得不把地球的形状考虑在内。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"to a depth of","matchedForm":"to a depth of","meaning":"达到……的深度","note":"depth 为深度；描述向下延伸时，to 表示达到的限度。","example":"The platforms extend to a depth of over 100 feet under the sea.","exampleZh":"这些平台伸至海面下一百多英尺的深处。","sourceParagraphIndex":1,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"be packed with","matchedForm":"packed with","meaning":"挤满，塞满","note":"packed 强调密集；本句 were 与 would 配合，表达假设条件。","example":"It has been estimated that if the bridge were packed with cars, it would still only be carrying a third of its total capacity.","exampleZh":"据估计，即使桥上挤满汽车，承受的重量也仅为其总承载能力的三分之一。","sourceParagraphIndex":1,"sourceSentenceIndex":10,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l018","book":3,"number":18,"title":"Electric currents in modern art","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Modern sculpture rarely surprises us any more.","zh":"现代雕塑已很少再让我们惊讶了。","kind":"narration","speaker":"旁白"},{"en":"The idea that modern art can only be seen in museums is mistaken.","zh":"认为只有在博物馆里才能见到现代艺术，这种看法是错误的。","kind":"narration","speaker":"旁白"},{"en":"Even people who take no interest in art cannot have failed to notice examples of modern sculpture on display in public places.","zh":"即使对艺术毫无兴趣的人，也不可能没有注意到公共场所陈列的现代雕塑作品。","kind":"narration","speaker":"旁白"},{"en":"Strange forms stand in gardens, and outside buildings and shops.","zh":"花园里、建筑物和商店外，到处矗立着奇形怪状的造型。","kind":"narration","speaker":"旁白"},{"en":"We have got quite used to them.","zh":"我们已经相当习惯它们了。","kind":"narration","speaker":"旁白"},{"en":"Some so-called ‘modern’ pieces have been on display for nearly eighty years.","zh":"有些所谓的“现代”作品，已经展出将近八十年了。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"In spite of this, some people—including myself—were surprised by a recent exhibition of modern sculpture.","zh":"尽管如此，最近的一次现代雕塑展还是使一些人——包括我在内——感到意外。","kind":"narration","speaker":"旁白"},{"en":"The first thing I saw when I entered the art gallery was a notice which said: ‘Do not touch the exhibits.","zh":"我一走进美术馆，首先看到的是一块告示，上面写着：“请勿触摸展品。","kind":"note","speaker":"展览告示"},{"en":"Some of them are dangerous!’","zh":"其中一些有危险！”","kind":"note","speaker":"展览告示"},{"en":"The objects on display were pieces of moving sculpture.","zh":"展出的都是些能够运动的雕塑。","kind":"narration","speaker":"旁白"},{"en":"Oddly shaped forms that are suspended from the ceiling and move in response to a gust of wind are quite familiar to everybody.","zh":"那些吊在天花板上、随一阵风而动的奇特造型，大家都很熟悉。","kind":"narration","speaker":"旁白"},{"en":"These objects, however, were different.","zh":"可是，这些展品却不同。","kind":"narration","speaker":"旁白"},{"en":"Lined up against the wall, there were long thin wires attached to metal spheres.","zh":"沿着墙排列着一些细长的金属线，线上连着金属球。","kind":"narration","speaker":"旁白"},{"en":"The spheres had been magnetized and attracted or repelled each other all the time.","zh":"这些球已经磁化，始终在彼此吸引或排斥。","kind":"narration","speaker":"旁白"},{"en":"In the centre of the hall, there were a number of tall structures which contained coloured lights.","zh":"大厅中央有一些高大的构架，里面装着彩灯。","kind":"narration","speaker":"旁白"},{"en":"These lights flickered continuously like traffic lights which have gone mad.","zh":"这些灯不停地闪烁，像发了疯的交通信号灯。","kind":"narration","speaker":"旁白"},{"en":"Sparks were emitted from small black boxes and red lamps flashed on and off angrily.","zh":"小黑盒子里迸出火花，红灯气势汹汹地忽明忽灭。","kind":"narration","speaker":"旁白"},{"en":"It was rather like an exhibition of prehistoric electronic equipment.","zh":"这倒很像一场史前电子设备展览。","kind":"narration","speaker":"旁白"},{"en":"These peculiar forms not only seemed designed to shock people emotionally, but to give them electric shocks as well!","zh":"这些奇特的造型，似乎不仅是为了在情感上震撼人们，还要给人实实在在的电击！","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"take an interest in","matchedForm":"take no interest in","meaning":"对……感兴趣","note":"interest 前可加 an、little 或 no 等；本句 no 表示毫无兴趣。","example":"Even people who take no interest in art cannot have failed to notice examples of modern sculpture on display in public places.","exampleZh":"即使对艺术毫无兴趣的人，也不可能没有注意到公共场所陈列的现代雕塑作品。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"on display","matchedForm":"on display","meaning":"陈列着，展出中","note":"常作表语或后置定语；也可说 be on display。","example":"Even people who take no interest in art cannot have failed to notice examples of modern sculpture on display in public places.","exampleZh":"即使对艺术毫无兴趣的人，也不可能没有注意到公共场所陈列的现代雕塑作品。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"get used to","matchedForm":"got quite used to","meaning":"变得习惯于","note":"to 为介词，后接名词、代词或动名词；get 强调逐渐适应的过程。","example":"We have got quite used to them.","exampleZh":"我们已经相当习惯它们了。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"in response to","matchedForm":"in response to","meaning":"响应，随着……而反应","note":"既可用于对问题作出回应，也可描述事物受外界刺激而变化。","example":"Oddly shaped forms that are suspended from the ceiling and move in response to a gust of wind are quite familiar to everybody.","exampleZh":"那些吊在天花板上、随一阵风而动的奇特造型，大家都很熟悉。","sourceParagraphIndex":1,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"on and off","matchedForm":"on and off","meaning":"时开时关，忽明忽灭","note":"在本句修饰 flash，表示灯反复亮灭；也可指某活动断断续续。","example":"Sparks were emitted from small black boxes and red lamps flashed on and off angrily.","exampleZh":"小黑盒子里迸出火花，红灯气势汹汹地忽明忽灭。","sourceParagraphIndex":1,"sourceSentenceIndex":10,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l019","book":3,"number":19,"title":"A very dear cat","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Kidnappers are rarely interested in animals, but they recently took considerable interest in Mrs. Eleanor Ramsay’s cat.","zh":"绑架者很少对动物感兴趣，可最近他们却对埃莉诺·拉姆齐太太的猫产生了浓厚兴趣。","kind":"narration","speaker":"旁白"},{"en":"Mrs. Eleanor Ramsay, a very wealthy old lady, has shared a flat with her cat, Rastus, for a great many years.","zh":"埃莉诺·拉姆齐太太是位十分富有的老太太，多年来一直和她的猫拉斯特斯同住一套公寓。","kind":"narration","speaker":"旁白"},{"en":"Rastus leads an orderly life.","zh":"拉斯特斯的生活很有规律。","kind":"narration","speaker":"旁白"},{"en":"He usually takes a short walk in the evenings and is always home by seven o’clock.","zh":"他通常傍晚出去散步一小会儿，最迟七点就会回到家。","kind":"narration","speaker":"旁白"},{"en":"One evening, however, he failed to arrive.","zh":"然而，有一天晚上，他没有回来。","kind":"narration","speaker":"旁白"},{"en":"Mrs. Ramsay got very worried.","zh":"拉姆齐太太十分担心。","kind":"narration","speaker":"旁白"},{"en":"She looked everywhere for him but could not find him.","zh":"她到处寻找，却怎么也找不到他。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Three days after Rastus’ disappearance, Mrs. Ramsay received an anonymous letter.","zh":"拉斯特斯失踪三天后，拉姆齐太太收到了一封匿名信。","kind":"narration","speaker":"旁白"},{"en":"The writer stated that Rastus was in safe hands and would be returned immediately if Mrs. Ramsay paid a ransom of £1,000.","zh":"写信的人声称，拉斯特斯正受到妥善照顾，只要拉姆齐太太付一千英镑赎金，就马上把他送回来。","kind":"narration","speaker":"旁白"},{"en":"Mrs. Ramsay was instructed to place the money in a cardboard box and to leave it outside her door.","zh":"信中要求拉姆齐太太把钱放进一个纸板盒，留在自家门外。","kind":"narration","speaker":"旁白"},{"en":"At first, she decided to go to the police, but fearing that she would never see Rastus again—the letter had made that quite clear—she changed her mind.","zh":"起初，她决定去报警，可又担心再也见不到拉斯特斯——信里已把这一点说得很清楚——于是改变了主意。","kind":"narration","speaker":"旁白"},{"en":"She withdrew £1,000 from her bank and followed the kidnapper’s instructions.","zh":"她从银行取出一千英镑，照绑架者的指示做了。","kind":"narration","speaker":"旁白"},{"en":"The next morning, the box had disappeared but Mrs. Ramsay was sure that the kidnapper would keep his word.","zh":"第二天早晨，盒子不见了，但拉姆齐太太相信绑架者会信守诺言。","kind":"narration","speaker":"旁白"},{"en":"Sure enough, Rastus arrived punctually at seven o'clock that evening.","zh":"果然，那天晚上七点，拉斯特斯准时回来了。","kind":"narration","speaker":"旁白"},{"en":"He looked very well, though he was rather thirsty, for he drank half a bottle of milk.","zh":"他看起来很好，不过相当口渴，因为他喝了半瓶牛奶。","kind":"narration","speaker":"旁白"},{"en":"The police were astounded when Mrs. Ramsay told them what she had done.","zh":"拉姆齐太太把自己的做法告诉警方时，警察们大为震惊。","kind":"narration","speaker":"旁白"},{"en":"She explained that Rastus was very dear to her.","zh":"她解释说，拉斯特斯对她而言非常珍贵。","kind":"narration","speaker":"旁白"},{"en":"Considering the amount she paid, he was dear in more ways than one!","zh":"想想她付出的那笔钱，他的“贵”可不止一层意思！","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"a great many","matchedForm":"a great many","meaning":"很多，大量","note":"后接可数名词复数；若接不可数名词，通常用 a great deal of。","example":"Mrs. Eleanor Ramsay, a very wealthy old lady, has shared a flat with her cat, Rastus, for a great many years.","exampleZh":"埃莉诺·拉姆齐太太是位十分富有的老太太，多年来一直和她的猫拉斯特斯同住一套公寓。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"lead an orderly life","matchedForm":"leads an orderly life","meaning":"过有规律的生活","note":"lead a ... life 表示过着某种生活，形容词用于说明生活状态。","example":"Rastus leads an orderly life.","exampleZh":"拉斯特斯的生活很有规律。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"in safe hands","matchedForm":"in safe hands","meaning":"受到可靠照料","note":"强调由可信赖的人照管；本句只是匿名信中的声称。","example":"The writer stated that Rastus was in safe hands and would be returned immediately if Mrs. Ramsay paid a ransom of £1,000.","exampleZh":"写信的人声称，拉斯特斯正受到妥善照顾，只要拉姆齐太太付一千英镑赎金，就马上把他送回来。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"keep one’s word","matchedForm":"keep his word","meaning":"信守诺言","note":"word 在此指承诺，通常用单数，不说 keep one’s words 表达同一习语。","example":"The next morning, the box had disappeared but Mrs. Ramsay was sure that the kidnapper would keep his word.","exampleZh":"第二天早晨，盒子不见了，但拉姆齐太太相信绑架者会信守诺言。","sourceParagraphIndex":1,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"sure enough","matchedForm":"Sure enough","meaning":"果然","note":"用来引出实际发生且印证此前预期的结果。","example":"Sure enough, Rastus arrived punctually at seven o'clock that evening.","exampleZh":"果然，那天晚上七点，拉斯特斯准时回来了。","sourceParagraphIndex":1,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"in more ways than one","matchedForm":"in more ways than one","meaning":"不止在一个方面","note":"本课利用 dear 的双关，既指珍爱，也指花费昂贵。","example":"Considering the amount she paid, he was dear in more ways than one!","exampleZh":"想想她付出的那笔钱，他的“贵”可不止一层意思！","sourceParagraphIndex":1,"sourceSentenceIndex":10,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l020","book":3,"number":20,"title":"Pioneer pilots","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"In 1908 Lord Northcliffe offered a prize of £1,000 to the first man who would fly across the English Channel.","zh":"一九〇八年，诺思克利夫勋爵悬赏一千英镑，奖给第一个驾机飞越英吉利海峡的人。","kind":"narration","speaker":"旁白"},{"en":"Over a year passed before the first attempt was made.","zh":"一年多过去后，才有人进行首次尝试。","kind":"narration","speaker":"旁白"},{"en":"On July 19th, 1909, in the early morning, Hubert Latham took off from the French coast in his plane the ‘Antoinette IV’.","zh":"一九〇九年七月十九日清晨，休伯特·莱瑟姆驾驶“安托瓦内特四号”飞机从法国海岸起飞。","kind":"narration","speaker":"旁白"},{"en":"He had travelled only seven miles across the Channel when his engine failed and he was forced to land on the sea.","zh":"他在海峡上空才飞了七英里，发动机就出了故障，被迫在海上降落。","kind":"narration","speaker":"旁白"},{"en":"The ‘Antoinette’ floated on the water until Latham was picked up by a ship.","zh":"“安托瓦内特号”一直浮在水面上，直到一艘船把莱瑟姆救起。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Two days later, Louis Bleriot arrived near Calais with a plane called ‘No. XI’.","zh":"两天后，路易·布莱里奥带着一架名叫“十一号”的飞机，来到加来附近。","kind":"narration","speaker":"旁白"},{"en":"Bleriot had been making planes since 1905 and this was his latest model.","zh":"布莱里奥从一九〇五年起就一直制造飞机，这架是他的最新机型。","kind":"narration","speaker":"旁白"},{"en":"A week before, he had completed a successful overland flight during which he covered twenty-six miles.","zh":"一周前，他成功完成了一次陆上飞行，飞越了二十六英里。","kind":"narration","speaker":"旁白"},{"en":"Latham, however, did not give up easily.","zh":"然而，莱瑟姆并没有轻易放弃。","kind":"narration","speaker":"旁白"},{"en":"He, too, arrived near Calais on the same day with a new ‘Antoinette’.","zh":"同一天，他也带着一架新的“安托瓦内特号”来到加来附近。","kind":"narration","speaker":"旁白"},{"en":"It looked as if there would be an exciting race across the Channel.","zh":"看来，一场激动人心的飞越海峡比赛即将展开。","kind":"narration","speaker":"旁白"},{"en":"Both planes were going to take off on July 25th, but Latham failed to get up early enough.","zh":"两架飞机原定七月二十五日起飞，但莱瑟姆没能起得足够早。","kind":"narration","speaker":"旁白"},{"en":"After making a short test flight at 4.15 a.m., Bleriot set off half an hour later.","zh":"凌晨四点十五分，布莱里奥作了一次短暂试飞，半小时后正式出发。","kind":"narration","speaker":"旁白"},{"en":"His great flight lasted thirty-seven minutes.","zh":"他这次伟大的飞行持续了三十七分钟。","kind":"narration","speaker":"旁白"},{"en":"When he landed near Dover, the first person to greet him was a local policeman.","zh":"他在多佛附近降落时，第一个前来迎接他的人是一名当地警察。","kind":"narration","speaker":"旁白"},{"en":"Latham made another attempt a week later and got within half a mile of Dover, but he was unlucky again.","zh":"一周后，莱瑟姆再次尝试，飞到了距离多佛不到半英里的地方，可他又一次遭遇了不幸。","kind":"narration","speaker":"旁白"},{"en":"His engine failed and he landed on the sea for the second time.","zh":"他的发动机出了故障，第二次降落在海上。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"take off","matchedForm":"took off","meaning":"起飞","note":"用于飞机离开地面；还可表示脱下衣物，需根据宾语和语境区分。","example":"On July 19th, 1909, in the early morning, Hubert Latham took off from the French coast in his plane the ‘Antoinette IV’.","exampleZh":"一九〇九年七月十九日清晨，休伯特·莱瑟姆驾驶“安托瓦内特四号”飞机从法国海岸起飞。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"be forced to","matchedForm":"forced to","meaning":"被迫做某事","note":"表示情势或外力使人不得不行动，后接动词原形。","example":"He had travelled only seven miles across the Channel when his engine failed and he was forced to land on the sea.","exampleZh":"他在海峡上空才飞了七英里，发动机就出了故障，被迫在海上降落。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"pick up","matchedForm":"picked up","meaning":"接走，搭救","note":"本句指船从水中救人；被动语态下救助者由 by 引出。","example":"The ‘Antoinette’ floated on the water until Latham was picked up by a ship.","exampleZh":"“安托瓦内特号”一直浮在水面上，直到一艘船把莱瑟姆救起。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"give up","matchedForm":"give up","meaning":"放弃","note":"可单独使用，也可后接名词或动名词；不直接接 to do 表示停止做某事。","example":"Latham, however, did not give up easily.","exampleZh":"然而，莱瑟姆并没有轻易放弃。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"look as if","matchedForm":"looked as if","meaning":"看起来好像","note":"as if 引导表语从句，可根据真实可能性使用相应时态。","example":"It looked as if there would be an exciting race across the Channel.","exampleZh":"看来，一场激动人心的飞越海峡比赛即将展开。","sourceParagraphIndex":1,"sourceSentenceIndex":5,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l021","book":3,"number":21,"title":"Daniel Mendoza","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Boxing matches were very popular in England two hundred years ago.","zh":"两百年前，拳击比赛在英国很受欢迎。","kind":"narration","speaker":"旁白"},{"en":"In those days, boxers fought with bare fists for prize money.","zh":"那时，拳手们赤手空拳地比赛，以争取奖金。","kind":"narration","speaker":"旁白"},{"en":"Because of this, they were known as ‘prizefighters’.","zh":"因此，他们被称为“职业奖金拳手”。","kind":"narration","speaker":"旁白"},{"en":"However, boxing was very crude, for there were no rules and a prizefighter could be seriously injured or even killed during a match.","zh":"不过，当时的拳击十分野蛮，因为没有规则，拳手在比赛中可能严重受伤，甚至丧命。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"One of the most colourful figures in boxing history was Daniel Mendoza, who was born in 1764.","zh":"拳击史上最富传奇色彩的人物之一，是生于一七六四年的丹尼尔·门多萨。","kind":"narration","speaker":"旁白"},{"en":"The use of gloves was not introduced until 1860, when the Marquis of Queensberry drew up the first set of rules.","zh":"直到一八六〇年，昆斯伯里侯爵拟定第一套规则时，拳击才开始采用拳套。","kind":"narration","speaker":"旁白"},{"en":"Though he was technically a prizefighter, Mendoza did much to change crude prizefighting into a sport, for he brought science to the game.","zh":"严格说来，门多萨也是一名以奖金为生的拳手，但他把科学方法引入拳击，为把野蛮的职业拳赛变成一项体育运动作出了很大贡献。","kind":"narration","speaker":"旁白"},{"en":"In his day, Mendoza enjoyed tremendous popularity.","zh":"在他那个时代，门多萨极受欢迎。","kind":"narration","speaker":"旁白"},{"en":"He was adored by rich and poor alike.","zh":"无论贫富，人们都很崇拜他。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"Mendoza rose to fame swiftly after a boxing match when he was only fourteen years old.","zh":"门多萨年仅十四岁时，在一场拳击比赛后迅速成名。","kind":"narration","speaker":"旁白"},{"en":"This attracted the attention of Richard Humphries who was then the most eminent boxer in England.","zh":"这引起了理查德·汉弗莱斯的注意，他当时是英国最杰出的拳手。","kind":"narration","speaker":"旁白"},{"en":"He offered to train Mendoza and his young pupil was quick to learn.","zh":"他提出训练门多萨，而这名年轻弟子学得很快。","kind":"narration","speaker":"旁白"},{"en":"In fact, Mendoza soon became so successful that Humphries turned against him.","zh":"事实上，门多萨很快就大获成功，以至汉弗莱斯反而与他为敌。","kind":"narration","speaker":"旁白"},{"en":"The two men quarrelled bitterly and it was clear that the argument could only be settled by a fight.","zh":"两人激烈争吵，显然这场争执只能靠打一场来解决。","kind":"narration","speaker":"旁白"},{"en":"A match was held at Stilton, where both men fought for an hour.","zh":"比赛在斯蒂尔顿举行，两人打了一个小时。","kind":"narration","speaker":"旁白"},{"en":"The public bet a great deal of money on Mendoza, but he was defeated.","zh":"公众把大笔赌注押在门多萨身上，可他却输了。","kind":"narration","speaker":"旁白"},{"en":"Mendoza met Humphries in the ring on a later occasion and he lost for a second time.","zh":"后来，门多萨又一次在拳台上迎战汉弗莱斯，第二次落败。","kind":"narration","speaker":"旁白"},{"en":"It was not until his third match in 1790 that he finally beat Humphries and became Champion of England.","zh":"直到一七九〇年的第三次交手，他才终于击败汉弗莱斯，成为英国拳击冠军。","kind":"narration","speaker":"旁白"},{"en":"Meanwhile, he founded a highly successful Academy and even Lord Byron became one of his pupils.","zh":"与此同时，他创办了一所极为成功的拳击学校，就连拜伦勋爵也成了他的学生。","kind":"narration","speaker":"旁白"},{"en":"He earned enormous sums of money and was paid as much as £100 for a single appearance.","zh":"他赚了大笔钱财，单次出场的报酬就高达一百英镑。","kind":"narration","speaker":"旁白"},{"en":"Despite this, he was so extravagant that he was always in debt.","zh":"尽管如此，他挥霍无度，始终债台高筑。","kind":"narration","speaker":"旁白"},{"en":"After he was defeated by a boxer called Gentleman Jackson, he was quickly forgotten.","zh":"被一个叫“绅士杰克逊”的拳手击败后，他很快就被人遗忘了。","kind":"narration","speaker":"旁白"},{"en":"He was sent to prison for failing to pay his debts and died in poverty in 1836.","zh":"他因无力偿还债务而入狱，一八三六年在贫困中死去。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"with bare fists","matchedForm":"with bare fists","meaning":"赤手空拳","note":"bare 表示没有遮盖，fists 指拳头；文中与后来使用拳套相对。","example":"In those days, boxers fought with bare fists for prize money.","exampleZh":"那时，拳手们赤手空拳地比赛，以争取奖金。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"draw up","matchedForm":"drew up","meaning":"拟定，起草","note":"常用于规则、合同、计划等正式文件，过去式 draw 变为 drew。","example":"The use of gloves was not introduced until 1860, when the Marquis of Queensberry drew up the first set of rules.","exampleZh":"直到一八六〇年，昆斯伯里侯爵拟定第一套规则时，拳击才开始采用拳套。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"rise to fame","matchedForm":"rose to fame","meaning":"成名，声名鹊起","note":"rise 在这里是不及物动词，过去式为 rose，不要与及物动词 raise 混用。","example":"Mendoza rose to fame swiftly after a boxing match when he was only fourteen years old.","exampleZh":"门多萨年仅十四岁时，在一场拳击比赛后迅速成名。","sourceParagraphIndex":2,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"turn against","matchedForm":"turned against","meaning":"转而反对，与……为敌","note":"表示态度由支持或友好转为敌对，against 后接对象。","example":"In fact, Mendoza soon became so successful that Humphries turned against him.","exampleZh":"事实上，门多萨很快就大获成功，以至汉弗莱斯反而与他为敌。","sourceParagraphIndex":2,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"in debt","matchedForm":"in debt","meaning":"负债","note":"be in debt 表示欠债状态，get into debt 强调开始负债。","example":"Despite this, he was so extravagant that he was always in debt.","exampleZh":"尽管如此，他挥霍无度，始终债台高筑。","sourceParagraphIndex":2,"sourceSentenceIndex":11,"sourceType":"textbook-passage"},{"phrase":"in poverty","matchedForm":"in poverty","meaning":"处于贫困之中","note":"poverty 为不可数名词；die in poverty 指在贫困中死去。","example":"He was sent to prison for failing to pay his debts and died in poverty in 1836.","exampleZh":"他因无力偿还债务而入狱，一八三六年在贫困中死去。","sourceParagraphIndex":2,"sourceSentenceIndex":13,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l022","book":3,"number":22,"title":"By heart","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Some plays are so successful that they run for years on end.","zh":"有些戏剧十分成功，连演多年不衰。","kind":"narration","speaker":"旁白"},{"en":"In many ways, this is unfortunate for the poor actors who are required to go on repeating the same lines night after night.","zh":"从许多方面看，这对可怜的演员们并不幸运，因为他们得一夜又一夜地不断重复同样的台词。","kind":"narration","speaker":"旁白"},{"en":"One would expect them to know their parts by heart and never have cause to falter.","zh":"按理说，人们会以为他们早已把自己的戏份背得滚瓜烂熟，绝不会有说不下去的时候。","kind":"narration","speaker":"旁白"},{"en":"Yet this is not always the case.","zh":"然而，情况并非总是如此。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"A famous actor in a highly successful play was once cast in the role of an aristocrat who had been imprisoned in the Bastille for twenty years.","zh":"有一次，在一部极受欢迎的戏里，一位名演员被选中扮演一名在巴士底狱关押了二十年的贵族。","kind":"narration","speaker":"旁白"},{"en":"In the last act, a gaoler would always come on to the stage with a letter which he would hand to the prisoner.","zh":"到最后一幕，总有一个狱卒拿着一封信上台，把信交给囚犯。","kind":"narration","speaker":"旁白"},{"en":"Even though the noble was expected to read the letter at each performance, he always insisted that it should be written out in full.","zh":"虽然这位贵族每场演出都得读这封信，他却坚持要求把信的全文写出来。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"One night, the gaoler decided to play a joke on his colleague to find out if, after so many performances, he had managed to learn the contents of the letter by heart.","zh":"一天晚上，狱卒决定跟同事开个玩笑，看看演了这么多场以后，他究竟有没有把信的内容背下来。","kind":"narration","speaker":"旁白"},{"en":"The curtain went up on the final act of the play and revealed the aristocrat sitting alone behind bars in his dark cell.","zh":"最后一幕的帷幕拉开，观众看见贵族独自坐在昏暗牢房的铁栏后面。","kind":"narration","speaker":"旁白"},{"en":"Just then, the gaoler appeared with the precious letter in his hands.","zh":"就在这时，狱卒手里拿着那封宝贵的信出现了。","kind":"narration","speaker":"旁白"},{"en":"He entered the cell and presented the letter to the aristocrat.","zh":"他走进牢房，把信递给贵族。","kind":"narration","speaker":"旁白"},{"en":"But the copy he gave him had not been written out in full as usual.","zh":"可他这次交出的信，并没有像往常一样写出全文。","kind":"narration","speaker":"旁白"},{"en":"It was simply a blank sheet of paper.","zh":"那只是一张白纸。","kind":"narration","speaker":"旁白"},{"en":"The gaoler looked on eagerly, anxious to see if his fellow actor had at last learnt his lines.","zh":"狱卒急切地在旁观看，想知道这位搭档到底有没有记住自己的台词。","kind":"narration","speaker":"旁白"},{"en":"The noble stared at the blank sheet of paper for a few seconds.","zh":"贵族盯着白纸看了几秒钟。","kind":"narration","speaker":"旁白"},{"en":"Then, squinting his eyes, he said: ‘The light is dim.","zh":"接着，他眯起眼睛说：“光线太暗了。","kind":"speech","speaker":"扮演贵族的演员"},{"en":"Read the letter to me.’","zh":"把信念给我听。”","kind":"speech","speaker":"扮演贵族的演员"},{"en":"And he promptly handed the sheet of paper to the gaoler.","zh":"说着，他立即把那张纸递给了狱卒。","kind":"narration","speaker":"旁白"},{"en":"Finding that he could not remember a word of the letter either, the gaoler replied: ‘The light is indeed dim, sire.","zh":"狱卒发现自己也记不起信里的一个字，便回答：“光线确实很暗，大人。","kind":"speech","speaker":"扮演狱卒的演员"},{"en":"I must get my glasses.’","zh":"我得去拿眼镜。”","kind":"speech","speaker":"扮演狱卒的演员"},{"en":"With this, he hurried off the stage.","zh":"说完，他匆匆离开了舞台。","kind":"narration","speaker":"旁白"},{"en":"Much to the aristocrat’s amusement, the gaoler returned a few moments later with a pair of glasses and the usual copy of the letter which he proceeded to read to the prisoner.","zh":"让那位贵族大觉好笑的是，片刻后，狱卒拿着一副眼镜和往常那封信回来了，随即开始给囚犯念信。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"for years on end","matchedForm":"for years on end","meaning":"连续多年","note":"on end 表示连续不断地持续一段时间，前面常接 hours、days、years 等。","example":"Some plays are so successful that they run for years on end.","exampleZh":"有些戏剧十分成功，连演多年不衰。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"by heart","matchedForm":"by heart","meaning":"熟记在心，凭记忆","note":"learn 或 know something by heart 表示能够不看原文而记住或复述。","example":"One would expect them to know their parts by heart and never have cause to falter.","exampleZh":"按理说，人们会以为他们早已把自己的戏份背得滚瓜烂熟，绝不会有说不下去的时候。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"be the case","matchedForm":"is not always the case","meaning":"情况是如此","note":"the case 指实际情况，not always 是并非总是，并非完全否定。","example":"Yet this is not always the case.","exampleZh":"然而，情况并非总是如此。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"in full","matchedForm":"in full","meaning":"完整地，全文地","note":"可用于文字、付款等，强调全部而无省略。","example":"Even though the noble was expected to read the letter at each performance, he always insisted that it should be written out in full.","exampleZh":"虽然这位贵族每场演出都得读这封信，他却坚持要求把信的全文写出来。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"play a joke on","matchedForm":"play a joke on","meaning":"跟……开玩笑，戏弄","note":"on 后接被戏弄的人；不说 play a joke to somebody。","example":"One night, the gaoler decided to play a joke on his colleague to find out if, after so many performances, he had managed to learn the contents of the letter by heart.","exampleZh":"一天晚上，狱卒决定跟同事开个玩笑，看看演了这么多场以后，他究竟有没有把信的内容背下来。","sourceParagraphIndex":2,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"look on","matchedForm":"looked on","meaning":"旁观","note":"on 在此是副词；若要引出观看的事件，可另加介词结构。","example":"The gaoler looked on eagerly, anxious to see if his fellow actor had at last learnt his lines.","exampleZh":"狱卒急切地在旁观看，想知道这位搭档到底有没有记住自己的台词。","sourceParagraphIndex":2,"sourceSentenceIndex":6,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l023","book":3,"number":23,"title":"One man’s meat is another man’s poison","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"People become quite illogical when they try to decide what can be eaten and what cannot be eaten.","zh":"人们一旦试着判断什么能吃、什么不能吃，就会变得十分不讲道理。","kind":"narration","speaker":"旁白"},{"en":"If you lived in the Mediterranean, for instance, you would consider octopus a great delicacy.","zh":"例如，如果你生活在地中海地区，就会把章鱼视为一道美味佳肴。","kind":"narration","speaker":"旁白"},{"en":"You would not be able to understand why some people find it repulsive.","zh":"你会无法理解，为什么有人会觉得它令人作呕。","kind":"narration","speaker":"旁白"},{"en":"On the other hand, your stomach would turn at the idea of frying potatoes in animal fat—the normally accepted practice in many northern countries.","zh":"反过来，一想到用动物油脂炸土豆，你就会反胃，然而在许多北方国家，这却是通常被接受的做法。","kind":"narration","speaker":"旁白"},{"en":"The sad truth is that most of us have been brought up to eat certain foods and we stick to them all our lives.","zh":"令人遗憾的事实是，我们大多数人从小被培养着吃某些食物，此后一辈子都不肯改变。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"No creature has received more praise and abuse than the common garden snail.","zh":"没有哪种生物像常见的花园蜗牛这样，既受到如此多的赞美，又遭到如此多的嫌恶。","kind":"narration","speaker":"旁白"},{"en":"Cooked in wine, snails are a great luxury in various parts of the world.","zh":"在世界上的许多地方，用葡萄酒烹制的蜗牛是一道奢侈佳肴。","kind":"narration","speaker":"旁白"},{"en":"There are countless people who, ever since their early years, have learned to associate snails with food.","zh":"无数人从小就学会把蜗牛和食物联系起来。","kind":"narration","speaker":"旁白"},{"en":"My friend, Robert, lives in a country where snails are despised.","zh":"我的朋友罗伯特住在一个人们厌恶蜗牛的国家。","kind":"narration","speaker":"旁白"},{"en":"As his flat is in a large town, he has no garden of his own.","zh":"他的公寓位于一座大城市里，所以没有自己的花园。","kind":"narration","speaker":"旁白"},{"en":"For years he has been asking me to collect snails from my garden and take them to him.","zh":"多年来，他一直请我从花园里捉些蜗牛带给他。","kind":"narration","speaker":"旁白"},{"en":"The idea never appealed to me very much, but one day, after a heavy shower, I happened to be walking in my garden when I noticed a huge number of snails taking a stroll on some of my prize plants.","zh":"这个主意从来都不太吸引我；不过，有一天，一场大阵雨过后，我正好在花园里散步，发现许多蜗牛正悠然爬过我那些珍爱的花木。","kind":"narration","speaker":"旁白"},{"en":"Acting on a sudden impulse, I collected several dozen, put them in a paper bag, and took them to Robert.","zh":"一时冲动之下，我捉了几十只，装进纸袋，带去给罗伯特。","kind":"narration","speaker":"旁白"},{"en":"Robert was delighted to see me and equally pleased with my little gift.","zh":"罗伯特见到我非常高兴，对这份小礼物也同样喜欢。","kind":"narration","speaker":"旁白"},{"en":"I left the bag in the hall and Robert and I went into the living room where we talked for a couple of hours.","zh":"我把纸袋放在门厅，然后和罗伯特进了客厅，在那里聊了几个小时。","kind":"narration","speaker":"旁白"},{"en":"I had forgotten all about the snails when Robert suddenly said that I must stay to dinner.","zh":"我早把蜗牛忘得一干二净，这时罗伯特突然说，我一定得留下来吃晚饭。","kind":"narration","speaker":"旁白"},{"en":"Snails would, of course, be the main dish.","zh":"当然，主菜会是蜗牛。","kind":"narration","speaker":"旁白"},{"en":"I did not fancy the idea and I reluctantly followed Robert out of the room.","zh":"我并不喜欢这个主意，却还是不情愿地跟着罗伯特走出房间。","kind":"narration","speaker":"旁白"},{"en":"To our dismay, we saw that there were snails everywhere: they had escaped from the paper bag and had taken complete possession of the hall!","zh":"令我们沮丧的是，眼前到处都是蜗牛：它们从纸袋里逃了出来，把门厅完全占领了！","kind":"narration","speaker":"旁白"},{"en":"I have never been able to look at a snail since then.","zh":"从那以后，我再也没法正眼看一只蜗牛了。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"at the idea of","matchedForm":"at the idea of","meaning":"一想到……就……","note":"at 表示引起反应的原因，of 后接名词或动名词。","example":"On the other hand, your stomach would turn at the idea of frying potatoes in animal fat—the normally accepted practice in many northern countries.","exampleZh":"反过来，一想到用动物油脂炸土豆，你就会反胃，然而在许多北方国家，这却是通常被接受的做法。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"stick to","matchedForm":"stick to","meaning":"坚持，不改变","note":"to 是介词，后接所坚持的习惯、计划等；这里指不改变从小的饮食习惯。","example":"The sad truth is that most of us have been brought up to eat certain foods and we stick to them all our lives.","exampleZh":"令人遗憾的事实是，我们大多数人从小被培养着吃某些食物，此后一辈子都不肯改变。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"associate ... with","matchedForm":"associate snails with food","meaning":"把……与……联系起来","note":"associate A with B 表示在认识中建立两者的联系。","example":"There are countless people who, ever since their early years, have learned to associate snails with food.","exampleZh":"无数人从小就学会把蜗牛和食物联系起来。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"appeal to","matchedForm":"appealed to","meaning":"吸引，使感兴趣","note":"表示某事物对某人有吸引力，通常以事物为主语。","example":"The idea never appealed to me very much, but one day, after a heavy shower, I happened to be walking in my garden when I noticed a huge number of snails taking a stroll on some of my prize plants.","exampleZh":"这个主意从来都不太吸引我；不过，有一天，一场大阵雨过后，我正好在花园里散步，发现许多蜗牛正悠然爬过我那些珍爱的花木。","sourceParagraphIndex":1,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"on a sudden impulse","matchedForm":"on a sudden impulse","meaning":"一时冲动之下","note":"impulse 指未经充分思考的突然念头，on 表示受其驱动。","example":"Acting on a sudden impulse, I collected several dozen, put them in a paper bag, and took them to Robert.","exampleZh":"一时冲动之下，我捉了几十只，装进纸袋，带去给罗伯特。","sourceParagraphIndex":1,"sourceSentenceIndex":7,"sourceType":"textbook-passage"},{"phrase":"take possession of","matchedForm":"taken complete possession of","meaning":"占据，控制","note":"possession 前可加 complete 等修饰词；本文把蜗牛写得像占领者，带幽默意味。","example":"To our dismay, we saw that there were snails everywhere: they had escaped from the paper bag and had taken complete possession of the hall!","exampleZh":"令我们沮丧的是，眼前到处都是蜗牛：它们从纸袋里逃了出来，把门厅完全占领了！","sourceParagraphIndex":1,"sourceSentenceIndex":13,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l024","book":3,"number":24,"title":"A skeleton in the cupboard","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"We often read in novels how a seemingly respectable person or family has some terrible secret which has been concealed from strangers for years.","zh":"我们常在小说里读到：一个表面上体面的人或家庭，竟有一个多年来一直向外人隐瞒的可怕秘密。","kind":"narration","speaker":"旁白"},{"en":"The English language possesses a vivid saying to describe this sort of situation.","zh":"英语里有一句生动的说法，用来形容这种情况。","kind":"narration","speaker":"旁白"},{"en":"The terrible secret is called ‘a skeleton in the cupboard’.","zh":"这个可怕的秘密叫作“壁橱里的骷髅”。","kind":"narration","speaker":"旁白"},{"en":"At some dramatic moment in the story, the terrible secret becomes known and a reputation is ruined.","zh":"故事发展到某个戏剧性时刻，秘密被揭开，某个人的名声也就毁了。","kind":"narration","speaker":"旁白"},{"en":"The reader’s hair stands on end when he reads in the final pages of the novel that the heroine, a dear old lady who had always been so kind to everybody, had, in her youth, poisoned every one of her five husbands.","zh":"当读者在小说最后几页读到，那位始终对人人都很和善、令人喜爱的老太太主人公，年轻时竟把自己的五任丈夫一一毒死时，便会毛骨悚然。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"It is all very well for such things to occur in fiction.","zh":"这种事发生在小说里倒也罢了。","kind":"narration","speaker":"旁白"},{"en":"To varying degrees, we all have secrets which we do not want even our closest friends to learn, but few of us have skeletons in the cupboard.","zh":"我们每个人都多少有些连最亲密的朋友也不想让其知道的秘密，但真正藏有见不得人丑事的，却没有几个。","kind":"narration","speaker":"旁白"},{"en":"The only person I know who has a skeleton in the cupboard is George Carlton, and he is very proud of the fact.","zh":"我认识的人里，唯一在壁橱里藏着骷髅的是乔治·卡尔顿，而且他对此颇为自豪。","kind":"narration","speaker":"旁白"},{"en":"George studied medicine in his youth.","zh":"乔治年轻时学过医。","kind":"narration","speaker":"旁白"},{"en":"Instead of becoming a doctor, however, he became a successful writer of detective stories.","zh":"然而，他没有成为医生，倒成了一名成功的侦探小说作家。","kind":"narration","speaker":"旁白"},{"en":"I once spent an uncomfortable weekend which I shall never forget at his house.","zh":"有一次，我在他家度过了一个令人不安、永生难忘的周末。","kind":"narration","speaker":"旁白"},{"en":"George showed me to the guestroom which, he said, was rarely used.","zh":"乔治领我去客房，说那间房很少使用。","kind":"narration","speaker":"旁白"},{"en":"He told me to unpack my things and then come down to dinner.","zh":"他让我把东西拿出来放好，然后下楼吃晚饭。","kind":"narration","speaker":"旁白"},{"en":"After I had stacked my shirts and underclothes in two empty drawers, I decided to hang one of the two suits I had brought with me in the cupboard.","zh":"我把衬衫和内衣叠放进两个空抽屉后，决定把随身带来的两套西装中的一套挂进壁橱。","kind":"narration","speaker":"旁白"},{"en":"I opened the cupboard door and then stood in front of it petrified.","zh":"我打开橱门，随后站在门前，吓得动弹不得。","kind":"narration","speaker":"旁白"},{"en":"A skeleton was dangling before my eyes.","zh":"一具骷髅正吊在我眼前。","kind":"narration","speaker":"旁白"},{"en":"The sudden movement of the door made it sway slightly and it gave me the impression that it was about to leap out at me.","zh":"猛然开门使它轻轻晃动，让我觉得它就要朝我扑出来。","kind":"narration","speaker":"旁白"},{"en":"Dropping my suit, I dashed downstairs to tell George.","zh":"我扔下西装，冲到楼下去告诉乔治。","kind":"narration","speaker":"旁白"},{"en":"This was worse than ‘a terrible secret’; this was a real skeleton!","zh":"这比“可怕的秘密”还要糟：这是一具真的骷髅！","kind":"narration","speaker":"旁白"},{"en":"But George was unsympathetic.","zh":"可是，乔治却毫不体谅。","kind":"narration","speaker":"旁白"},{"en":"‘Oh, that,’ he said with a smile as if he were talking about an old friend.","zh":"“哦，那个呀，”他笑着说，好像在谈一位老朋友。","kind":"speech","speaker":"乔治·卡尔顿"},{"en":"‘That's Sebastian.","zh":"“那是塞巴斯蒂安。","kind":"speech","speaker":"乔治·卡尔顿"},{"en":"You forget that I was a medical student once upon a time.’","zh":"你忘了，我从前可是一名医学生。”","kind":"speech","speaker":"乔治·卡尔顿"}]}],"usage":[{"phrase":"a skeleton in the cupboard","matchedForm":"a skeleton in the cupboard","meaning":"不可告人的家丑或秘密","note":"英国英语习语；美国英语也常说 a skeleton in the closet。本课后来又按字面写真的骷髅。","example":"The terrible secret is called ‘a skeleton in the cupboard’.","exampleZh":"这个可怕的秘密叫作“壁橱里的骷髅”。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"one’s hair stands on end","matchedForm":"hair stands on end","meaning":"某人毛骨悚然","note":"形容极度恐惧或惊骇，不必理解为头发真的全部竖起来。","example":"The reader’s hair stands on end when he reads in the final pages of the novel that the heroine, a dear old lady who had always been so kind to everybody, had, in her youth, poisoned every one of her five husbands.","exampleZh":"当读者在小说最后几页读到，那位始终对人人都很和善、令人喜爱的老太太主人公，年轻时竟把自己的五任丈夫一一毒死时，便会毛骨悚然。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"to varying degrees","matchedForm":"To varying degrees","meaning":"程度不同地","note":"用于说明情况普遍存在，但各人或各事物的程度不一样。","example":"To varying degrees, we all have secrets which we do not want even our closest friends to learn, but few of us have skeletons in the cupboard.","exampleZh":"我们每个人都多少有些连最亲密的朋友也不想让其知道的秘密，但真正藏有见不得人丑事的，却没有几个。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"be about to","matchedForm":"was about to","meaning":"即将，马上要","note":"后接动词原形，强调眼看就要发生，不宜与明确的较远将来时间搭配。","example":"The sudden movement of the door made it sway slightly and it gave me the impression that it was about to leap out at me.","exampleZh":"猛然开门使它轻轻晃动，让我觉得它就要朝我扑出来。","sourceParagraphIndex":1,"sourceSentenceIndex":11,"sourceType":"textbook-passage"},{"phrase":"once upon a time","matchedForm":"once upon a time","meaning":"从前，曾经","note":"常见于故事开头，本文在谈话中诙谐地指自己当医学生的过去。","example":"You forget that I was a medical student once upon a time.’","exampleZh":"你忘了，我从前可是一名医学生。”","sourceParagraphIndex":1,"sourceSentenceIndex":17,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l025","book":3,"number":25,"title":"The Cutty Sark","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"One of the most famous sailing ships of the nineteenth century, the Cutty Sark, can still be seen at Greenwich.","zh":"十九世纪最著名的帆船之一“卡蒂萨克号”，如今仍可在格林尼治看到。","kind":"narration","speaker":"旁白"},{"en":"She stands on dry land and is visited by thousands of people each year.","zh":"它安置在陆地上，每年有成千上万的人前来参观。","kind":"narration","speaker":"旁白"},{"en":"She serves as an impressive reminder of the great ships of the past.","zh":"它让人们鲜明地想起昔日那些巨大的帆船。","kind":"narration","speaker":"旁白"},{"en":"Before they were replaced by steamships, sailing vessels like the Cutty Sark were used to carry tea from China and wool from Australia.","zh":"在被蒸汽船取代以前，像“卡蒂萨克号”这样的帆船，曾被用来从中国运茶、从澳大利亚运羊毛。","kind":"narration","speaker":"旁白"},{"en":"The Cutty Sark was one of the fastest sailing ships that has ever been built.","zh":"“卡蒂萨克号”是有史以来建造的最快的帆船之一。","kind":"narration","speaker":"旁白"},{"en":"The only other ship to match her was the Thermopylae.","zh":"唯一能与它匹敌的船是“塞莫皮莱号”。","kind":"narration","speaker":"旁白"},{"en":"Both these ships set out from Shanghai on June 18th, 1872 on an exciting race to England.","zh":"一八七二年六月十八日，两艘船同时从上海出发，展开了一场驶往英国的激动人心的比赛。","kind":"narration","speaker":"旁白"},{"en":"This race, which went on for exactly four months, was the last of its kind.","zh":"这场比赛整整持续了四个月，也是此类比赛的最后一次。","kind":"narration","speaker":"旁白"},{"en":"It marked the end of the great tradition of ships with sails and the beginning of a new era.","zh":"它标志着伟大的帆船传统走向终结，一个新时代由此开始。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"The first of the two ships to reach Java after the race had begun was the Thermopylae, but on the Indian Ocean, the Cutty Sark took the lead.","zh":"比赛开始后，两艘船中先到爪哇的是“塞莫皮莱号”，但到了印度洋，“卡蒂萨克号”取得了领先。","kind":"narration","speaker":"旁白"},{"en":"It seemed certain that she would be the first ship home, but during the race she had a lot of bad luck.","zh":"看来，它一定会最先返回英国，可在比赛中它却接连遭遇不幸。","kind":"narration","speaker":"旁白"},{"en":"In August, she was struck by a very heavy storm during which her rudder was torn away.","zh":"八月，它受到一场猛烈风暴的袭击，船舵被风暴扯掉了。","kind":"narration","speaker":"旁白"},{"en":"The Cutty Sark rolled from side to side and it became impossible to steer her.","zh":"“卡蒂萨克号”左右摇摆，已经无法操纵方向。","kind":"narration","speaker":"旁白"},{"en":"A temporary rudder was made on board from spare planks and it was fitted with great difficulty.","zh":"船员在船上用备用木板做了一只临时船舵，费了很大劲才装上。","kind":"narration","speaker":"旁白"},{"en":"This greatly reduced the speed of the ship, for there was a danger that if she travelled too quickly, this rudder would be torn away as well.","zh":"这大大降低了航速，因为船一旦开得太快，这只船舵也有被扯掉的危险。","kind":"narration","speaker":"旁白"},{"en":"Because of this, the Cutty Sark lost her lead.","zh":"因此，“卡蒂萨克号”失去了领先地位。","kind":"narration","speaker":"旁白"},{"en":"After crossing the Equator, the captain called in at a port to have a new rudder fitted, but by now the Thermopylae was over five hundred miles ahead.","zh":"驶过赤道后，船长在一个港口停靠，换装新船舵，可这时“塞莫皮莱号”已领先五百多英里了。","kind":"narration","speaker":"旁白"},{"en":"Though the new rudder was fitted at tremendous speed, it was impossible for the Cutty Sark to win.","zh":"尽管新舵以极快的速度装好了，“卡蒂萨克号”还是不可能获胜了。","kind":"narration","speaker":"旁白"},{"en":"She arrived in England a week after the Thermopylae.","zh":"它比“塞莫皮莱号”晚一周到达英国。","kind":"narration","speaker":"旁白"},{"en":"Even this was remarkable, considering that she had had so many delays.","zh":"考虑到它耽搁了这么多次，连这样的成绩也很了不起。","kind":"narration","speaker":"旁白"},{"en":"There is no doubt that if she had not lost her rudder she would have won the race easily.","zh":"毫无疑问，如果它没有丢失船舵，本来是能轻松赢得比赛的。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"serve as","matchedForm":"serves as","meaning":"起……作用，充当","note":"as 后接所起的作用或所承担的角色，不一定指职业。","example":"She serves as an impressive reminder of the great ships of the past.","exampleZh":"它让人们鲜明地想起昔日那些巨大的帆船。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"take the lead","matchedForm":"took the lead","meaning":"取得领先","note":"强调开始领先的动作；lose one’s lead 表示失去领先优势。","example":"The first of the two ships to reach Java after the race had begun was the Thermopylae, but on the Indian Ocean, the Cutty Sark took the lead.","exampleZh":"比赛开始后，两艘船中先到爪哇的是“塞莫皮莱号”，但到了印度洋，“卡蒂萨克号”取得了领先。","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"from side to side","matchedForm":"from side to side","meaning":"左右来回","note":"表示两侧之间的反复运动，不是从一侧只移动到另一侧一次。","example":"The Cutty Sark rolled from side to side and it became impossible to steer her.","exampleZh":"“卡蒂萨克号”左右摇摆，已经无法操纵方向。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"on board","matchedForm":"on board","meaning":"在船上","note":"也可用于飞机、火车等交通工具；本文指在帆船上制作临时船舵。","example":"A temporary rudder was made on board from spare planks and it was fitted with great difficulty.","exampleZh":"船员在船上用备用木板做了一只临时船舵，费了很大劲才装上。","sourceParagraphIndex":1,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"call in at","matchedForm":"called in at","meaning":"短暂停靠某地","note":"交通工具到某港口或地点顺路停留；at 后接具体地点。","example":"After crossing the Equator, the captain called in at a port to have a new rudder fitted, but by now the Thermopylae was over five hundred miles ahead.","exampleZh":"驶过赤道后，船长在一个港口停靠，换装新船舵，可这时“塞莫皮莱号”已领先五百多英里了。","sourceParagraphIndex":1,"sourceSentenceIndex":7,"sourceType":"textbook-passage"},{"phrase":"there is no doubt that","matchedForm":"There is no doubt that","meaning":"毫无疑问……","note":"that 后接判断内容；后半句 had not lost 与 would have won 表示对过去的反事实假设。","example":"There is no doubt that if she had not lost her rudder she would have won the race easily.","exampleZh":"毫无疑问，如果它没有丢失船舵，本来是能轻松赢得比赛的。","sourceParagraphIndex":1,"sourceSentenceIndex":11,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l026","book":3,"number":26,"title":"Wanted: a large biscuit tin","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"No one can avoid being influenced by advertisements.","zh":"没有人能够不受广告影响。","kind":"narration","speaker":"旁白"},{"en":"Much as we may pride ourselves on our good taste, we are no longer free to choose the things we want, for advertising exerts a subtle influence on us.","zh":"尽管我们可能很为自己的鉴赏力自豪，可我们已无法自由选择想要的东西，因为广告正对我们施加潜移默化的影响。","kind":"narration","speaker":"旁白"},{"en":"In their efforts to persuade us to buy this or that product, advertisers have made a close study of human nature and have classified all our little weaknesses.","zh":"广告商为说服我们购买这样那样的产品，深入研究了人性，并把我们所有的小弱点都分门别类。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Advertisers discovered years ago that all of us love to get something for nothing.","zh":"广告商多年前就发现，我们人人都喜欢不花钱就得到东西。","kind":"narration","speaker":"旁白"},{"en":"An advertisement which begins with the magic word FREE can rarely go wrong.","zh":"一则用“免费”这个神奇词语开头的广告，很少会失手。","kind":"narration","speaker":"旁白"},{"en":"These days, advertisers not only offer free samples, but free cars, free houses, and free trips round the world as well.","zh":"如今，广告商不仅提供免费样品，还提供免费汽车、免费房屋和免费的环球旅行。","kind":"narration","speaker":"旁白"},{"en":"They devise hundreds of competitions which will enable us to win huge sums of money.","zh":"他们设计出几百种竞赛，让我们有机会赢得巨额奖金。","kind":"narration","speaker":"旁白"},{"en":"Radio and television have made it possible for advertisers to capture the attention of millions of people in this way.","zh":"广播和电视使广告商能够用这种办法吸引数百万人的注意。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"During a radio programme, a company of biscuit manufacturers once asked listeners to bake biscuits and send them to their factory.","zh":"有一次，一家饼干制造公司在广播节目中请听众烤制饼干，并把成品送到他们的工厂。","kind":"narration","speaker":"旁白"},{"en":"They offered to pay $10 a pound for the biggest biscuit baked by a listener.","zh":"他们提出，对听众烤出的最大一块饼干，按每磅十美元付款。","kind":"narration","speaker":"旁白"},{"en":"The response to this competition was tremendous.","zh":"这项比赛引起了极大的反响。","kind":"narration","speaker":"旁白"},{"en":"Before long, biscuits of all shapes and sizes began arriving at the factory.","zh":"不久，各种形状、各种大小的饼干便开始送到工厂。","kind":"narration","speaker":"旁白"},{"en":"One lady brought in a biscuit on a wheelbarrow.","zh":"一位女士用独轮手推车运来了一块饼干。","kind":"narration","speaker":"旁白"},{"en":"It weighed nearly 500 pounds.","zh":"它重近五百磅。","kind":"narration","speaker":"旁白"},{"en":"A little later, a man came along with a biscuit which occupied the whole boot of his car.","zh":"又过了一会儿，一个男人带来一块饼干，占满了汽车的整个行李厢。","kind":"narration","speaker":"旁白"},{"en":"All the biscuits that were sent were carefully weighed.","zh":"所有送来的饼干都经过了仔细称重。","kind":"narration","speaker":"旁白"},{"en":"The largest was 713 pounds.","zh":"最大的一块重七百一十三磅。","kind":"narration","speaker":"旁白"},{"en":"It seemed certain that this would win the prize.","zh":"看来，这块饼干肯定会获奖。","kind":"narration","speaker":"旁白"},{"en":"But just before the competition closed, a lorry arrived at the factory with a truly colossal biscuit which weighed 2,400 pounds.","zh":"可就在比赛快结束时，一辆卡车来到工厂，载着一块真正硕大无比、重达两千四百磅的饼干。","kind":"narration","speaker":"旁白"},{"en":"It had been baked by a college student who had used over 1,000 pounds of flour, 800 pounds of sugar, 200 pounds of fat, and 400 pounds of various other ingredients.","zh":"这块饼干是一名大学生烤的，他用了超过一千磅面粉、八百磅糖、两百磅油脂，以及四百磅其他各类配料。","kind":"narration","speaker":"旁白"},{"en":"It was so heavy that a crane had to be used to remove it from the lorry.","zh":"它重得必须动用起重机，才能从卡车上卸下来。","kind":"narration","speaker":"旁白"},{"en":"The manufacturers had to pay more money than they had anticipated, for they bought the biscuit from the student for $24,000.","zh":"厂家只好比预想的多花钱，因为他们以两万四千美元的价格向那名学生买下了这块饼干。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"pride oneself on","matchedForm":"pride ourselves on","meaning":"以……自豪","note":"on 后接引以为豪的事物或动名词，反身代词须与主语一致。","example":"Much as we may pride ourselves on our good taste, we are no longer free to choose the things we want, for advertising exerts a subtle influence on us.","exampleZh":"尽管我们可能很为自己的鉴赏力自豪，可我们已无法自由选择想要的东西，因为广告正对我们施加潜移默化的影响。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"exert an influence on","matchedForm":"exerts a subtle influence on","meaning":"对……施加影响","note":"influence 前可加 subtle、strong 等形容词；subtle 强调细微而不易察觉。","example":"Much as we may pride ourselves on our good taste, we are no longer free to choose the things we want, for advertising exerts a subtle influence on us.","exampleZh":"尽管我们可能很为自己的鉴赏力自豪，可我们已无法自由选择想要的东西，因为广告正对我们施加潜移默化的影响。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"get something for nothing","matchedForm":"get something for nothing","meaning":"不付代价而得到东西","note":"常指免费获得物品或好处，带有不劳而获的意味。","example":"Advertisers discovered years ago that all of us love to get something for nothing.","exampleZh":"广告商多年前就发现，我们人人都喜欢不花钱就得到东西。","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"go wrong","matchedForm":"go wrong","meaning":"出错，失败","note":"这里指广告达不到预期效果，并非物品走错方向。","example":"An advertisement which begins with the magic word FREE can rarely go wrong.","exampleZh":"一则用“免费”这个神奇词语开头的广告，很少会失手。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"before long","matchedForm":"Before long","meaning":"不久以后","note":"表示很快就发生；不要与 long before（很久以前）混淆。","example":"Before long, biscuits of all shapes and sizes began arriving at the factory.","exampleZh":"不久，各种形状、各种大小的饼干便开始送到工厂。","sourceParagraphIndex":2,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"of all shapes and sizes","matchedForm":"of all shapes and sizes","meaning":"各种形状和大小的","note":"of 短语可作名词后置定语，用于强调外形或尺寸多种多样。","example":"Before long, biscuits of all shapes and sizes began arriving at the factory.","exampleZh":"不久，各种形状、各种大小的饼干便开始送到工厂。","sourceParagraphIndex":2,"sourceSentenceIndex":3,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l027","book":3,"number":27,"title":"Nothing to sell and nothing to buy","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"It has been said that everyone lives by selling something.","zh":"有人说，每个人都靠出售某种东西为生。","kind":"narration","speaker":"旁白"},{"en":"In the light of this statement, teachers live by selling knowledge, philosophers by selling wisdom and priests by selling spiritual comfort.","zh":"按照这种说法，教师靠出售知识生活，哲学家靠出售智慧生活，牧师则靠出售精神慰藉生活。","kind":"narration","speaker":"旁白"},{"en":"Though it may be possible to measure the value of material goods in terms of money, it is extremely difficult to estimate the true value of the services which people perform for us.","zh":"物质商品的价值也许可以用金钱衡量，但要估计别人为我们提供的服务究竟价值几何，却极其困难。","kind":"narration","speaker":"旁白"},{"en":"There are times when we would willingly give everything we possess to save our lives, yet we might grudge paying a surgeon a high fee for offering us precisely this service.","zh":"有时，我们愿意付出自己拥有的一切来保全性命，可当外科医生恰恰为我们提供这种服务时，我们又可能舍不得付给他高额费用。","kind":"narration","speaker":"旁白"},{"en":"The conditions of society are such that skills have to be paid for in the same way that goods are paid for at a shop.","zh":"社会现实如此：技能必须获得报酬，正如在商店购买商品必须付款一样。","kind":"narration","speaker":"旁白"},{"en":"Everyone has something to sell.","zh":"每个人都有东西可卖。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Tramps seem to be the only exception to this general rule.","zh":"流浪汉似乎是这条普遍规律的唯一例外。","kind":"narration","speaker":"旁白"},{"en":"Beggars almost sell themselves as human beings to arouse the pity of passers-by.","zh":"乞丐为了博取过路人的怜悯，几乎把自己作为人的身份都拿来出卖。","kind":"narration","speaker":"旁白"},{"en":"But real tramps are not beggars.","zh":"但真正的流浪汉并不是乞丐。","kind":"narration","speaker":"旁白"},{"en":"They have nothing to sell and require nothing from others.","zh":"他们没有东西出售，也不向别人索取什么。","kind":"narration","speaker":"旁白"},{"en":"In seeking independence, they do not sacrifice their human dignity.","zh":"他们在追求独立时，并不牺牲自己做人的尊严。","kind":"narration","speaker":"旁白"},{"en":"A tramp may ask you for money, but he will never ask you to feel sorry for him.","zh":"流浪汉也许会向你讨钱，但绝不会请求你同情他。","kind":"narration","speaker":"旁白"},{"en":"He has deliberately chosen to lead the life he leads and is fully aware of the consequences.","zh":"他是有意选择自己所过的这种生活，而且完全明白其后果。","kind":"narration","speaker":"旁白"},{"en":"He may never be sure where the next meal is coming from, but he is free from the thousands of anxieties which afflict other people.","zh":"他也许从来不知道下一顿饭在哪里，可他摆脱了困扰他人的千百种忧虑。","kind":"narration","speaker":"旁白"},{"en":"His few material possessions make it possible for him to move from place to place with ease.","zh":"他拥有的物品很少，因此可以轻松地从一处迁往另一处。","kind":"narration","speaker":"旁白"},{"en":"By having to sleep in the open, he gets far closer to the world of nature than most of us ever do.","zh":"由于不得不露宿户外，他与大自然的接近程度，远非我们大多数人所能及。","kind":"narration","speaker":"旁白"},{"en":"He may hunt, beg, or steal occasionally to keep himself alive; he may even, in times of real need, do a little work; but he will never sacrifice his freedom.","zh":"他也许偶尔打猎、乞讨或偷窃来维生；真正需要时，甚至可能干一点活；但他绝不肯牺牲自己的自由。","kind":"narration","speaker":"旁白"},{"en":"We often speak of tramps with contempt and put them in the same class as beggars, but how many of us can honestly say that we have not felt a little envious of their simple way of life and their freedom from care?","zh":"我们谈起流浪汉，常常满怀鄙夷，把他们与乞丐归为一类；可是，我们中又有几人能坦诚地说，自己从未有一点羡慕他们简朴的生活和无忧无虑呢？","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"live by","matchedForm":"lives by","meaning":"靠……为生","note":"by 后接谋生方式，常用动名词；不同于 live on 后接食物或收入来源。","example":"It has been said that everyone lives by selling something.","exampleZh":"有人说，每个人都靠出售某种东西为生。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"in the light of","matchedForm":"In the light of","meaning":"根据，考虑到","note":"用于依据某种信息、说法或情况重新解释或判断，语气较正式。","example":"In the light of this statement, teachers live by selling knowledge, philosophers by selling wisdom and priests by selling spiritual comfort.","exampleZh":"按照这种说法，教师靠出售知识生活，哲学家靠出售智慧生活，牧师则靠出售精神慰藉生活。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"in terms of","matchedForm":"in terms of","meaning":"以……来衡量或表达","note":"引出衡量标准、角度或表达方式，本课以金钱作为价值尺度。","example":"Though it may be possible to measure the value of material goods in terms of money, it is extremely difficult to estimate the true value of the services which people perform for us.","exampleZh":"物质商品的价值也许可以用金钱衡量，但要估计别人为我们提供的服务究竟价值几何，却极其困难。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"be aware of","matchedForm":"aware of","meaning":"意识到，清楚知道","note":"of 后接名词性内容；接完整从句时可用 be aware that。","example":"He has deliberately chosen to lead the life he leads and is fully aware of the consequences.","exampleZh":"他是有意选择自己所过的这种生活，而且完全明白其后果。","sourceParagraphIndex":1,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"with ease","matchedForm":"with ease","meaning":"轻松地，毫不费力地","note":"名词 ease 在此指轻松、不费力；可对应副词 easily。","example":"His few material possessions make it possible for him to move from place to place with ease.","exampleZh":"他拥有的物品很少，因此可以轻松地从一处迁往另一处。","sourceParagraphIndex":1,"sourceSentenceIndex":8,"sourceType":"textbook-passage"},{"phrase":"in the open","matchedForm":"in the open","meaning":"在户外，露天","note":"本文指露宿；其他语境还可指事情公开、不再隐瞒。","example":"By having to sleep in the open, he gets far closer to the world of nature than most of us ever do.","exampleZh":"由于不得不露宿户外，他与大自然的接近程度，远非我们大多数人所能及。","sourceParagraphIndex":1,"sourceSentenceIndex":9,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l028","book":3,"number":28,"title":"Five pounds too dear","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Small boats loaded with wares sped to the great liner as she was entering the harbour.","zh":"巨型客轮正在驶入港口时，满载货物的小船朝它飞快驶来。","kind":"narration","speaker":"旁白"},{"en":"Before she had anchored, the men from the boats had climbed on board and the decks were soon covered with colourful rugs from Persia, silks from India, copper coffee pots, and beautiful handmade silverware.","zh":"客轮还未抛锚，小船上的人就已经爬上了船；很快，甲板上摆满了色彩鲜艳的波斯地毯、印度丝绸、铜咖啡壶和精美的手工银器。","kind":"narration","speaker":"旁白"},{"en":"It was difficult not to be tempted.","zh":"人很难不动心。","kind":"narration","speaker":"旁白"},{"en":"Many of the tourists on board had begun bargaining with the tradesmen, but I decided not to buy anything until I had disembarked.","zh":"船上许多游客已经开始与商贩讨价还价，可我决定下船以后再买东西。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"I had no sooner got off the ship than I was assailed by a man who wanted to sell me a diamond ring.","zh":"我刚一下船，就被一个想卖钻戒给我的男人缠住了。","kind":"narration","speaker":"旁白"},{"en":"I had no intention of buying one, but I could not conceal the fact that I was impressed by the size of the diamonds.","zh":"我根本无意买钻戒，却无法掩饰那些钻石的大小给我留下了深刻印象。","kind":"narration","speaker":"旁白"},{"en":"Some of them were as big as marbles.","zh":"有些钻石足有玻璃弹珠那么大。","kind":"narration","speaker":"旁白"},{"en":"The man went to great lengths to prove that the diamonds were real.","zh":"那人想尽办法，证明钻石是真的。","kind":"narration","speaker":"旁白"},{"en":"As we were walking past a shop, he held a diamond firmly against the window and made a deep impression in the glass.","zh":"我们路过一家商店时，他把一颗钻石紧压在橱窗玻璃上，在玻璃上划出了一道深痕。","kind":"narration","speaker":"旁白"},{"en":"It took me over half an hour to get rid of him.","zh":"我花了半个多小时才摆脱他。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"The next man to approach me was selling expensive pens and watches.","zh":"接下来走近我的人，卖的是昂贵的钢笔和手表。","kind":"narration","speaker":"旁白"},{"en":"I examined one of the pens closely.","zh":"我仔细查看了其中一支钢笔。","kind":"narration","speaker":"旁白"},{"en":"It certainly looked genuine.","zh":"它看起来确实像真货。","kind":"narration","speaker":"旁白"},{"en":"At the base of the gold cap, the words ‘made in the U.S.A.’ had been neatly inscribed.","zh":"金色笔帽的底部，整整齐齐地刻着“美国制造”几个字。","kind":"note","speaker":"笔帽铭文"},{"en":"The man said that the pen was worth £50, but as a special favour, he would let me have it for £30.","zh":"那人说，这支笔值五十英镑，不过可以特别照顾我，三十英镑就卖给我。","kind":"narration","speaker":"旁白"},{"en":"I shook my head and held up five fingers indicating that I was willing to pay £5.","zh":"我摇摇头，伸出五根手指，表示只愿付五英镑。","kind":"narration","speaker":"旁白"},{"en":"Gesticulating wildly, the man acted as if he found my offer outrageous, but he eventually reduced the price to £10.","zh":"他疯狂地比画着，装出觉得我的出价简直离谱的样子，不过最终还是把价格降到了十英镑。","kind":"narration","speaker":"旁白"},{"en":"Shrugging my shoulders, I began to walk away when, a moment later, he ran after me and thrust the pen into my hands.","zh":"我耸耸肩，开始往前走；过了一会儿，他追了上来，把笔塞进我手里。","kind":"narration","speaker":"旁白"},{"en":"Though he kept throwing up his arms in despair, he readily accepted the £5 I gave him.","zh":"他虽然不停地绝望地扬起双臂，却爽快地收下了我递过去的五英镑。","kind":"narration","speaker":"旁白"},{"en":"I felt especially pleased with my wonderful bargain — until I got back to the ship.","zh":"我为这笔绝妙的便宜买卖格外得意——直到回到船上。","kind":"narration","speaker":"旁白"},{"en":"No matter how hard I tried, it was impossible to fill this beautiful pen with ink and to this day it has never written a single word!","zh":"无论我怎么努力，都无法给这支漂亮的钢笔灌进墨水；直到今天，它连一个字也没写出来过！","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"bargain with","matchedForm":"bargaining with","meaning":"与……讨价还价","note":"with 后接谈价的人；bargain 作名词则可指划算的买卖。","example":"Many of the tourists on board had begun bargaining with the tradesmen, but I decided not to buy anything until I had disembarked.","exampleZh":"船上许多游客已经开始与商贩讨价还价，可我决定下船以后再买东西。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"have no intention of","matchedForm":"had no intention of","meaning":"无意做某事","note":"of 后接名词或动名词；表达没有某种打算，不等同于无意间做了某事。","example":"I had no intention of buying one, but I could not conceal the fact that I was impressed by the size of the diamonds.","exampleZh":"我根本无意买钻戒，却无法掩饰那些钻石的大小给我留下了深刻印象。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"go to great lengths","matchedForm":"went to great lengths","meaning":"费尽心思，想尽办法","note":"常接 to do something，说明为达目的所作的巨大努力。","example":"The man went to great lengths to prove that the diamonds were real.","exampleZh":"那人想尽办法，证明钻石是真的。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"get rid of","matchedForm":"get rid of","meaning":"摆脱，除去","note":"后接不想要的人或事物；本课指摆脱纠缠自己的商贩。","example":"It took me over half an hour to get rid of him.","exampleZh":"我花了半个多小时才摆脱他。","sourceParagraphIndex":1,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"no matter how","matchedForm":"No matter how","meaning":"无论怎样","note":"how 后可接形容词、副词或从句，引导让步结构。","example":"No matter how hard I tried, it was impossible to fill this beautiful pen with ink and to this day it has never written a single word!","exampleZh":"无论我怎么努力，都无法给这支漂亮的钢笔灌进墨水；直到今天，它连一个字也没写出来过！","sourceParagraphIndex":2,"sourceSentenceIndex":10,"sourceType":"textbook-passage"},{"phrase":"to this day","matchedForm":"to this day","meaning":"直到今天","note":"强调从过去延续至今的情况，常与现在完成时搭配。","example":"No matter how hard I tried, it was impossible to fill this beautiful pen with ink and to this day it has never written a single word!","exampleZh":"无论我怎么努力，都无法给这支漂亮的钢笔灌进墨水；直到今天，它连一个字也没写出来过！","sourceParagraphIndex":2,"sourceSentenceIndex":10,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l029","book":3,"number":29,"title":"Funny or not?","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Whether we find a joke funny or not largely depends on where we have been brought up.","zh":"我们是否觉得一个笑话好笑，在很大程度上取决于我们从小在哪里长大。","kind":"narration","speaker":"旁白"},{"en":"The sense of humour is mysteriously bound up with national characteristics.","zh":"幽默感与民族特性之间，有着难以解释的密切联系。","kind":"narration","speaker":"旁白"},{"en":"A Frenchman, for instance, might find it hard to laugh at a Russian joke.","zh":"例如，法国人可能很难听一个俄国笑话就笑起来。","kind":"narration","speaker":"旁白"},{"en":"In the same way, a Russian might fail to see anything amusing in a joke which would make an Englishman laugh to tears.","zh":"同样，一个俄国人也可能完全看不出某个笑话有何可笑之处，而这个笑话却会使英国人笑出眼泪。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Most funny stories are based on comic situations.","zh":"大多数笑话都建立在滑稽的情境上。","kind":"narration","speaker":"旁白"},{"en":"In spite of national differences, certain funny situations have a universal appeal.","zh":"尽管存在民族差异，某些滑稽情境却对所有人都有吸引力。","kind":"narration","speaker":"旁白"},{"en":"No matter where you live, you would find it difficult not to laugh at, say, Charlie Chaplin's early films.","zh":"无论你住在哪里，譬如看查理·卓别林的早期电影时，你都会很难忍住不笑。","kind":"narration","speaker":"旁白"},{"en":"However, a new type of humour, which stems largely from the U.S., has recently come into fashion.","zh":"不过，最近一种主要源于美国的新式幽默开始流行。","kind":"narration","speaker":"旁白"},{"en":"It is called ‘sick humour’.","zh":"它被称为“病态幽默”。","kind":"narration","speaker":"旁白"},{"en":"Comedians base their jokes on tragic situations like violent death or serious accidents.","zh":"喜剧演员用暴死、严重事故等悲惨情境来编笑话。","kind":"narration","speaker":"旁白"},{"en":"Many people find this sort of joke distasteful.","zh":"许多人觉得这类笑话令人反感。","kind":"narration","speaker":"旁白"},{"en":"The following example of ‘sick humour’ will enable you to judge for yourself.","zh":"下面这个“病态幽默”的例子，可以让你自行判断。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"A man who had broken his right leg was taken to hospital a few weeks before Christmas.","zh":"圣诞节前几个星期，一个摔断右腿的男人被送进了医院。","kind":"narration","speaker":"旁白"},{"en":"From the moment he arrived there, he kept on pestering his doctor to tell him when he would be able to go home.","zh":"从进医院那一刻起，他就不断缠着医生，要医生告诉他什么时候能回家。","kind":"narration","speaker":"旁白"},{"en":"He dreaded having to spend Christmas in hospital.","zh":"他很害怕不得不在医院过圣诞节。","kind":"narration","speaker":"旁白"},{"en":"Though the doctor did his best, the patient’s recovery was slow.","zh":"尽管医生竭尽全力，病人的恢复还是很慢。","kind":"narration","speaker":"旁白"},{"en":"On Christmas Day, the man still had his right leg in plaster.","zh":"圣诞节那天，他的右腿仍打着石膏。","kind":"narration","speaker":"旁白"},{"en":"He spent a miserable day in bed thinking of all the fun he was missing.","zh":"他躺在床上，想着自己错过的种种欢乐，难过地度过了一天。","kind":"narration","speaker":"旁白"},{"en":"The following day, however, the doctor consoled him by telling him that his chances of being able to leave hospital in time for New Year celebrations were good.","zh":"然而，第二天，医生安慰他说，他很有希望赶在新年庆祝活动前出院。","kind":"narration","speaker":"旁白"},{"en":"The man took heart and, sure enough, on New Year's Eve he was able to hobble along to a party.","zh":"那人振作起来；果然，除夕那天，他已能一瘸一拐地去参加聚会了。","kind":"narration","speaker":"旁白"},{"en":"To compensate for his unpleasant experiences in hospital, the man drank a little more than was good for him.","zh":"为了补偿住院时那些不愉快的经历，他喝酒喝得稍微过了量。","kind":"narration","speaker":"旁白"},{"en":"In the process, he enjoyed himself thoroughly and kept telling everybody how much he hated hospitals.","zh":"在这过程中，他玩得十分尽兴，还不停地告诉大家自己有多么讨厌医院。","kind":"narration","speaker":"旁白"},{"en":"He was still mumbling something about hospitals at the end of the party when he slipped on a piece of ice and broke his left leg.","zh":"聚会结束时，他还在含糊地嘟囔着医院的事，忽然踩上一块冰滑了一跤，把左腿摔断了。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"depend on","matchedForm":"depends on","meaning":"取决于","note":"on 后接决定因素，可以是名词，也可以是疑问词引导的从句。","example":"Whether we find a joke funny or not largely depends on where we have been brought up.","exampleZh":"我们是否觉得一个笑话好笑，在很大程度上取决于我们从小在哪里长大。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"be bound up with","matchedForm":"bound up with","meaning":"与……密切相关","note":"bound up with 强调紧密联系，不是物理意义上捆绑在一起。","example":"The sense of humour is mysteriously bound up with national characteristics.","exampleZh":"幽默感与民族特性之间，有着难以解释的密切联系。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"stem from","matchedForm":"stems largely from","meaning":"源于","note":"from 引出来源或原因；largely 插在动词与介词之间，表示主要。","example":"However, a new type of humour, which stems largely from the U.S., has recently come into fashion.","exampleZh":"不过，最近一种主要源于美国的新式幽默开始流行。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"come into fashion","matchedForm":"come into fashion","meaning":"开始流行","note":"come 强调进入流行状态；be in fashion 表示处于流行状态。","example":"However, a new type of humour, which stems largely from the U.S., has recently come into fashion.","exampleZh":"不过，最近一种主要源于美国的新式幽默开始流行。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"take heart","matchedForm":"took heart","meaning":"振作起来，受到鼓舞","note":"heart 前通常不加冠词；lose heart 则表示灰心。","example":"The man took heart and, sure enough, on New Year's Eve he was able to hobble along to a party.","exampleZh":"那人振作起来；果然，除夕那天，他已能一瘸一拐地去参加聚会了。","sourceParagraphIndex":2,"sourceSentenceIndex":7,"sourceType":"textbook-passage"},{"phrase":"compensate for","matchedForm":"compensate for","meaning":"补偿，弥补","note":"for 后接损失、缺陷或不快经历，本句指用享乐补偿先前住院的不快。","example":"To compensate for his unpleasant experiences in hospital, the man drank a little more than was good for him.","exampleZh":"为了补偿住院时那些不愉快的经历，他喝酒喝得稍微过了量。","sourceParagraphIndex":2,"sourceSentenceIndex":8,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l030","book":3,"number":30,"title":"The death of a ghost","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"For years, villagers believed that Endley Farm was haunted.","zh":"多年来，村民们一直相信恩德利农场闹鬼。","kind":"narration","speaker":"旁白"},{"en":"The farm was owned by two brothers, Joe and Bob Cox.","zh":"农场属于乔·考克斯和鲍勃·考克斯兄弟俩。","kind":"narration","speaker":"旁白"},{"en":"They employed a few farmhands, but no one was willing to work there long.","zh":"他们雇过几个农工，可没有人愿意在那里长干。","kind":"narration","speaker":"旁白"},{"en":"Every time a worker gave up his job, he told the same story.","zh":"每当有工人辞职，他都会讲同一个故事。","kind":"narration","speaker":"旁白"},{"en":"Farm labourers said that they always woke up to find that work had been done overnight.","zh":"农工们说，他们每次醒来，总会发现活儿已经在夜里干好了。","kind":"narration","speaker":"旁白"},{"en":"Hay had been cut and cowsheds had been cleaned.","zh":"干草割好了，牛棚也打扫干净了。","kind":"narration","speaker":"旁白"},{"en":"A farm worker, who stayed up all night, claimed to have seen a figure cutting corn in the moonlight.","zh":"有一个农工一夜没睡，声称看到一个身影在月光下收割庄稼。","kind":"narration","speaker":"旁白"},{"en":"In time, it became an accepted fact that the Cox brothers employed a conscientious ghost that did most of their work for them.","zh":"久而久之，人们都认定，考克斯兄弟雇了一个尽职尽责的鬼，替他们干了大部分活。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"No one suspected that there might be someone else on the farm who had never been seen.","zh":"没有人想到，农场上也许另有一个从未露过面的人。","kind":"narration","speaker":"旁白"},{"en":"This was indeed the case.","zh":"实际情况确实如此。","kind":"narration","speaker":"旁白"},{"en":"A short time ago, villagers were astonished to learn that the ghost of Endley had died.","zh":"不久前，村民们惊讶地得知，恩德利的那个鬼死了。","kind":"narration","speaker":"旁白"},{"en":"Everyone went to the funeral, for the ‘ghost’ was none other than Eric Cox, a third brother who was supposed to have died as a young man.","zh":"所有人都去参加了葬礼，因为这个“鬼”不是别人，正是埃里克·考克斯，是兄弟中的另一个，大家一直以为他年轻时就死了。","kind":"narration","speaker":"旁白"},{"en":"After the funeral, Joe and Bob revealed a secret which they had kept for over fifty years.","zh":"葬礼过后，乔和鲍勃说出了一个他们保守了五十多年的秘密。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"Eric had been the eldest son of the family, very much older than his two brothers.","zh":"埃里克是家中的长子，比两个弟弟年长很多。","kind":"narration","speaker":"旁白"},{"en":"He had been obliged to join the army during the Second World War.","zh":"第二次世界大战期间，他被迫参了军。","kind":"narration","speaker":"旁白"},{"en":"As he hated army life, he decided to desert his regiment.","zh":"由于讨厌军队生活，他决定从所属部队逃走。","kind":"narration","speaker":"旁白"},{"en":"When he learnt that he would be sent abroad, he returned to the farm and his father hid him until the end of the war.","zh":"得知自己将被派往国外后，他回到农场，父亲便把他藏了起来，直到战争结束。","kind":"narration","speaker":"旁白"},{"en":"Fearing the authorities, Eric remained in hiding after the war as well.","zh":"因为害怕当局追究，战后埃里克也一直躲藏着。","kind":"narration","speaker":"旁白"},{"en":"His father told everybody that Eric had been killed in action.","zh":"父亲告诉所有人，埃里克已经在战斗中阵亡。","kind":"narration","speaker":"旁白"},{"en":"The only other people who knew the secret were Joe and Bob.","zh":"除此之外，知道秘密的就只有乔和鲍勃。","kind":"narration","speaker":"旁白"},{"en":"They did not even tell their wives.","zh":"他们甚至连妻子都没告诉。","kind":"narration","speaker":"旁白"},{"en":"When their father died, they thought it their duty to keep Eric in hiding.","zh":"父亲去世后，他们觉得有责任继续把埃里克藏起来。","kind":"narration","speaker":"旁白"},{"en":"All these years, Eric had lived as a recluse.","zh":"这些年来，埃里克一直过着隐居生活。","kind":"narration","speaker":"旁白"},{"en":"He used to sleep during the day and work at night, quite unaware of the fact that he had become the ghost of Endley.","zh":"他白天睡觉、夜里干活，全然不知自己已经成了恩德利的鬼。","kind":"narration","speaker":"旁白"},{"en":"When he died, however, his brothers found it impossible to keep the secret any longer.","zh":"然而，他死后，两个弟弟再也无法保守这个秘密了。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"stay up","matchedForm":"stayed up","meaning":"熬夜，不睡觉","note":"up 表示仍未上床；stay up all night 指整夜未睡。","example":"A farm worker, who stayed up all night, claimed to have seen a figure cutting corn in the moonlight.","exampleZh":"有一个农工一夜没睡，声称看到一个身影在月光下收割庄稼。","sourceParagraphIndex":0,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"in time","matchedForm":"In time","meaning":"渐渐，经过一段时间后","note":"本句意为随着时间推移，不是赶在截止时间之前的及时，要结合语境区分。","example":"In time, it became an accepted fact that the Cox brothers employed a conscientious ghost that did most of their work for them.","exampleZh":"久而久之，人们都认定，考克斯兄弟雇了一个尽职尽责的鬼，替他们干了大部分活。","sourceParagraphIndex":0,"sourceSentenceIndex":7,"sourceType":"textbook-passage"},{"phrase":"none other than","matchedForm":"none other than","meaning":"不是别人，正是","note":"用于揭示令人意外的身份，强调就是所说的这个人。","example":"Everyone went to the funeral, for the ‘ghost’ was none other than Eric Cox, a third brother who was supposed to have died as a young man.","exampleZh":"所有人都去参加了葬礼，因为这个“鬼”不是别人，正是埃里克·考克斯，是兄弟中的另一个，大家一直以为他年轻时就死了。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"in hiding","matchedForm":"in hiding","meaning":"躲藏着，隐匿中","note":"表示为避免被发现或抓捕而藏身的状态。","example":"Fearing the authorities, Eric remained in hiding after the war as well.","exampleZh":"因为害怕当局追究，战后埃里克也一直躲藏着。","sourceParagraphIndex":2,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"be killed in action","matchedForm":"killed in action","meaning":"在战斗中阵亡","note":"军事用语；本句是父亲向外界提供的说法，随后故事揭示并不属实。","example":"His father told everybody that Eric had been killed in action.","exampleZh":"父亲告诉所有人，埃里克已经在战斗中阵亡。","sourceParagraphIndex":2,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"be unaware of","matchedForm":"unaware of","meaning":"不知道，未意识到","note":"unaware 是 aware 的否定形式，of 后接名词性内容；原句 quite 加强了全然不知的程度。","example":"He used to sleep during the day and work at night, quite unaware of the fact that he had become the ghost of Endley.","exampleZh":"他白天睡觉、夜里干活，全然不知自己已经成了恩德利的鬼。","sourceParagraphIndex":2,"sourceSentenceIndex":10,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l031","book":3,"number":31,"title":"A lovable eccentric","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"True eccentrics never deliberately set out to draw attention to themselves.","zh":"真正的怪人从不会刻意设法引人注意。","kind":"narration","speaker":"旁白"},{"en":"They disregard social conventions without being conscious that they are doing anything extraordinary.","zh":"他们不理会社会习俗，却并不觉得自己的举动有什么出格。","kind":"narration","speaker":"旁白"},{"en":"This invariably wins them the love and respect of others, for they add colour to the dull routine of everyday life.","zh":"这总能为他们赢来别人的喜爱和尊重，因为他们给单调的日常生活增添了色彩。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Up to the time of his death, Richard Colson was one of the most notable figures in our town.","zh":"理查德·科尔森一直到去世时，都是我们镇上最出名的人物之一。","kind":"narration","speaker":"旁白"},{"en":"He was a shrewd and wealthy businessman, but most people in the town hardly knew anything about this side of his life.","zh":"他是个精明而富有的商人，但镇上大多数人对他生活的这一面几乎一无所知。","kind":"narration","speaker":"旁白"},{"en":"He was known to us all as Dickie and his eccentricity had become legendary long before he died.","zh":"大家都叫他迪基；早在他去世以前，他的种种怪癖就已成了传奇。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"Dickie disliked snobs intensely.","zh":"迪基极其讨厌势利眼。","kind":"narration","speaker":"旁白"},{"en":"Though he owned a large car, he hardly ever used it, preferring always to go on foot.","zh":"他虽然有一辆大汽车，却几乎从来不用，总爱步行出门。","kind":"narration","speaker":"旁白"},{"en":"Even when it was raining heavily, he refused to carry an umbrella.","zh":"即使下着大雨，他也不肯带伞。","kind":"narration","speaker":"旁白"},{"en":"One day, he walked into an expensive shop after having been caught in a particularly heavy shower.","zh":"一天，他被一场特别猛烈的阵雨淋了个透，随后走进了一家高档商店。","kind":"narration","speaker":"旁白"},{"en":"He wanted to buy a £300 watch for his wife, but he was in such a bedraggled condition that an assistant refused to serve him.","zh":"他想给妻子买一块价值三百英镑的手表，可他浑身湿透、狼狈不堪，一个店员竟不肯接待他。","kind":"narration","speaker":"旁白"},{"en":"Dickie left the shop without a word and returned carrying a large cloth bag.","zh":"迪基一声不吭地离开商店，又提着一只大布袋回来了。","kind":"narration","speaker":"旁白"},{"en":"As it was extremely heavy, he dumped it on the counter.","zh":"袋子重极了，他把它重重地放在柜台上。","kind":"narration","speaker":"旁白"},{"en":"The assistant asked him to leave, but Dickie paid no attention to him and requested to see the manager.","zh":"店员叫他出去，迪基却毫不理睬，要求见经理。","kind":"narration","speaker":"旁白"},{"en":"Recognizing who the customer was, the manager was most apologetic and reprimanded the assistant severely.","zh":"经理认出了这位顾客是谁，连忙赔不是，并狠狠训斥了那个店员。","kind":"narration","speaker":"旁白"},{"en":"When Dickie was given the watch, he presented the assistant with the cloth bag.","zh":"拿到手表以后，迪基把布袋递给了店员。","kind":"narration","speaker":"旁白"},{"en":"It contained £300 in pennies.","zh":"袋里装的是三百英镑，全是一便士的硬币。","kind":"narration","speaker":"旁白"},{"en":"He insisted on the assistant’s counting the money before he left— 30,000 pennies in all!","zh":"他坚持要店员把钱数清以后自己才走——总共三万枚一便士硬币！","kind":"narration","speaker":"旁白"},{"en":"On another occasion, he invited a number of important critics to see his private collection of modern paintings.","zh":"还有一次，他邀请了许多重要的评论家来参观他私人收藏的现代绘画。","kind":"narration","speaker":"旁白"},{"en":"This exhibition received a great deal of attention in the press, for though the pictures were supposed to be the work of famous artists, they had in fact been painted by Dickie.","zh":"这次展览引起了报界的广泛关注；这些画虽然号称出自名家之手，实际上却全是迪基自己画的。","kind":"narration","speaker":"旁白"},{"en":"It took him four years to stage this elaborate joke simply to prove that critics do not always know what they are talking about.","zh":"为了策划这场煞费苦心的玩笑，他花了四年时间，只是要证明评论家并非总知道自己在说些什么。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"draw attention to oneself","matchedForm":"draw attention to themselves","meaning":"引起别人对自己的注意","note":"draw attention to 后接被关注的人或事；反身代词要随主语变化。","example":"True eccentrics never deliberately set out to draw attention to themselves.","exampleZh":"真正的怪人从不会刻意设法引人注意。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"hardly know anything about","matchedForm":"hardly knew anything about","meaning":"对……几乎一无所知","note":"hardly 已含否定意味，通常不再加 not；anything 常与它搭配。","example":"He was a shrewd and wealthy businessman, but most people in the town hardly knew anything about this side of his life.","exampleZh":"他是个精明而富有的商人，但镇上大多数人对他生活的这一面几乎一无所知。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"without a word","matchedForm":"without a word","meaning":"一声不吭地","note":"表示什么也没说，可描述离开或接受某事时的沉默。","example":"Dickie left the shop without a word and returned carrying a large cloth bag.","exampleZh":"迪基一声不吭地离开商店，又提着一只大布袋回来了。","sourceParagraphIndex":2,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"pay no attention to","matchedForm":"paid no attention to","meaning":"完全不理会","note":"to 是介词，后接人、事或动名词；paid 是 pay 的过去式。","example":"The assistant asked him to leave, but Dickie paid no attention to him and requested to see the manager.","exampleZh":"店员叫他出去，迪基却毫不理睬，要求见经理。","sourceParagraphIndex":2,"sourceSentenceIndex":7,"sourceType":"textbook-passage"},{"phrase":"in all","matchedForm":"in all","meaning":"合计；总共","note":"常放在数量后或句末，用来说明总数。","example":"He insisted on the assistant’s counting the money before he left— 30,000 pennies in all!","exampleZh":"他坚持要店员把钱数清以后自己才走——总共三万枚一便士硬币！","sourceParagraphIndex":2,"sourceSentenceIndex":11,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l032","book":3,"number":32,"title":"A lost ship","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"The salvage operation had been a complete failure.","zh":"这次打捞行动彻底失败了。","kind":"narration","speaker":"旁白"},{"en":"The small ship, Elkor, which had been searching the Barents Sea for weeks, was on its way home.","zh":"小船“埃尔科号”在巴伦支海搜寻了几个星期，现在正驶向归途。","kind":"narration","speaker":"旁白"},{"en":"A radio message from the mainland had been received by the ship’s captain instructing him to give up the search.","zh":"船长已经收到了大陆发来的一封无线电报，指示他放弃搜寻。","kind":"narration","speaker":"旁白"},{"en":"The captain knew that another attempt would be made later, for the sunken ship he was trying to find had been carrying a precious cargo of gold bullion.","zh":"船长知道以后还会再次尝试，因为他一直在寻找的那艘沉船当时载着一批贵重的金条。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Despite the message, the captain of the Elkor decided to try once more.","zh":"尽管收到了电报，“埃尔科号”的船长还是决定再试一次。","kind":"narration","speaker":"旁白"},{"en":"The sea bed was scoured with powerful nets and there was tremendous excitement on board when a chest was raised from the bottom.","zh":"船员用结实的大网搜遍海底；当一只箱子从海底被吊上来时，全船都激动不已。","kind":"narration","speaker":"旁白"},{"en":"Though the crew were at first under the impression that the lost ship had been found, the contents of the chest proved them wrong.","zh":"船员们起初以为找到了要找的沉船，可箱里的东西证明他们弄错了。","kind":"narration","speaker":"旁白"},{"en":"What they had in fact found was a ship which had been sunk many years before.","zh":"他们实际找到的是一艘多年前就已沉没的船。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"The chest contained the personal belongings of a seaman, Alan Fielding.","zh":"箱里装着海员艾伦·菲尔丁的私人物品。","kind":"narration","speaker":"旁白"},{"en":"There were books, clothing and photographs, together with letters which the seaman had once received from his wife.","zh":"里面有书、衣服和照片，还有这位海员生前收到的妻子来信。","kind":"narration","speaker":"旁白"},{"en":"The captain of the Elkor ordered his men to salvage as much as possible from the wreck.","zh":"“埃尔科号”的船长命令手下尽可能多地从沉船上打捞物品。","kind":"narration","speaker":"旁白"},{"en":"Nothing of value was found, but the numerous items which were brought to the surface proved to be of great interest.","zh":"虽然没找到值钱的东西，但打捞上来的众多物件却十分引人关注。","kind":"narration","speaker":"旁白"},{"en":"From a heavy gun that was raised, the captain realized that the ship must have been a cruiser.","zh":"从吊上来的一门重炮判断，船长意识到这艘船一定是巡洋舰。","kind":"narration","speaker":"旁白"},{"en":"In another chest, which contained the belongings of a ship’s officer, there was an unfinished letter which had been written on March 14th, 1943.","zh":"另一只箱子里装的是一位舰上军官的物品，其中有一封写于一九四三年三月十四日、尚未写完的信。","kind":"narration","speaker":"旁白"},{"en":"The captain learnt from the letter that the name of the lost ship was the Karen.","zh":"船长从信中得知，这艘沉船叫“卡伦号”。","kind":"narration","speaker":"旁白"},{"en":"The most valuable find of all was the ship’s log book, parts of which it was still possible to read.","zh":"最有价值的发现是船上的航海日志，其中有些部分的字迹仍然可以辨认。","kind":"narration","speaker":"旁白"},{"en":"From this the captain was able to piece together all the information that had come to light.","zh":"船长凭着这本日志，把已经发现的所有信息拼凑了起来。","kind":"narration","speaker":"旁白"},{"en":"The Karen had been sailing in a convoy to Russia when she was torpedoed by an enemy submarine.","zh":"“卡伦号”当时随一支护航船队驶往俄罗斯，途中被敌方潜艇的鱼雷击中。","kind":"narration","speaker":"旁白"},{"en":"This was later confirmed by a naval official at the Ministry of Defence after the Elkor had returned home.","zh":"“埃尔科号”返航后，国防部的一位海军官员随后证实了这一情况。","kind":"narration","speaker":"旁白"},{"en":"All the items that were found were sent to the War Museum.","zh":"找到的所有物品都被送进了战争博物馆。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"once more","matchedForm":"once more","meaning":"再一次","note":"可与 try、ask、read 等动词搭配，强调重复一次。","example":"Despite the message, the captain of the Elkor decided to try once more.","exampleZh":"尽管收到了电报，“埃尔科号”的船长还是决定再试一次。","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"be under the impression that","matchedForm":"under the impression that","meaning":"原以为……","note":"表示某人的认识或印象，常暗示这种认识可能并不正确。","example":"Though the crew were at first under the impression that the lost ship had been found, the contents of the chest proved them wrong.","exampleZh":"船员们起初以为找到了要找的沉船，可箱里的东西证明他们弄错了。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"personal belongings","matchedForm":"personal belongings","meaning":"私人物品","note":"belongings 表示随身或个人所有的东西，通常用复数。","example":"The chest contained the personal belongings of a seaman, Alan Fielding.","exampleZh":"箱里装着海员艾伦·菲尔丁的私人物品。","sourceParagraphIndex":2,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"piece together","matchedForm":"piece together","meaning":"把零散信息拼合起来","note":"可用于线索、故事或经过，强调逐步还原整体。","example":"From this the captain was able to piece together all the information that had come to light.","exampleZh":"船长凭着这本日志，把已经发现的所有信息拼凑了起来。","sourceParagraphIndex":2,"sourceSentenceIndex":8,"sourceType":"textbook-passage"},{"phrase":"come to light","matchedForm":"come to light","meaning":"被发现；显露出来","note":"常以 facts、evidence、information 作主语，表示原先未知的事情浮现。","example":"From this the captain was able to piece together all the information that had come to light.","exampleZh":"船长凭着这本日志，把已经发现的所有信息拼凑了起来。","sourceParagraphIndex":2,"sourceSentenceIndex":8,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l033","book":3,"number":33,"title":"A day to remember","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"We have all experienced days when everything goes wrong.","zh":"我们都经历过事事不顺的日子。","kind":"narration","speaker":"旁白"},{"en":"A day may begin well enough, but suddenly everything seems to get out of control.","zh":"一天开始时也许还挺顺利，可突然间，一切似乎都失去了控制。","kind":"narration","speaker":"旁白"},{"en":"What invariably happens is that a great number of things choose to go wrong at precisely the same moment.","zh":"总会出现这样的情形：一大堆事情偏偏在同一时刻出了岔子。","kind":"narration","speaker":"旁白"},{"en":"It is as if a single unimportant event set up a chain of reactions.","zh":"仿佛一件微不足道的小事引发了一连串反应。","kind":"narration","speaker":"旁白"},{"en":"Let us suppose that you are preparing a meal and keeping an eye on the baby at the same time.","zh":"假设你一边做饭，一边照看孩子。","kind":"narration","speaker":"旁白"},{"en":"The telephone rings and this marks the prelude to an unforeseen series of catastrophes.","zh":"电话铃响了，这就拉开了一连串意想不到的灾难的序幕。","kind":"narration","speaker":"旁白"},{"en":"While you are on the phone, the baby pulls the tablecloth off the table, smashing half your best crockery and cutting himself in the process.","zh":"你正打着电话，孩子把桌布从桌上拽下来，摔碎了你一半最好的餐具，还在这过程中划伤了自己。","kind":"narration","speaker":"旁白"},{"en":"You hang up hurriedly and attend to baby, crockery, etc. Meanwhile, the meal gets burnt.","zh":"你匆忙挂断电话，去照料孩子、收拾餐具等等；与此同时，饭菜烧焦了。","kind":"narration","speaker":"旁白"},{"en":"As if this were not enough to reduce you to tears, your husband arrives, unexpectedly bringing three guests to dinner.","zh":"这些仿佛还不足以让你哭出来似的，你丈夫回来了，还出乎意料地带了三位客人来吃饭。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Things can go wrong on a big scale, as a number of people recently discovered in Parramatta, a suburb of Sydney.","zh":"出乱子也能波及很大范围，悉尼郊区帕拉马塔的一些人最近就发现了这一点。","kind":"narration","speaker":"旁白"},{"en":"During the rush hour one evening two cars collided and both drivers began to argue.","zh":"一天傍晚的交通高峰期，两辆汽车相撞，两位司机争吵了起来。","kind":"narration","speaker":"旁白"},{"en":"The woman immediately behind the two cars happened to be a learner.","zh":"紧跟在这两辆车后面的女司机碰巧还是个学车的新手。","kind":"narration","speaker":"旁白"},{"en":"She suddenly got into a panic and stopped her car.","zh":"她一下慌了神，把车停了下来。","kind":"narration","speaker":"旁白"},{"en":"This made the driver following her brake hard.","zh":"这使跟在她后面的司机猛踩刹车。","kind":"narration","speaker":"旁白"},{"en":"His wife was sitting beside him holding a large cake.","zh":"他的妻子坐在他身旁，手里捧着一只大蛋糕。","kind":"narration","speaker":"旁白"},{"en":"As she was thrown forward, the cake went right through the windscreen and landed on the road.","zh":"她的身体被猛地甩向前方，蛋糕径直穿过挡风玻璃，落到了马路上。","kind":"narration","speaker":"旁白"},{"en":"Seeing a cake flying through the air, a lorry driver who was drawing up alongside the car, pulled up all of a sudden.","zh":"一位卡车司机正把车开到这辆汽车旁边，看到一个蛋糕在空中飞来，突然停下了车。","kind":"narration","speaker":"旁白"},{"en":"The lorry was loaded with empty beer bottles and hundreds of them slid off the back of the vehicle and on to the road.","zh":"卡车上装满了空啤酒瓶，几百只瓶子从车尾滑落到路面上。","kind":"narration","speaker":"旁白"},{"en":"This led to yet another angry argument.","zh":"这又引发了一场怒气冲冲的争吵。","kind":"narration","speaker":"旁白"},{"en":"Meanwhile, the traffic piled up behind.","zh":"与此同时，后面的车辆越堵越多。","kind":"narration","speaker":"旁白"},{"en":"It took the police nearly an hour to get the traffic on the move again.","zh":"警察用了将近一小时，才使车辆重新通行。","kind":"narration","speaker":"旁白"},{"en":"In the meantime, the lorry driver had to sweep up hundreds of broken bottles.","zh":"在此期间，卡车司机不得不清扫几百只摔碎的瓶子。","kind":"narration","speaker":"旁白"},{"en":"Only two stray dogs benefited from all this confusion, for they greedily devoured what was left of the cake.","zh":"只有两条流浪狗从这场混乱中得了好处，它们贪婪地吞吃了剩下的蛋糕。","kind":"narration","speaker":"旁白"},{"en":"It was just one of those days!","zh":"这可真是诸事不顺的一天！","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"go wrong","matchedForm":"goes wrong","meaning":"出问题；不顺利","note":"可指事情出岔子或计划不顺，不一定指做错道德上的事。","example":"We have all experienced days when everything goes wrong.","exampleZh":"我们都经历过事事不顺的日子。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"get out of control","matchedForm":"get out of control","meaning":"失去控制","note":"get 强调从可控变为失控的过程。","example":"A day may begin well enough, but suddenly everything seems to get out of control.","exampleZh":"一天开始时也许还挺顺利，可突然间，一切似乎都失去了控制。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"keep an eye on","matchedForm":"keeping an eye on","meaning":"留意照看","note":"表示一边做别的事一边留心，eye 在这个短语中用单数。","example":"Let us suppose that you are preparing a meal and keeping an eye on the baby at the same time.","exampleZh":"假设你一边做饭，一边照看孩子。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"get into a panic","matchedForm":"got into a panic","meaning":"慌了神","note":"表示进入惊慌状态；panic 作可数名词时可用 a panic。","example":"She suddenly got into a panic and stopped her car.","exampleZh":"她一下慌了神，把车停了下来。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"all of a sudden","matchedForm":"all of a sudden","meaning":"突然","note":"固定说法，相当于 suddenly，其中有 a。","example":"Seeing a cake flying through the air, a lorry driver who was drawing up alongside the car, pulled up all of a sudden.","exampleZh":"一位卡车司机正把车开到这辆汽车旁边，看到一个蛋糕在空中飞来，突然停下了车。","sourceParagraphIndex":1,"sourceSentenceIndex":7,"sourceType":"textbook-passage"},{"phrase":"benefit from","matchedForm":"benefited from","meaning":"从……中受益","note":"from 引出好处的来源；可用于人、组织或事物。","example":"Only two stray dogs benefited from all this confusion, for they greedily devoured what was left of the cake.","exampleZh":"只有两条流浪狗从这场混乱中得了好处，它们贪婪地吞吃了剩下的蛋糕。","sourceParagraphIndex":1,"sourceSentenceIndex":13,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l034","book":3,"number":34,"title":"A happy discovery","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Antique shops exert a peculiar fascination on a great many people.","zh":"古董店对许多人有一种特别的吸引力。","kind":"narration","speaker":"旁白"},{"en":"The more expensive kind of antique shop where rare objects are beautifully displayed in glass cases to keep them free from dust is usually a forbidding place.","zh":"价格较高的那类古董店通常令人望而却步，店里把稀罕物件精美地陈列在玻璃柜中，以免沾上灰尘。","kind":"narration","speaker":"旁白"},{"en":"But no one has to muster up courage to enter a less pretentious antique shop.","zh":"不过，走进一家不那么讲排场的古董店，谁也用不着鼓起勇气。","kind":"narration","speaker":"旁白"},{"en":"There is always hope that in its labyrinth of musty, dark, disordered rooms a real rarity will be found amongst the piles of assorted junk that litter the floors.","zh":"在那些迷宫般霉味扑鼻、昏暗杂乱的房间里，地上堆着各式各样的废旧东西，人们总抱着能从中找到真正珍品的希望。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"No one discovers a rarity by chance.","zh":"谁也不是单凭偶然就能发现珍品的。","kind":"narration","speaker":"旁白"},{"en":"A truly dedicated bargain hunter must have patience, and above all, the ability to recognize the worth of something when he sees it.","zh":"一个真正热衷于淘便宜货的人必须有耐心，最重要的是，东西一到眼前就能看出它的价值。","kind":"narration","speaker":"旁白"},{"en":"To do this, he must be at least as knowledgeable as the dealer.","zh":"要做到这一点，他至少得和古董商一样内行。","kind":"narration","speaker":"旁白"},{"en":"Like a scientist bent on making a discovery, he must cherish the hope that one day he will be amply rewarded.","zh":"就像一位一心要有所发现的科学家，他必须珍视这样的希望：总有一天自己会得到丰厚的回报。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"My old friend, Frank Halliday, is just such a person.","zh":"我的老朋友弗兰克·哈利迪就是这样一个人。","kind":"narration","speaker":"旁白"},{"en":"He has often described to me how he picked up a masterpiece for a mere £50.","zh":"他常向我讲述自己如何只花五十英镑就淘到了一幅名作。","kind":"narration","speaker":"旁白"},{"en":"One Saturday morning, Frank visited an antique shop in my neighbourhood.","zh":"一个星期六的上午，弗兰克走进了我家附近的一家古董店。","kind":"narration","speaker":"旁白"},{"en":"As he had never been there before, he found a great deal to interest him.","zh":"他以前从没去过那里，因而发现许多东西都让他感兴趣。","kind":"narration","speaker":"旁白"},{"en":"The morning passed rapidly and Frank was about to leave when he noticed a large packing case lying on the floor.","zh":"一上午很快过去了，弗兰克正要离开，忽然看见地上放着一个大包装箱。","kind":"narration","speaker":"旁白"},{"en":"The dealer told him that it had just come in, but that he could not be bothered to open it.","zh":"店主告诉他，这箱东西刚送来，不过他懒得打开。","kind":"narration","speaker":"旁白"},{"en":"Frank begged him to do so and the dealer reluctantly prised it open.","zh":"弗兰克恳求他打开，店主这才不大情愿地把箱子撬开。","kind":"narration","speaker":"旁白"},{"en":"The contents were disappointing.","zh":"箱里的东西令人失望。","kind":"narration","speaker":"旁白"},{"en":"Apart from an interesting-looking carved dagger, the box was full of crockery, much of it broken.","zh":"除了一把样子颇有趣、带雕饰的短剑以外，箱里全是陶瓷餐具，而且大多已经破损。","kind":"narration","speaker":"旁白"},{"en":"Frank gently lifted the crockery out of the box and suddenly noticed a miniature painting at the bottom of the packing case.","zh":"弗兰克把餐具轻轻地从箱中取出，突然发现箱底有一幅微型画。","kind":"narration","speaker":"旁白"},{"en":"As its composition and line reminded him of an Italian painting he knew well, he decided to buy it.","zh":"画的构图和线条使他想起一幅自己很熟悉的意大利画作，他于是决定买下它。","kind":"narration","speaker":"旁白"},{"en":"Glancing at it briefly, the dealer told him that it was worth £50.","zh":"店主匆匆瞥了一眼，告诉他这画值五十英镑。","kind":"narration","speaker":"旁白"},{"en":"Frank could hardly conceal his excitement, for he knew that he had made a real discovery.","zh":"弗兰克几乎掩饰不住自己的兴奋，因为他知道自己确实发现了宝贝。","kind":"narration","speaker":"旁白"},{"en":"The tiny painting proved to be an unknown masterpiece by Correggio and was worth hundreds of thousands of pounds.","zh":"这幅小画后来被证实是科雷乔一幅此前不为人知的杰作，价值数十万英镑。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"muster up courage","matchedForm":"muster up courage","meaning":"鼓起勇气","note":"muster up 常与 courage、energy 等搭配，强调努力调动起所需的力量。","example":"But no one has to muster up courage to enter a less pretentious antique shop.","exampleZh":"不过，走进一家不那么讲排场的古董店，谁也用不着鼓起勇气。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"by chance","matchedForm":"by chance","meaning":"偶然地","note":"表示事情碰巧发生；也可用于否定句，强调并非偶然。","example":"No one discovers a rarity by chance.","exampleZh":"谁也不是单凭偶然就能发现珍品的。","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"above all","matchedForm":"above all","meaning":"最重要的是","note":"用于突出几项条件中最关键的一项。","example":"A truly dedicated bargain hunter must have patience, and above all, the ability to recognize the worth of something when he sees it.","exampleZh":"一个真正热衷于淘便宜货的人必须有耐心，最重要的是，东西一到眼前就能看出它的价值。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"be bent on","matchedForm":"bent on","meaning":"一心要……","note":"on 后接名词或动名词，常带意志坚定甚至执意如此的意味。","example":"Like a scientist bent on making a discovery, he must cherish the hope that one day he will be amply rewarded.","exampleZh":"就像一位一心要有所发现的科学家，他必须珍视这样的希望：总有一天自己会得到丰厚的回报。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"hundreds of thousands of","matchedForm":"hundreds of thousands of","meaning":"数十万的","note":"表达不确定的大致数量时 hundreds 和 thousands 都用复数，后面保留 of。","example":"The tiny painting proved to be an unknown masterpiece by Correggio and was worth hundreds of thousands of pounds.","exampleZh":"这幅小画后来被证实是科雷乔一幅此前不为人知的杰作，价值数十万英镑。","sourceParagraphIndex":2,"sourceSentenceIndex":13,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l035","book":3,"number":35,"title":"Justice was done","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"The word justice is usually associated with courts of law.","zh":"“正义”这个词通常使人联想到法庭。","kind":"narration","speaker":"旁白"},{"en":"We might say that justice has been done when a man’s innocence or guilt has been proved beyond doubt.","zh":"当一个人无罪或有罪已被确凿地证实后，我们也许会说正义得到了伸张。","kind":"narration","speaker":"旁白"},{"en":"Justice is part of the complex machinery of the law.","zh":"正义是法律这套复杂运作机制的一部分。","kind":"narration","speaker":"旁白"},{"en":"Those who seek it undertake an arduous journey and can never be sure that they will find it.","zh":"寻求正义的人踏上的是一段艰辛的旅程，而且永远无法确定自己最终能否找到它。","kind":"narration","speaker":"旁白"},{"en":"Judges, however wise or eminent, are human and can make mistakes.","zh":"法官无论多么睿智、多么显赫，也都是人，照样可能犯错。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"There are rare instances when justice almost ceases to be an abstract concept.","zh":"极少数时候，正义几乎不再只是一个抽象的概念。","kind":"narration","speaker":"旁白"},{"en":"Reward or punishment are meted out quite independent of human interference.","zh":"奖赏或惩罚的降临，完全不受人为干预。","kind":"narration","speaker":"旁白"},{"en":"At such times, justice acts like a living force.","zh":"在这种时候，正义仿佛是一股有生命的力量。","kind":"narration","speaker":"旁白"},{"en":"When we use a phrase like ‘it serves him right’, we are, in part, admitting that a certain set of circumstances has enabled justice to act of its own accord.","zh":"当我们说“他活该”这样的话时，也就在某种程度上承认，某些特定的情形使正义得以自行发挥作用。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"When a thief was caught on the premises of a large jewellery store one morning, the shop assistants must have found it impossible to resist the temptation to say ‘it serves him right’.","zh":"一天上午，一个小偷在一家大珠宝店里被抓住，店员们一定忍不住想说“他活该”。","kind":"narration","speaker":"旁白"},{"en":"The shop was an old converted house with many large, disused fireplaces and tall, narrow chimneys.","zh":"这家商店由一栋老房子改建而成，里面有许多废弃的大壁炉和又高又窄的烟囱。","kind":"narration","speaker":"旁白"},{"en":"Towards midday, a girl heard a muffled cry coming from behind one of the walls.","zh":"快到中午时，一位女店员听到一面墙后传来低沉的呼救声。","kind":"narration","speaker":"旁白"},{"en":"As the cry was repeated several times, she ran to tell the manager who promptly rang up the fire brigade.","zh":"呼救声接连响了几次，她就跑去告诉经理，经理立即打电话叫来了消防队。","kind":"narration","speaker":"旁白"},{"en":"The cry had certainly come from one of the chimneys, but as there were so many of them, the fire fighters could not be certain which one it was.","zh":"声音肯定来自某根烟囱，但烟囱太多，消防员一时无法确定是哪一根。","kind":"narration","speaker":"旁白"},{"en":"They located the right chimney by tapping at the walls and listening for the man’s cries.","zh":"他们一边敲墙，一边听那人的呼喊，终于找对了烟囱。","kind":"narration","speaker":"旁白"},{"en":"After chipping through a wall which was eighteen inches thick, they found that a man had been trapped in the chimney.","zh":"凿穿一堵十八英寸厚的墙以后，他们发现有个人困在烟囱里。","kind":"narration","speaker":"旁白"},{"en":"As it was extremely narrow, the man was unable to move, but the fire fighters were eventually able to free him by cutting a huge hole in the wall.","zh":"烟囱极窄，那人动弹不得；不过，消防员最后在墙上凿出一个大洞，把他解救了出来。","kind":"narration","speaker":"旁白"},{"en":"The sorry-looking, blackened figure that emerged, admitted at once that he had tried to break into the shop during the night but had got stuck in the chimney.","zh":"这个出来时满身漆黑、模样狼狈的人立刻承认，他夜里曾试图闯进商店，却卡在了烟囱里。","kind":"narration","speaker":"旁白"},{"en":"He had been there for nearly ten hours.","zh":"他已经在那里待了将近十个小时。","kind":"narration","speaker":"旁白"},{"en":"Justice had been done even before the man was handed over to the police.","zh":"那人还没被移交给警察，正义就已经得到了伸张。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"be associated with","matchedForm":"associated with","meaning":"与……联系在一起","note":"常用被动形式表达概念上的联系；with 后接联想到的事物。","example":"The word justice is usually associated with courts of law.","exampleZh":"“正义”这个词通常使人联想到法庭。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"beyond doubt","matchedForm":"beyond doubt","meaning":"毫无疑问；确凿无疑","note":"用于强调证据或结论没有合理疑问，常接在 prove 之后。","example":"We might say that justice has been done when a man’s innocence or guilt has been proved beyond doubt.","exampleZh":"当一个人无罪或有罪已被确凿地证实后，我们也许会说正义得到了伸张。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"of one’s own accord","matchedForm":"of its own accord","meaning":"自行；自发地","note":"表示没有外力推动便自行发生；one’s 随主语变化。","example":"When we use a phrase like ‘it serves him right’, we are, in part, admitting that a certain set of circumstances has enabled justice to act of its own accord.","exampleZh":"当我们说“他活该”这样的话时，也就在某种程度上承认，某些特定的情形使正义得以自行发挥作用。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"break into","matchedForm":"break into","meaning":"强行闯入","note":"这里指非法进入建筑物，不要与表示进入某行业的引申义混淆。","example":"The sorry-looking, blackened figure that emerged, admitted at once that he had tried to break into the shop during the night but had got stuck in the chimney.","exampleZh":"这个出来时满身漆黑、模样狼狈的人立刻承认，他夜里曾试图闯进商店，却卡在了烟囱里。","sourceParagraphIndex":2,"sourceSentenceIndex":8,"sourceType":"textbook-passage"},{"phrase":"hand over to","matchedForm":"handed over to","meaning":"移交给","note":"可说 hand someone over to the police；代词作宾语时放在 hand 与 over 之间。","example":"Justice had been done even before the man was handed over to the police.","exampleZh":"那人还没被移交给警察，正义就已经得到了伸张。","sourceParagraphIndex":2,"sourceSentenceIndex":10,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l036","book":3,"number":36,"title":"A chance in a million","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"We are less credulous than we used to be.","zh":"我们如今不像过去那样轻信了。","kind":"narration","speaker":"旁白"},{"en":"In the nineteenth century, a novelist would bring his story to a conclusion by presenting his readers with a series of coincidences — most of them wildly improbable.","zh":"十九世纪的小说家常用一连串巧合来收束故事，其中大多数巧合都离奇得令人难以相信。","kind":"narration","speaker":"旁白"},{"en":"Readers happily accepted the fact that an obscure maidservant was really the hero’s mother.","zh":"一个不起眼的女仆竟然是男主人公的母亲，读者也欣然接受。","kind":"narration","speaker":"旁白"},{"en":"A long-lost brother, who was presumed dead, was really alive all the time and wickedly plotting to bring about the hero’s downfall.","zh":"一个失散多年、被认为已经死去的兄弟，其实一直活着，还在恶毒地密谋让男主人公垮台。","kind":"narration","speaker":"旁白"},{"en":"And so on.","zh":"诸如此类。","kind":"narration","speaker":"旁白"},{"en":"Modern readers would find such naive solutions totally unacceptable.","zh":"现代读者会觉得，这样天真的结局安排完全无法接受。","kind":"narration","speaker":"旁白"},{"en":"Yet, in real life, circumstances do sometimes conspire to bring about coincidences which anyone but a nineteenth century novelist would find incredible.","zh":"然而在现实生活中，各种情形有时确实会凑在一起，造成一些巧合，除了十九世纪的小说家，任何人都会觉得不可思议。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"When I was a boy, my grandfather told me how a German taxi driver, Franz Bussman, found a brother who was thought to have been killed twenty years before.","zh":"我小时候，祖父曾告诉我，一个名叫弗朗茨·巴斯曼的德国出租车司机，如何找到了被认为二十年前就已遇难的兄弟。","kind":"narration","speaker":"旁白"},{"en":"While on a walking tour with his wife, he stopped to talk to a workman.","zh":"他和妻子在徒步旅行途中停下来，同一个工人聊了几句。","kind":"narration","speaker":"旁白"},{"en":"After they had gone on, Mrs. Bussman commented on the workman's close resemblance to her husband and even suggested that he might be his brother.","zh":"他们继续往前走后，巴斯曼夫人谈到那工人的相貌和丈夫极其相像，甚至提出那人也许就是他的兄弟。","kind":"narration","speaker":"旁白"},{"en":"Franz poured scorn on the idea, pointing out that his brother had been killed in action during the war.","zh":"弗朗茨对这个想法嗤之以鼻，并指出自己的兄弟在战争中已经阵亡。","kind":"narration","speaker":"旁白"},{"en":"Though Mrs. Bussman was fully acquainted with this story, she thought that there was a chance in a million that she might be right.","zh":"巴斯曼夫人虽然对这件往事一清二楚，却觉得自己的猜测也许还有百万分之一的可能是对的。","kind":"narration","speaker":"旁白"},{"en":"A few days later, she sent a boy to the workman to ask him if his name was Hans Bussman.","zh":"几天后，她派一个男孩去找那个工人，问他是否叫汉斯·巴斯曼。","kind":"narration","speaker":"旁白"},{"en":"Needless to say, the man’s name was Hans Bussman and he really was Franz’s long-lost brother.","zh":"不用说，那人果然叫汉斯·巴斯曼，而且确实就是弗朗茨失散多年的兄弟。","kind":"narration","speaker":"旁白"},{"en":"When the brothers were reunited, Hans explained how it was that he was still alive.","zh":"兄弟俩重逢时，汉斯解释了自己究竟是怎样活下来的。","kind":"narration","speaker":"旁白"},{"en":"After having been wounded towards the end of the war, he had been sent to hospital and was separated from his unit.","zh":"战争将近结束时，他负了伤，被送进医院，因此和部队失去了联系。","kind":"narration","speaker":"旁白"},{"en":"The hospital had been bombed and Hans had made his way back into Western Germany on foot.","zh":"医院遭到轰炸，汉斯步行返回了德国西部。","kind":"narration","speaker":"旁白"},{"en":"Meanwhile, his unit was lost and all records of him had been destroyed.","zh":"这期间，他所在的部队已不复存在，关于他的全部档案也都毁掉了。","kind":"narration","speaker":"旁白"},{"en":"Hans returned to his family home, but the house had been bombed and no one in the neighbourhood knew what had become of the inhabitants.","zh":"汉斯回到了家，可房子已经被炸毁，邻居们谁也不知道原来的住户后来怎么样了。","kind":"narration","speaker":"旁白"},{"en":"Assuming that his family had been killed during an air raid, Hans settled down in a village fifty miles away where he had remained ever since.","zh":"汉斯以为家人都死于一次空袭，就在五十英里外的一个村子定居下来，从此一直住在那里。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"bring something to a conclusion","matchedForm":"bring his story to a conclusion","meaning":"使……结束","note":"bring 后接事物，再接 to a conclusion；这里表示给故事收尾。","example":"In the nineteenth century, a novelist would bring his story to a conclusion by presenting his readers with a series of coincidences — most of them wildly improbable.","exampleZh":"十九世纪的小说家常用一连串巧合来收束故事，其中大多数巧合都离奇得令人难以相信。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"bring about","matchedForm":"bring about","meaning":"造成；促使发生","note":"常搭配 change、downfall 等结果，不表示把具体物品带来。","example":"A long-lost brother, who was presumed dead, was really alive all the time and wickedly plotting to bring about the hero’s downfall.","exampleZh":"一个失散多年、被认为已经死去的兄弟，其实一直活着，还在恶毒地密谋让男主人公垮台。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"pour scorn on","matchedForm":"poured scorn on","meaning":"对……嗤之以鼻","note":"scorn 表示强烈轻蔑，语气比普通的 disagree 更重。","example":"Franz poured scorn on the idea, pointing out that his brother had been killed in action during the war.","exampleZh":"弗朗茨对这个想法嗤之以鼻，并指出自己的兄弟在战争中已经阵亡。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"needless to say","matchedForm":"Needless to say","meaning":"不用说","note":"常作句首评注语，引出读者可以预料到的情况。","example":"Needless to say, the man’s name was Hans Bussman and he really was Franz’s long-lost brother.","exampleZh":"不用说，那人果然叫汉斯·巴斯曼，而且确实就是弗朗茨失散多年的兄弟。","sourceParagraphIndex":1,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"settle down","matchedForm":"settled down","meaning":"定居下来","note":"这里指开始长期居住；还可表示生活逐渐安定。","example":"Assuming that his family had been killed during an air raid, Hans settled down in a village fifty miles away where he had remained ever since.","exampleZh":"汉斯以为家人都死于一次空袭，就在五十英里外的一个村子定居下来，从此一直住在那里。","sourceParagraphIndex":1,"sourceSentenceIndex":12,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l037","book":3,"number":37,"title":"The Westhaven Express","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"We have learnt to expect that trains will be punctual.","zh":"我们已经习惯了认为火车应当准时。","kind":"narration","speaker":"旁白"},{"en":"After years of conditioning, most of us have developed an unshakable faith in railway timetables.","zh":"经过多年的习惯养成，我们大多数人对铁路时刻表有了不可动摇的信任。","kind":"narration","speaker":"旁白"},{"en":"Ships may be delayed by storms; flights may be cancelled because of bad weather; but trains must be on time.","zh":"轮船可能因风暴而延误，航班可能因恶劣天气而取消，但火车一定得准点。","kind":"narration","speaker":"旁白"},{"en":"Only an exceptionally heavy snowfall might temporarily dislocate railway services.","zh":"只有格外猛烈的降雪，才可能暂时打乱铁路运输。","kind":"narration","speaker":"旁白"},{"en":"It is all too easy to blame the railway authorities when something does go wrong.","zh":"一旦真出了什么岔子，人们太容易把责任推给铁路部门了。","kind":"narration","speaker":"旁白"},{"en":"The truth is that when mistakes occur, they are more likely to be ours than theirs.","zh":"事实上，出了差错时，更有可能是我们自己出了错，而非铁路部门。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"After consulting my railway timetable, I noted with satisfaction that there was an express train to Westhaven.","zh":"查过铁路时刻表以后，我满意地发现有一班开往韦斯特黑文的快车。","kind":"narration","speaker":"旁白"},{"en":"It went direct from my local station and the journey lasted a mere hour and seventeen minutes.","zh":"它从我当地的车站直达目的地，全程只需一小时十七分钟。","kind":"narration","speaker":"旁白"},{"en":"When I boarded the train, I could not help noticing that a great many local people got on as well.","zh":"上车时，我不由得注意到还有很多当地人也上了车。","kind":"narration","speaker":"旁白"},{"en":"At the time, this did not strike me as odd.","zh":"当时我并不觉得这有什么奇怪。","kind":"narration","speaker":"旁白"},{"en":"I reflected that there must be a great many people besides myself who wished to take advantage of this excellent service.","zh":"我想，除我以外，一定还有许多人也希望享受这么好的列车服务。","kind":"thought","speaker":"叙述者"},{"en":"Neither was I surprised when the train stopped at Widley, a tiny station a few miles along the line.","zh":"列车在沿线几英里外的一个小站威德利停下时，我也并不惊讶。","kind":"narration","speaker":"旁白"},{"en":"Even a mighty express train can be held up by signals.","zh":"就连气势十足的快车，也可能因为信号而停下来等候。","kind":"narration","speaker":"旁白"},{"en":"But when the train dawdled at station after station, I began to wonder.","zh":"可是，火车一站接着一站地磨蹭，我便开始犯嘀咕了。","kind":"narration","speaker":"旁白"},{"en":"It suddenly dawned on me that this express was not roaring down the line at ninety miles an hour, but barely chugging along at thirty.","zh":"我猛然明白，这趟快车并没有以每小时九十英里的速度沿着铁路线疾驰，而是在以勉强每小时三十英里的速度吭哧吭哧地慢行。","kind":"narration","speaker":"旁白"},{"en":"One hour and seventeen minutes passed and we had not even covered half the distance.","zh":"一小时十七分钟过去了，我们连一半的路程都还没走完。","kind":"narration","speaker":"旁白"},{"en":"I asked a passenger if this was the Westhaven Express, but he had not even heard of it.","zh":"我问一位乘客这是不是韦斯特黑文快车，他却连听都没听说过。","kind":"narration","speaker":"旁白"},{"en":"I determined to lodge a complaint as soon as we arrived.","zh":"我打定主意，一到站就提出投诉。","kind":"narration","speaker":"旁白"},{"en":"Two hours later, I was talking angrily to the station master at Westhaven.","zh":"两小时后，我正在韦斯特黑文气愤地向站长诉说。","kind":"narration","speaker":"旁白"},{"en":"When he denied the train’s existence, I borrowed his copy of the timetable.","zh":"站长说根本没有这趟列车，我就借来了他的时刻表。","kind":"narration","speaker":"旁白"},{"en":"There was a note of triumph in my voice when I told him that it was there in black and white.","zh":"我告诉他表上白纸黑字写着呢，声音里带着几分得意。","kind":"narration","speaker":"旁白"},{"en":"Glancing at it briefly, he told me to look again.","zh":"他匆匆瞥了一眼，叫我再仔细看看。","kind":"narration","speaker":"旁白"},{"en":"A tiny asterisk conducted me to a footnote at the bottom of the page.","zh":"一个小小的星号把我的视线引到了页面底部的一条注释上。","kind":"narration","speaker":"旁白"},{"en":"It said: ‘This service has been suspended.’","zh":"上面写着：“本次列车已停运。”","kind":"note","speaker":"铁路时刻表注释"}]}],"usage":[{"phrase":"on time","matchedForm":"on time","meaning":"准时","note":"指在规定或约定的时间；与表示来得及的 in time 区别开。","example":"Ships may be delayed by storms; flights may be cancelled because of bad weather; but trains must be on time.","exampleZh":"轮船可能因风暴而延误，航班可能因恶劣天气而取消，但火车一定得准点。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"go wrong","matchedForm":"go wrong","meaning":"出岔子","note":"does go wrong 中 does 用来加强语气，go 仍用原形。","example":"It is all too easy to blame the railway authorities when something does go wrong.","exampleZh":"一旦真出了什么岔子，人们太容易把责任推给铁路部门了。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"cannot help doing","matchedForm":"could not help noticing","meaning":"不由得注意到","note":"cannot help 后接动名词，表示无法抑制某种反应；不是不能帮助。","example":"When I boarded the train, I could not help noticing that a great many local people got on as well.","exampleZh":"上车时，我不由得注意到还有很多当地人也上了车。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"dawn on someone","matchedForm":"dawned on me","meaning":"使某人突然明白","note":"常用 it dawns on someone that... 表示某个道理逐渐或突然进入意识。","example":"It suddenly dawned on me that this express was not roaring down the line at ninety miles an hour, but barely chugging along at thirty.","exampleZh":"我猛然明白，这趟快车并没有以每小时九十英里的速度沿着铁路线疾驰，而是在以勉强每小时三十英里的速度吭哧吭哧地慢行。","sourceParagraphIndex":1,"sourceSentenceIndex":8,"sourceType":"textbook-passage"},{"phrase":"in black and white","matchedForm":"in black and white","meaning":"白纸黑字地","note":"这里指书面记载清清楚楚，可用来强调有文字为证。","example":"There was a note of triumph in my voice when I told him that it was there in black and white.","exampleZh":"我告诉他表上白纸黑字写着呢，声音里带着几分得意。","sourceParagraphIndex":1,"sourceSentenceIndex":14,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l038","book":3,"number":38,"title":"The first calendar","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Future historians will be in a unique position when they come to record the history of our own times.","zh":"未来的历史学家在记述我们这个时代的历史时，将具备独特的有利条件。","kind":"narration","speaker":"旁白"},{"en":"They will hardly know which facts to select from the great mass of evidence that steadily accumulates.","zh":"面对不断积累的大量史料，他们几乎不知道该挑选哪些事实才好。","kind":"narration","speaker":"旁白"},{"en":"What is more, they will not have to rely solely on the written word.","zh":"而且，他们不必只依赖文字记载。","kind":"narration","speaker":"旁白"},{"en":"Films, videos, CDs and CD-ROMs are just some of the bewildering amount of information they will have.","zh":"电影、录像、光盘和只读光盘，不过是他们届时掌握的、数量多得令人眼花缭乱的信息中的一部分。","kind":"narration","speaker":"旁白"},{"en":"They will be able, as it were, to see and hear us in action.","zh":"可以说，他们将能亲眼看见、亲耳听见我们活动时的情形。","kind":"narration","speaker":"旁白"},{"en":"But the historian attempting to reconstruct the distant past is always faced with a difficult task.","zh":"然而，想要重建遥远往昔的历史学家，总会面临一项艰难的任务。","kind":"narration","speaker":"旁白"},{"en":"He has to deduce what he can from the few scanty clues available.","zh":"他只能根据现存的寥寥几条线索，尽可能作出推断。","kind":"narration","speaker":"旁白"},{"en":"Even seemingly insignificant remains can shed interesting light on the history of early man.","zh":"即使看似无关紧要的遗存，也能为理解早期人类的历史提供有意思的启示。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Up to now, historians have assumed that calendars came into being with the advent of agriculture, for then man was faced with a real need to understand something about the seasons.","zh":"迄今为止，历史学家一直认为，历法随着农业的出现而产生，因为到了那时，人类才真正需要对季节有所了解。","kind":"narration","speaker":"旁白"},{"en":"Recent scientific evidence seems to indicate that this assumption is incorrect.","zh":"近来的科学证据似乎表明，这个假设并不正确。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"Historians have long been puzzled by dots, lines and symbols which have been engraved on walls, bones, and the ivory tusks of mammoths.","zh":"刻在墙壁、骨头和猛犸象牙上的那些点、线和符号，长期以来一直困扰着历史学家。","kind":"narration","speaker":"旁白"},{"en":"The nomads who made these markings lived by hunting and fishing during the last Ice Age which began about 35,000 B.C. and ended about 10,000 B.C.","zh":"留下这些记号的游牧人，生活在大约始于公元前三万五千年、终于公元前一万年的最后一个冰期，以狩猎和捕鱼为生。","kind":"narration","speaker":"旁白"},{"en":"By correlating markings made in various parts of the world, historians have been able to read this difficult code.","zh":"通过比对世界各地的记号，历史学家已经能够解读这种难懂的密码。","kind":"narration","speaker":"旁白"},{"en":"They have found that it is connected with the passage of days and the phases of the moon.","zh":"他们发现，它与日子的流逝和月相的变化有关。","kind":"narration","speaker":"旁白"},{"en":"It is, in fact, a primitive type of calendar.","zh":"实际上，这是一种原始的历法。","kind":"narration","speaker":"旁白"},{"en":"It has long been known that the hunting scenes depicted on walls were not simply a form of artistic expression.","zh":"人们早已知道，墙壁上描绘的狩猎场景并非仅仅是艺术表现形式。","kind":"narration","speaker":"旁白"},{"en":"They had a definite meaning, for they were as near as early man could get to writing.","zh":"这些画面具有明确的含义，因为对早期人类而言，它们已是最接近文字的表达方式。","kind":"narration","speaker":"旁白"},{"en":"It is possible that there is a definite relation between these paintings and the markings that sometimes accompany them.","zh":"这些画与有时出现在它们旁边的记号之间，可能存在某种确定的联系。","kind":"narration","speaker":"旁白"},{"en":"It seems that man was making a real effort to understand the seasons 20,000 years earlier than has been supposed.","zh":"看来，人类开始认真尝试了解季节的时间，比过去推测的还早两万年。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"what is more","matchedForm":"What is more","meaning":"而且；更有甚者","note":"在已有论据之外补充一层意思，常在句首后接逗号。","example":"What is more, they will not have to rely solely on the written word.","exampleZh":"而且，他们不必只依赖文字记载。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"as it were","matchedForm":"as it were","meaning":"可以说；仿佛","note":"用于提示后面的说法带有比喻或不完全按字面理解的意味。","example":"They will be able, as it were, to see and hear us in action.","exampleZh":"可以说，他们将能亲眼看见、亲耳听见我们活动时的情形。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"shed light on","matchedForm":"shed interesting light on","meaning":"为理解……提供启示","note":"shed light on 表示帮助澄清问题，light 在这里是不可数名词。","example":"Even seemingly insignificant remains can shed interesting light on the history of early man.","exampleZh":"即使看似无关紧要的遗存，也能为理解早期人类的历史提供有意思的启示。","sourceParagraphIndex":0,"sourceSentenceIndex":7,"sourceType":"textbook-passage"},{"phrase":"come into being","matchedForm":"came into being","meaning":"产生；开始存在","note":"表示事物出现，不等于表示实行的 come into effect。","example":"Up to now, historians have assumed that calendars came into being with the advent of agriculture, for then man was faced with a real need to understand something about the seasons.","exampleZh":"迄今为止，历史学家一直认为，历法随着农业的出现而产生，因为到了那时，人类才真正需要对季节有所了解。","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"be connected with","matchedForm":"is connected with","meaning":"与……有关","note":"描述事物之间的联系；with 后接相关对象。","example":"They have found that it is connected with the passage of days and the phases of the moon.","exampleZh":"他们发现，它与日子的流逝和月相的变化有关。","sourceParagraphIndex":2,"sourceSentenceIndex":3,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l039","book":3,"number":39,"title":"Nothing to worry about","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"The rough road across the plain soon became so bad that we tried to get Bruce to drive back to the village we had come from.","zh":"穿过平原的那条崎岖道路很快就糟糕得让我们试图劝布鲁斯把车开回出发的村庄。","kind":"narration","speaker":"旁白"},{"en":"Even though the road was littered with boulders and pitted with holes, Bruce was not in the least perturbed.","zh":"尽管路上大石遍地、坑洼密布，布鲁斯却丝毫不为所动。","kind":"narration","speaker":"旁白"},{"en":"Glancing at his map, he informed us that the next village was a mere twenty miles away.","zh":"他瞥了一眼地图，告诉我们下一个村子离这里只有二十英里。","kind":"narration","speaker":"旁白"},{"en":"It was not that Bruce always underestimated difficulties.","zh":"这并不是说布鲁斯总把困难估计得太轻。","kind":"narration","speaker":"旁白"},{"en":"He simply had no sense of danger at all.","zh":"他只是完全没有危险意识。","kind":"narration","speaker":"旁白"},{"en":"No matter what the conditions were, he believed that a car should be driven as fast as it could possibly go.","zh":"无论路况怎样，他都认为车就应该开到能开的最快速度。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"As we bumped over the dusty track, we swerved to avoid large boulders.","zh":"我们在尘土飞扬的小路上颠簸前进，不时急转方向躲避大石。","kind":"narration","speaker":"旁白"},{"en":"The wheels scooped up stones which hammered ominously under the car.","zh":"车轮卷起石块，石块在车底敲得砰砰响，让人觉得不祥。","kind":"narration","speaker":"旁白"},{"en":"We felt sure that sooner or later a stone would rip a hole in our petrol tank or damage the engine.","zh":"我们认定，迟早会有石块把油箱划出一个洞，或者把发动机撞坏。","kind":"narration","speaker":"旁白"},{"en":"Because of this, we kept looking back, wondering if we were leaving a trail of oil and petrol behind us.","zh":"正因为如此，我们不断向后张望，担心身后是不是已经留下一路机油和汽油。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"What a relief it was when the boulders suddenly disappeared, giving way to a stretch of plain where the only obstacles were clumps of bushes.","zh":"大石突然不见了，眼前换成一片平地，障碍只剩下一丛丛灌木，我们不禁大大松了口气。","kind":"narration","speaker":"旁白"},{"en":"But there was worse to come.","zh":"可是，更糟的事还在后头。","kind":"narration","speaker":"旁白"},{"en":"Just ahead of us there was a huge fissure.","zh":"就在前面，地上出现了一道大裂缝。","kind":"narration","speaker":"旁白"},{"en":"In response to renewed pleadings, Bruce stopped.","zh":"在我们又一次苦苦请求之下，布鲁斯停了车。","kind":"narration","speaker":"旁白"},{"en":"Though we all got out to examine the fissure, he remained in the car.","zh":"我们都下车查看裂缝，他却仍坐在车里。","kind":"narration","speaker":"旁白"},{"en":"We informed him that the fissure extended for fifty yards and was two feet wide and four feet deep.","zh":"我们告诉他，这道裂缝长达五十码，宽两英尺，深四英尺。","kind":"narration","speaker":"旁白"},{"en":"Even this had no effect.","zh":"就连这样也没起作用。","kind":"narration","speaker":"旁白"},{"en":"Bruce went into a low gear and drove at a terrifying speed, keeping the front wheels astride the crack as he followed its zigzag course.","zh":"布鲁斯挂上低挡，以吓人的速度往前开，让两个前轮跨在裂缝两侧，沿着弯弯曲曲的裂缝前进。","kind":"narration","speaker":"旁白"},{"en":"Before we had time to worry about what might happen, we were back on the plain again.","zh":"我们还来不及担心会出什么事，就又回到了平地上。","kind":"narration","speaker":"旁白"},{"en":"Bruce consulted the map once more and told us that the village was now only fifteen miles away.","zh":"布鲁斯又看了一次地图，告诉我们现在离村子只有十五英里了。","kind":"narration","speaker":"旁白"},{"en":"Our next obstacle was a shallow pool of water about half a mile across.","zh":"下一个障碍是一片浅水洼，横跨约半英里。","kind":"narration","speaker":"旁白"},{"en":"Bruce charged at it, but in the middle, the car came to a grinding halt.","zh":"布鲁斯驾车冲了进去，可到了中间，车便嘎然停住了。","kind":"narration","speaker":"旁白"},{"en":"A yellow light on the dashboard flashed angrily and Bruce cheerfully announced that there was no oil in the engine!","zh":"仪表盘上的一盏黄灯气急败坏似的闪着，布鲁斯却兴高采烈地宣布，发动机里没机油了！","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"not in the least","matchedForm":"not in the least","meaning":"一点也不","note":"用来加强否定，常修饰 worried、surprised 等形容词。","example":"Even though the road was littered with boulders and pitted with holes, Bruce was not in the least perturbed.","exampleZh":"尽管路上大石遍地、坑洼密布，布鲁斯却丝毫不为所动。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"sooner or later","matchedForm":"sooner or later","meaning":"迟早","note":"表示时间不确定，但说话人认为事情终会发生。","example":"We felt sure that sooner or later a stone would rip a hole in our petrol tank or damage the engine.","exampleZh":"我们认定，迟早会有石块把油箱划出一个洞，或者把发动机撞坏。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"give way to","matchedForm":"giving way to","meaning":"被……取代","note":"这里描述景物转变，不是向某人让步的含义。","example":"What a relief it was when the boulders suddenly disappeared, giving way to a stretch of plain where the only obstacles were clumps of bushes.","exampleZh":"大石突然不见了，眼前换成一片平地，障碍只剩下一丛丛灌木，我们不禁大大松了口气。","sourceParagraphIndex":2,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"in response to","matchedForm":"In response to","meaning":"应……而；作为对……的回应","note":"to 是介词，后接请求、变化或刺激等名词。","example":"In response to renewed pleadings, Bruce stopped.","exampleZh":"在我们又一次苦苦请求之下，布鲁斯停了车。","sourceParagraphIndex":2,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"come to a grinding halt","matchedForm":"came to a grinding halt","meaning":"嘎然停住；突然彻底停下","note":"可形容车辆骤停，也可引申为工作或活动突然停顿。","example":"Bruce charged at it, but in the middle, the car came to a grinding halt.","exampleZh":"布鲁斯驾车冲了进去，可到了中间，车便嘎然停住了。","sourceParagraphIndex":2,"sourceSentenceIndex":11,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-fa4874-l040","book":3,"number":40,"title":"Who’s who","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"It has never been explained why university students seem to enjoy practical jokes more than anyone else.","zh":"大学生为什么似乎比其他人都更喜欢恶作剧，这一点始终没有人解释清楚。","kind":"narration","speaker":"旁白"},{"en":"Students specialize in a particular type of practical joke: the hoax.","zh":"学生尤其擅长一种特殊的恶作剧：设骗局捉弄人。","kind":"narration","speaker":"旁白"},{"en":"Inviting the fire brigade to put out a nonexistent fire is a crude form of deception which no self-respecting student would ever indulge in.","zh":"叫消防队来扑灭根本不存在的火，是一种粗劣的骗术；凡是有自尊心的学生，都不会干这种事。","kind":"narration","speaker":"旁白"},{"en":"Students often create amusing situations which are funny to everyone except the victims.","zh":"学生常常制造出一些有趣的场面，除了受害者，人人都觉得好笑。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"When a student recently saw two workmen using a pneumatic drill outside his university, he immediately telephoned the police and informed them that two students dressed up as workmen were tearing up the road with a pneumatic drill.","zh":"最近，一名学生看见两个工人在大学外用风钻干活，就立刻给警察打电话，说有两个学生装扮成工人，正在用风钻挖马路。","kind":"narration","speaker":"旁白"},{"en":"As soon as he had hung up, he went over to the workmen and told them that if a policeman ordered them to go away, they were not to take him seriously.","zh":"电话一挂，他就走到工人跟前，告诉他们，如果有警察叫他们离开，不必当真。","kind":"narration","speaker":"旁白"},{"en":"He added that a student had dressed up as a policeman and was playing all sorts of silly jokes on people.","zh":"他还说，有个学生扮成警察，正在到处跟人开各种无聊的玩笑。","kind":"narration","speaker":"旁白"},{"en":"Both the police and the workmen were grateful to the student for this piece of advance information.","zh":"警察和工人都很感激这个学生提前通风报信。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"The student hid in an archway nearby where he could watch and hear everything that went on.","zh":"学生藏进附近一个拱门里，在那里既能看见，又能听见事情的全部经过。","kind":"narration","speaker":"旁白"},{"en":"Sure enough, a policeman arrived on the scene and politely asked the workmen to go away.","zh":"果然，一个警察来到了现场，客气地请工人离开。","kind":"narration","speaker":"旁白"},{"en":"When he received a very rude reply from one of the workmen, he threatened to remove them by force.","zh":"一个工人非常粗鲁地回了他一句，他便威胁说要动用武力把他们赶走。","kind":"narration","speaker":"旁白"},{"en":"The workmen told him to do as he pleased and the policeman telephoned for help.","zh":"工人叫他随便怎么办，警察于是打电话求援。","kind":"narration","speaker":"旁白"},{"en":"Shortly afterwards, four more policemen arrived and remonstrated with the workmen.","zh":"没过多久，又来了四个警察，劝告并责备这两个工人。","kind":"narration","speaker":"旁白"},{"en":"As the men refused to stop working, the police attempted to seize the pneumatic drill.","zh":"工人不肯停工，警察就试图夺走风钻。","kind":"narration","speaker":"旁白"},{"en":"The workmen struggled fiercely and one of them lost his temper.","zh":"工人激烈反抗，其中一个发了脾气。","kind":"narration","speaker":"旁白"},{"en":"He threatened to call the police.","zh":"他扬言要报警。","kind":"narration","speaker":"旁白"},{"en":"At this, the police pointed out ironically that this would hardly be necessary as the men were already under arrest.","zh":"听到这话，警察讥讽地指出，大概没这个必要了，因为他们已经被逮捕了。","kind":"narration","speaker":"旁白"},{"en":"Pretending to speak seriously, one of the workmen asked if he might make a telephone call before being taken to the station.","zh":"一个工人装出一本正经的样子，问能不能在被带到警察局之前打个电话。","kind":"narration","speaker":"旁白"},{"en":"Permission was granted and a policeman accompanied him to a pay phone.","zh":"警察同意了，一个警察陪他走到一部公用电话旁。","kind":"narration","speaker":"旁白"},{"en":"Only when he saw that the man was actually telephoning the police did he realize that they had all been the victims of a hoax.","zh":"直到看见那人真的在给警察打电话，这个警察才明白，他们全都成了一场骗局的受害者。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"practical joke","matchedForm":"practical jokes","meaning":"恶作剧","note":"指用行动捉弄别人，不是单纯讲一个笑话；可用 play a practical joke on someone。","example":"It has never been explained why university students seem to enjoy practical jokes more than anyone else.","exampleZh":"大学生为什么似乎比其他人都更喜欢恶作剧，这一点始终没有人解释清楚。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"dress up as","matchedForm":"dressed up as","meaning":"装扮成","note":"as 后接扮演的身份，dress up 也可单独表示盛装或乔装。","example":"When a student recently saw two workmen using a pneumatic drill outside his university, he immediately telephoned the police and informed them that two students dressed up as workmen were tearing up the road with a pneumatic drill.","exampleZh":"最近，一名学生看见两个工人在大学外用风钻干活，就立刻给警察打电话，说有两个学生装扮成工人，正在用风钻挖马路。","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"take someone seriously","matchedForm":"take him seriously","meaning":"把某人的话当真","note":"seriously 放在宾语后；也可用 take something seriously 表示认真对待某事。","example":"As soon as he had hung up, he went over to the workmen and told them that if a policeman ordered them to go away, they were not to take him seriously.","exampleZh":"电话一挂，他就走到工人跟前，告诉他们，如果有警察叫他们离开，不必当真。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"sure enough","matchedForm":"Sure enough","meaning":"果然","note":"常引出证实预想的结果。","example":"Sure enough, a policeman arrived on the scene and politely asked the workmen to go away.","exampleZh":"果然，一个警察来到了现场，客气地请工人离开。","sourceParagraphIndex":2,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"lose one’s temper","matchedForm":"lost his temper","meaning":"发脾气","note":"temper 在这里指脾气；所有格随发怒的人变化。","example":"The workmen struggled fiercely and one of them lost his temper.","exampleZh":"工人激烈反抗，其中一个发了脾气。","sourceParagraphIndex":2,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"under arrest","matchedForm":"under arrest","meaning":"被逮捕；在拘捕中","note":"arrest 在此固定表达中不加冠词，常与 be 或 place 搭配。","example":"At this, the police pointed out ironically that this would hardly be necessary as the men were already under arrest.","exampleZh":"听到这话，警察讥讽地指出，大概没这个必要了，因为他们已经被逮捕了。","sourceParagraphIndex":2,"sourceSentenceIndex":8,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-140ed4-l041","book":3,"number":41,"title":"Illusions of pastoral peace","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"The quiet life of the country has never appealed to me.","zh":"乡村宁静的生活从来没有吸引过我。","kind":"narration","speaker":"旁白"},{"en":"City born and city bred, I have always regarded the country as something you look at through a train window, or something you occasionally visit during the weekend.","zh":"我生在城里、长在城里，一向觉得乡村是坐火车时从车窗里看看的景色，或者偶尔周末去一趟的地方。","kind":"narration","speaker":"旁白"},{"en":"Most of my friends live in the city, yet they always go into raptures at the mere mention of the country.","zh":"我的朋友大多住在城里，可是一提到乡村，他们就总会兴奋得赞不绝口。","kind":"narration","speaker":"旁白"},{"en":"Though they extol the virtues of the peaceful life, only one of them has ever gone to live in the country and he was back in town within six months.","zh":"他们虽然极力赞美宁静生活的种种好处，却只有一个人真的搬到乡下住过，而他不到六个月就回城了。","kind":"narration","speaker":"旁白"},{"en":"Even he still lives under the illusion that country life is somehow superior to town life.","zh":"即便是他，也仍然抱着一种错觉，觉得乡村生活总归比城市生活更好。","kind":"narration","speaker":"旁白"},{"en":"He is forever talking about the friendly people, the clean atmosphere, the closeness to nature and the gentle pace of living.","zh":"他没完没了地谈论友善的居民、清新的空气、与大自然的亲近，以及悠缓的生活节奏。","kind":"narration","speaker":"旁白"},{"en":"Nothing can be compared, he maintains, with the first cockcrow, the twittering of birds at dawn, the sight of the rising sun glinting on the trees and pastures.","zh":"他坚称，无论什么都比不上清晨第一声鸡啼、黎明时鸟儿的啁啾，以及初升的阳光在树木和牧场上闪耀的景象。","kind":"narration","speaker":"旁白"},{"en":"This idyllic pastoral scene is only part of the picture.","zh":"这番诗情画意的田园景色，只反映了实际情况的一部分。","kind":"narration","speaker":"旁白"},{"en":"My friend fails to mention the long and friendless winter evenings in front of the TV — virtually the only form of entertainment.","zh":"我的朋友没有提到，冬夜漫长又孤寂，只能守着电视机度日——这实际上是唯一的娱乐。","kind":"narration","speaker":"旁白"},{"en":"He says nothing about the poor selection of goods in the shops, or about those unfortunate people who have to travel from the country to the city every day to get to work.","zh":"他也绝口不提商店里可供挑选的商品少得可怜，更不提那些不幸的人，他们每天不得不从乡下赶到城里上班。","kind":"narration","speaker":"旁白"},{"en":"Why people are prepared to tolerate a four-hour journey each day for the dubious privilege of living in the country is beyond me.","zh":"为了享受住在乡下这种好处难说的“特权”，人们竟甘愿每天忍受四小时的路程，这真让我无法理解。","kind":"narration","speaker":"旁白"},{"en":"They could be saved so much misery and expense if they chose to live in the city where they rightly belong.","zh":"如果他们选择住在本来就适合自己的城里，就能省掉那么多苦恼和开销。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"If you can do without the few pastoral pleasures of the country, you will find the city can provide you with the best that life can offer.","zh":"如果你可以舍弃乡村那几样田园乐趣，就会发现，城市能把生活中最美好的享受提供给你。","kind":"narration","speaker":"旁白"},{"en":"You never have to travel miles to see your friends.","zh":"你永远用不着跑上好几英里去看朋友。","kind":"narration","speaker":"旁白"},{"en":"They invariably live nearby and are always available for an informal chat or an evening’s entertainment.","zh":"他们总住在附近，随时都能一起随意聊聊天，或者共度一个娱乐之夜。","kind":"narration","speaker":"旁白"},{"en":"Some of my acquaintances in the country come up to town once or twice a year to visit the theatre as a special treat.","zh":"我在乡下认识的一些人，每年只进城一两次看戏，把这当作特别的享受。","kind":"narration","speaker":"旁白"},{"en":"For them this is a major operation which involves considerable planning.","zh":"对他们来说，这是一件大事，需要做相当多的安排。","kind":"narration","speaker":"旁白"},{"en":"As the play draws to its close, they wonder whether they will ever catch that last train home.","zh":"戏快演完时，他们就开始担心，自己到底能不能赶上回家的末班火车。","kind":"narration","speaker":"旁白"},{"en":"The city dweller never experiences anxieties of this sort.","zh":"城里人从来不会为这类事情焦虑。","kind":"narration","speaker":"旁白"},{"en":"The latest exhibitions, films, or plays are only a short bus ride away.","zh":"坐一小段公交车，就能看到最新的展览、电影或戏剧。","kind":"narration","speaker":"旁白"},{"en":"Shopping, too, is always a pleasure.","zh":"购物也总是件乐事。","kind":"narration","speaker":"旁白"},{"en":"There is so much variety that you never have to make do with second best.","zh":"商品品种如此丰富，你永远不必退而求其次。","kind":"narration","speaker":"旁白"},{"en":"Country people run wild when they go shopping in the city and stagger home loaded with as many of the exotic items as they can carry.","zh":"乡下人进城购物时就像脱了缰一般，尽量买满自己能拿得动的新奇物件，满载着踉跄回家。","kind":"narration","speaker":"旁白"},{"en":"Nor is the city without its moments of beauty.","zh":"城市也并非没有美丽的时刻。","kind":"narration","speaker":"旁白"},{"en":"There is something comforting about the warm glow shed by advertisements on cold wet winter nights.","zh":"在寒冷潮湿的冬夜，广告灯散发出的暖光让人觉得有几分慰藉。","kind":"narration","speaker":"旁白"},{"en":"Few things could be more impressive than the peace that descends on deserted city streets at weekends when the thousands that travel to work every day are tucked away in their homes in the country.","zh":"每天进城上班的成千上万人，周末都躲回乡下家中，空荡荡的城市街道于是笼罩在一片宁静里；很少有什么景象能比这更让人印象深刻。","kind":"narration","speaker":"旁白"},{"en":"It has always been a mystery to me why city dwellers, who appreciate all these things, obstinately pretend that they would prefer to live in the country.","zh":"城里人明明懂得欣赏这一切，却偏要固执地装作更愿意住在乡下，这一直让我百思不解。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"appeal to","matchedForm":"appealed to","meaning":"对……有吸引力","note":"以事物作主语、以人作 to 的宾语；这里不是呼吁的意思。","example":"The quiet life of the country has never appealed to me.","exampleZh":"乡村宁静的生活从来没有吸引过我。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"go into raptures","matchedForm":"go into raptures","meaning":"欣喜若狂；赞不绝口","note":"raptures 用复数，常用 over 或 about 引出令人兴奋的事。","example":"Most of my friends live in the city, yet they always go into raptures at the mere mention of the country.","exampleZh":"我的朋友大多住在城里，可是一提到乡村，他们就总会兴奋得赞不绝口。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"live under the illusion that","matchedForm":"lives under the illusion that","meaning":"抱着……的错觉生活","note":"that 引出错觉的具体内容；语气表示说话人认为这想法不符合实际。","example":"Even he still lives under the illusion that country life is somehow superior to town life.","exampleZh":"即便是他，也仍然抱着一种错觉，觉得乡村生活总归比城市生活更好。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"do without","matchedForm":"do without","meaning":"没有……也能过；舍弃","note":"后接名词或动名词，强调在缺少某物时仍能应付。","example":"If you can do without the few pastoral pleasures of the country, you will find the city can provide you with the best that life can offer.","exampleZh":"如果你可以舍弃乡村那几样田园乐趣，就会发现，城市能把生活中最美好的享受提供给你。","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"draw to a close","matchedForm":"draws to its close","meaning":"接近尾声","note":"主语通常是会议、演出或一段时期；its close 是带所有格的变体。","example":"As the play draws to its close, they wonder whether they will ever catch that last train home.","exampleZh":"戏快演完时，他们就开始担心，自己到底能不能赶上回家的末班火车。","sourceParagraphIndex":1,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"make do with","matchedForm":"make do with","meaning":"拿……将就；凑合使用","note":"with 引出并不完全令人满意的替代物，常带退而求其次的意味。","example":"There is so much variety that you never have to make do with second best.","exampleZh":"商品品种如此丰富，你永远不必退而求其次。","sourceParagraphIndex":1,"sourceSentenceIndex":9,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-f4cefe-l042","book":3,"number":42,"title":"Modern cavemen","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Cave exploration, or pot-holing, as it has come to be known, is a relatively new sport.","zh":"洞穴探险，也就是如今人们所说的“探洞”，是一项相对新兴的运动。","kind":"narration","speaker":"旁白"},{"en":"Perhaps it is the desire for solitude or the chance of making an unexpected discovery that lures people down to the depths of the earth.","zh":"也许是渴望独处，也许是期待意外发现的机会，吸引着人们深入地下。","kind":"narration","speaker":"旁白"},{"en":"It is impossible to give a satisfactory explanation for a pot-holer’s motives.","zh":"要为探洞者的动机作出令人满意的解释，是不可能的。","kind":"narration","speaker":"旁白"},{"en":"For him, caves have the same peculiar fascination which high mountains have for the climber.","zh":"对探洞者来说，洞穴有着一种特殊的吸引力，正如高山之于登山者一样。","kind":"narration","speaker":"旁白"},{"en":"They arouse instincts which can only be dimly understood.","zh":"它们唤起了某些本能，而人们对这些本能只能模糊地理解。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Exploring really deep caves is not a task for the Sunday afternoon rambler.","zh":"探察真正深邃的洞穴，可不是周日下午悠闲散步的人所能胜任的。","kind":"narration","speaker":"旁白"},{"en":"Such undertakings require the precise planning and foresight of military operations.","zh":"这种行动需要像军事行动一样周密地筹划，预先考虑各种情况。","kind":"narration","speaker":"旁白"},{"en":"It can take as long as eight days to rig up rope ladders and to establish supply bases before a descent can be made into a very deep cave.","zh":"在能够下到一个极深的洞穴之前，光是架设绳梯、建立补给基地，就可能需要长达八天。","kind":"narration","speaker":"旁白"},{"en":"Precautions of this sort are necessary, for it is impossible to foretell the exact nature of the difficulties which will confront the pot-holer.","zh":"采取这类预防措施很有必要，因为无法预知探洞者将会遇到的困难究竟是什么样的。","kind":"narration","speaker":"旁白"},{"en":"The deepest known cave in the world is the Gouffre Berger near Grenoble.","zh":"世界上已知最深的洞穴，是格勒诺布尔附近的贝尔热深洞。","kind":"narration","speaker":"旁白"},{"en":"It extends to a depth of 3,723 feet.","zh":"它的深度达到三千七百二十三英尺。","kind":"narration","speaker":"旁白"},{"en":"This immense chasm has been formed by an underground stream which has tunnelled a course through a flaw in the rocks.","zh":"这道巨大的深渊是一条地下溪流沿着岩层的一处裂隙冲刷出通道而形成的。","kind":"narration","speaker":"旁白"},{"en":"The entrance to the cave is on a plateau in the Dauphiné Alps.","zh":"洞口位于多菲内阿尔卑斯山区的一片高原上。","kind":"narration","speaker":"旁白"},{"en":"As it is only six feet across, it is barely noticeable.","zh":"洞口横宽只有六英尺，几乎看不出来。","kind":"narration","speaker":"旁白"},{"en":"The cave might never have been discovered had not the entrance been spotted by the distinguished French pot-holer, Berger.","zh":"要不是法国著名探洞家贝尔热发现了洞口，这个洞穴也许永远不会被人发现。","kind":"narration","speaker":"旁白"},{"en":"Since its discovery, it has become a sort of pot-holers’ Everest.","zh":"自从被发现以来，它便成了探洞者心中某种意义上的珠穆朗玛峰。","kind":"narration","speaker":"旁白"},{"en":"Though a number of descents have been made, much of it still remains to be explored.","zh":"虽然已有不少人下去探察过，但洞内仍有很大一部分有待探索。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"A team of pot-holers recently went down the Gouffre Berger.","zh":"最近，一队探洞者下到了贝尔热深洞。","kind":"narration","speaker":"旁白"},{"en":"After entering the narrow gap on the plateau, they climbed down the steep sides of the cave until they came to a narrow corridor.","zh":"他们钻进高原上的狭窄裂口后，沿着陡峭的洞壁往下攀爬，直到来到一条狭窄的通道。","kind":"narration","speaker":"旁白"},{"en":"They had to edge their way along this, sometimes wading across shallow streams, or swimming across deep pools.","zh":"他们不得不侧着身子沿通道挪动，有时涉过浅溪，有时游过深潭。","kind":"narration","speaker":"旁白"},{"en":"Suddenly they came to a waterfall which dropped into an underground lake at the bottom of the cave.","zh":"突然，他们来到一处瀑布前，瀑布直落洞底的一个地下湖。","kind":"narration","speaker":"旁白"},{"en":"They plunged into the lake, and after loading their gear on an inflatable rubber dinghy, let the current carry them to the other side.","zh":"他们跳进湖里，把装备装到一只充气橡皮艇上，任凭水流把他们带到对岸。","kind":"narration","speaker":"旁白"},{"en":"To protect themselves from the icy water, they had to wear special rubber suits.","zh":"为了防止冰冷湖水的侵袭，他们必须穿上特制的橡胶服。","kind":"narration","speaker":"旁白"},{"en":"At the far end of the lake, they came to huge piles of rubble which had been washed up by the water.","zh":"到了湖的另一头，他们遇到了被水冲积起来的大堆碎石。","kind":"narration","speaker":"旁白"},{"en":"In this part of the cave, they could hear an insistent booming sound which they found was caused by a small waterspout shooting down into a pool from the roof of the cave.","zh":"在洞穴的这一部分，他们听到持续不断的轰鸣，后来发现，这是洞顶的一股细小水柱直冲下面水潭所发出的声音。","kind":"narration","speaker":"旁白"},{"en":"Squeezing through a cleft in the rocks, the pot-holers arrived at an enormous cavern, the size of a huge concert hall.","zh":"探洞者从岩石间的一条裂缝挤过去，来到一个庞大的洞厅，大小如同一座巨型音乐厅。","kind":"narration","speaker":"旁白"},{"en":"After switching on powerful arc lights, they saw great stalagmites — some of them over forty feet high — rising up like tree-trunks to meet the stalactites suspended from the roof.","zh":"打开强力弧光灯后，他们看到巨大的石笋，有的高达四十多英尺，像树干一样向上伸展，与洞顶垂下的钟乳石相接。","kind":"narration","speaker":"旁白"},{"en":"Round about, piles of limestone glistened in all the colours of the rainbow.","zh":"四周成堆的石灰岩闪烁着彩虹般的各种颜色。","kind":"narration","speaker":"旁白"},{"en":"In the eerie silence of the cavern, the only sound that could be heard was made by water which dripped continuously from the high dome above them.","zh":"洞厅里寂静得有些阴森，唯一听得见的声音，是头顶高高的穹窿上不断滴下的水声。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"have a fascination for","matchedForm":"have the same peculiar fascination","meaning":"具有同样特殊的吸引力","note":"fascination 表示强烈的吸引；可说 something has a fascination for someone。","example":"For him, caves have the same peculiar fascination which high mountains have for the climber.","exampleZh":"对探洞者来说，洞穴有着一种特殊的吸引力，正如高山之于登山者一样。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"rig up","matchedForm":"rig up","meaning":"搭设；架设","note":"常指为了眼前用途搭起设备或装置，这里搭配 rope ladders。","example":"It can take as long as eight days to rig up rope ladders and to establish supply bases before a descent can be made into a very deep cave.","exampleZh":"在能够下到一个极深的洞穴之前，光是架设绳梯、建立补给基地，就可能需要长达八天。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"remain to be done","matchedForm":"remains to be explored","meaning":"仍有待……","note":"remain 后接被动不定式，表示工作尚未完成；不是已经完成。","example":"Though a number of descents have been made, much of it still remains to be explored.","exampleZh":"虽然已有不少人下去探察过，但洞内仍有很大一部分有待探索。","sourceParagraphIndex":1,"sourceSentenceIndex":11,"sourceType":"textbook-passage"},{"phrase":"edge one’s way","matchedForm":"edge their way","meaning":"慢慢挪动前进","note":"edge 在这里作动词，常带有空间狭窄、必须小心移动的含义。","example":"They had to edge their way along this, sometimes wading across shallow streams, or swimming across deep pools.","exampleZh":"他们不得不侧着身子沿通道挪动，有时涉过浅溪，有时游过深潭。","sourceParagraphIndex":2,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"protect oneself from","matchedForm":"protect themselves from","meaning":"保护自己免受……","note":"from 后接危险或伤害来源；反身代词与主语一致。","example":"To protect themselves from the icy water, they had to wear special rubber suits.","exampleZh":"为了防止冰冷湖水的侵袭，他们必须穿上特制的橡胶服。","sourceParagraphIndex":2,"sourceSentenceIndex":5,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-63de95-l043","book":3,"number":43,"title":"Fully insured","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Insurance companies are normally willing to insure anything.","zh":"保险公司通常什么都愿意承保。","kind":"narration","speaker":"旁白"},{"en":"Insuring public or private property is a standard practice in most countries in the world.","zh":"在世界上大多数国家，为公共财产或私人财产投保都是惯常做法。","kind":"narration","speaker":"旁白"},{"en":"If, however, you were holding an open air garden party or a fete it would be equally possible to insure yourself in the event of bad weather.","zh":"不过，如果你要举办露天花园聚会或游园会，也同样可以投保，以防遇上坏天气。","kind":"narration","speaker":"旁白"},{"en":"Needless to say, the bigger the risk an insurance company takes, the higher the premium you will have to pay.","zh":"不用说，保险公司承担的风险越大，你需要支付的保险费也就越高。","kind":"narration","speaker":"旁白"},{"en":"It is not uncommon to hear that a shipping company has made a claim for the cost of salvaging a sunken ship.","zh":"听说某家航运公司为打捞沉船的费用提出索赔，并不稀奇。","kind":"narration","speaker":"旁白"},{"en":"But the claim made by a local authority to recover the cost of salvaging a sunken pie dish must surely be unique.","zh":"然而，一个地方当局竟为打捞沉入水底的馅饼盘所花的费用索赔，这想必真是独一无二了。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Admittedly it was an unusual pie dish, for it was eighteen feet long and six feet wide.","zh":"诚然，这可不是普通的馅饼盘，因为它长十八英尺、宽六英尺。","kind":"narration","speaker":"旁白"},{"en":"It had been purchased by a local authority so that an enormous pie could be baked for an annual fair.","zh":"地方当局买下它，是为了给一年一度的集市烤一个巨大的馅饼。","kind":"narration","speaker":"旁白"},{"en":"The pie committee decided that the best way to transport the dish would be by canal, so they insured it for the trip.","zh":"馅饼筹备委员会认定，用运河运输这个盘子最为合适，于是为这趟运输给它买了保险。","kind":"narration","speaker":"旁白"},{"en":"Shortly after it was launched, the pie committee went to a local inn to celebrate.","zh":"盘子下水后不久，委员会的成员就去当地一家小酒馆庆祝。","kind":"narration","speaker":"旁白"},{"en":"At the same time, a number of teenagers climbed on to the dish and held a little party of their own.","zh":"与此同时，几个十几岁的少年爬上盘子，自顾自地开起了小聚会。","kind":"narration","speaker":"旁白"},{"en":"Dancing proved to be more than the dish could bear, for during the party it capsized and sank in seven feet of water.","zh":"盘子经受不住他们跳舞时的折腾，在聚会中翻了个底朝天，沉到了七英尺深的水底。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"The pie committee telephoned a local garage owner who arrived in a recovery truck to salvage the pie dish.","zh":"馅饼委员会给当地一家修车厂的老板打了电话，他开着一辆救援拖车来打捞馅饼盘。","kind":"narration","speaker":"旁白"},{"en":"Shivering in their wet clothes, the teenagers looked on while three men dived repeatedly into the water to locate the dish.","zh":"少年们穿着湿衣服，冻得发抖，在旁边看着三个男人反复潜入水中寻找盘子。","kind":"narration","speaker":"旁白"},{"en":"They had little difficulty in finding it, but hauling it out of the water proved to be a serious problem.","zh":"他们没费多少劲就找到了盘子，但要把它从水里拖出来，却成了个大难题。","kind":"narration","speaker":"旁白"},{"en":"The sides of the dish were so smooth that it was almost impossible to attach hawsers and chains to the rim without damaging it.","zh":"盘壁十分光滑，要把粗缆绳和铁链固定在盘边，又不把它弄坏，几乎是不可能的。","kind":"narration","speaker":"旁白"},{"en":"Eventually chains were fixed to one end of the dish and a powerful winch was put into operation.","zh":"最后，他们把铁链固定在盘子的一端，开动了一台大功率绞车。","kind":"narration","speaker":"旁白"},{"en":"The dish rose to the surface and was gently drawn towards the canal bank.","zh":"盘子升到了水面，被缓缓拉向运河岸边。","kind":"narration","speaker":"旁白"},{"en":"For one agonizing moment, the dish was perched precariously on the bank of the canal, but it suddenly overbalanced and slid back into the water.","zh":"有那么一瞬间，盘子摇摇欲坠地搁在岸上，令人揪心；但它突然失去平衡，又滑回了水里。","kind":"narration","speaker":"旁白"},{"en":"The men were now obliged to try once more.","zh":"他们只好再试一次。","kind":"narration","speaker":"旁白"},{"en":"This time they fixed heavy metal clamps to both sides of the dish so that they could fasten the chains.","zh":"这一次，他们在盘子两侧装上沉重的金属夹具，以便系牢铁链。","kind":"narration","speaker":"旁白"},{"en":"The dish now had to be lifted vertically because one edge was resting against the side of the canal.","zh":"由于一条盘边抵在运河侧壁上，这回必须把盘子竖着吊起来。","kind":"narration","speaker":"旁白"},{"en":"The winch was again put into operation and one of the men started up the truck.","zh":"绞车再次开动，其中一个人发动了卡车。","kind":"narration","speaker":"旁白"},{"en":"Several minutes later, the dish was successfully hauled above the surface of the water.","zh":"几分钟后，盘子终于成功地被吊出了水面。","kind":"narration","speaker":"旁白"},{"en":"Water streamed in torrents over its sides with such force that it set up a huge wave in the canal.","zh":"水从盘子四边倾泻而下，力量之大，在运河里激起了一道巨浪。","kind":"narration","speaker":"旁白"},{"en":"There was a danger that the wave would rebound off the other side of the bank and send the dish plunging into the water again.","zh":"这道浪有可能撞到对岸后反弹回来，把盘子再度掀进水里。","kind":"narration","speaker":"旁白"},{"en":"By working at tremendous speed, the men managed to get the dish on to dry land before the wave returned.","zh":"他们动作飞快，终于赶在浪头回涌前把盘子弄上了干地。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"standard practice","matchedForm":"a standard practice","meaning":"惯常做法","note":"practice 这里指通行的办事方式，不是练习。","example":"Insuring public or private property is a standard practice in most countries in the world.","exampleZh":"在世界上大多数国家，为公共财产或私人财产投保都是惯常做法。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"in the event of","matchedForm":"in the event of","meaning":"如果发生；万一遇到","note":"of 后接名词；若后接完整句子，可使用 in the event that。","example":"If, however, you were holding an open air garden party or a fete it would be equally possible to insure yourself in the event of bad weather.","exampleZh":"不过，如果你要举办露天花园聚会或游园会，也同样可以投保，以防遇上坏天气。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"make a claim for","matchedForm":"made a claim for","meaning":"就……提出索赔","note":"claim 在保险语境指索赔，for 后接所要求赔付的费用或损失。","example":"It is not uncommon to hear that a shipping company has made a claim for the cost of salvaging a sunken ship.","exampleZh":"听说某家航运公司为打捞沉船的费用提出索赔，并不稀奇。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"be obliged to","matchedForm":"were now obliged to","meaning":"不得不……","note":"表示受到情况或责任的迫使；后接动词原形。","example":"The men were now obliged to try once more.","exampleZh":"他们只好再试一次。","sourceParagraphIndex":2,"sourceSentenceIndex":7,"sourceType":"textbook-passage"},{"phrase":"put into operation","matchedForm":"put into operation","meaning":"使运转；投入使用","note":"这里描述启动设备，也可用于实施计划或制度。","example":"The winch was again put into operation and one of the men started up the truck.","exampleZh":"绞车再次开动，其中一个人发动了卡车。","sourceParagraphIndex":2,"sourceSentenceIndex":10,"sourceType":"textbook-passage"}]},{"lessonId":"nce-b3-8160be-l044","book":3,"number":44,"title":"Speed and comfort","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"People travelling long distances frequently have to decide whether they would prefer to go by land, sea, or air.","zh":"长途旅行的人常常必须决定，自己更愿意走陆路、坐船，还是乘飞机。","kind":"narration","speaker":"旁白"},{"en":"Hardly anyone can positively enjoy sitting in a train for more than a few hours.","zh":"一连坐上好几个小时的火车，几乎没有谁能真正享受其中。","kind":"narration","speaker":"旁白"},{"en":"Train compartments soon get cramped and stuffy.","zh":"火车车厢很快就让人觉得拥挤、闷热。","kind":"narration","speaker":"旁白"},{"en":"It is almost impossible to take your mind off the journey.","zh":"你几乎不可能把注意力从旅途本身移开。","kind":"narration","speaker":"旁白"},{"en":"Reading is only a partial solution, for the monotonous rhythm of the wheels clicking on the rails soon lulls you to sleep.","zh":"阅读只能解决一部分问题，因为车轮在铁轨上咔嗒作响的单调节奏，很快就会把你催入梦乡。","kind":"narration","speaker":"旁白"},{"en":"During the day, sleep comes in snatches.","zh":"白天，你总是断断续续地睡上一会儿。","kind":"narration","speaker":"旁白"},{"en":"At night, when you really wish to go to sleep, you rarely manage to do so.","zh":"到了夜里，你真正想睡时，却往往睡不着。","kind":"narration","speaker":"旁白"},{"en":"If you are lucky enough to get a sleeper, you spend half the night staring at the small blue light in the ceiling, or fumbling to find your ticket for inspection.","zh":"如果你足够幸运，弄到一张卧铺，半个夜晚也得花在盯着天花板上的小蓝灯，或摸索着寻找车票应付查票上。","kind":"narration","speaker":"旁白"},{"en":"Inevitably you arrive at your destination almost exhausted.","zh":"到达目的地时，你免不了已精疲力竭。","kind":"narration","speaker":"旁白"},{"en":"Long car journeys are even less pleasant, for it is quite impossible even to read.","zh":"坐汽车长途旅行就更不愉快了，因为连看书都完全不可能。","kind":"narration","speaker":"旁白"},{"en":"On motorways you can, at least, travel fairly safely at high speeds, but more often than not, the greater part of the journey is spent on roads with few service stations and too much traffic.","zh":"在高速公路上，你至少还能相当安全地高速行驶；但大多数时候，旅程的大部分是在服务站寥寥无几、车辆却太多的道路上度过的。","kind":"narration","speaker":"旁白"},{"en":"By comparison, ferry trips or cruises offer a great variety of civilized comforts.","zh":"相形之下，乘渡轮或坐游轮能让人享受到各种体面舒适的便利。","kind":"narration","speaker":"旁白"},{"en":"You can stretch your legs on the spacious decks, play games, meet interesting people and enjoy good food — always assuming, of course, that the sea is calm.","zh":"你可以在宽敞的甲板上活动腿脚、玩游戏、结识有趣的人、享用美食——当然，这一切始终得以海面平静为前提。","kind":"narration","speaker":"旁白"},{"en":"If it is not, and you are likely to get seasick, no form of transport could be worse.","zh":"如果海面不平静，而你又容易晕船，那就没有比这更糟的交通方式了。","kind":"narration","speaker":"旁白"},{"en":"Even if you travel in ideal weather, sea journeys take a long time.","zh":"即使天气理想，海上旅程也很耗时。","kind":"narration","speaker":"旁白"},{"en":"Relatively few people are prepared to sacrifice holiday time for the pleasure of travelling by sea.","zh":"愿意为了乘船的乐趣而牺牲假期时间的人，相对来说很少。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Aeroplanes have the reputation of being dangerous and even hardened travellers are intimidated by them.","zh":"飞机素有危险之名，连久经旅途的老手也对它心存畏惧。","kind":"narration","speaker":"旁白"},{"en":"They also have the disadvantage of being an expensive form of transport.","zh":"它还有一个缺点，就是费用高昂。","kind":"narration","speaker":"旁白"},{"en":"But nothing can match them for speed and comfort.","zh":"但论速度和舒适程度，没有什么能比得上飞机。","kind":"narration","speaker":"旁白"},{"en":"Travelling at a height of 30,000 feet, far above the clouds, and at over 500 miles an hour is an exhilarating experience.","zh":"在远高于云层的三万英尺高空，以每小时五百多英里的速度飞行，是一种令人振奋的体验。","kind":"narration","speaker":"旁白"},{"en":"You do not have to devise ways of taking your mind off the journey, for an aeroplane gets you to your destination rapidly.","zh":"你不必费心设法把注意力从旅途上移开，因为飞机很快就把你送到目的地了。","kind":"narration","speaker":"旁白"},{"en":"For a few hours, you settle back in a deep armchair to enjoy the flight.","zh":"几个小时里，你舒舒服服地靠在宽大的扶手椅上，享受飞行。","kind":"narration","speaker":"旁白"},{"en":"The real escapist can watch a film and sip champagne on some services.","zh":"在某些航班上，真正想暂时逃离现实的人，还可以一边看电影，一边小口品着香槟。","kind":"narration","speaker":"旁白"},{"en":"But even when such refinements are not available, there is plenty to keep you occupied.","zh":"即使没有这些精致享受，也有足够多的事情让你消磨时间。","kind":"narration","speaker":"旁白"},{"en":"An aeroplane offers you an unusual and breathtaking view of the world.","zh":"飞机让你以不同寻常、令人屏息的视角俯瞰世界。","kind":"narration","speaker":"旁白"},{"en":"You soar effortlessly over high mountains and deep valleys.","zh":"你毫不费力地飞越高山深谷。","kind":"narration","speaker":"旁白"},{"en":"You really see the shape of the land.","zh":"你能真切地看到大地的形状。","kind":"narration","speaker":"旁白"},{"en":"If the landscape is hidden from view, you can enjoy the extraordinary sight of unbroken cloud plains that stretch out for miles before you, while the sun shines brilliantly in a clear sky.","zh":"如果地面景色被遮住，你还可以欣赏连绵数英里的壮观云海，在你眼前铺展，而太阳正在晴朗的天空中灿烂地照耀。","kind":"narration","speaker":"旁白"},{"en":"The journey is so smooth that there is nothing to prevent you from reading or sleeping.","zh":"旅途平稳得很，没有什么会妨碍你阅读或睡觉。","kind":"narration","speaker":"旁白"},{"en":"However you decide to spend your time, one thing is certain: you will arrive at your destination fresh and uncrumpled.","zh":"无论你决定怎样打发时间，有一点是肯定的：你到达目的地时，会精神饱满、衣着平整。","kind":"narration","speaker":"旁白"},{"en":"You will not have to spend the next few days recovering from a long and arduous journey.","zh":"你不必再用接下来的几天时间，从一次漫长而艰苦的旅程中恢复过来。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"take one’s mind off","matchedForm":"take your mind off","meaning":"把注意力从……移开","note":"off 后接让人烦心或难以忘怀的事情；所有格随主语变化。","example":"It is almost impossible to take your mind off the journey.","exampleZh":"你几乎不可能把注意力从旅途本身移开。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"in snatches","matchedForm":"in snatches","meaning":"断断续续地；一阵一阵地","note":"常与 sleep 等搭配，表示时间短促且不连续。","example":"During the day, sleep comes in snatches.","exampleZh":"白天，你总是断断续续地睡上一会儿。","sourceParagraphIndex":0,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"more often than not","matchedForm":"more often than not","meaning":"多半；往往","note":"整体表示经常发生，不能逐词理解成对次数的简单否定。","example":"On motorways you can, at least, travel fairly safely at high speeds, but more often than not, the greater part of the journey is spent on roads with few service stations and too much traffic.","exampleZh":"在高速公路上，你至少还能相当安全地高速行驶；但大多数时候，旅程的大部分是在服务站寥寥无几、车辆却太多的道路上度过的。","sourceParagraphIndex":0,"sourceSentenceIndex":10,"sourceType":"textbook-passage"},{"phrase":"settle back","matchedForm":"settle back","meaning":"舒服地向后靠坐","note":"常用于坐进椅子里准备休息或享受某事的情景。","example":"For a few hours, you settle back in a deep armchair to enjoy the flight.","exampleZh":"几个小时里，你舒舒服服地靠在宽大的扶手椅上，享受飞行。","sourceParagraphIndex":1,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"recover from","matchedForm":"recovering from","meaning":"从……中恢复","note":"from 引出疾病、劳累或打击等需要恢复的原因。","example":"You will not have to spend the next few days recovering from a long and arduous journey.","exampleZh":"你不必再用接下来的几天时间，从一次漫长而艰苦的旅程中恢复过来。","sourceParagraphIndex":1,"sourceSentenceIndex":14,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b3-l045","book":3,"number":45,"title":"The power of the press","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"In democratic countries any efforts to restrict the freedom of the press are rightly condemned.","zh":"在民主国家，任何限制新闻自由的企图都会受到谴责，这样的谴责是正当的。","kind":"narration","speaker":"旁白"},{"en":"However, this freedom can easily be abused.","zh":"不过，这种自由很容易被滥用。","kind":"narration","speaker":"旁白"},{"en":"Stories about people often attract far more public attention than political events.","zh":"有关人物的报道所吸引的公众注意，往往远远超过政治事件。","kind":"narration","speaker":"旁白"},{"en":"Though we may enjoy reading about the lives of others, it is extremely doubtful whether we would equally enjoy reading about ourselves.","zh":"我们也许喜欢读别人的生活故事，可如果读到的是自己的生活，是否还会同样高兴，就很值得怀疑了。","kind":"narration","speaker":"旁白"},{"en":"Acting on the contention that facts are sacred, reporters can cause untold suffering to individuals by publishing details about their private lives.","zh":"记者奉行“事实神圣不可侵犯”的主张，把个人私生活的细节公之于众，可能给当事人造成无法言尽的痛苦。","kind":"narration","speaker":"旁白"},{"en":"Newspapers exert such tremendous influence that they can not only bring about major changes to the lives of ordinary people but can even overthrow a government.","zh":"报纸的影响力如此巨大，不仅能使普通人的生活发生重大变化，甚至能推翻一个政府。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"The story of a poor family that acquired fame and fortune overnight, dramatically illustrates the power of the press.","zh":"有个穷困家庭一夜之间名利双收，它的故事鲜明地显示了新闻界的力量。","kind":"narration","speaker":"旁白"},{"en":"The family lived in Aberdeen, a small town of 23,000 inhabitants in South Dakota.","zh":"这家人住在南达科他州的阿伯丁，那是一个有两万三千名居民的小镇。","kind":"narration","speaker":"旁白"},{"en":"As the parents had five children, life was a perpetual struggle against poverty.","zh":"父母已经有五个孩子，因此生活始终是在贫困中挣扎。","kind":"narration","speaker":"旁白"},{"en":"They were expecting their sixth child and were faced with even more pressing economic problems.","zh":"他们正等着第六个孩子出生，面临着更加迫切的经济难题。","kind":"narration","speaker":"旁白"},{"en":"If they had only had one more child, the fact would have passed unnoticed.","zh":"如果他们只是再添一个孩子，这件事本来不会引起任何注意。","kind":"narration","speaker":"旁白"},{"en":"They would have continued to struggle against economic odds and would have lived in obscurity.","zh":"他们本会继续在经济困境中苦苦支撑，默默无闻地生活下去。","kind":"narration","speaker":"旁白"},{"en":"But they suddenly became the parents of quintuplets, four girls and a boy, an event which radically changed their lives.","zh":"然而，他们突然成了五胞胎的父母——四个女孩和一个男孩；这件事彻底改变了他们的生活。","kind":"narration","speaker":"旁白"},{"en":"The day after the birth of the five children, an aeroplane arrived in Aberdeen bringing sixty reporters and photographers.","zh":"五个孩子出生后的第二天，一架飞机带着六十名记者和摄影师来到了阿伯丁。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"The rise to fame was swift.","zh":"他们迅速成了名人。","kind":"narration","speaker":"旁白"},{"en":"Television cameras and newspapers carried the news to everyone in the country.","zh":"电视摄像机和报纸把这条消息传给了全国每一个人。","kind":"narration","speaker":"旁白"},{"en":"Newspapers and magazines offered the family huge sums for the exclusive rights to publish stories and photographs.","zh":"报纸和杂志愿意付给这家人巨额报酬，以获得独家刊登报道和照片的权利。","kind":"narration","speaker":"旁白"},{"en":"Gifts poured in not only from unknown people, but from baby food and soap manufacturers who wished to advertise their products.","zh":"礼物源源不断地涌来，不仅来自素不相识的人，也来自想为产品做广告的婴儿食品和肥皂制造商。","kind":"narration","speaker":"旁白"},{"en":"The old farmhouse the family lived in was to be replaced by a new $500,000 home.","zh":"这家人住的旧农舍，将被一栋价值五十万美元的新住宅所取代。","kind":"narration","speaker":"旁白"},{"en":"Reporters kept pressing for interviews so lawyers had to be employed to act as spokesmen for the family at press conferences.","zh":"记者不断要求采访，因此他们不得不雇用律师，在新闻发布会上充当这个家庭的发言人。","kind":"narration","speaker":"旁白"},{"en":"While the five babies were still quietly sleeping in oxygen tents in a hospital nursery, their parents were paying the price for fame.","zh":"五个婴儿还在医院育婴室的氧气帐里安静地睡着，父母却已经在为出名付出代价了。","kind":"narration","speaker":"旁白"},{"en":"It would never again be possible for them to lead normal lives.","zh":"从此，他们再也不可能过正常的生活。","kind":"narration","speaker":"旁白"},{"en":"They had become the victims of commercialization, for their names had acquired a market value.","zh":"他们成了商业化的受害者，因为他们的名字已经有了市场价值。","kind":"narration","speaker":"旁白"},{"en":"Instead of being five new family members, these children had immediately become a commodity.","zh":"这五个孩子一出生就成了商品，而不再只是家里新添的五个成员。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"bring about","matchedForm":"bring about","meaning":"引起；造成","note":"后面接变化或结果，强调促成其发生。","example":"Newspapers exert such tremendous influence that they can not only bring about major changes to the lives of ordinary people but can even overthrow a government.","exampleZh":"报纸的影响力如此巨大，不仅能使普通人的生活发生重大变化，甚至能推翻一个政府。","sourceParagraphIndex":0,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"fame and fortune","matchedForm":"fame and fortune","meaning":"名声与财富","note":"常用于 acquire、achieve、seek 等动词后，表示名利双收或追求名利。","example":"The story of a poor family that acquired fame and fortune overnight, dramatically illustrates the power of the press.","exampleZh":"有个穷困家庭一夜之间名利双收，它的故事鲜明地显示了新闻界的力量。","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"live in obscurity","matchedForm":"lived in obscurity","meaning":"默默无闻地生活","note":"obscurity 在这里指不为人知，不是光线昏暗。","example":"They would have continued to struggle against economic odds and would have lived in obscurity.","exampleZh":"他们本会继续在经济困境中苦苦支撑，默默无闻地生活下去。","sourceParagraphIndex":1,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"pour in","matchedForm":"poured in","meaning":"大量涌来","note":"常用于礼物、消息、捐款等接连到来，主语通常是涌来的事物。","example":"Gifts poured in not only from unknown people, but from baby food and soap manufacturers who wished to advertise their products.","exampleZh":"礼物源源不断地涌来，不仅来自素不相识的人，也来自想为产品做广告的婴儿食品和肥皂制造商。","sourceParagraphIndex":2,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"pay the price for","matchedForm":"paying the price for","meaning":"为……付出代价","note":"这里是比喻用法，price 不一定指金钱；for 后接付出代价的缘由。","example":"While the five babies were still quietly sleeping in oxygen tents in a hospital nursery, their parents were paying the price for fame.","exampleZh":"五个婴儿还在医院育婴室的氧气帐里安静地睡着，父母却已经在为出名付出代价了。","sourceParagraphIndex":2,"sourceSentenceIndex":6,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b3-l046","book":3,"number":46,"title":"Do it yourself","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"So great is our passion for doing things for ourselves, that we are becoming increasingly less dependent on specialized labour.","zh":"我们对自己动手做事的热情如此高涨，以至于对专业工人的依赖正日益减少。","kind":"narration","speaker":"旁白"},{"en":"No one can plead ignorance of a subject any longer, for there are countless do-it-yourself publications.","zh":"现在谁也不能再借口说自己对某个领域一无所知，因为教人自己动手的出版物多得数不清。","kind":"narration","speaker":"旁白"},{"en":"Armed with the right tools and materials, newlyweds gaily embark on the task of decorating their own homes.","zh":"新婚夫妇备齐合适的工具和材料，便兴致勃勃地开始装修自己的家。","kind":"narration","speaker":"旁白"},{"en":"Men, particularly, spend hours of their leisure time installing their own fireplaces, laying out their own gardens; building garages and making furniture.","zh":"尤其是男人，会花上许多闲暇时间，自己安装壁炉、布置花园、盖车库、做家具。","kind":"narration","speaker":"旁白"},{"en":"Some really keen enthusiasts go so far as to build their own computers.","zh":"有些格外痴迷的爱好者，甚至连电脑也自己组装。","kind":"narration","speaker":"旁白"},{"en":"Shops cater for the do-it-yourself craze not only by running special advisory services for novices, but by offering consumers bits and pieces which they can assemble at home.","zh":"商店为迎合这股自己动手的热潮，不仅为新手提供专门的咨询服务，还向顾客出售可以带回家自行组装的各种零部件。","kind":"narration","speaker":"旁白"},{"en":"Such things provide an excellent outlet for pent up creative energy, but unfortunately not all of us are born handymen.","zh":"这些活动为积蓄已久的创造力提供了绝佳的释放途径，但遗憾的是，并非人人天生都有一双巧手。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Some wives tend to believe that their husbands are infinitely resourceful and can fix anything.","zh":"有些妻子总以为丈夫有无穷的办法，什么都修得好。","kind":"narration","speaker":"旁白"},{"en":"Even men who can hardly drive a nail in straight are supposed to be born electricians, carpenters, plumbers and mechanics.","zh":"就连那些几乎连钉子都钉不直的男人，也被当成天生的电工、木匠、水管工和机械修理工。","kind":"narration","speaker":"旁白"},{"en":"When lights fuse, furniture gets rickety, pipes get clogged, or vacuum cleaners fail to operate, some women assume that their husbands will somehow put things right.","zh":"灯的保险丝烧断了，家具摇晃了，管子堵了，或者吸尘器不工作了，有些女人就认定丈夫总能想办法修好。","kind":"narration","speaker":"旁白"},{"en":"The worst thing about the do-it-yourself game is that sometimes even men live under the delusion that they can do anything, even when they have repeatedly been proved wrong.","zh":"自己动手这件事最糟糕的一点，是有时连男人自己也误以为什么都能干，哪怕事实已经一再证明他们错了。","kind":"narration","speaker":"旁白"},{"en":"It is a question of pride as much as anything else.","zh":"这很大程度上也是个面子问题。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"Last spring my wife suggested that I call in a man to look at our lawn mower.","zh":"去年春天，妻子提议叫个人来看看我们的割草机。","kind":"narration","speaker":"旁白"},{"en":"It had broken down the previous summer, and though I promised to repair it, I had never got round to it.","zh":"它前一年夏天就坏了；我虽然答应修，却始终没抽出时间来动手。","kind":"narration","speaker":"旁白"},{"en":"I would not hear of the suggestion and said that I would fix it myself.","zh":"我坚决不接受这个建议，说要自己把它修好。","kind":"narration","speaker":"旁白"},{"en":"One Saturday afternoon, I hauled the machine into the garden and had a close look at it.","zh":"一个星期六的下午，我把机器拖到花园里，仔细检查了一番。","kind":"narration","speaker":"旁白"},{"en":"As far as I could see, it needed only a minor adjustment: a turn of a screw here, a little tightening up there, a drop of oil and it would be as good as new.","zh":"在我看来，它只需要稍作调整：这里拧一下螺丝，那里紧一紧，再滴一点油，就能像新的一样了。","kind":"narration","speaker":"旁白"},{"en":"Inevitably the repair job was not quite so simple.","zh":"不出所料，修理起来并没有那么简单。","kind":"narration","speaker":"旁白"},{"en":"The mower firmly refused to mow, so I decided to dismantle it.","zh":"割草机就是不肯割草，我于是决定把它拆开。","kind":"narration","speaker":"旁白"},{"en":"The garden was soon littered with chunks of metal which had once made up a lawn mower.","zh":"不一会儿，花园里就散落着大块大块的金属零件，它们原先合在一起就是一台割草机。","kind":"narration","speaker":"旁白"},{"en":"But I was extremely pleased with myself.","zh":"可我却对自己十分满意。","kind":"narration","speaker":"旁白"},{"en":"I had traced the cause of the trouble.","zh":"我已经找出了故障的原因。","kind":"narration","speaker":"旁白"},{"en":"One of the links in the chain that drives the wheels had snapped.","zh":"驱动车轮的链条上，有一节链环断了。","kind":"narration","speaker":"旁白"},{"en":"After buying a new chain I was faced with the insurmountable task of putting the confusing jigsaw puzzle together again.","zh":"买来新链条后，我却面临着一个无法完成的任务：把这堆令人眼花缭乱的拼图再拼回去。","kind":"narration","speaker":"旁白"},{"en":"I was not surprised to find that the machine still refused to work after I had reassembled it, for the simple reason that I was left with several curiously shaped bits of metal which did not seem to fit anywhere.","zh":"重新装好后，机器仍不肯工作，我对此并不惊讶，原因很简单：我面前还剩着几块形状古怪的金属零件，似乎哪儿都装不上。","kind":"narration","speaker":"旁白"},{"en":"I gave up in despair.","zh":"我绝望地放弃了。","kind":"narration","speaker":"旁白"},{"en":"The weeks passed and the grass grew.","zh":"几个星期过去，草也长高了。","kind":"narration","speaker":"旁白"},{"en":"When my wife nagged me to do something about it, I told her that either I would have to buy a new mower or let the grass grow.","zh":"妻子唠叨着让我想想办法，我告诉她，要么得买台新割草机，要么就任草长下去。","kind":"narration","speaker":"旁白"},{"en":"Needless to say our house is now surrounded by a jungle.","zh":"不用说，我们家如今已经被一片丛林包围了。","kind":"narration","speaker":"旁白"},{"en":"Buried somewhere in deep grass there is a rusting lawn mower which I have promised to repair one day.","zh":"在深深的草丛某处，埋着一台正在生锈的割草机，而我还答应着总有一天把它修好。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"embark on","matchedForm":"embark on","meaning":"开始着手","note":"常用于开始一项重要或需花费精力的任务、事业或旅程。","example":"Armed with the right tools and materials, newlyweds gaily embark on the task of decorating their own homes.","exampleZh":"新婚夫妇备齐合适的工具和材料，便兴致勃勃地开始装修自己的家。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"bits and pieces","matchedForm":"bits and pieces","meaning":"零零碎碎的东西；各种零部件","note":"固定并列短语，既可指小物件，也可指零星的信息。","example":"Shops cater for the do-it-yourself craze not only by running special advisory services for novices, but by offering consumers bits and pieces which they can assemble at home.","exampleZh":"商店为迎合这股自己动手的热潮，不仅为新手提供专门的咨询服务，还向顾客出售可以带回家自行组装的各种零部件。","sourceParagraphIndex":0,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"put things right","matchedForm":"put things right","meaning":"把问题解决；把东西修好","note":"right 在这里表示恢复正常，也可用于纠正错误或弥补局面。","example":"When lights fuse, furniture gets rickety, pipes get clogged, or vacuum cleaners fail to operate, some women assume that their husbands will somehow put things right.","exampleZh":"灯的保险丝烧断了，家具摇晃了，管子堵了，或者吸尘器不工作了，有些女人就认定丈夫总能想办法修好。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"get round to","matchedForm":"got round to","meaning":"终于抽出时间做","note":"to 是介词，后接名词或动名词；常用于拖延后才着手的事情。","example":"It had broken down the previous summer, and though I promised to repair it, I had never got round to it.","exampleZh":"它前一年夏天就坏了；我虽然答应修，却始终没抽出时间来动手。","sourceParagraphIndex":2,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"in despair","matchedForm":"in despair","meaning":"绝望地","note":"常作状语说明人的心境，despair 是不可数名词。","example":"I gave up in despair.","exampleZh":"我绝望地放弃了。","sourceParagraphIndex":2,"sourceSentenceIndex":13,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b3-l047","book":3,"number":47,"title":"Too high a price?","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Pollution is the price we pay for an overpopulated, over-industrialized planet.","zh":"污染，是我们为一个人口过多、工业化过度的地球所付出的代价。","kind":"narration","speaker":"旁白"},{"en":"When you come to think about it, there are only four ways you can deal with rubbish: dump it, burn it, turn it into something you can use again, attempt to produce less of it.","zh":"仔细想来，处理垃圾只有四种办法：倾倒、焚烧、把它变成可再次利用的东西，以及设法少制造一些。","kind":"narration","speaker":"旁白"},{"en":"We keep trying all four methods, but the sheer volume of rubbish we produce worldwide threatens to overwhelm us.","zh":"这四种办法我们一直都在尝试，但全世界制造出来的垃圾数量实在太大，几乎要把我们淹没。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Rubbish, however, is only part of the problem of polluting our planet.","zh":"然而，垃圾只是地球污染问题的一部分。","kind":"narration","speaker":"旁白"},{"en":"The need to produce ever-increasing quantities of cheap food leads to a different kind of pollution.","zh":"人们需要生产数量不断增长的廉价食物，这又导致了另一种污染。","kind":"narration","speaker":"旁白"},{"en":"Industrialized farming methods produce cheap meat products: beef, pork and chicken.","zh":"工业化的养殖方法带来了廉价的肉类产品：牛肉、猪肉和鸡肉。","kind":"narration","speaker":"旁白"},{"en":"The use of pesticides and fertilizers produces cheap grain and vegetables.","zh":"使用农药和化肥，带来了廉价的粮食和蔬菜。","kind":"narration","speaker":"旁白"},{"en":"The price we pay for cheap food may be already too high: Mad Cow Disease (BSE) in cattle, salmonella in chicken and eggs, and listeria in dairy products.","zh":"我们为廉价食物付出的代价，也许早已过高：牛身上的疯牛病，即牛海绵状脑病，鸡肉和鸡蛋中的沙门氏菌，以及乳制品中的李斯特菌。","kind":"narration","speaker":"旁白"},{"en":"And if you think you'll abandon meat and become a vegetarian, you have the choice of very expensive organically-grown vegetables or a steady diet of pesticides every time you think you're eating fresh salads and vegetables, or just having an innocent glass of water!","zh":"而如果你打算不再吃肉，改做素食者，那么摆在面前的选择是：要么吃价格极高的有机蔬菜，要么每次自以为在吃新鲜沙拉和蔬菜，甚至只是喝一杯本以为无害的水时，都在不断摄入农药！","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"However, there is an even more insidious kind of pollution that particularly affects urban areas and invades our daily lives, and that is noise.","zh":"然而，还有一种更为隐蔽的污染，尤其影响城市地区，侵入我们的日常生活，那就是噪声。","kind":"narration","speaker":"旁白"},{"en":"Burglar alarms going off at any time of the day or night serve only to annoy passers-by and actually assist burglars to burgle.","zh":"防盗警报不分昼夜地响起，只能惹得路人烦躁，实际上倒帮了窃贼行窃。","kind":"narration","speaker":"旁白"},{"en":"Car alarms constantly scream at us in the street and are a source of profound irritation.","zh":"汽车警报在街上不停地对着我们尖叫，让人极其恼火。","kind":"narration","speaker":"旁白"},{"en":"A recent survey of the effects of noise revealed (surprisingly?)","zh":"最近一项关于噪声影响的调查揭示了这样一个结果（意外吗？）：","kind":"narration","speaker":"旁白"},{"en":"that dogs barking incessantly in the night rated the highest form of noise pollution on a scale ranging from 1 to 7.","zh":"在一到七级的评定尺度上，夜间不停的狗叫声被评为最严重的噪声污染。","kind":"narration","speaker":"旁白"},{"en":"The survey revealed a large number of sources of noise that we really dislike.","zh":"调查列出了大量我们确实厌恶的噪声来源。","kind":"narration","speaker":"旁白"},{"en":"Lawn mowers whining on a summer’s day, late-night parties in apartment blocks, noisy neighbours, vehicles of all kinds, especially large container trucks thundering through quiet villages, planes and helicopters flying overhead, large radios carried round in public places and played at maximum volume.","zh":"夏日里嗡嗡作响的割草机，公寓楼内深夜的聚会，吵闹的邻居，各种车辆，尤其是轰隆隆驶过宁静村庄的大型集装箱卡车，头顶飞过的飞机和直升机，还有人们带到公共场所、把音量开到最大的大收音机。","kind":"narration","speaker":"旁白"},{"en":"New technology has also made its own contribution to noise.","zh":"新技术也为噪声作出了自己的“贡献”。","kind":"narration","speaker":"旁白"},{"en":"A lot of people object to mobile phones, especially when they are used in public places like restaurants or on public transport.","zh":"很多人反感手机，尤其反感人们在餐馆或公共交通工具上等公共场所使用手机。","kind":"narration","speaker":"旁白"},{"en":"Loud conversations on mobile phones invade our thoughts or interrupt the pleasure of meeting friends for a quiet chat.","zh":"用手机大声交谈，会侵扰我们的思绪，或打断与朋友安静聊天的乐趣。","kind":"narration","speaker":"旁白"},{"en":"The noise pollution survey revealed a rather surprising and possibly amusing old-fashioned source of noise.","zh":"这次噪声污染调查还发现了一种相当出人意料、也许还颇为好笑的老式噪声来源。","kind":"narration","speaker":"旁白"},{"en":"It turned out to be snoring!","zh":"结果竟然是打鼾！","kind":"narration","speaker":"旁白"},{"en":"Men were found to be the worst offenders.","zh":"调查发现，男人是最严重的制造者。","kind":"narration","speaker":"旁白"},{"en":"It was revealed that 20% of men in their mid-thirties snore.","zh":"调查表明，三十五岁左右的男性中，有百分之二十打鼾。","kind":"narration","speaker":"旁白"},{"en":"This figure rises to a staggering 60% of men in their sixties.","zh":"到了六十多岁的男性中，这个比例上升到惊人的百分之六十。","kind":"narration","speaker":"旁白"},{"en":"Against these figures, it was found that only 5% of women snore regularly, while the rest are constantly woken or kept awake by their trumpeting partners.","zh":"相比之下，只有百分之五的女性经常打鼾，其余女性却常被伴侣喇叭般的鼾声吵醒，或吵得无法入睡。","kind":"narration","speaker":"旁白"},{"en":"Whatever the source of noise, one thing is certain: silence, it seems, has become a golden memory.","zh":"不管噪声来自哪里，有一点是肯定的：寂静似乎已成为珍贵的回忆。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"come to think about it","matchedForm":"come to think about it","meaning":"仔细想一想","note":"用来引出经过考虑后注意到的一点，常放在从句或插入语中。","example":"When you come to think about it, there are only four ways you can deal with rubbish: dump it, burn it, turn it into something you can use again, attempt to produce less of it.","exampleZh":"仔细想来，处理垃圾只有四种办法：倾倒、焚烧、把它变成可再次利用的东西，以及设法少制造一些。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"go off","matchedForm":"going off","meaning":"突然响起","note":"警报、闹钟等作主语时，go off 指发出响声，并非停止工作。","example":"Burglar alarms going off at any time of the day or night serve only to annoy passers-by and actually assist burglars to burgle.","exampleZh":"防盗警报不分昼夜地响起，只能惹得路人烦躁，实际上倒帮了窃贼行窃。","sourceParagraphIndex":2,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"object to","matchedForm":"object to","meaning":"反对；不喜欢","note":"to 是介词，后接名词或动名词；名词 object 的读音和动词不同。","example":"A lot of people object to mobile phones, especially when they are used in public places like restaurants or on public transport.","exampleZh":"很多人反感手机，尤其反感人们在餐馆或公共交通工具上等公共场所使用手机。","sourceParagraphIndex":2,"sourceSentenceIndex":8,"sourceType":"textbook-passage"},{"phrase":"turn out to be","matchedForm":"turned out to be","meaning":"结果竟是；最终发现是","note":"用来说明后来查明的实际情况，往往带意外意味。","example":"It turned out to be snoring!","exampleZh":"结果竟然是打鼾！","sourceParagraphIndex":2,"sourceSentenceIndex":11,"sourceType":"textbook-passage"},{"phrase":"keep someone awake","matchedForm":"kept awake","meaning":"使某人无法入睡","note":"awake 是形容词，置于宾语之后；本例为被动形式。","example":"Against these figures, it was found that only 5% of women snore regularly, while the rest are constantly woken or kept awake by their trumpeting partners.","exampleZh":"相比之下，只有百分之五的女性经常打鼾，其余女性却常被伴侣喇叭般的鼾声吵醒，或吵得无法入睡。","sourceParagraphIndex":2,"sourceSentenceIndex":15,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b3-l048","book":3,"number":48,"title":"The silent village","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"In this much-travelled world, there are still thousands of places which are inaccessible to tourists.","zh":"如今世界各地人们频繁旅行，却仍有成千上万个地方是游客无法到达的。","kind":"narration","speaker":"旁白"},{"en":"We always assume that villagers in remote places are friendly and hospitable.","zh":"我们总以为，偏远地方的村民都友善好客。","kind":"narration","speaker":"旁白"},{"en":"But people who are cut off not only from foreign tourists, but even from their own countrymen can be hostile to travellers.","zh":"然而，有些人不仅与外国游客隔绝，甚至与本国其他人也少有往来，他们可能会对旅人怀有敌意。","kind":"narration","speaker":"旁白"},{"en":"Visits to really remote villages are seldom enjoyable — as my wife and I discovered during a tour through the Balkans.","zh":"游览真正偏僻的村庄，很少是件愉快的事；我和妻子在穿行巴尔干地区的一次旅行中，就发现了这一点。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"We had spent several days in a small town and visited a number of old churches in the vicinity.","zh":"我们在一个小镇住了几天，游览了附近好几座古老的教堂。","kind":"narration","speaker":"旁白"},{"en":"These attracted many visitors, for they were not only of great architectural interest, but contained a large number of beautifully preserved frescoes as well.","zh":"这些教堂吸引了许多游客，因为它们不仅在建筑上很有观赏价值，里面还保存着大量完好的精美壁画。","kind":"narration","speaker":"旁白"},{"en":"On the day before our departure, several bus loads of tourists descended on the town.","zh":"在我们离开的前一天，几大车游客涌进了镇子。","kind":"narration","speaker":"旁白"},{"en":"This was more than we could bear, so we decided to spend our last day exploring the countryside.","zh":"这实在让我们受不了，于是我们决定，把最后一天用来探索乡间。","kind":"narration","speaker":"旁白"},{"en":"Taking a path which led out of the town, we crossed a few fields until we came to a dense wood.","zh":"我们沿一条通往镇外的小路，穿过几块田地，来到一片茂密的树林。","kind":"narration","speaker":"旁白"},{"en":"We expected the path to end abruptly, but we found that it traced its way through the trees.","zh":"我们以为小路会就此突然中断，却发现它继续蜿蜒穿过树林。","kind":"narration","speaker":"旁白"},{"en":"We tramped through the wood for over two hours until we arrived at a deep stream.","zh":"我们在林中跋涉了两个多小时，来到一条水很深的溪流旁。","kind":"narration","speaker":"旁白"},{"en":"We could see that the path continued on the other side, but we had no idea how we could get across the stream.","zh":"我们看得见小路在对岸继续延伸，却不知道怎样才能过溪。","kind":"narration","speaker":"旁白"},{"en":"Suddenly my wife spotted a boat moored to the bank.","zh":"突然，妻子发现岸边泊着一条船。","kind":"narration","speaker":"旁白"},{"en":"In it there was a boatman fast asleep.","zh":"船里有个船夫正睡得很熟。","kind":"narration","speaker":"旁白"},{"en":"We gently woke him up and asked him to ferry us to the other side.","zh":"我们轻轻叫醒他，请他把我们渡到对岸。","kind":"narration","speaker":"旁白"},{"en":"Though he was reluctant to do so at first, we eventually persuaded him to take us.","zh":"他起初不大愿意，但我们最后还是说服他载我们过去了。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"The path led to a tiny village perched on the steep sides of a mountain.","zh":"小路通向一个小村庄，村子依在陡峭的山坡上。","kind":"narration","speaker":"旁白"},{"en":"The place consisted of a straggling unmade road which was lined on either side by small houses.","zh":"村里只有一条弯曲散漫、未经铺修的道路，两旁排列着小房子。","kind":"narration","speaker":"旁白"},{"en":"Even under a clear blue sky, the village looked forbidding, as all the houses were built of grey mud bricks.","zh":"所有房屋都是灰色土坯砌成的，因而即便头顶是明净的蓝天，整个村子仍显得阴沉得令人却步。","kind":"narration","speaker":"旁白"},{"en":"The village seemed deserted, the only sign of life being an ugly-looking black goat on a short length of rope tied to a tree in a field nearby.","zh":"村子仿佛空无一人，唯一有生命的迹象，是附近田里一只丑陋的黑山羊，用一截短绳拴在树上。","kind":"narration","speaker":"旁白"},{"en":"Sitting down on a dilapidated wooden fence near the field, we opened a couple of tins of sardines and had a picnic lunch.","zh":"我们在田边一道破旧的木栅栏上坐下，打开几罐沙丁鱼，吃了一顿野餐午饭。","kind":"narration","speaker":"旁白"},{"en":"All at once, I noticed that my wife seemed to be filled with alarm.","zh":"突然，我注意到妻子似乎满脸惊恐。","kind":"narration","speaker":"旁白"},{"en":"Looking up I saw that we were surrounded by children in rags who were looking at us silently as we ate.","zh":"抬头一看，我发现一群衣衫褴褛的孩子围在我们身边，默默地看着我们吃东西。","kind":"narration","speaker":"旁白"},{"en":"We offered them food and spoke to them kindly, but they remained motionless.","zh":"我们把食物递给他们，和气地同他们说话，他们却仍一动不动。","kind":"narration","speaker":"旁白"},{"en":"I concluded that they were simply shy of strangers.","zh":"我认定，他们只是怕生罢了。","kind":"narration","speaker":"旁白"},{"en":"When we later walked down the main street of the village, we were followed by a silent procession of children.","zh":"后来我们沿着村里的大街走去，一队默不作声的孩子跟在我们后面。","kind":"narration","speaker":"旁白"},{"en":"The village which had seemed deserted, immediately came to life.","zh":"刚才似乎空无一人的村庄，一下子活了过来。","kind":"narration","speaker":"旁白"},{"en":"Faces appeared at windows.","zh":"窗口出现了一张张面孔。","kind":"narration","speaker":"旁白"},{"en":"Men in shirt sleeves stood outside their houses and glared at us.","zh":"只穿着衬衣的男人站在屋外，怒目瞪着我们。","kind":"narration","speaker":"旁白"},{"en":"Old women in black shawls peered at us from doorways.","zh":"披着黑色披肩的老妇人从门口探头望着我们。","kind":"narration","speaker":"旁白"},{"en":"The most frightening thing of all was that not a sound could be heard.","zh":"最吓人的是，竟然听不到一点声音。","kind":"narration","speaker":"旁白"},{"en":"There was no doubt that we were unwelcome visitors.","zh":"毫无疑问，我们是不受欢迎的来客。","kind":"narration","speaker":"旁白"},{"en":"We needed no further warning.","zh":"我们不需要再有什么警告了。","kind":"narration","speaker":"旁白"},{"en":"Turning back down the main street, we quickened our pace and made our way rapidly towards the stream where we hoped the boatman was waiting.","zh":"我们沿大街掉头往回走，加快脚步，迅速朝溪流赶去，希望船夫还在那里等着。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"be cut off from","matchedForm":"are cut off not only from","meaning":"与……隔绝","note":"cut off 与 from 构成搭配；本例插入 not only，说明隔绝不止一种对象。","example":"But people who are cut off not only from foreign tourists, but even from their own countrymen can be hostile to travellers.","exampleZh":"然而，有些人不仅与外国游客隔绝，甚至与本国其他人也少有往来，他们可能会对旅人怀有敌意。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"fast asleep","matchedForm":"fast asleep","meaning":"熟睡着","note":"fast 在这里表示睡得很沉，不表示速度快；常作表语或补语。","example":"In it there was a boatman fast asleep.","exampleZh":"船里有个船夫正睡得很熟。","sourceParagraphIndex":1,"sourceSentenceIndex":9,"sourceType":"textbook-passage"},{"phrase":"all at once","matchedForm":"All at once","meaning":"突然；一下子","note":"在这里相当于 suddenly；其他语境中也可表示同时。","example":"All at once, I noticed that my wife seemed to be filled with alarm.","exampleZh":"突然，我注意到妻子似乎满脸惊恐。","sourceParagraphIndex":2,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"come to life","matchedForm":"came to life","meaning":"活跃起来；恢复生气","note":"既可形容地方突然热闹，也可指故事或人物被生动呈现。","example":"The village which had seemed deserted, immediately came to life.","exampleZh":"刚才似乎空无一人的村庄，一下子活了过来。","sourceParagraphIndex":2,"sourceSentenceIndex":10,"sourceType":"textbook-passage"},{"phrase":"there is no doubt that","matchedForm":"There was no doubt that","meaning":"毫无疑问……","note":"that 后接完整句子，用来表达确定的判断。","example":"There was no doubt that we were unwelcome visitors.","exampleZh":"毫无疑问，我们是不受欢迎的来客。","sourceParagraphIndex":2,"sourceSentenceIndex":15,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b3-l049","book":3,"number":49,"title":"The ideal servant","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"It is a good thing my aunt Harriet died years ago.","zh":"幸好我的哈丽特姨妈多年前就去世了。","kind":"narration","speaker":"旁白"},{"en":"If she were alive today she would not be able to air her views on her favourite topic of conversation: domestic servants.","zh":"假如她今天还活着，就没法再就她最爱谈的话题——家佣——发表高论了。","kind":"narration","speaker":"旁白"},{"en":"Aunt Harriet lived in that leisurely age when servants were employed to do housework.","zh":"哈丽特姨妈生活在那个悠闲的年代，那时人们会雇佣仆人料理家务。","kind":"narration","speaker":"旁白"},{"en":"She had a huge, rambling country house called ‘The Gables’.","zh":"她有一栋占地宽广、房间错落延伸的乡间大宅，名叫“山墙庄园”。","kind":"narration","speaker":"旁白"},{"en":"She was sentimentally attached to this house, for even though it was far too big for her needs, she persisted in living there long after her husband’s death.","zh":"她对这房子有深厚的感情；尽管房子远远大于她实际所需，丈夫去世很久以后，她仍执意住在那里。","kind":"narration","speaker":"旁白"},{"en":"Before she grew old, Aunt Harriet used to entertain lavishly.","zh":"哈丽特姨妈年纪还不大时，经常大摆筵席招待客人。","kind":"narration","speaker":"旁白"},{"en":"I often visited The Gables when I was a boy.","zh":"我小时候常去山墙庄园。","kind":"narration","speaker":"旁白"},{"en":"No matter how many guests were present, the great house was always immaculate.","zh":"无论来了多少客人，大宅里总是一尘不染。","kind":"narration","speaker":"旁白"},{"en":"The parquet floors shone like mirrors; highly polished silver was displayed in gleaming glass cabinets; even my uncle’s huge collection of books was kept miraculously free from dust.","zh":"拼花地板亮如镜面；擦得锃亮的银器陈列在闪闪发光的玻璃柜里；就连姨父数量庞大的藏书，也奇迹般地毫无灰尘。","kind":"narration","speaker":"旁白"},{"en":"Aunt Harriet presided over an invisible army of servants that continuously scrubbed, cleaned, and polished.","zh":"哈丽特姨妈统领着一支看不见的仆人大军，他们不停地刷洗、清扫、擦亮各种东西。","kind":"narration","speaker":"旁白"},{"en":"She always referred to them as ‘the shifting population’, for they came and went with such frequency that I never even got a chance to learn their names.","zh":"她总称他们为“流动人口”，因为他们来来去去太频繁，我甚至都没有机会记住他们的名字。","kind":"narration","speaker":"旁白"},{"en":"Though my aunt pursued what was, in those days, an enlightened policy, in that she never allowed her domestic staff to work more than eight hours a day, she was extremely difficult to please.","zh":"姨妈从不让家佣每天工作超过八小时，这在当年算得上开明的做法，可她却极难伺候得满意。","kind":"narration","speaker":"旁白"},{"en":"While she always criticized the fickleness of human nature, she carried on an unrelenting search for the ideal servant to the end of her days, even after she had been sadly disillusioned by Bessie.","zh":"她一面总是批评人性反复无常，一面又从不放弃寻找理想仆人，直到生命的最后一天；即使贝茜曾让她的幻想痛苦地破灭，她也仍是如此。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Bessie worked for Aunt Harriet for three years.","zh":"贝茜给哈丽特姨妈做了三年事。","kind":"narration","speaker":"旁白"},{"en":"During that time she so gained my aunt’s confidence, that she was put in charge of the domestic staff.","zh":"在那段时间里，她深得姨妈信任，以至于被任命为家佣的主管。","kind":"narration","speaker":"旁白"},{"en":"Aunt Harriet could not find words to praise Bessie’s industriousness and efficiency.","zh":"哈丽特姨妈对贝茜的勤劳和办事效率，简直赞不绝口。","kind":"narration","speaker":"旁白"},{"en":"In addition to all her other qualifications, Bessie was an expert cook.","zh":"除了其他种种长处，贝茜还是一位烹饪能手。","kind":"narration","speaker":"旁白"},{"en":"She acted the role of the perfect servant for three years before Aunt Harriet discovered her ‘little weakness’.","zh":"她扮演了三年的完美仆人之后，哈丽特姨妈才发现了她那点“小毛病”。","kind":"narration","speaker":"旁白"},{"en":"After being absent from The Gables for a week, my aunt unexpectedly returned one afternoon with a party of guests and instructed Bessie to prepare dinner.","zh":"姨妈离开山墙庄园一个星期后，一天下午突然带着一群客人回来，吩咐贝茜准备晚餐。","kind":"narration","speaker":"旁白"},{"en":"Not only was the meal well below the usual standard, but Bessie seemed unable to walk steadily.","zh":"那顿饭不仅远低于平日的水准，连贝茜走起路来也似乎摇摇晃晃。","kind":"narration","speaker":"旁白"},{"en":"She bumped into the furniture and kept mumbling about the guests.","zh":"她一会儿撞到家具，一会儿又不停含糊地嘟囔着客人的事。","kind":"narration","speaker":"旁白"},{"en":"When she came in with the last course — a huge pudding — she tripped on the carpet and the pudding went flying through the air, narrowly missed my aunt, and crashed on the dining table with considerable force.","zh":"端着最后一道菜——一个巨大的布丁——进来时，她被地毯绊了一跤，布丁飞上半空，险些砸中姨妈，最后重重地摔在餐桌上。","kind":"narration","speaker":"旁白"},{"en":"Though this caused great mirth among the guests, Aunt Harriet was horrified.","zh":"客人们为此乐不可支，哈丽特姨妈却吓坏了。","kind":"narration","speaker":"旁白"},{"en":"She reluctantly came to the conclusion that Bessie was drunk.","zh":"她不得不承认一个自己不愿接受的结论：贝茜喝醉了。","kind":"narration","speaker":"旁白"},{"en":"The guests had, of course, realized this from the moment Bessie opened the door for them and, long before the final catastrophe, had had a difficult time trying to conceal their amusement.","zh":"当然，贝茜替客人开门的那一刻，他们就已明白了这一点；远在最后那场灾难发生之前，他们就已经忍笑忍得很辛苦了。","kind":"narration","speaker":"旁白"},{"en":"The poor girl was dismissed instantly.","zh":"这个可怜的姑娘立刻被辞退了。","kind":"narration","speaker":"旁白"},{"en":"After her departure, Aunt Harriet discovered that there were piles of empty wine bottles of all shapes and sizes neatly stacked in what had once been Bessie’s wardrobe.","zh":"她离开后，哈丽特姨妈发现，在贝茜原来的衣柜里，整整齐齐地码着成堆的空酒瓶，形状大小各不相同。","kind":"narration","speaker":"旁白"},{"en":"They had mysteriously found their way there from the wine cellar!","zh":"它们竟然神不知鬼不觉地从酒窖里跑到了这里！","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"air one’s views","matchedForm":"air her views","meaning":"发表自己的看法","note":"air 在这里是动词，表示公开表达意见；所有格随主语变化。","example":"If she were alive today she would not be able to air her views on her favourite topic of conversation: domestic servants.","exampleZh":"假如她今天还活着，就没法再就她最爱谈的话题——家佣——发表高论了。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"persist in","matchedForm":"persisted in","meaning":"坚持；执意","note":"in 后接名词或动名词，往往带不因困难或反对而改变的意味。","example":"She was sentimentally attached to this house, for even though it was far too big for her needs, she persisted in living there long after her husband’s death.","exampleZh":"她对这房子有深厚的感情；尽管房子远远大于她实际所需，丈夫去世很久以后，她仍执意住在那里。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"refer to ... as","matchedForm":"referred to them as","meaning":"把……称为……","note":"to 后是被称呼的对象，as 后是名称或身份。","example":"She always referred to them as ‘the shifting population’, for they came and went with such frequency that I never even got a chance to learn their names.","exampleZh":"她总称他们为“流动人口”，因为他们来来去去太频繁，我甚至都没有机会记住他们的名字。","sourceParagraphIndex":0,"sourceSentenceIndex":10,"sourceType":"textbook-passage"},{"phrase":"put someone in charge of","matchedForm":"put in charge of","meaning":"让某人负责……","note":"in charge of 表示负责管理；本例为被动结构，被任命者是 she。","example":"During that time she so gained my aunt’s confidence, that she was put in charge of the domestic staff.","exampleZh":"在那段时间里，她深得姨妈信任，以至于被任命为家佣的主管。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"in addition to","matchedForm":"In addition to","meaning":"除……之外还","note":"to 是介词，后接名词或动名词；此处在已有优点上继续补充。","example":"In addition to all her other qualifications, Bessie was an expert cook.","exampleZh":"除了其他种种长处，贝茜还是一位烹饪能手。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"come to the conclusion that","matchedForm":"came to the conclusion that","meaning":"得出……的结论","note":"that 后接结论内容；come to 强调形成判断的过程。","example":"She reluctantly came to the conclusion that Bessie was drunk.","exampleZh":"她不得不承认一个自己不愿接受的结论：贝茜喝醉了。","sourceParagraphIndex":1,"sourceSentenceIndex":10,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b3-l050","book":3,"number":50,"title":"New Year resolutions","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"The New Year is a time for resolutions.","zh":"新年是下决心的时候。","kind":"narration","speaker":"旁白"},{"en":"Mentally, at least, most of us could compile formidable lists of ‘dos’ and ‘don’ts’.","zh":"至少在脑海里，我们大多数人都能列出一长串该做和不该做的事，长得令人望而生畏。","kind":"narration","speaker":"旁白"},{"en":"The same old favourites recur year in year out with monotonous regularity.","zh":"年复一年，反复出现的总是那些老项目，规律得单调乏味。","kind":"narration","speaker":"旁白"},{"en":"We resolve to get up earlier each morning, eat less, find more time to play with the children, do a thousand and one jobs about the house, be nice to people we don’t like, drive carefully, and take the dog for a walk every day.","zh":"我们决心每天早上起得更早，少吃一点，多找时间陪孩子玩，处理家里千头万绪的杂事，对不喜欢的人也友善一些，开车小心，每天遛狗。","kind":"narration","speaker":"旁白"},{"en":"Past experience has taught us that certain accomplishments are beyond attainment.","zh":"以往的经验让我们明白，有些目标是办不到的。","kind":"narration","speaker":"旁白"},{"en":"If we remain inveterate smokers, it is only because we have so often experienced the frustration that results from failure.","zh":"如果我们仍是烟瘾深重的人，那只是因为我们太多次经历了失败带来的挫败感。","kind":"narration","speaker":"旁白"},{"en":"Most of us fail in our efforts at self-improvement because our schemes are too ambitious and we never have time to carry them out.","zh":"我们大多数人在自我改进上的努力以失败告终，是因为计划太过宏大，始终没有时间付诸实行。","kind":"narration","speaker":"旁白"},{"en":"We also make the fundamental error of announcing our resolutions to everybody so that we look even more foolish when we slip back into our bad old ways.","zh":"我们还犯了一个根本性的错误：逢人便宣布自己的决心，以至于重蹈老习惯时，显得更加可笑。","kind":"narration","speaker":"旁白"},{"en":"Aware of these pitfalls, this year I attempted to keep my resolutions to myself.","zh":"意识到这些陷阱后，今年我试着把自己的决心藏在心里。","kind":"narration","speaker":"旁白"},{"en":"I limited myself to two modest ambitions: to do physical exercises every morning and to read more of an evening.","zh":"我只给自己定了两个不算高的目标：每天早上锻炼身体，晚上多读点书。","kind":"narration","speaker":"旁白"},{"en":"An all-night party on New Year’s Eve provided me with a good excuse for not carrying out either of these new resolutions on the first day of the year, but on the second, I applied myself assiduously to the task.","zh":"除夕的一场通宵聚会，让我有了一个很好的借口，新年第一天两项新决心都没实行；但到了第二天，我就勤勤恳恳地投入了行动。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"The daily exercises lasted only eleven minutes and I proposed to do them early in the morning before anyone had got up.","zh":"每天的锻炼只需十一分钟，我打算在清早别人都还没起床时做完。","kind":"narration","speaker":"旁白"},{"en":"The self-discipline required to drag myself out of bed eleven minutes earlier than usual was considerable.","zh":"要比平常早十一分钟强迫自己离开被窝，需要相当大的自制力。","kind":"narration","speaker":"旁白"},{"en":"Nevertheless, I managed to creep down into the living room for two days before anyone found me out.","zh":"尽管如此，我还是悄悄溜到楼下客厅练了两天，才被人发现。","kind":"narration","speaker":"旁白"},{"en":"After jumping about on the carpet and twisting the human frame into uncomfortable positions, I sat down at the breakfast table in an exhausted condition.","zh":"在地毯上又蹦又跳，把身体扭成各种不舒服的姿势后，我精疲力竭地坐到早餐桌前。","kind":"narration","speaker":"旁白"},{"en":"It was this that betrayed me.","zh":"正是这一点泄露了我的秘密。","kind":"narration","speaker":"旁白"},{"en":"The next morning the whole family trooped in to watch the performance.","zh":"第二天早上，全家人都成群结队地进来观看表演。","kind":"narration","speaker":"旁白"},{"en":"That was really unsettling, but I fended off the taunts and jibes of the family good-humouredly and soon everybody got used to the idea.","zh":"这实在让我很不自在，不过我好脾气地招架住家人的冷嘲热讽，很快大家也就习以为常了。","kind":"narration","speaker":"旁白"},{"en":"However, my enthusiasm waned.","zh":"然而，我的热情渐渐消退。","kind":"narration","speaker":"旁白"},{"en":"The time I spent at exercises gradually diminished.","zh":"我花在锻炼上的时间逐步减少。","kind":"narration","speaker":"旁白"},{"en":"Little by little the eleven minutes fell to zero.","zh":"那十一分钟一点点缩减，最后变成了零。","kind":"narration","speaker":"旁白"},{"en":"By January 10th, I was back to where I had started from.","zh":"到了一月十日，我又回到了起点。","kind":"narration","speaker":"旁白"},{"en":"I argued that if I spent less time exhausting myself at exercises in the morning, I would keep my mind fresh for reading when I got home from work.","zh":"我给自己辩解说，如果早晨少花些时间锻炼、免得累坏自己，下班回家看书时就能保持头脑清醒。","kind":"narration","speaker":"旁白"},{"en":"Resisting the hypnotizing effect of television, I sat in my room for a few evenings with my eyes glued to a book.","zh":"有几个晚上，我抵挡着电视的催眠作用，坐在房间里，眼睛紧盯着书本。","kind":"narration","speaker":"旁白"},{"en":"One night, however, feeling cold and lonely, I went downstairs and sat in front of the television pretending to read.","zh":"不过，有一天晚上，我觉得又冷又孤单，就下了楼，坐到电视机前，装着看书。","kind":"narration","speaker":"旁白"},{"en":"That proved to be my undoing, for I soon got back to my old bad habit of dozing off in front of the screen.","zh":"这一步最终毁了我的计划，因为我很快又恢复了在屏幕前打瞌睡的老毛病。","kind":"narration","speaker":"旁白"},{"en":"I still haven't given up my resolution to do more reading.","zh":"我仍然没有放弃多读书的决心。","kind":"narration","speaker":"旁白"},{"en":"In fact, I have just bought a book entitled How to Read a Thousand Words a Minute.","zh":"事实上，我刚买了一本名叫《如何一分钟读一千词》的书。","kind":"narration","speaker":"旁白"},{"en":"Perhaps it will solve my problem, but I just haven't had time to read it!","zh":"也许它能解决我的问题，只是我还没抽出时间来读它！","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"year in year out","matchedForm":"year in year out","meaning":"年复一年","note":"固定习语，强调多年反复不变；通常带有重复得令人厌倦的意味。","example":"The same old favourites recur year in year out with monotonous regularity.","exampleZh":"年复一年，反复出现的总是那些老项目，规律得单调乏味。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"carry out","matchedForm":"carry them out","meaning":"实行；落实","note":"短语动词接代词宾语时，要把代词放在 carry 和 out 之间。","example":"Most of us fail in our efforts at self-improvement because our schemes are too ambitious and we never have time to carry them out.","exampleZh":"我们大多数人在自我改进上的努力以失败告终，是因为计划太过宏大，始终没有时间付诸实行。","sourceParagraphIndex":0,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"keep something to oneself","matchedForm":"keep my resolutions to myself","meaning":"把……藏在心里不告诉别人","note":"to oneself 表示只留给自己，这里强调没有向别人宣布。","example":"Aware of these pitfalls, this year I attempted to keep my resolutions to myself.","exampleZh":"意识到这些陷阱后，今年我试着把自己的决心藏在心里。","sourceParagraphIndex":0,"sourceSentenceIndex":8,"sourceType":"textbook-passage"},{"phrase":"little by little","matchedForm":"Little by little","meaning":"一点一点地","note":"表示渐进变化，常置于句首或句末。","example":"Little by little the eleven minutes fell to zero.","exampleZh":"那十一分钟一点点缩减，最后变成了零。","sourceParagraphIndex":1,"sourceSentenceIndex":9,"sourceType":"textbook-passage"},{"phrase":"doze off","matchedForm":"dozing off","meaning":"打起瞌睡；迷迷糊糊睡去","note":"强调从清醒进入浅睡的过程，常指并非刻意入睡。","example":"That proved to be my undoing, for I soon got back to my old bad habit of dozing off in front of the screen.","exampleZh":"这一步最终毁了我的计划，因为我很快又恢复了在屏幕前打瞌睡的老毛病。","sourceParagraphIndex":1,"sourceSentenceIndex":14,"sourceType":"textbook-passage"},{"phrase":"give up","matchedForm":"given up","meaning":"放弃","note":"后接名词或动名词；这里现在完成时与 still、not 连用，表示至今未放弃。","example":"I still haven't given up my resolution to do more reading.","exampleZh":"我仍然没有放弃多读书的决心。","sourceParagraphIndex":1,"sourceSentenceIndex":15,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b3-l051","book":3,"number":51,"title":"Predicting the future","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Predicting the future is notoriously difficult.","zh":"预测未来之难，是人所共知的。","kind":"narration","speaker":"旁白"},{"en":"Who could have imagined, in the mid 1970s, for example, that by the end of the 20th century, computers would be as common in people’s homes as TV sets?","zh":"譬如，在二十世纪七十年代中期，谁能想象到，到了二十世纪末，电脑会在家庭中像电视机一样普遍呢？","kind":"narration","speaker":"旁白"},{"en":"In the 1970s, computers were common enough, but only in big business, government departments, and large organizations.","zh":"二十世纪七十年代，电脑已相当常见，但仅限于大企业、政府部门和大型机构。","kind":"narration","speaker":"旁白"},{"en":"These were the so-called mainframe machines.","zh":"那就是所谓的大型主机。","kind":"narration","speaker":"旁白"},{"en":"Mainframe computers were very large indeed, often occupying whole air-conditioned rooms, employing full-time technicians and run on specially-written software.","zh":"大型主机确实非常庞大，常常占据整间空调房，需要专职技术人员照管，并运行专门编写的软件。","kind":"narration","speaker":"旁白"},{"en":"Though these large machines still exist, many of their functions have been taken over by small powerful personal computers, commonly known as PCs.","zh":"这些大型机器虽然仍然存在，但它们的许多功能已经被小巧而强大的个人电脑接替，个人电脑通常简称为PC。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"In 1975, a primitive machine called the Altair, was launched in the USA.","zh":"一九七五年，美国推出了一种叫作“牛郎星”的原始机器。","kind":"narration","speaker":"旁白"},{"en":"It can properly be described as the first ‘home computer’ and it pointed the way to the future.","zh":"把它称为第一台“家用电脑”是恰当的，它为未来指明了方向。","kind":"narration","speaker":"旁白"},{"en":"This was followed, at the end of the 1970s, by a machine called an Apple.","zh":"随后，二十世纪七十年代末，又出现了一种名叫“苹果”的机器。","kind":"narration","speaker":"旁白"},{"en":"In the early 1980s, the computer giant, IBM produced the world’s first Personal Computer.","zh":"二十世纪八十年代初，电脑巨头IBM制造了世界上第一台个人电脑。","kind":"narration","speaker":"旁白"},{"en":"This ran on an ‘operating system’ called DOS, produced by a then small company named Microsoft.","zh":"它使用一种名叫DOS的“操作系统”，由当时一家叫微软的小公司开发。","kind":"narration","speaker":"旁白"},{"en":"The IBM Personal Computer was widely copied.","zh":"IBM的个人电脑被广泛仿制。","kind":"narration","speaker":"旁白"},{"en":"From those humble beginnings, we have seen the development of the user-friendly home computers and multimedia machines which are in common use today.","zh":"从这些不起眼的开端，我们看到了如今普遍使用、操作便捷的家用电脑和多媒体机器的发展。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"Considering how recent these developments are, it is even more remarkable that as long ago as the 1960s, an Englishman, Leon Bagrit, was able to predict some of the uses of computers which we know today.","zh":"考虑到这些发展都是如此近来的事，早在二十世纪六十年代，一位名叫利昂·巴格里特的英国人就能预见到我们今天熟知的电脑的一些用途，便更显得非同寻常。","kind":"narration","speaker":"旁白"},{"en":"Bagrit dismissed the idea that computers would learn to ‘think’ for themselves and would ‘rule the world’, which people liked to believe in those days.","zh":"巴格里特不认同当时人们乐于相信的一种说法，即电脑会学会自行“思考”，并且“统治世界”。","kind":"narration","speaker":"旁白"},{"en":"Bagrit foresaw a time when computers would be small enough to hold in the hand, when they would be capable of providing information about traffic jams and suggesting alternative routes, when they would be used in hospitals to help doctors to diagnose illnesses, when they would relieve office workers and accountants of dull, repetitive clerical work.","zh":"巴格里特预见，有一天电脑会小到可以拿在手里，会提供交通拥堵信息并建议其他路线，会被用于医院协助医生诊断疾病，还会把办公室职员和会计从枯燥、重复的文书工作中解放出来。","kind":"narration","speaker":"旁白"},{"en":"All these computer uses have become commonplace.","zh":"电脑的所有这些用途，都已经变得司空见惯。","kind":"narration","speaker":"旁白"},{"en":"Of course, Leon Bagrit could not possibly have foreseen the development of the Internet, the worldwide system that enables us to communicate instantly with anyone in any part of the world by using computers linked to telephone networks.","zh":"当然，利昂·巴格里特绝不可能预见互联网的发展；这个覆盖全球的系统，让我们能借助连接电话网络的电脑，与世界任何地方的任何人即时通信。","kind":"narration","speaker":"旁白"},{"en":"Nor could he have foreseen how we could use the Internet to obtain information on every known subject, so we can read it on a screen in our homes and even print it as well if we want to.","zh":"他也不可能预见，我们能够通过互联网获取各个已知领域的信息，在家中的屏幕上阅读，需要时甚至还能打印出来。","kind":"narration","speaker":"旁白"},{"en":"Computers have become smaller and smaller, more and more powerful and cheaper and cheaper.","zh":"电脑变得越来越小、功能越来越强、价格也越来越低。","kind":"narration","speaker":"旁白"},{"en":"This is what makes Leon Bagrit’s predictions particularly remarkable.","zh":"这正是利昂·巴格里特的预言格外令人惊叹的原因。","kind":"narration","speaker":"旁白"},{"en":"If he, or someone like him, were alive today, he might be able to tell us what to expect in the next fifty years.","zh":"如果他，或像他这样的人，今天还活着，也许能告诉我们未来五十年会有什么事情发生。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"take over","matchedForm":"taken over","meaning":"接替；接管","note":"这里以功能作被接替的对象，表示由新的机器承担原来的工作。","example":"Though these large machines still exist, many of their functions have been taken over by small powerful personal computers, commonly known as PCs.","exampleZh":"这些大型机器虽然仍然存在，但它们的许多功能已经被小巧而强大的个人电脑接替，个人电脑通常简称为PC。","sourceParagraphIndex":0,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"point the way to","matchedForm":"pointed the way to","meaning":"为……指明方向","note":"既可指实际道路，也常比喻为未来发展提供方向。","example":"It can properly be described as the first ‘home computer’ and it pointed the way to the future.","exampleZh":"把它称为第一台“家用电脑”是恰当的，它为未来指明了方向。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"in common use","matchedForm":"in common use","meaning":"被普遍使用","note":"常与 be 连用，说明某项技术或某种说法已广泛应用。","example":"From those humble beginnings, we have seen the development of the user-friendly home computers and multimedia machines which are in common use today.","exampleZh":"从这些不起眼的开端，我们看到了如今普遍使用、操作便捷的家用电脑和多媒体机器的发展。","sourceParagraphIndex":1,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"relieve someone of","matchedForm":"relieve office workers and accountants of","meaning":"使某人摆脱……","note":"of 后接负担或职责，表示减轻或解除某人承担的工作。","example":"Bagrit foresaw a time when computers would be small enough to hold in the hand, when they would be capable of providing information about traffic jams and suggesting alternative routes, when they would be used in hospitals to help doctors to diagnose illnesses, when they would relieve office workers and accountants of dull, repetitive clerical work.","exampleZh":"巴格里特预见，有一天电脑会小到可以拿在手里，会提供交通拥堵信息并建议其他路线，会被用于医院协助医生诊断疾病，还会把办公室职员和会计从枯燥、重复的文书工作中解放出来。","sourceParagraphIndex":2,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"become commonplace","matchedForm":"have become commonplace","meaning":"变得司空见惯","note":"commonplace 在这里作形容词，强调原本新奇的事如今十分普遍。","example":"All these computer uses have become commonplace.","exampleZh":"电脑的所有这些用途，都已经变得司空见惯。","sourceParagraphIndex":2,"sourceSentenceIndex":3,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b3-l052","book":3,"number":52,"title":"Mud is mud","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"My cousin, Harry, keeps a large curiously-shaped bottle on permanent display in his study.","zh":"我的表兄哈里在书房里一直摆着一只形状古怪的大瓶子。","kind":"narration","speaker":"旁白"},{"en":"Despite the fact that the bottle is tinted a delicate shade of green, an observant visitor would soon notice that it is filled with what looks like a thick, greyish substance.","zh":"瓶身虽然带着一层淡淡的绿色，细心的来客却很快就会看出，里面装满了某种看上去黏稠、呈灰色的东西。","kind":"narration","speaker":"旁白"},{"en":"If you were to ask Harry what was in the bottle, he would tell you that it contained perfumed mud.","zh":"你要是问哈里瓶里装的是什么，他会告诉你，里面是香泥。","kind":"narration","speaker":"旁白"},{"en":"If you expressed doubt or surprise, he would immediately invite you to smell it and then to rub some into your skin.","zh":"你要是表示怀疑或惊讶，他会立刻请你闻一闻，再抹一点在皮肤上。","kind":"narration","speaker":"旁白"},{"en":"This brief experiment would dispel any further doubts you might have.","zh":"这番简短的试验，会让你不再有任何疑问。","kind":"narration","speaker":"旁白"},{"en":"The bottle really does contain perfumed mud.","zh":"瓶里确实装着香泥。","kind":"narration","speaker":"旁白"},{"en":"How Harry came into the possession of this outlandish stuff makes an interesting story which he is fond of relating.","zh":"哈里如何得到这种稀奇古怪的东西，是一个有趣的故事，他很爱把它讲给别人听。","kind":"narration","speaker":"旁白"},{"en":"Furthermore, the acquisition of this bottle cured him of a bad habit he had been developing for years.","zh":"而且，得到这只瓶子，还治好了他多年来逐渐养成的一个坏习惯。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Harry used to consider it a great joke to go into expensive cosmetic shops and make outrageous requests for goods that do not exist.","zh":"哈里过去常把这样一件事当作大乐子：走进高档化妆品店，提出一些离谱的要求，索要根本不存在的商品。","kind":"narration","speaker":"旁白"},{"en":"He would invent fanciful names on the spot.","zh":"他会当场编出各种异想天开的名称。","kind":"narration","speaker":"旁白"},{"en":"On entering a shop, he would ask for a new perfume called ‘Scented Shadow’ or for ‘insoluble bath cubes’.","zh":"一进商店，他就要一种叫“香影”的新香水，或者“不溶解的沐浴块”。","kind":"narration","speaker":"旁白"},{"en":"If a shop assistant told him she had not heard of it, he would pretend to be considerably put out.","zh":"要是女店员告诉他没听说过，他就装出十分不快的样子。","kind":"narration","speaker":"旁白"},{"en":"He loved to be told that one of his imaginary products was temporarily out of stock and he would faithfully promise to call again at some future date, but of course he never did.","zh":"他最喜欢听店员说，他虚构的某种产品只是暂时缺货；他还会信誓旦旦地答应改天再来，当然，他从来不来。","kind":"narration","speaker":"旁白"},{"en":"How Harry managed to keep a straight face during these performances is quite beyond me.","zh":"哈里表演这些把戏时，怎么能一直板着面孔不笑，我真是无法理解。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"Harry does not need to be prompted to explain how he bought his precious bottle of mud.","zh":"用不着别人提醒，哈里就会主动讲起自己怎样买下那瓶珍贵的香泥。","kind":"narration","speaker":"旁白"},{"en":"One day, he went to an exclusive shop in London and asked for ‘Myrolite’.","zh":"有一天，他走进伦敦一家高档商店，开口就要“迈罗莱特”。","kind":"narration","speaker":"旁白"},{"en":"The shop assistant looked puzzled and Harry repeated the word, slowly stressing each syllable.","zh":"女店员露出困惑的神色，哈里又慢慢重复了一遍，把每个音节都念得格外清楚。","kind":"narration","speaker":"旁白"},{"en":"When the woman shook her head in bewilderment, Harry went on to explain that ‘myrolite’ was a hard, amber-like substance which could be used to remove freckles.","zh":"那位女士迷惑地摇摇头，哈里便接着解释说，“迈罗莱特”是一种类似琥珀的坚硬物质，可以用来去雀斑。","kind":"narration","speaker":"旁白"},{"en":"This explanation evidently conveyed something to the woman who searched shelf after shelf.","zh":"这番解释显然让那位女士想到了什么，她开始一架接一架地寻找。","kind":"narration","speaker":"旁白"},{"en":"She produced all sorts of weird concoctions, but none of them met with Harry's requirements.","zh":"她拿出各种古怪的调制品，却没有一种符合哈里的要求。","kind":"narration","speaker":"旁白"},{"en":"When Harry put on his act of being mildly annoyed, the assistant promised to order some for him.","zh":"哈里装出略微恼火的样子，店员便答应替他订一些。","kind":"narration","speaker":"旁白"},{"en":"Intoxicated by his success, Harry then asked for perfumed mud.","zh":"哈里被自己的成功冲昏了头，接着又要香泥。","kind":"narration","speaker":"旁白"},{"en":"He expected the assistant to look at him in blank astonishment.","zh":"他本以为店员会满脸茫然、惊愕地看着自己。","kind":"narration","speaker":"旁白"},{"en":"However, it was his turn to be surprised, for the woman’s eyes immediately lit up and she fetched several bottles which she placed on the counter for Harry to inspect.","zh":"然而，这回轮到他吃惊了：那位女士顿时眼睛一亮，取来几只瓶子，放在柜台上让哈里查看。","kind":"narration","speaker":"旁白"},{"en":"For once, Harry had to admit defeat.","zh":"这一次，哈里不得不认输了。","kind":"narration","speaker":"旁白"},{"en":"He picked up what seemed to be the smallest bottle and discreetly asked the price.","zh":"他拿起看来最小的一瓶，小心翼翼地问价钱。","kind":"narration","speaker":"旁白"},{"en":"He was glad to get away with a mere twenty pounds and he beat a hasty retreat, clutching the precious bottle under his arm.","zh":"只付出二十英镑便能脱身，他已经很高兴了，连忙把那只珍贵的瓶子夹在胳膊下面，匆匆撤退。","kind":"narration","speaker":"旁白"},{"en":"From then on, Harry decided that this little game he had invented might prove to be expensive.","zh":"从那以后，哈里就认定，自己发明的这场小游戏，玩起来可能要花不少钱。","kind":"narration","speaker":"旁白"},{"en":"The curious bottle, which now adorns the bookcase in his study, was his first and last purchase of rare cosmetics.","zh":"如今点缀在他书房书柜上的这只怪瓶子，是他第一次、也是最后一次购买罕见的化妆品。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"cure someone of","matchedForm":"cured him of","meaning":"使某人改掉……","note":"of 后接疾病或坏习惯；这里把坏习惯比作需要治愈的问题。","example":"Furthermore, the acquisition of this bottle cured him of a bad habit he had been developing for years.","exampleZh":"而且，得到这只瓶子，还治好了他多年来逐渐养成的一个坏习惯。","sourceParagraphIndex":0,"sourceSentenceIndex":7,"sourceType":"textbook-passage"},{"phrase":"on the spot","matchedForm":"on the spot","meaning":"当场；就地","note":"这里指无需准备就立即编出，不是只说明地理位置。","example":"He would invent fanciful names on the spot.","exampleZh":"他会当场编出各种异想天开的名称。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"out of stock","matchedForm":"out of stock","meaning":"缺货","note":"可与 be 或 temporarily 连用；反义表达为 in stock。","example":"He loved to be told that one of his imaginary products was temporarily out of stock and he would faithfully promise to call again at some future date, but of course he never did.","exampleZh":"他最喜欢听店员说，他虚构的某种产品只是暂时缺货；他还会信誓旦旦地答应改天再来，当然，他从来不来。","sourceParagraphIndex":1,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"keep a straight face","matchedForm":"keep a straight face","meaning":"忍住不笑；板着脸","note":"通常用于明知可笑却努力保持严肃的情景，face 前保留 a。","example":"How Harry managed to keep a straight face during these performances is quite beyond me.","exampleZh":"哈里表演这些把戏时，怎么能一直板着面孔不笑，我真是无法理解。","sourceParagraphIndex":1,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"admit defeat","matchedForm":"admit defeat","meaning":"认输","note":"defeat 在这个固定搭配中不加冠词，指承认自己失败。","example":"For once, Harry had to admit defeat.","exampleZh":"这一次，哈里不得不认输了。","sourceParagraphIndex":2,"sourceSentenceIndex":10,"sourceType":"textbook-passage"},{"phrase":"beat a hasty retreat","matchedForm":"beat a hasty retreat","meaning":"仓促撤退；赶紧溜走","note":"常带诙谐语气，可描述在尴尬场合赶紧离开。","example":"He was glad to get away with a mere twenty pounds and he beat a hasty retreat, clutching the precious bottle under his arm.","exampleZh":"只付出二十英镑便能脱身，他已经很高兴了，连忙把那只珍贵的瓶子夹在胳膊下面，匆匆撤退。","sourceParagraphIndex":2,"sourceSentenceIndex":12,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b3-l053","book":3,"number":53,"title":"In the public interest","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"The Scandinavian countries are much admired all over the world for their enlightened social policies.","zh":"斯堪的纳维亚各国因其开明的社会政策，在全世界广受赞誉。","kind":"narration","speaker":"旁白"},{"en":"Sweden has evolved an excellent system for protecting the individual citizen from high-handed or incompetent public officers.","zh":"瑞典逐步建立了一套出色的制度，保护公民个人不受专横或不称职的公职人员侵害。","kind":"narration","speaker":"旁白"},{"en":"The system has worked so well, that it has been adopted in other countries too.","zh":"这套制度成效甚佳，其他国家也采用了它。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"The Swedes were the first to recognize that public officials like civil servants, police officers, health inspectors or tax-collectors can make mistakes or act over-zealously in the belief that they are serving the public.","zh":"瑞典人最先认识到，公务员、警察、卫生检查员或税务人员等公职人员，可能会出错，也可能因自以为是在为公众服务而行事过火。","kind":"narration","speaker":"旁白"},{"en":"As long ago as 1809, the Swedish Parliament introduced a scheme to safeguard the interest of the individual.","zh":"早在一八〇九年，瑞典议会就推出了一项保护个人利益的制度。","kind":"narration","speaker":"旁白"},{"en":"A parliamentary committee representing all political parties appoints a person who is suitably qualified to investigate private grievances against the State.","zh":"一个代表所有政党的议会委员会，会任命一位具备适当资格的人，调查个人针对国家机关提出的申诉。","kind":"narration","speaker":"旁白"},{"en":"The official title of the person is ‘Justiteombudsman’, but the Swedes commonly refer to him as the ‘J.O.’ or ‘Ombudsman’.","zh":"此人的正式头衔是“Justiteombudsman”，不过瑞典人通常简称他为“J.O.”或“Ombudsman”，即监察专员。","kind":"narration","speaker":"旁白"},{"en":"The Ombudsman is not subject to political pressure.","zh":"监察专员不受政治压力左右。","kind":"narration","speaker":"旁白"},{"en":"He investigates complaints large and small that come to him from all levels of society.","zh":"他调查来自社会各阶层、提交给他的各种大小申诉。","kind":"narration","speaker":"旁白"},{"en":"As complaints must be made in writing, the Ombudsman receives an average of 1,200 letters a year.","zh":"申诉必须以书面形式提出，因此监察专员平均每年收到一千二百封信。","kind":"narration","speaker":"旁白"},{"en":"He has eight lawyer assistants to help him and he examines every single letter in detail.","zh":"他有八位律师助手协助工作，并会详细审阅每一封来信。","kind":"narration","speaker":"旁白"},{"en":"There is nothing secretive about the Ombudsman’s work, for his correspondence is open to public inspection.","zh":"监察专员的工作没有什么保密之处，因为他的往来函件都可供公众查阅。","kind":"narration","speaker":"旁白"},{"en":"If a citizen’s complaint is justified, the Ombudsman will act on his behalf.","zh":"如果公民的申诉有理，监察专员就会代表他采取行动。","kind":"narration","speaker":"旁白"},{"en":"The action he takes varies according to the nature of the complaint.","zh":"他采取什么行动，取决于申诉的性质。","kind":"narration","speaker":"旁白"},{"en":"He may gently reprimand an official or even suggest to parliament that a law be altered.","zh":"他可能会温和地训诫某位官员，甚至可能向议会建议修改某项法律。","kind":"narration","speaker":"旁白"},{"en":"The following case is a typical example of the Ombudsman's work.","zh":"下面这个案例，就是监察专员工作的一个典型例子。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"A foreigner living in a Swedish village wrote to the Ombudsman complaining that he had been ill-treated by the police, simply because he was a foreigner.","zh":"一位住在瑞典某村庄的外国人写信给监察专员，投诉自己仅仅因为是外国人，就受到了警察的粗暴对待。","kind":"narration","speaker":"旁白"},{"en":"The Ombudsman immediately wrote to the Chief of Police in the district asking him to send a record of the case.","zh":"监察专员立刻写信给该地区的警察局长，要求他寄来这个案件的记录。","kind":"narration","speaker":"旁白"},{"en":"There was nothing in the record to show that the foreigner’s complaint was justified and the Chief of Police strongly denied the accusation.","zh":"记录中没有任何内容能够表明该外国人的申诉有理，而警察局长也坚决否认这项指控。","kind":"narration","speaker":"旁白"},{"en":"It was impossible for the Ombudsman to take action, but when he received a similar complaint from another foreigner in the same village, he immediately sent one of his lawyers to investigate the matter.","zh":"监察专员无法采取行动；但当他又接到同一村庄另一名外国人的类似投诉时，就立即派一位律师去调查此事。","kind":"narration","speaker":"旁白"},{"en":"The lawyer ascertained that a policeman had indeed dealt roughly with foreigners on several occasions.","zh":"律师查明，一名警察确实曾好几次粗暴对待外国人。","kind":"narration","speaker":"旁白"},{"en":"The fact that the policeman was prejudiced against foreigners could not be recorded in the official files.","zh":"那个警察对外国人怀有偏见这一事实，不可能记载在官方档案里。","kind":"narration","speaker":"旁白"},{"en":"It was only possible for the Ombudsman to find this out by sending one of his representatives to check the facts.","zh":"监察专员只有派一位代表去核查事实，才能查出这一情况。","kind":"narration","speaker":"旁白"},{"en":"The policeman in question was severely reprimanded and was informed that if any further complaints were lodged against him, he would be prosecuted.","zh":"涉事警察受到严厉训斥，并被告知，如果再有人投诉他，他就会受到起诉。","kind":"narration","speaker":"旁白"},{"en":"The Ombudsman’s prompt action at once put an end to an unpleasant practice which might have gone unnoticed.","zh":"监察专员的迅速行动，立刻终止了一种原本可能无人察觉的恶劣做法。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"protect someone from","matchedForm":"protecting the individual citizen from","meaning":"保护某人免受……","note":"from 后接威胁来源；强调使保护对象不受到伤害或侵害。","example":"Sweden has evolved an excellent system for protecting the individual citizen from high-handed or incompetent public officers.","exampleZh":"瑞典逐步建立了一套出色的制度，保护公民个人不受专横或不称职的公职人员侵害。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"be subject to","matchedForm":"is not subject to","meaning":"受……支配；受到……影响","note":"subject 在这里作形容词，to 是介词；否定形式表示不受其左右。","example":"The Ombudsman is not subject to political pressure.","exampleZh":"监察专员不受政治压力左右。","sourceParagraphIndex":1,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"in writing","matchedForm":"in writing","meaning":"以书面形式","note":"用于正式通知、申请或申诉，区别于口头表达。","example":"As complaints must be made in writing, the Ombudsman receives an average of 1,200 letters a year.","exampleZh":"申诉必须以书面形式提出，因此监察专员平均每年收到一千二百封信。","sourceParagraphIndex":1,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"on someone’s behalf","matchedForm":"on his behalf","meaning":"代表某人；为某人的利益","note":"所有格随所代表的人变化；也可说 on behalf of someone。","example":"If a citizen’s complaint is justified, the Ombudsman will act on his behalf.","exampleZh":"如果公民的申诉有理，监察专员就会代表他采取行动。","sourceParagraphIndex":1,"sourceSentenceIndex":9,"sourceType":"textbook-passage"},{"phrase":"in question","matchedForm":"in question","meaning":"所涉及的；有关的","note":"位于名词之后，指上文正在谈到的人或物；不一定表示有疑问。","example":"The policeman in question was severely reprimanded and was informed that if any further complaints were lodged against him, he would be prosecuted.","exampleZh":"涉事警察受到严厉训斥，并被告知，如果再有人投诉他，他就会受到起诉。","sourceParagraphIndex":2,"sourceSentenceIndex":7,"sourceType":"textbook-passage"},{"phrase":"put an end to","matchedForm":"put an end to","meaning":"终止；结束","note":"to 是介词，后接要停止的行为或情况；end 前有 an。","example":"The Ombudsman’s prompt action at once put an end to an unpleasant practice which might have gone unnoticed.","exampleZh":"监察专员的迅速行动，立刻终止了一种原本可能无人察觉的恶劣做法。","sourceParagraphIndex":2,"sourceSentenceIndex":8,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b3-l054","book":3,"number":54,"title":"Instinct or cleverness?","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"We have been brought up to fear insects.","zh":"我们从小就被教得害怕昆虫。","kind":"narration","speaker":"旁白"},{"en":"We regard them as unnecessary creatures that do more harm than good.","zh":"我们把它们看作多余的生物，认为它们弊大于利。","kind":"narration","speaker":"旁白"},{"en":"We continually wage war on them, for they contaminate our food, carry diseases, or devour our crops.","zh":"我们不断向它们开战，因为它们污染食物、传播疾病，或吞食庄稼。","kind":"narration","speaker":"旁白"},{"en":"They sting or bite without provocation; they fly uninvited into our rooms on summer nights, or beat against our lighted windows.","zh":"它们会无缘无故地蜇人或咬人；夏夜里不请自来地飞进房间，或者撞击亮着灯的窗户。","kind":"narration","speaker":"旁白"},{"en":"We live in dread not only of unpleasant insects like spiders or wasps, but of quite harmless ones like moths.","zh":"我们不仅害怕蜘蛛、黄蜂这类讨厌的虫子，甚至也害怕飞蛾这类完全无害的虫子。","kind":"narration","speaker":"旁白"},{"en":"Reading about them increases our understanding without dispelling our fears.","zh":"阅读有关它们的书，虽能增进了解，却不能消除恐惧。","kind":"narration","speaker":"旁白"},{"en":"Knowing that the industrious ant lives in a highly organized society does nothing to prevent us from being filled with revulsion when we find hordes of them crawling over a carefully prepared picnic lunch.","zh":"即使知道勤劳的蚂蚁生活在一个组织严密的社会里，当我们发现成群的蚂蚁爬满精心准备的野餐午饭时，也仍然会满心厌恶。","kind":"narration","speaker":"旁白"},{"en":"No matter how much we like honey, or how much we have read about the uncanny sense of direction which bees possess, we have a horror of being stung.","zh":"无论我们多么喜欢蜂蜜，读过多少关于蜜蜂那神奇方向感的文章，还是会害怕被蜇。","kind":"narration","speaker":"旁白"},{"en":"Most of our fears are unreasonable; but they are impossible to erase.","zh":"我们的恐惧大多没有道理，却又无法消除。","kind":"narration","speaker":"旁白"},{"en":"At the same time, however, insects are strangely fascinating.","zh":"然而与此同时，昆虫又有一种奇妙的吸引力。","kind":"narration","speaker":"旁白"},{"en":"We enjoy reading about them, especially when we find that, like the praying mantis, they lead perfectly horrible lives.","zh":"我们爱读关于它们的故事，尤其当我们发现，它们像螳螂一样，过着极其可怕的生活时。","kind":"narration","speaker":"旁白"},{"en":"We enjoy staring at them, entranced as they go about their business, unaware (we hope) of our presence.","zh":"我们喜欢出神地盯着它们，看它们各忙各的，浑然不觉我们在场——但愿如此。","kind":"narration","speaker":"旁白"},{"en":"Who has not stood in awe at the sight of a spider pouncing on a fly, or a column of ants triumphantly bearing home an enormous dead beetle?","zh":"看到蜘蛛扑向苍蝇，或一队蚂蚁得意地把一只巨大的死甲虫抬回家，谁不曾肃然惊叹？","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Last summer I spent days in the garden watching thousands of ants crawling up the trunk of my prize peach tree.","zh":"去年夏天，我在花园里接连几天观察成千上万只蚂蚁，看它们沿着我那棵引以为傲的桃树的树干往上爬。","kind":"narration","speaker":"旁白"},{"en":"The tree has grown against a warm wall on a sheltered side of the house.","zh":"这棵树靠着房屋背风一侧的一面温暖的墙生长。","kind":"narration","speaker":"旁白"},{"en":"I am especially proud of it, not only because it has survived several severe winters, but because it occasionally produces luscious peaches.","zh":"我对它格外自豪，不仅因为它熬过了几个严冬，还因为它偶尔能结出甘美多汁的桃子。","kind":"narration","speaker":"旁白"},{"en":"During the summer, I noticed that the leaves of the tree were beginning to wither.","zh":"夏天里，我注意到树叶开始枯萎。","kind":"narration","speaker":"旁白"},{"en":"Clusters of tiny insects called aphids were to be found on the underside of the leaves.","zh":"叶子的背面能看到一团团叫作蚜虫的小虫。","kind":"narration","speaker":"旁白"},{"en":"They were visited by a large colony of ants which obtained a sort of honey from them.","zh":"一大群蚂蚁经常来找它们，从它们身上取得一种蜜汁。","kind":"narration","speaker":"旁白"},{"en":"I immediately embarked on an experiment which, even though it failed to get rid of the ants, kept me fascinated for twenty-four hours.","zh":"我立刻着手做了一项试验；虽然没能赶走蚂蚁，却让我整整二十四小时着迷不已。","kind":"narration","speaker":"旁白"},{"en":"I bound the base of the tree with sticky tape, making it impossible for the ants to reach the aphids.","zh":"我用黏胶带缠住树干基部，让蚂蚁无法接近蚜虫。","kind":"narration","speaker":"旁白"},{"en":"The tape was so sticky that they did not dare to cross it.","zh":"胶带黏得厉害，蚂蚁不敢从上面爬过去。","kind":"narration","speaker":"旁白"},{"en":"For a long time, I watched them scurrying around the base of the tree in bewilderment.","zh":"我久久地看着它们困惑地在树根周围匆匆乱跑。","kind":"narration","speaker":"旁白"},{"en":"I even went out at midnight with a torch and noted with satisfaction (and surprise) that the ants were still swarming around the sticky tape without being able to do anything about it.","zh":"我甚至在半夜拿着手电筒出去，满意又惊讶地发现，蚂蚁仍在黏胶带周围聚作一团，束手无策。","kind":"narration","speaker":"旁白"},{"en":"I got up early next morning hoping to find that the ants had given up in despair.","zh":"第二天一早我就起了床，希望看到蚂蚁已经绝望地放弃。","kind":"narration","speaker":"旁白"},{"en":"Instead, I saw that they had discovered a new route.","zh":"但我看到的却是，它们已经找到了一条新路线。","kind":"narration","speaker":"旁白"},{"en":"They were climbing up the wall of the house and then on to the leaves of the tree.","zh":"它们先爬上房子的墙，再爬到树叶上。","kind":"narration","speaker":"旁白"},{"en":"I realized sadly that I had been completely defeated by their ingenuity.","zh":"我沮丧地意识到，自己已经彻底败给了它们的机灵。","kind":"narration","speaker":"旁白"},{"en":"The ants had been quick to find an answer to my thoroughly unscientific methods!","zh":"对于我那完全不科学的办法，蚂蚁很快就找到了对策！","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"bring up","matchedForm":"brought up","meaning":"教育；养育","note":"这里为被动形式，bring someone up to do something 表示从小培养某种态度或习惯。","example":"We have been brought up to fear insects.","exampleZh":"我们从小就被教得害怕昆虫。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"do more harm than good","matchedForm":"do more harm than good","meaning":"弊大于利","note":"固定比较表达，harm 和 good 都作名词，表示坏处和好处。","example":"We regard them as unnecessary creatures that do more harm than good.","exampleZh":"我们把它们看作多余的生物，认为它们弊大于利。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"wage war on","matchedForm":"wage war on","meaning":"向……开战","note":"可用于实际战争，也常比喻持续对抗害虫、疾病等问题。","example":"We continually wage war on them, for they contaminate our food, carry diseases, or devour our crops.","exampleZh":"我们不断向它们开战，因为它们污染食物、传播疾病，或吞食庄稼。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"get rid of","matchedForm":"get rid of","meaning":"摆脱；除掉","note":"后接不想保留的人、物或问题；这里指赶走蚂蚁。","example":"I immediately embarked on an experiment which, even though it failed to get rid of the ants, kept me fascinated for twenty-four hours.","exampleZh":"我立刻着手做了一项试验；虽然没能赶走蚂蚁，却让我整整二十四小时着迷不已。","sourceParagraphIndex":1,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"give up in despair","matchedForm":"given up in despair","meaning":"绝望地放弃","note":"give up 可单独使用，in despair 补充放弃时的心情。","example":"I got up early next morning hoping to find that the ants had given up in despair.","exampleZh":"第二天一早我就起了床，希望看到蚂蚁已经绝望地放弃。","sourceParagraphIndex":1,"sourceSentenceIndex":11,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b3-l055","book":3,"number":55,"title":"From the earth: Greetings","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Recent developments in astronomy have made it possible to detect planets in our own Milky Way and in other galaxies.","zh":"天文学近期的发展，使人类能够探测到我们银河系以及其他星系中的行星。","kind":"narration","speaker":"旁白"},{"en":"This is a major achievement because, in relative terms, planets are very small and do not emit light.","zh":"这是一项重大成就，因为相对而言，行星十分微小，而且自身不发光。","kind":"narration","speaker":"旁白"},{"en":"Finding planets is proving hard enough, but finding life on them will prove infinitely more difficult.","zh":"寻找行星已经证明够困难了，但要在行星上寻找生命，难度将大得不可比拟。","kind":"narration","speaker":"旁白"},{"en":"The first question to answer is whether a planet can actually support life.","zh":"首先需要回答的问题是，一颗行星究竟能不能维持生命。","kind":"narration","speaker":"旁白"},{"en":"In our own solar system, for example, Venus is far too hot and Mars is far too cold to support life.","zh":"例如，在我们的太阳系里，金星太热，火星又太冷，都无法维持生命。","kind":"narration","speaker":"旁白"},{"en":"Only the Earth provides ideal conditions, and even here it has taken more than four billion years for plant and animal life to evolve.","zh":"只有地球提供了理想的条件；可即便在这里，动植物生命的演化也花了四十多亿年。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Whether a planet can support life depends on the size and brightness of its star, that is its ‘sun’.","zh":"一颗行星能否维持生命，取决于它所属恒星，也就是它的“太阳”的大小和亮度。","kind":"narration","speaker":"旁白"},{"en":"Imagine a star up to twenty times larger, brighter and hotter than our own sun.","zh":"想象一颗恒星，它的大小、亮度和温度，都可达到我们太阳的二十倍。","kind":"narration","speaker":"旁白"},{"en":"A planet would have to be a very long way from it to be capable of supporting life.","zh":"一颗行星必须离它非常远，才有可能维持生命。","kind":"narration","speaker":"旁白"},{"en":"Alternatively, if the star were small, the life-supporting planet would have to have a close orbit round it and also provide the perfect conditions for life forms to develop.","zh":"反过来，如果恒星很小，能够维持生命的行星就必须沿着离它很近的轨道运行，同时还得具备让生命形态发展的完美条件。","kind":"narration","speaker":"旁白"},{"en":"But how would we find such a planet?","zh":"可是，我们怎样才能找到这样的行星呢？","kind":"narration","speaker":"旁白"},{"en":"At present, there is no telescope in existence that is capable of detecting the presence of life.","zh":"目前，还没有一架现存的望远镜能够探测生命的存在。","kind":"narration","speaker":"旁白"},{"en":"The development of such a telescope will be one of the great astronomical projects of the twenty-first century.","zh":"研制这样的望远镜，将成为二十一世纪天文学的重大项目之一。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"It is impossible to look for life on another planet using earth-based telescopes.","zh":"用设在地球上的望远镜，不可能寻找其他行星上的生命。","kind":"narration","speaker":"旁白"},{"en":"Our own warm atmosphere and the heat generated by the telescope would make it impossible to detect objects as small as planets.","zh":"我们自身温暖的大气，以及望远镜产生的热量，会让探测像行星这样小的物体成为不可能。","kind":"narration","speaker":"旁白"},{"en":"Even a telescope in orbit round the earth, like the very successful Hubble telescope, would not be suitable because of the dust particles in our solar system.","zh":"即使是像极为成功的哈勃望远镜那样绕地球运行的望远镜，也会由于太阳系内的尘埃颗粒而不适合这项任务。","kind":"narration","speaker":"旁白"},{"en":"A telescope would have to be as far away as the planet Jupiter to look for life in outer space, because the dust becomes thinner the further we travel towards the outer edges of our own solar system.","zh":"要寻找外太空的生命，望远镜必须远到木星所在的位置，因为越往太阳系外围走，尘埃就越稀薄。","kind":"narration","speaker":"旁白"},{"en":"Once we detected a planet, we would have to find a way of blotting out the light from its star, so that we would be able to ‘see’ the planet properly and analyse its atmosphere.","zh":"一旦探测到一颗行星，我们还必须想办法遮住它所属恒星的光，才能真正“看清”这颗行星，分析它的大气。","kind":"narration","speaker":"旁白"},{"en":"In the first instance, we would be looking for plant life, rather than ‘little green men’.","zh":"最初，我们要寻找的会是植物生命，而不是“小绿人”。","kind":"narration","speaker":"旁白"},{"en":"The life forms most likely to develop on a planet would be bacteria.","zh":"一颗行星上最可能发展出的生命形态，会是细菌。","kind":"narration","speaker":"旁白"},{"en":"It is bacteria that have generated the oxygen we breathe on earth.","zh":"正是细菌产生了我们在地球上呼吸的氧气。","kind":"narration","speaker":"旁白"},{"en":"For most of the earth’s history they have been the only form of life on our planet.","zh":"在地球历史的大部分时期，它们都是这个星球上唯一的生命形态。","kind":"narration","speaker":"旁白"},{"en":"As Earth-dwellers, we always cherish the hope that we will be visited by little green men and that we will be able to communicate with them.","zh":"身为地球居民，我们总怀着希望，盼着小绿人来访，并且能够与他们沟通。","kind":"narration","speaker":"旁白"},{"en":"But this hope is always in the realms of science fiction.","zh":"不过，这种希望始终只存在于科幻领域之中。","kind":"narration","speaker":"旁白"},{"en":"If we were able to discover lowly forms of life like bacteria on another planet, it would completely change our view of ourselves.","zh":"如果我们能在另一颗行星上发现像细菌这样的低等生命，就会彻底改变我们对自身的看法。","kind":"narration","speaker":"旁白"},{"en":"As Daniel Goldin of NASA observed, ‘Finding life elsewhere would change everything.","zh":"正如美国国家航空航天局的丹尼尔·戈尔丁所说：“在别处发现生命，将会改变一切。","kind":"speech","speaker":"丹尼尔·戈尔丁"},{"en":"No human endeavour or thought would be unchanged by it.’","zh":"人类的任何努力、任何思想，都会因此发生改变。”","kind":"speech","speaker":"丹尼尔·戈尔丁"}]}],"usage":[{"phrase":"in relative terms","matchedForm":"in relative terms","meaning":"相对而言","note":"用于说明判断是比较后的结果，避免把相对大小说成绝对大小。","example":"This is a major achievement because, in relative terms, planets are very small and do not emit light.","exampleZh":"这是一项重大成就，因为相对而言，行星十分微小，而且自身不发光。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"support life","matchedForm":"support life","meaning":"维持生命存在","note":"support 在此指提供生存条件，不是对某种看法表示支持。","example":"The first question to answer is whether a planet can actually support life.","exampleZh":"首先需要回答的问题是，一颗行星究竟能不能维持生命。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"blot out","matchedForm":"blotting out","meaning":"遮蔽；挡住","note":"常用于遮住光线或视线，也可引申为从记忆中抹去。","example":"Once we detected a planet, we would have to find a way of blotting out the light from its star, so that we would be able to ‘see’ the planet properly and analyse its atmosphere.","exampleZh":"一旦探测到一颗行星，我们还必须想办法遮住它所属恒星的光，才能真正“看清”这颗行星，分析它的大气。","sourceParagraphIndex":2,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"in the first instance","matchedForm":"In the first instance","meaning":"起初；首先","note":"强调行动或考虑的第一步，常用于较正式的表达。","example":"In the first instance, we would be looking for plant life, rather than ‘little green men’.","exampleZh":"最初，我们要寻找的会是植物生命，而不是“小绿人”。","sourceParagraphIndex":2,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"cherish the hope that","matchedForm":"cherish the hope that","meaning":"怀着……的希望","note":"that 后接希望实现的事情；cherish 带有珍视并长期抱有的意味。","example":"As Earth-dwellers, we always cherish the hope that we will be visited by little green men and that we will be able to communicate with them.","exampleZh":"身为地球居民，我们总怀着希望，盼着小绿人来访，并且能够与他们沟通。","sourceParagraphIndex":2,"sourceSentenceIndex":9,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b3-l056","book":3,"number":56,"title":"Our neighbour, the river","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"The river which forms the eastern boundary of our farm has always played an important part in our lives.","zh":"那条构成我们农场东部边界的河，一直在我们的生活中扮演着重要角色。","kind":"narration","speaker":"旁白"},{"en":"Without it we could not make a living.","zh":"没有它，我们就无法谋生。","kind":"narration","speaker":"旁白"},{"en":"There is only enough spring water to supply the needs of the house, so we have to pump from the river for farm use.","zh":"泉水只够供家里生活所需，所以农场用水必须从河里抽取。","kind":"narration","speaker":"旁白"},{"en":"We tell the river all our secrets.","zh":"我们把所有秘密都告诉这条河。","kind":"narration","speaker":"旁白"},{"en":"We know instinctively, just as beekeepers with their bees, that misfortune might overtake us if the important events of our lives were not related to it.","zh":"正如养蜂人与蜜蜂之间的关系一样，我们本能地知道，如果不把生活中的重大事情讲给河听，厄运就可能降临到我们头上。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"We have special river birthday parties in the summer.","zh":"夏天，我们会举办别具一格的河畔生日聚会。","kind":"narration","speaker":"旁白"},{"en":"Sometimes we go upstream to a favourite backwater, sometimes we have our party at the boathouse, which a predecessor of ours at the farm built in the meadow hard by the deepest pool for swimming and diving.","zh":"有时，我们逆流而上，去一处最喜欢的回水湾；有时就在船屋聚会，那是以前经营这座农场的一位主人，建在紧挨着最深水潭的草地上的，供游泳和跳水之用。","kind":"narration","speaker":"旁白"},{"en":"In a heat wave we choose a midnight birthday party and that is the most exciting of all.","zh":"热浪来袭时，我们选择在午夜开生日聚会，这种聚会是最令人兴奋的。","kind":"narration","speaker":"旁白"},{"en":"We welcome the seasons by the riverside, crowning the youngest girl with flowers in the spring, holding a summer festival on Midsummer Eve, giving thanks for the harvest in the autumn, and throwing a holly wreath into the current in the winter.","zh":"我们在河边迎接四季：春天给最小的女孩戴上花冠，仲夏前夜举行夏日庆典，秋天感谢丰收，冬天则把冬青花环投入水流。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"After a long period of rain the river may overflow its banks.","zh":"久雨之后，河水可能漫过两岸。","kind":"narration","speaker":"旁白"},{"en":"This is a rare occurrence as our climate seldom goes to extremes.","zh":"这种情况很少发生，因为我们这里的气候很少走向极端。","kind":"narration","speaker":"旁白"},{"en":"We are lucky in that only the lower fields, which make up a very small proportion of our farm, are affected by flooding, but other farms are less favourably sited, and flooding can sometimes spell disaster for their owners.","zh":"我们很幸运，只有低洼的田地会受洪水影响，而这些田地只占农场很小的一部分；但别的农场位置没这么好，洪水有时会给农场主带来灾难。","kind":"narration","speaker":"旁白"}]},{"index":3,"rows":[{"en":"One bad winter we watched the river creep up the lower meadows.","zh":"有一年冬天格外恶劣，我们看着河水慢慢漫上地势较低的草场。","kind":"narration","speaker":"旁白"},{"en":"All the cattle had been moved into stalls and we stood to lose little.","zh":"牛群已全都赶进牛棚，因此我们预计损失不会很大。","kind":"narration","speaker":"旁白"},{"en":"We were, however, worried about our nearest neighbours, whose farm was low lying and who were newcomers to the district.","zh":"不过，我们担心最近的邻居；他们的农场地势低，而且他们刚搬来这个地区不久。","kind":"narration","speaker":"旁白"},{"en":"As the floods had put the telephone out of order, we could not find out how they were managing.","zh":"洪水使电话出了故障，我们无法打听他们应付得怎么样。","kind":"narration","speaker":"旁白"},{"en":"From an attic window we could get a sweeping view of the river where their land joined ours, and at the most critical juncture we took turns in watching that point.","zh":"从阁楼的窗户望去，我们能把两家土地相接处的河段尽收眼底；到了最危急的关头，我们轮流守望着那里。","kind":"narration","speaker":"旁白"},{"en":"The first sign of disaster was a dead sheep floating down.","zh":"灾难最初的迹象，是一只顺流漂下来的死羊。","kind":"narration","speaker":"旁白"},{"en":"Next came a horse, swimming bravely, but we were afraid that the strength of the current would prevent its landing anywhere before it became exhausted.","zh":"接着来了一匹马，奋力游着；但我们担心，水流太强，它恐怕还来不及找到地方上岸，就会筋疲力尽。","kind":"narration","speaker":"旁白"},{"en":"Suddenly a raft appeared, looking rather like Noah's ark, carrying the whole family, a few hens, the dogs, a cat, and a bird in a cage.","zh":"突然，一只木筏出现了，看起来颇像诺亚方舟，上面载着那一家人、几只母鸡、几条狗、一只猫，还有笼中的一只鸟。","kind":"narration","speaker":"旁白"},{"en":"We realized that they must have become unduly frightened by the rising flood, for their house, which had sound foundations, would have stood stoutly even if it had been almost submerged.","zh":"我们明白，他们一定是被不断上涨的洪水吓过了头，因为他们的房子地基牢固，即使几乎被水淹没，也会坚稳地屹立着。","kind":"narration","speaker":"旁白"},{"en":"The men of our family waded down through our flooded meadows with boathooks, in the hope of being able to grapple a corner of the raft and pull it out of the current towards our bank.","zh":"我们家的男人拿着船钩，涉过被淹的草场，希望能钩住木筏的一角，把它从急流中拉向我们这边的河岸。","kind":"narration","speaker":"旁白"},{"en":"We still think it a miracle that they were able to do so.","zh":"他们居然做到了，我们至今仍觉得这是个奇迹。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"play an important part in","matchedForm":"played an important part in","meaning":"在……中起重要作用","note":"part 在这里指作用或角色；可把 important 换成 major、vital 等。","example":"The river which forms the eastern boundary of our farm has always played an important part in our lives.","exampleZh":"那条构成我们农场东部边界的河，一直在我们的生活中扮演着重要角色。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"make a living","matchedForm":"make a living","meaning":"谋生","note":"常用 by doing something 说明谋生方式；living 前保留 a。","example":"Without it we could not make a living.","exampleZh":"没有它，我们就无法谋生。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"go to extremes","matchedForm":"goes to extremes","meaning":"走向极端","note":"可形容人的行为，也可像本例一样形容气候变化过于极端。","example":"This is a rare occurrence as our climate seldom goes to extremes.","exampleZh":"这种情况很少发生，因为我们这里的气候很少走向极端。","sourceParagraphIndex":2,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"out of order","matchedForm":"out of order","meaning":"发生故障；不能正常使用","note":"常用于电话、机器等设备；在别的语境中也可指秩序不当。","example":"As the floods had put the telephone out of order, we could not find out how they were managing.","exampleZh":"洪水使电话出了故障，我们无法打听他们应付得怎么样。","sourceParagraphIndex":3,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"take turns in doing","matchedForm":"took turns in watching","meaning":"轮流做……","note":"表示几个人交替承担同一件事；也常用 take turns doing。","example":"From an attic window we could get a sweeping view of the river where their land joined ours, and at the most critical juncture we took turns in watching that point.","exampleZh":"从阁楼的窗户望去，我们能把两家土地相接处的河段尽收眼底；到了最危急的关头，我们轮流守望着那里。","sourceParagraphIndex":3,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"in the hope of","matchedForm":"in the hope of","meaning":"抱着……的希望","note":"of 后接名词或动名词；若用 that，则后接完整句子。","example":"The men of our family waded down through our flooded meadows with boathooks, in the hope of being able to grapple a corner of the raft and pull it out of the current towards our bank.","exampleZh":"我们家的男人拿着船钩，涉过被淹的草场，希望能钩住木筏的一角，把它从急流中拉向我们这边的河岸。","sourceParagraphIndex":3,"sourceSentenceIndex":9,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b3-l057","book":3,"number":57,"title":"Back in the old country","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"I stopped to let the car cool off and to study the map.","zh":"我停下车，让汽车降降温，也研究一下地图。","kind":"narration","speaker":"旁白"},{"en":"I had expected to be near my objective by now, but everything still seemed alien to me.","zh":"我原以为到这时应该已经接近目的地，可周围一切对我来说仍显得陌生。","kind":"narration","speaker":"旁白"},{"en":"I was only five when my father had taken me abroad, and that was eighteen years ago.","zh":"父亲带我出国时，我才五岁，那是十八年前的事了。","kind":"narration","speaker":"旁白"},{"en":"When my mother had died after a tragic accident, he did not quickly recover from the shock and loneliness.","zh":"母亲在一次悲惨的事故后去世，父亲久久无法从打击和孤独中恢复过来。","kind":"narration","speaker":"旁白"},{"en":"Everything around him was full of her presence, continually reopening the wound.","zh":"身边处处都留着母亲的影子，不断揭开他心头的伤口。","kind":"narration","speaker":"旁白"},{"en":"So he decided to emigrate.","zh":"于是，他决定移民。","kind":"narration","speaker":"旁白"},{"en":"In the new country he became absorbed in making a new life for the two of us, so that he gradually ceased to grieve.","zh":"到了新的国家，他一心为我们俩开创新生活，渐渐不再那么悲痛。","kind":"narration","speaker":"旁白"},{"en":"He did not marry again and I was brought up without a woman’s care; but I lacked for nothing, for he was both father and mother to me.","zh":"他没有再婚，我在没有女性照料的环境下长大；但我什么也不缺，因为他对我既当父亲，又当母亲。","kind":"narration","speaker":"旁白"},{"en":"He always meant to go back one day, but not to stay.","zh":"他一直打算总有一天回去一趟，但并不准备留下来。","kind":"narration","speaker":"旁白"},{"en":"His roots and mine had become too firmly embedded in the new land.","zh":"他和我的根，已经在新的土地上扎得太深。","kind":"narration","speaker":"旁白"},{"en":"But he wanted to see the old folk again and to visit my mother’s grave.","zh":"不过，他想再看看故乡的父老，也想去母亲墓前祭扫。","kind":"narration","speaker":"旁白"},{"en":"He became mortally ill a few months before we had planned to go and, when he knew that he was dying, he made me promise to go on my own.","zh":"在我们计划动身前的几个月，他患上了绝症；知道自己不久于人世时，他要我答应独自回去。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"I hired a car the day after landing and bought a comprehensive book of maps, which I found most helpful on the cross-country journey, but which I did not think I should need on the last stage.","zh":"抵达的第二天，我租了一辆汽车，买了一本详尽的地图册；它在横穿乡间的旅程中帮了我很大的忙，但我原以为，最后一段路就用不上它了。","kind":"narration","speaker":"旁白"},{"en":"It was not that I actually remembered anything at all.","zh":"这并不是因为我实际上还记得什么。","kind":"narration","speaker":"旁白"},{"en":"But my father had described over and over again what we should see at every milestone, after leaving the nearest town, so that I was positive I should recognize it as familiar territory.","zh":"而是父亲一遍又一遍描述过，离开最近的小镇后，每经过一个里程碑，我们会看到什么，因此我确信自己会认出那片熟悉的地方。","kind":"narration","speaker":"旁白"},{"en":"Well, I had been wrong, for I was now lost.","zh":"可是我想错了，因为我现在迷路了。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"I looked at the map and then at the milometer.","zh":"我看了看地图，又看了看里程表。","kind":"narration","speaker":"旁白"},{"en":"I had come ten miles since leaving the town, and at this point, according to my father, I should be looking at farms and cottages in a valley, with the spire of the church of our village showing in the far distance.","zh":"离开小镇以来，我已开了十英里；照父亲的说法，在这里我应该能看到山谷中的农场和村舍，以及远处我们村教堂的尖塔。","kind":"narration","speaker":"旁白"},{"en":"I could see no valley, no farms, no cottages and no church spire — only a lake.","zh":"我看不见山谷、农场、村舍，也看不见教堂尖塔——只有一片湖。","kind":"narration","speaker":"旁白"},{"en":"I decided that I must have taken a wrong turning somewhere.","zh":"我认定自己一定是在某个地方拐错了路。","kind":"narration","speaker":"旁白"},{"en":"So I drove back to the town and began to retrace the route, taking frequent glances at the map.","zh":"于是我开回小镇，重新沿着那条路线走，不时看一眼地图。","kind":"narration","speaker":"旁白"},{"en":"I landed up at the same corner.","zh":"结果，我又回到了同一个转角。","kind":"narration","speaker":"旁白"},{"en":"The curious thing was that the lake was not marked on the map.","zh":"奇怪的是，地图上并没有标出这个湖。","kind":"narration","speaker":"旁白"},{"en":"I felt as if I had stumbled into a nightmare country, as you sometimes do in dreams.","zh":"我觉得自己好像误入了一个噩梦般的国度，就像有时在梦中会发生的那样。","kind":"narration","speaker":"旁白"},{"en":"And, as in a nightmare, there was nobody in sight to help me.","zh":"也像噩梦里一样，视线中没有一个能帮我的人。","kind":"narration","speaker":"旁白"},{"en":"Fortunately for me, as I was wondering what to do next, there appeared on the horizon a man on horseback, riding in my direction.","zh":"幸好，就在我盘算下一步该怎么办时，地平线上出现了一个骑马的人，正朝我这边过来。","kind":"narration","speaker":"旁白"},{"en":"I waited till he came near, then I asked him the way to our old village.","zh":"我等他走近，便向他打听通往我们旧日村庄的路。","kind":"narration","speaker":"旁白"},{"en":"He said that there was now no village.","zh":"他说，如今已经没有那个村子了。","kind":"narration","speaker":"旁白"},{"en":"I thought he must have misunderstood me, so I repeated its name.","zh":"我以为他一定误解了我的话，于是又说了一遍村名。","kind":"narration","speaker":"旁白"},{"en":"This time he pointed to the lake.","zh":"这一次，他指向了湖。","kind":"narration","speaker":"旁白"},{"en":"The village no longer existed because it had been submerged, and all the valley too.","zh":"村庄已经不复存在，因为它连同整个山谷都被水淹没了。","kind":"narration","speaker":"旁白"},{"en":"The lake was not a natural one, but a man-made reservoir.","zh":"那个湖并不是天然湖泊，而是一座人工水库。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"cool off","matchedForm":"cool off","meaning":"冷却；降温","note":"此处指汽车散热，也可比喻人冷静下来、怒气消退。","example":"I stopped to let the car cool off and to study the map.","exampleZh":"我停下车，让汽车降降温，也研究一下地图。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"be absorbed in","matchedForm":"became absorbed in","meaning":"专心投入……","note":"in 后接名词或动名词，强调注意力完全投入其中。","example":"In the new country he became absorbed in making a new life for the two of us, so that he gradually ceased to grieve.","exampleZh":"到了新的国家，他一心为我们俩开创新生活，渐渐不再那么悲痛。","sourceParagraphIndex":0,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"lack for nothing","matchedForm":"lacked for nothing","meaning":"应有尽有；什么也不缺","note":"lack for 通常用于否定句；本例强调生活所需得到充分满足。","example":"He did not marry again and I was brought up without a woman’s care; but I lacked for nothing, for he was both father and mother to me.","exampleZh":"他没有再婚，我在没有女性照料的环境下长大；但我什么也不缺，因为他对我既当父亲，又当母亲。","sourceParagraphIndex":0,"sourceSentenceIndex":7,"sourceType":"textbook-passage"},{"phrase":"over and over again","matchedForm":"over and over again","meaning":"一遍又一遍","note":"强调重复很多次，常用于讲述、练习或检查。","example":"But my father had described over and over again what we should see at every milestone, after leaving the nearest town, so that I was positive I should recognize it as familiar territory.","exampleZh":"而是父亲一遍又一遍描述过，离开最近的小镇后，每经过一个里程碑，我们会看到什么，因此我确信自己会认出那片熟悉的地方。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"land up","matchedForm":"landed up","meaning":"最后到了；结果落在","note":"口语中常表示非预期地到达某处，也可用 land up in 或 at 引出地点。","example":"I landed up at the same corner.","exampleZh":"结果，我又回到了同一个转角。","sourceParagraphIndex":2,"sourceSentenceIndex":5,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b3-l058","book":3,"number":58,"title":"A spot of bother","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"The old lady was glad to be back at the block of flats where she lived.","zh":"老太太回到自己住的那幢公寓楼，很是高兴。","kind":"narration","speaker":"旁白"},{"en":"Her shopping had tired her and her basket had grown heavier with every step of the way home.","zh":"买东西让她累坏了，回家的一路上，每走一步都觉得篮子更重些。","kind":"narration","speaker":"旁白"},{"en":"In the lift her thoughts were on lunch and a good rest; but when she got out at her own floor, both were forgotten in her sudden discovery that her front door was open.","zh":"坐电梯时，她想着吃午饭、好好休息；可到了自己的楼层一出电梯，突然发现家门开着，这两个念头顿时全忘了。","kind":"narration","speaker":"旁白"},{"en":"She was thinking that she must reprimand her home help the next morning for such a monstrous piece of negligence, when she remembered that she had gone shopping after the home help had left and she knew that she had turned both keys in their locks.","zh":"她正想着第二天早上一定要责备家务帮工，怎么会如此严重地疏忽，忽然又想起来，自己是在帮工走后才出门购物的，而且她清楚记得，两把钥匙都已在锁里转过、把门锁好了。","kind":"narration","speaker":"旁白"},{"en":"She walked slowly into the hall and at once noticed that all the room doors were open, yet following her regular practice she had shut them before going out.","zh":"她慢慢走进门厅，马上发现各个房间的门都敞着，可她出门前明明照老习惯把它们都关上了。","kind":"narration","speaker":"旁白"},{"en":"Looking into the drawing room, she saw a scene of confusion over by her writing desk.","zh":"朝客厅里望去，她看到写字台那边一片狼藉。","kind":"narration","speaker":"旁白"},{"en":"It was as clear as daylight then that burglars had forced an entry during her absence.","zh":"这下再清楚不过了：她不在家时，有窃贼闯了进来。","kind":"narration","speaker":"旁白"},{"en":"Her first impulse was to go round all the rooms looking for the thieves, but then she decided that at her age it might be more prudent to have someone with her, so she went to fetch the porter from his basement.","zh":"她的第一个念头是挨个房间找一找小偷，但转念又觉得，以自己这把年纪，有个人陪着也许更稳妥，于是便去地下室找门房。","kind":"narration","speaker":"旁白"},{"en":"By this time her legs were beginning to tremble, so she sat down and accepted a cup of very strong tea, while he telephoned the police.","zh":"这时她的双腿开始发抖，便坐下来，接过一杯很浓的茶喝着，而门房则打电话报警。","kind":"narration","speaker":"旁白"},{"en":"Then, her composure regained, she was ready to set off with the porter’s assistance to search for any intruders who might still be lurking in her flat.","zh":"随后，她恢复了镇定，准备在门房的协助下出发，搜查可能仍潜伏在公寓里的入侵者。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"They went through the rooms, being careful to touch nothing, as they did not want to hinder the police in their search for fingerprints.","zh":"他们逐个房间查看，小心地不碰任何东西，以免妨碍警察寻找指纹。","kind":"narration","speaker":"旁白"},{"en":"The chaos was inconceivable.","zh":"屋内的混乱简直难以想象。","kind":"narration","speaker":"旁白"},{"en":"She had lived in the flat for thirty years and was a veritable magpie at hoarding; and it seemed as though everything she possessed had been tossed out and turned over and over.","zh":"她在这套公寓里住了三十年，收藏杂物的本领真像一只喜鹊；她所有的东西似乎都被抛了出来，翻了个底朝天。","kind":"narration","speaker":"旁白"},{"en":"At least sorting out the things she should have discarded years ago was now being made easier for her.","zh":"至少，那些她多年前就该扔掉的东西，现在更方便清理了。","kind":"narration","speaker":"旁白"},{"en":"Then a police inspector arrived with a constable and she told them of her discovery of the ransacked flat.","zh":"接着，一位警官带着一名警员赶到，她向他们讲述了自己如何发现家里被洗劫。","kind":"narration","speaker":"旁白"},{"en":"The inspector began to look for fingerprints, while the constable checked that the front door locks had not been forced, thereby proving that the burglars had either used skeleton keys or entered over the balcony.","zh":"警官开始寻找指纹，警员则检查并确认前门的锁并未被撬坏，从而证明窃贼要么用了万能钥匙，要么是翻过阳台进来的。","kind":"narration","speaker":"旁白"},{"en":"There was no trace of fingerprints, but the inspector found a dirty red bundle that contained jewellery which the old lady said was not hers.","zh":"没有找到任何指纹，但警官发现了一个脏兮兮的红色包袱，里面装着首饰，老太太说那不是她的。","kind":"narration","speaker":"旁白"},{"en":"So their entry into this flat was apparently not the burglars’ first job that day and they must have been disturbed.","zh":"因此，闯进这套公寓显然不是窃贼当天干的第一起案子，而且他们准是受了惊扰才离开的。","kind":"narration","speaker":"旁白"},{"en":"The inspector then asked the old lady to try to check what was missing by the next day and advised her not to stay alone in the flat for a few nights.","zh":"警官随后请老太太尽量到第二天时查清丢了什么，并劝她这几晚别独自住在公寓里。","kind":"narration","speaker":"旁白"},{"en":"The old lady thought he was a fussy creature, but since the porter agreed with him, she rang up her daughter and asked for her help in what she described as a little spot of bother.","zh":"老太太觉得他未免大惊小怪，但既然门房也赞同他的话，她就打电话给女儿，请女儿来帮忙，处理她口中这点“小小的麻烦”。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"as clear as daylight","matchedForm":"as clear as daylight","meaning":"明明白白；再清楚不过","note":"比喻事实非常明显，常作表语；不要按字面理解为房间很明亮。","example":"It was as clear as daylight then that burglars had forced an entry during her absence.","exampleZh":"这下再清楚不过了：她不在家时，有窃贼闯了进来。","sourceParagraphIndex":0,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"set off","matchedForm":"set off","meaning":"出发；动身","note":"此处指开始行动或行程；后面可接 for 引出目的地。","example":"Then, her composure regained, she was ready to set off with the porter’s assistance to search for any intruders who might still be lurking in her flat.","exampleZh":"随后，她恢复了镇定，准备在门房的协助下出发，搜查可能仍潜伏在公寓里的入侵者。","sourceParagraphIndex":0,"sourceSentenceIndex":9,"sourceType":"textbook-passage"},{"phrase":"sort out","matchedForm":"sorting out","meaning":"整理；清理","note":"表示把杂乱物品分清并妥善处理，也可用于解决问题。","example":"At least sorting out the things she should have discarded years ago was now being made easier for her.","exampleZh":"至少，那些她多年前就该扔掉的东西，现在更方便清理了。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"no trace of","matchedForm":"no trace of","meaning":"没有任何……的痕迹","note":"trace 在这里表示可供发现或追踪的迹象，of 后接所寻找的东西。","example":"There was no trace of fingerprints, but the inspector found a dirty red bundle that contained jewellery which the old lady said was not hers.","exampleZh":"没有找到任何指纹，但警官发现了一个脏兮兮的红色包袱，里面装着首饰，老太太说那不是她的。","sourceParagraphIndex":1,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"a spot of bother","matchedForm":"a little spot of bother","meaning":"一点麻烦","note":"英式口语中的轻描淡写说法；此处与严重入室盗窃形成幽默反差。","example":"The old lady thought he was a fussy creature, but since the porter agreed with him, she rang up her daughter and asked for her help in what she described as a little spot of bother.","exampleZh":"老太太觉得他未免大惊小怪，但既然门房也赞同他的话，她就打电话给女儿，请女儿来帮忙，处理她口中这点“小小的麻烦”。","sourceParagraphIndex":1,"sourceSentenceIndex":9,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b3-l059","book":3,"number":59,"title":"Collecting","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"People tend to amass possessions, sometimes without being aware of doing so.","zh":"人们总容易积攒东西，有时自己还浑然不觉。","kind":"narration","speaker":"旁白"},{"en":"Indeed they can have a delightful surprise when they find something useful which they did not know they owned.","zh":"的确，发现一件原本不知道自己拥有、又派得上用场的东西，会让人惊喜不已。","kind":"narration","speaker":"旁白"},{"en":"Those who never have to move house become indiscriminate collectors of what can only be described as clutter.","zh":"那些从不用搬家的人，会不加选择地收藏各种东西，而这些东西只能称作杂物。","kind":"narration","speaker":"旁白"},{"en":"They leave unwanted objects in drawers, cupboards and attics for years, in the belief that they may one day need just those very things.","zh":"他们把用不着的物件放在抽屉、橱柜和阁楼里，一放就是多年，坚信自己也许哪天偏偏就会用到它们。","kind":"narration","speaker":"旁白"},{"en":"As they grow old, people also accumulate belongings for two other reasons, lack of physical and mental energy, both of which are essential in turning out and throwing away, and sentiment.","zh":"随着年纪增长，人们还会出于另外两个原因积存物品：一是缺乏清理和丢弃东西所必需的体力与精力，二是念旧。","kind":"narration","speaker":"旁白"},{"en":"Things owned for a long time are full of associations with the past, perhaps with relatives who are dead, and so they gradually acquire a value beyond their true worth.","zh":"拥有已久的东西，会让人联想起许多往事，也许还会让人想起已故的亲人，因此它们渐渐获得了超出实际价值的意义。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Some things are collected deliberately in the home in an attempt to avoid waste.","zh":"有些东西是人们为避免浪费而有意收存在家里的。","kind":"narration","speaker":"旁白"},{"en":"Among these I would list string and brown paper, kept by thrifty people when a parcel has been opened, to save buying these two requisites.","zh":"其中我会列入绳子和牛皮纸，节俭的人拆开包裹后会把它们留下，省得再花钱买这两样必需品。","kind":"narration","speaker":"旁白"},{"en":"Collecting small items can easily become a mania.","zh":"收集小东西，很容易变成一种癖好。","kind":"narration","speaker":"旁白"},{"en":"I know someone who always cuts sketches out from newspapers of model clothes that she would like to buy if she had the money.","zh":"我认识一个人，总从报纸上剪下时装样图，那些都是她如果有钱就想买的衣服。","kind":"narration","speaker":"旁白"},{"en":"As she is not rich, the chances that she will ever be able to afford such purchases are remote; but she is never sufficiently strong-minded to be able to stop the practice.","zh":"她并不富裕，因此将来真能买得起这些衣服的希望很渺茫；可她又始终缺乏足够的意志力，无法停止这种做法。","kind":"narration","speaker":"旁白"},{"en":"It is a harmless habit, but it litters up her desk to such an extent that every time she opens it, loose bits of paper fall out in every direction.","zh":"这习惯本身并无害处，却把她的书桌堆得如此杂乱，以至于每次打开抽屉，散碎的纸片都会四处掉出来。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"Collecting as a serious hobby is quite different and has many advantages.","zh":"把收藏当作一种认真的业余爱好，则完全是另一回事，而且好处很多。","kind":"narration","speaker":"旁白"},{"en":"It provides relaxation for leisure hours, as just looking at one’s treasures is always a joy.","zh":"它让人能在闲暇时放松，因为光是看看自己的宝贝，就总能令人愉快。","kind":"narration","speaker":"旁白"},{"en":"One does not have to go outside for amusement, since the collection is housed at home.","zh":"藏品就存放在家中，所以用不着外出找乐趣。","kind":"narration","speaker":"旁白"},{"en":"Whatever it consists of, stamps, records, first editions of books, china, glass, antique furniture, pictures, model cars, stuffed birds, toy animals, there is always something to do in connection with it, from finding the right place for the latest addition, to verifying facts in reference books.","zh":"无论收藏的是什么——邮票、唱片、初版书、瓷器、玻璃器皿、古董家具、画作、模型汽车、鸟类标本，还是玩具动物——总有相关的事情可做，从给新添的藏品寻找合适的位置，到查阅参考书核实资料，都是如此。","kind":"narration","speaker":"旁白"},{"en":"This hobby educates one not only in the chosen subject, but also in general matters which have some bearing on it.","zh":"这种爱好不仅让人在选定的领域增长知识，也让人了解与之有关的一般知识。","kind":"narration","speaker":"旁白"},{"en":"There are also other benefits.","zh":"此外，还有别的好处。","kind":"narration","speaker":"旁白"},{"en":"One wants to meet like-minded collectors, to get advice, to compare notes, to exchange articles, to show off the latest find.","zh":"人们会想结识志趣相投的收藏者，向他们请教、交流心得、交换藏品，并炫耀最新的发现。","kind":"narration","speaker":"旁白"},{"en":"So one’s circle of friends grows.","zh":"于是，朋友圈也就扩大了。","kind":"narration","speaker":"旁白"},{"en":"Soon the hobby leads to travel, perhaps to a meeting in another town, possibly a trip abroad in search of a rare specimen, for collectors are not confined to any one country.","zh":"不久，这种爱好还会带来旅行：也许是去另一个城镇参加聚会，也许是出国寻觅一件稀有藏品，因为收藏者并不局限于某一个国家。","kind":"narration","speaker":"旁白"},{"en":"Over the years, one may well become an authority on one’s hobby and will very probably be asked to give informal talks to little gatherings and then, if successful, to larger audiences.","zh":"多年下来，人们很可能成为自己收藏领域的权威，并很有可能受邀在小型聚会上作非正式的讲述；讲得好，还会面对更多听众。","kind":"narration","speaker":"旁白"},{"en":"In this way self-confidence grows, first from mastering a subject, then from being able to talk about it.","zh":"这样，自信心逐渐增长，先是来自掌握了一个领域的知识，再是来自能够把这些知识讲出来。","kind":"narration","speaker":"旁白"},{"en":"Collecting, by occupying spare time so constructively, makes a person contented, with no time for boredom.","zh":"收藏让人如此有益地利用闲暇，带来满足，也让人没有时间感到无聊。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"be aware of","matchedForm":"being aware of","meaning":"意识到；知道","note":"of 是介词，后接名词或动名词；也可用 be aware that 引出完整句子。","example":"People tend to amass possessions, sometimes without being aware of doing so.","exampleZh":"人们总容易积攒东西，有时自己还浑然不觉。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"in an attempt to","matchedForm":"in an attempt to","meaning":"试图；为了设法","note":"to 后接动词原形，说明所采取行动的目的，但不保证成功。","example":"Some things are collected deliberately in the home in an attempt to avoid waste.","exampleZh":"有些东西是人们为避免浪费而有意收存在家里的。","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"have a bearing on","matchedForm":"have some bearing on","meaning":"与……有关；对……有影响","note":"bearing 在这里表示关联，不是轴承；some、little、no 可表示关联程度。","example":"This hobby educates one not only in the chosen subject, but also in general matters which have some bearing on it.","exampleZh":"这种爱好不仅让人在选定的领域增长知识，也让人了解与之有关的一般知识。","sourceParagraphIndex":2,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"compare notes","matchedForm":"compare notes","meaning":"交流心得；交换看法","note":"固定搭配，notes 用复数，不一定真要交换书面笔记。","example":"One wants to meet like-minded collectors, to get advice, to compare notes, to exchange articles, to show off the latest find.","exampleZh":"人们会想结识志趣相投的收藏者，向他们请教、交流心得、交换藏品，并炫耀最新的发现。","sourceParagraphIndex":2,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"circle of friends","matchedForm":"circle of friends","meaning":"朋友圈；交友圈","note":"circle 比喻一群有联系的人，可与 widen、grow 等表示扩大的词搭配。","example":"So one’s circle of friends grows.","exampleZh":"于是，朋友圈也就扩大了。","sourceParagraphIndex":2,"sourceSentenceIndex":7,"sourceType":"textbook-passage"},{"phrase":"in search of","matchedForm":"in search of","meaning":"寻找；寻求","note":"介词短语，search 前不加冠词；不要与动词 search for 混用结构。","example":"Soon the hobby leads to travel, perhaps to a meeting in another town, possibly a trip abroad in search of a rare specimen, for collectors are not confined to any one country.","exampleZh":"不久，这种爱好还会带来旅行：也许是去另一个城镇参加聚会，也许是出国寻觅一件稀有藏品，因为收藏者并不局限于某一个国家。","sourceParagraphIndex":2,"sourceSentenceIndex":8,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b3-l060","book":3,"number":60,"title":"Too early and too late","sourceSha256":"35e7817ab4caa50d301fd27b72e10311ff885d804d127fefeeff7eb94e47420f","paragraphs":[{"index":0,"rows":[{"en":"Punctuality is a necessary habit in all public affairs in civilized society.","zh":"在文明社会的一切公共事务中，守时都是必不可少的习惯。","kind":"narration","speaker":"旁白"},{"en":"Without it, nothing could ever be brought to a conclusion; everything would be in a state of chaos.","zh":"没有它，任何事情都无法完成，一切都会陷入混乱。","kind":"narration","speaker":"旁白"},{"en":"Only in a sparsely-populated rural community is it possible to disregard it.","zh":"只有在人烟稀少的乡村社区，才可能不去理会守时。","kind":"narration","speaker":"旁白"},{"en":"In ordinary living, there can be some tolerance of unpunctuality.","zh":"日常生活中，对不守时的情况可以有一定的宽容。","kind":"narration","speaker":"旁白"},{"en":"The intellectual, who is working on some abstruse problem, has everything coordinated and organized for the matter in hand.","zh":"研究某个深奥问题的知识分子，已经把一切都协调、组织好，以便处理眼前的课题。","kind":"narration","speaker":"旁白"},{"en":"He is therefore forgiven if late for a dinner party.","zh":"因此，他赴晚宴迟到了，也会得到谅解。","kind":"narration","speaker":"旁白"},{"en":"But people are often reproached for unpunctuality when their only fault is cutting things fine.","zh":"不过，人们常因不守时而受到责备，其实唯一的过错只是把时间算得太紧。","kind":"narration","speaker":"旁白"},{"en":"It is hard for energetic, quick-minded people to waste time, so they are often tempted to finish a job before setting out to keep an appointment.","zh":"精力旺盛、头脑敏捷的人很难容忍浪费时间，因此他们常常忍不住想在动身赴约之前，再做完一件事。","kind":"narration","speaker":"旁白"},{"en":"If no accidents occur on the way, like punctured tyres, diversions of traffic, sudden descent of fog, they will be on time.","zh":"如果路上不发生爆胎、交通改道、突起大雾等意外，他们是能准时赶到的。","kind":"narration","speaker":"旁白"},{"en":"They are often more industrious, useful citizens than those who are never late.","zh":"与那些从不迟到的人相比，他们往往是更勤奋、更有益于社会的公民。","kind":"narration","speaker":"旁白"},{"en":"The over-punctual can be as much a trial to others as the unpunctual.","zh":"过分守时的人，给别人带来的烦恼可能和不守时的人一样多。","kind":"narration","speaker":"旁白"},{"en":"The guest who arrives half an hour too soon is the greatest nuisance.","zh":"提前半小时到的客人最让人头疼。","kind":"narration","speaker":"旁白"},{"en":"Some friends of my family had this irritating habit.","zh":"我们家有些朋友，就有这种讨厌的习惯。","kind":"narration","speaker":"旁白"},{"en":"The only thing to do was ask them to come half an hour later than the other guests.","zh":"唯一的办法，就是请他们比别的客人晚半小时来。","kind":"narration","speaker":"旁白"},{"en":"Then they arrived just when we wanted them.","zh":"这样，他们到达的时间，正好就是我们希望他们来的时间。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"If you are catching a train, it is always better to be comfortably early than even a fraction of a minute too late.","zh":"如果你要赶火车，宁可早一些、从容到站，也不要晚到哪怕不足一分钟。","kind":"narration","speaker":"旁白"},{"en":"Although being early may mean wasting a little time, this will be less than if you miss the train and have to wait an hour or more for the next one; and you avoid the frustration of arriving at the very moment when the train is drawing out of the station and being unable to get on it.","zh":"虽然早到可能意味着浪费一点时间，却总比误了火车、不得不再等一小时甚至更久才有下一班车的耗时少；而且也能避免那种沮丧：自己到站的那一刻，火车正开出车站，却怎么也上不去。","kind":"narration","speaker":"旁白"},{"en":"An even harder situation is to be on the platform in good time for a train and still to see it go off without you.","zh":"更难受的一种情形是，自己早已及时到达站台，却仍眼睁睁看着火车撇下自己开走。","kind":"narration","speaker":"旁白"},{"en":"Such an experience befell a certain young girl the first time she was travelling alone.","zh":"一个年轻姑娘第一次独自旅行时，就遭遇了这样的事。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"She entered the station twenty minutes before the train was due, since her parents had impressed upon her that it would be unforgivable to miss it and cause the friends with whom she was going to stay to make two journeys to meet her.","zh":"她在火车预定到站前二十分钟进了车站，因为父母反复叮嘱过她，要是误车，害得她要去投宿的那家朋友跑两趟来接她，那是不可原谅的。","kind":"narration","speaker":"旁白"},{"en":"She gave her luggage to a porter and showed him her ticket.","zh":"她把行李交给一个搬运工，并把车票拿给他看。","kind":"narration","speaker":"旁白"},{"en":"To her horror he said that she was two hours too soon.","zh":"令她惊恐的是，他说她早到了两个小时。","kind":"narration","speaker":"旁白"},{"en":"She felt in her handbag for the piece of paper on which her father had written down all the details of the journey and gave it to the porter.","zh":"她在手提包里摸出一张纸，上面是父亲写下的全部行程细节，然后把纸递给搬运工。","kind":"narration","speaker":"旁白"},{"en":"He agreed that a train did come into the station at the time on the paper and that it did stop, but only to take on mail, not passengers.","zh":"他承认，确实有一班火车会在纸上写的时间进站，也确实会停车，但只装载邮件，不上旅客。","kind":"narration","speaker":"旁白"},{"en":"The girl asked to see a timetable, feeling sure that her father could not have made such a mistake.","zh":"姑娘要求看时刻表，确信父亲不可能犯这样的错误。","kind":"narration","speaker":"旁白"},{"en":"The porter went to fetch one and arrived back with the station master, who produced it with a flourish and pointed out a microscopic ‘o’ beside the time of the arrival of the train at his station; this little ‘o’ indicated that the train only stopped for mail.","zh":"搬运工去取时刻表，回来时站长也一同来了；站长颇有派头地拿出时刻表，指出该站火车到达时间旁有个小得几乎看不见的“o”；这个小“o”表示，火车停车只是为了装邮件。","kind":"narration","speaker":"旁白"},{"en":"Just at that moment the train came into the station.","zh":"就在此时，火车进站了。","kind":"narration","speaker":"旁白"},{"en":"The girl, tears streaming down her face, begged to be allowed to slip into the guard’s van.","zh":"姑娘泪流满面，恳求让她悄悄上乘务员车厢。","kind":"narration","speaker":"旁白"},{"en":"But the station master was adamant: rules could not be broken.","zh":"可站长毫不通融：规章不能破。","kind":"narration","speaker":"旁白"},{"en":"And she had to watch that train disappear towards her destination while she was left behind.","zh":"于是，她只能看着那班火车朝自己的目的地驶去，自己却被留在了原地。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"in a state of chaos","matchedForm":"in a state of chaos","meaning":"处于混乱状态","note":"in a state of 后接状态名词；chaos 是不可数名词。","example":"Without it, nothing could ever be brought to a conclusion; everything would be in a state of chaos.","exampleZh":"没有它，任何事情都无法完成，一切都会陷入混乱。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"the matter in hand","matchedForm":"the matter in hand","meaning":"眼前正在处理的事","note":"in hand 在这里表示正在办理，不是字面上拿在手里。","example":"The intellectual, who is working on some abstruse problem, has everything coordinated and organized for the matter in hand.","exampleZh":"研究某个深奥问题的知识分子，已经把一切都协调、组织好，以便处理眼前的课题。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"cut things fine","matchedForm":"cutting things fine","meaning":"把时间安排得太紧；不留余地","note":"常用于出门或赶期限时几乎没有缓冲时间，带有险些来不及的意味。","example":"But people are often reproached for unpunctuality when their only fault is cutting things fine.","exampleZh":"不过，人们常因不守时而受到责备，其实唯一的过错只是把时间算得太紧。","sourceParagraphIndex":0,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"keep an appointment","matchedForm":"keep an appointment","meaning":"赴约；按约到场","note":"keep 在这里指履行约定；make an appointment 则是预约。","example":"It is hard for energetic, quick-minded people to waste time, so they are often tempted to finish a job before setting out to keep an appointment.","exampleZh":"精力旺盛、头脑敏捷的人很难容忍浪费时间，因此他们常常忍不住想在动身赴约之前，再做完一件事。","sourceParagraphIndex":0,"sourceSentenceIndex":7,"sourceType":"textbook-passage"},{"phrase":"in good time","matchedForm":"in good time","meaning":"及早；留足时间","note":"表示到得足够早、不会匆忙；语气比单纯的 on time 更强调余量。","example":"An even harder situation is to be on the platform in good time for a train and still to see it go off without you.","exampleZh":"更难受的一种情形是，自己早已及时到达站台，却仍眼睁睁看着火车撇下自己开走。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"impress upon someone that","matchedForm":"impressed upon her that","meaning":"向某人反复强调……","note":"that 后接需要牢记的内容；upon 也可换成 on。","example":"She entered the station twenty minutes before the train was due, since her parents had impressed upon her that it would be unforgivable to miss it and cause the friends with whom she was going to stay to make two journeys to meet her.","exampleZh":"她在火车预定到站前二十分钟进了车站，因为父母反复叮嘱过她，要是误车，害得她要去投宿的那家朋友跑两趟来接她，那是不可原谅的。","sourceParagraphIndex":2,"sourceSentenceIndex":0,"sourceType":"textbook-passage"}]},{"lessonId":"nce-textbook-b4-l001","book":4,"number":1,"title":"Finding fossil man","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"We can read of things that happened 5,000 years ago in the Near East, where people first learned to write.","zh":"我们能读到五千年前发生在近东的事情，人类最早就是在那里学会书写的。","kind":"narration","speaker":"旁白"},{"en":"But there are some parts of the world where even now people cannot write.","zh":"但世界上有些地方的人，直到今天仍不会书写。","kind":"narration","speaker":"旁白"},{"en":"The only way that they can preserve their history is to recount it as sagas—legends handed down from one generation of storytellers to another.","zh":"他们保存自身历史的唯一办法，是把它讲成传说故事——由一代讲故事的人传给下一代的传奇。","kind":"narration","speaker":"旁白"},{"en":"These legends are useful because they can tell us something about migrations of people who lived long ago, but none could write down what they did.","zh":"这些传说很有用，因为它们能让我们了解一些远古人群迁徙的情况；当时那些人却没有一个能把自己的所作所为记下来。","kind":"narration","speaker":"旁白"},{"en":"Anthropologists wondered where the remote ancestors of the Polynesian peoples now living in the Pacific Islands came from.","zh":"人类学家曾想知道，如今居住在太平洋群岛上的波利尼西亚各族的远祖究竟来自何处。","kind":"narration","speaker":"旁白"},{"en":"The sagas of these people explain that some of them came from Indonesia about 2,000 years ago.","zh":"这些民族的传说讲述，其中一部分人大约在两千年前来自印度尼西亚。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"But the first people who were like ourselves lived so long ago that even their sagas, if they had any, are forgotten.","zh":"然而，最早那些与我们相似的人生活的年代过于久远，就连他们的传说——假如他们有传说的话——也早已被遗忘了。","kind":"narration","speaker":"旁白"},{"en":"So archaeologists have neither history nor legends to help them to find out where the first ‘modern men’ came from.","zh":"所以，考古学家既没有史料，也没有传说可借助，来查明最早的“现代人”来自哪里。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"Fortunately, however, ancient men made tools of stone, especially flint, because this is easier to shape than other kinds.","zh":"不过幸运的是，古人用石头制造工具，尤其常用燧石，因为它比其他石头容易加工成形。","kind":"narration","speaker":"旁白"},{"en":"They may also have used wood and skins, but these have rotted away.","zh":"他们也可能用过木材和兽皮，但这些东西都已腐烂。","kind":"narration","speaker":"旁白"},{"en":"Stone does not decay, and so the tools of long ago have remained when even the bones of the men who made them have disappeared without trace.","zh":"石头不会腐朽，因此，哪怕制造工具的人的骨骼都已消失得无影无踪，那些远古的工具却仍保存了下来。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"read of","matchedForm":"read of","meaning":"读到；从文字中得知","note":"read of 后接所读到的人或事情，侧重获知其存在或事迹。","example":"We can read of things that happened 5,000 years ago in the Near East, where people first learned to write.","exampleZh":"我们能读到五千年前发生在近东的事情，人类最早就是在那里学会书写的。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"hand down","matchedForm":"handed down","meaning":"代代传下","note":"常用被动形式；hand down from one generation to another 指代际传承。","example":"The only way that they can preserve their history is to recount it as sagas—legends handed down from one generation of storytellers to another.","exampleZh":"他们保存自身历史的唯一办法，是把它讲成传说故事——由一代讲故事的人传给下一代的传奇。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"find out","matchedForm":"find out","meaning":"查明；弄清","note":"指通过调查或探究获得答案，可接疑问词引导的从句。","example":"So archaeologists have neither history nor legends to help them to find out where the first ‘modern men’ came from.","exampleZh":"所以，考古学家既没有史料，也没有传说可借助，来查明最早的“现代人”来自哪里。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"rot away","matchedForm":"rotted away","meaning":"腐烂消失","note":"away 强调逐渐腐烂直至不复存在，适用于木材等有机物。","example":"They may also have used wood and skins, but these have rotted away.","exampleZh":"他们也可能用过木材和兽皮，但这些东西都已腐烂。","sourceParagraphIndex":2,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"without trace","matchedForm":"without trace","meaning":"不留痕迹地","note":"通常用于消失等语境；也常说 without a trace。","example":"Stone does not decay, and so the tools of long ago have remained when even the bones of the men who made them have disappeared without trace.","exampleZh":"石头不会腐朽，因此，哪怕制造工具的人的骨骼都已消失得无影无踪，那些远古的工具却仍保存了下来。","sourceParagraphIndex":2,"sourceSentenceIndex":2,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l002","book":4,"number":2,"title":"Spare that spider","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Why, you may wonder, should spiders be our friends?","zh":"你也许会纳闷，蜘蛛为什么应该算我们的朋友？","kind":"narration","speaker":"旁白"},{"en":"Because they destroy so many insects, and insects include some of the greatest enemies of the human race.","zh":"因为它们消灭的昆虫非常多，而昆虫中有些正是人类最大的敌人。","kind":"narration","speaker":"旁白"},{"en":"Insects would make it impossible for us to live in the world: they would devour all our crops and kill our flocks and herds, if it were not for the protection we get from insect-eating animals.","zh":"要不是有食虫动物保护我们，昆虫会吞光我们的庄稼，杀死我们的牛羊牲畜，使我们根本无法在世上生存。","kind":"narration","speaker":"旁白"},{"en":"We owe a lot to the birds and beasts who eat insects but all of them put together kill only a fraction of the number destroyed by spiders.","zh":"我们很感激那些吃昆虫的鸟兽，但它们加在一起捕杀的昆虫，也仅是蜘蛛所消灭数量的一小部分。","kind":"narration","speaker":"旁白"},{"en":"Moreover, unlike some of the other insect eaters, spiders never do the least harm to us or our belongings.","zh":"而且，与某些其他食虫动物不同，蜘蛛对我们和我们的财物丝毫无害。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Spiders are not insects, as many people think, nor even nearly related to them.","zh":"蜘蛛并不像许多人以为的那样是昆虫，甚至与昆虫的亲缘关系也并不近。","kind":"narration","speaker":"旁白"},{"en":"One can tell the difference almost at a glance, for a spider always has eight legs and an insect never more than six.","zh":"人们几乎看一眼就能分清：蜘蛛总是有八条腿，而昆虫的腿从不超过六条。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"How many spiders are engaged in this work on our behalf?","zh":"究竟有多少蜘蛛在替我们做这项工作呢？","kind":"narration","speaker":"旁白"},{"en":"One authority on spiders made a census of the spiders in a grass field in the south of England, and he estimated that there were more than 2,250,000 in one acre; that is something like 6,000,000 spiders of different kinds on a football pitch.","zh":"一位蜘蛛研究权威曾清点英格兰南部一片草地里的蜘蛛，估算每英亩有二百二十五万只以上；也就是说，一块足球场大小的地方，大约有六百万只各种各样的蜘蛛。","kind":"narration","speaker":"旁白"},{"en":"Spiders are busy for at least half the year in killing insects.","zh":"蜘蛛一年至少有半年都在忙着捕杀昆虫。","kind":"narration","speaker":"旁白"},{"en":"It is impossible to make more than the wildest guess at how many they kill, but they are hungry creatures, not content with only three meals a day.","zh":"要说它们到底捕杀了多少昆虫，除了极不可靠的猜测，谁也无从估算；不过它们胃口很大，一天只吃三顿可满足不了。","kind":"narration","speaker":"旁白"},{"en":"It has been estimated that the weight of all the insects destroyed by spiders in Britain in one year would be greater than the total weight of all the human beings in the country.","zh":"据估计，英国蜘蛛一年消灭的全部昆虫，其重量会超过英国全体人口的体重总和。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"if it were not for","matchedForm":"if it were not for","meaning":"要不是；若非有","note":"用于与现在事实相反的假设，后接提供帮助或造成影响的人或事物。","example":"Insects would make it impossible for us to live in the world: they would devour all our crops and kill our flocks and herds, if it were not for the protection we get from insect-eating animals.","exampleZh":"要不是有食虫动物保护我们，昆虫会吞光我们的庄稼，杀死我们的牛羊牲畜，使我们根本无法在世上生存。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"owe a lot to","matchedForm":"owe a lot to","meaning":"很感激；得益于","note":"owe ... to ... 可表示把成就归功于某人，这里强调所受的恩惠。","example":"We owe a lot to the birds and beasts who eat insects but all of them put together kill only a fraction of the number destroyed by spiders.","exampleZh":"我们很感激那些吃昆虫的鸟兽，但它们加在一起捕杀的昆虫，也仅是蜘蛛所消灭数量的一小部分。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"at a glance","matchedForm":"at a glance","meaning":"一眼就；看一眼便","note":"作状语，表示不必仔细观察就能看出。","example":"One can tell the difference almost at a glance, for a spider always has eight legs and an insect never more than six.","exampleZh":"人们几乎看一眼就能分清：蜘蛛总是有八条腿，而昆虫的腿从不超过六条。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"on behalf of","matchedForm":"on our behalf","meaning":"代表；为了……的利益","note":"on someone’s behalf 也可表示替某人做事，此处是替人类消灭害虫。","example":"How many spiders are engaged in this work on our behalf?","exampleZh":"究竟有多少蜘蛛在替我们做这项工作呢？","sourceParagraphIndex":2,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"be content with","matchedForm":"content with","meaning":"满足于","note":"with 后接名词或动名词；否定时表示不以现有数量或状况为满足。","example":"It is impossible to make more than the wildest guess at how many they kill, but they are hungry creatures, not content with only three meals a day.","exampleZh":"要说它们到底捕杀了多少昆虫，除了极不可靠的猜测，谁也无从估算；不过它们胃口很大，一天只吃三顿可满足不了。","sourceParagraphIndex":2,"sourceSentenceIndex":3,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l003","book":4,"number":3,"title":"Matterhorn man","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Modern alpinists try to climb mountains by a route which will give them good sport, and the more difficult it is, the more highly it is regarded.","zh":"现代登山者选择攀登路线时，追求的是攀登的乐趣与挑战；路线越难，评价就越高。","kind":"narration","speaker":"旁白"},{"en":"In the pioneering days, however, this was not the case at all.","zh":"然而，在登山运动的开拓时期，情况完全不是这样。","kind":"narration","speaker":"旁白"},{"en":"The early climbers were looking for the easiest way to the top, because the summit was the prize they sought especially if it had never been attained before.","zh":"早期登山者寻找的是最容易到达山顶的路，因为登顶才是他们追求的奖赏，尤其是此前从未有人登上过的山顶。","kind":"narration","speaker":"旁白"},{"en":"It is true that during their explorations they often faced difficulties and dangers of the most perilous nature, equipped in a manner which would make a modern climber shudder at the thought, but they did not go out of their way to court such excitement.","zh":"诚然，他们探险时往往面临极其凶险的困难和危险，所携装备之简陋会让现代登山者想起来都打寒战；但他们并不会刻意去寻求这种刺激。","kind":"narration","speaker":"旁白"},{"en":"They had a single aim, a solitary goal—the top!","zh":"他们只有一个目的，一个唯一的目标——山顶！","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"It is hard for us to realize nowadays how difficult it was for the pioneers.","zh":"如今我们很难体会，那些先驱者当时有多么艰难。","kind":"narration","speaker":"旁白"},{"en":"Except for one or two places such as Zermatt and Chamonix, which had rapidly become popular, Alpine villages tended to be impoverished settlements cut off from civilization by the high mountains.","zh":"除了采尔马特和夏蒙尼等一两个迅速兴盛起来的地方，阿尔卑斯山区的村庄大多是穷困的聚居地，被高山阻隔，与外界文明隔绝。","kind":"narration","speaker":"旁白"},{"en":"Such inns as there were were generally dirty and flea-ridden; the food simply local cheese accompanied by bread often twelve months old, all washed down with coarse wine.","zh":"那寥寥几家客栈通常又脏又满是跳蚤；食物不过是当地的奶酪，配着往往已放了一年的面包，再用粗劣的葡萄酒把这些东西送下肚去。","kind":"narration","speaker":"旁白"},{"en":"Often a valley boasted no inn at all, and climbers found shelter wherever they could—sometimes with the local priest (who was usually as poor as his parishioners), sometimes with shepherds or cheese-makers.","zh":"一个山谷常常连客栈都没有，登山者只能有什么地方就在哪里栖身——有时借住当地神父家中（神父通常和他的教民一样穷），有时住在牧羊人或奶酪制作人的家里。","kind":"narration","speaker":"旁白"},{"en":"Invariably the background was the same: dirt and poverty, and very uncomfortable.","zh":"无论到哪里，周遭的情景总是一样：肮脏、贫穷，住着很不舒服。","kind":"narration","speaker":"旁白"},{"en":"For men accustomed to eating seven-course dinners and sleeping between fine linen sheets at home, the change to the Alps must have been very hard indeed.","zh":"这些人在家习惯吃有七道菜的正餐、睡铺着上等亚麻床单的床，来到阿尔卑斯山区后，生活上的改变必定让他们非常难受。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"not be the case","matchedForm":"was not the case","meaning":"情况并非如此","note":"the case 指前文所述的事实或情形；字典式用 not be the case，句中按时态变为 was not the case。","example":"In the pioneering days, however, this was not the case at all.","exampleZh":"然而，在登山运动的开拓时期，情况完全不是这样。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"go out of one’s way","matchedForm":"go out of their way","meaning":"刻意；特意费力","note":"后接 to do，表示超出正常需要去做某事。","example":"It is true that during their explorations they often faced difficulties and dangers of the most perilous nature, equipped in a manner which would make a modern climber shudder at the thought, but they did not go out of their way to court such excitement.","exampleZh":"诚然，他们探险时往往面临极其凶险的困难和危险，所携装备之简陋会让现代登山者想起来都打寒战；但他们并不会刻意去寻求这种刺激。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"cut off from","matchedForm":"cut off from","meaning":"与……隔绝","note":"cut off 常用被动形式，from 引出无法联系或到达的外界。","example":"Except for one or two places such as Zermatt and Chamonix, which had rapidly become popular, Alpine villages tended to be impoverished settlements cut off from civilization by the high mountains.","exampleZh":"除了采尔马特和夏蒙尼等一两个迅速兴盛起来的地方，阿尔卑斯山区的村庄大多是穷困的聚居地，被高山阻隔，与外界文明隔绝。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"wash down","matchedForm":"washed down","meaning":"用饮料把食物送下肚","note":"wash food down with a drink 是饮食搭配，不是洗涤食物。","example":"Such inns as there were were generally dirty and flea-ridden; the food simply local cheese accompanied by bread often twelve months old, all washed down with coarse wine.","exampleZh":"那寥寥几家客栈通常又脏又满是跳蚤；食物不过是当地的奶酪，配着往往已放了一年的面包，再用粗劣的葡萄酒把这些东西送下肚去。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"be accustomed to","matchedForm":"accustomed to","meaning":"习惯于","note":"to 是介词，后接名词或动名词，如这里的 eating 和 sleeping。","example":"For men accustomed to eating seven-course dinners and sleeping between fine linen sheets at home, the change to the Alps must have been very hard indeed.","exampleZh":"这些人在家习惯吃有七道菜的正餐、睡铺着上等亚麻床单的床，来到阿尔卑斯山区后，生活上的改变必定让他们非常难受。","sourceParagraphIndex":1,"sourceSentenceIndex":5,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l004","book":4,"number":4,"title":"Seeing hands","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Several cases have been reported in Russia recently of people who can read and detect colours with their fingers, and even see through solid doors and walls.","zh":"俄罗斯最近报道了几起事例：有人能用手指读字、辨认颜色，甚至能透过不透明的门和墙看见东西。","kind":"narration","speaker":"旁白"},{"en":"One case concerns an eleven-year-old schoolgirl, Vera Petrova, who has normal vision but who can also perceive things with different parts of her skin, and through solid walls.","zh":"其中一例涉及一名十一岁的女学生维拉·彼得罗娃；她视力正常，却还能用皮肤的不同部位感知事物，也能隔着实心墙感知东西。","kind":"narration","speaker":"旁白"},{"en":"This ability was first noticed by her father.","zh":"最先注意到这种能力的是她的父亲。","kind":"narration","speaker":"旁白"},{"en":"One day she came into his office and happened to put her hands on the door of a locked safe.","zh":"有一天，她走进父亲的办公室，碰巧把双手放在一只锁着的保险柜门上。","kind":"narration","speaker":"旁白"},{"en":"Suddenly she asked her father why he kept so many old newspapers locked away there, and even described the way they were done up in bundles.","zh":"她突然问父亲为什么把那么多旧报纸锁在那里，甚至描述出了报纸捆扎成束的样子。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Vera's curious talent was brought to the notice of a scientific research institute in the town of Ulyanovsk, near where she lives, and in April she was given a series of tests by a special commission of the Ministry of Health of the Russian Federal Republic.","zh":"维拉这种奇特的天赋引起了离她住处不远的乌里扬诺夫斯克市一家科研机构的注意；四月，俄罗斯联邦共和国卫生部的一个专门委员会对她进行了一系列测试。","kind":"narration","speaker":"旁白"},{"en":"During these tests she was able to read a newspaper through an opaque screen and, stranger still, by moving her elbow over a child's game of Lotto she was able to describe the figures and colours printed on it; and, in another instance, wearing stockings and slippers, to make out with her foot the outlines and colours of a picture hidden under a carpet.","zh":"测试中，她能隔着不透明的屏障读报；更奇怪的是，她把肘部从一种名叫乐透的儿童游戏上方移过，就能说出上面印的数字和颜色；另一次，她穿着袜子和拖鞋，还能用脚辨出藏在地毯下面的一幅画的轮廓和颜色。","kind":"narration","speaker":"旁白"},{"en":"Other experiments showed that her knees and shoulders had a similar sensitivity.","zh":"其他实验表明，她的膝部和肩部也具有类似的感知能力。","kind":"narration","speaker":"旁白"},{"en":"During all these tests Vera was blindfold; and, indeed, except when blindfold she lacked the ability to perceive things with her skin.","zh":"这些测试进行时，维拉始终蒙着眼；事实上，只有蒙上眼时，她才具有用皮肤感知事物的能力。","kind":"narration","speaker":"旁白"},{"en":"It was also found that although she could perceive things with her fingers this ability ceased the moment her hands were wet.","zh":"研究者还发现，虽然她能用手指感知东西，但只要双手一湿，这种能力就会消失。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"happen to","matchedForm":"happened to","meaning":"碰巧；恰好","note":"后接动词原形，说明事件偶然发生，并非有意安排。","example":"One day she came into his office and happened to put her hands on the door of a locked safe.","exampleZh":"有一天，她走进父亲的办公室，碰巧把双手放在一只锁着的保险柜门上。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"lock away","matchedForm":"locked away","meaning":"锁起来存放","note":"away 强调收起保管，常与柜子、贵重物品或文件相关。","example":"Suddenly she asked her father why he kept so many old newspapers locked away there, and even described the way they were done up in bundles.","exampleZh":"她突然问父亲为什么把那么多旧报纸锁在那里，甚至描述出了报纸捆扎成束的样子。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"bring to the notice of","matchedForm":"brought to the notice of","meaning":"使……注意到","note":"常用被动形式，表示某情况被提交给机构或个人关注。","example":"Vera's curious talent was brought to the notice of a scientific research institute in the town of Ulyanovsk, near where she lives, and in April she was given a series of tests by a special commission of the Ministry of Health of the Russian Federal Republic.","exampleZh":"维拉这种奇特的天赋引起了离她住处不远的乌里扬诺夫斯克市一家科研机构的注意；四月，俄罗斯联邦共和国卫生部的一个专门委员会对她进行了一系列测试。","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"make out","matchedForm":"make out","meaning":"辨认出；看清","note":"此处是辨别模糊或被遮蔽的视觉信息，并非编造或填写。","example":"During these tests she was able to read a newspaper through an opaque screen and, stranger still, by moving her elbow over a child's game of Lotto she was able to describe the figures and colours printed on it; and, in another instance, wearing stockings and slippers, to make out with her foot the outlines and colours of a picture hidden under a carpet.","exampleZh":"测试中，她能隔着不透明的屏障读报；更奇怪的是，她把肘部从一种名叫乐透的儿童游戏上方移过，就能说出上面印的数字和颜色；另一次，她穿着袜子和拖鞋，还能用脚辨出藏在地毯下面的一幅画的轮廓和颜色。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"the moment","matchedForm":"the moment","meaning":"一……就……","note":"作时间连词使用，可直接连接从句，不必另加 when。","example":"It was also found that although she could perceive things with her fingers this ability ceased the moment her hands were wet.","exampleZh":"研究者还发现，虽然她能用手指感知东西，但只要双手一湿，这种能力就会消失。","sourceParagraphIndex":1,"sourceSentenceIndex":4,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l005","book":4,"number":5,"title":"Youth","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"People are always talking about ‘the problem of youth’.","zh":"人们总在谈论“青年问题”。","kind":"narration","speaker":"旁白"},{"en":"If there is one—which I take leave to doubt—then it is older people who create it, not the young themselves.","zh":"假如确实有这个问题——对此我恕难苟同——制造问题的也是年长者，而不是青年自己。","kind":"narration","speaker":"旁白"},{"en":"Let us get down to fundamentals and agree that the young are after all human beings—people just like their elders.","zh":"让我们从根本说起，承认青年归根到底也是人，是和长辈一样的人。","kind":"narration","speaker":"旁白"},{"en":"There is only one difference between an old man and a young one: the young man has a glorious future before him and the old one has a splendid future behind him: and maybe that is where the rub is.","zh":"老人和青年只有一点不同：青年面前有灿烂的未来，老人身后有过往那曾经辉煌的“未来”；也许症结就在这里。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"When I was a teenager, I felt that I was just young and uncertain—that I was a new boy in a huge school, and I would have been very pleased to be regarded as something so interesting as a problem.","zh":"我十几岁时，只觉得自己年少而惶惑，像是刚进一所大学校的新生；倘若有人把我看作像“问题”那么引人关注的事物，我倒会非常高兴。","kind":"narration","speaker":"旁白"},{"en":"For one thing, being a problem gives you a certain identity, and that is one of the things the young are busily engaged in seeking.","zh":"首先，被当作一个问题能赋予你某种身份，而寻找自己的身份恰恰是青年正忙着做的事之一。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"I find young people exciting.","zh":"我觉得青年令人振奋。","kind":"narration","speaker":"旁白"},{"en":"They have an air of freedom, and they have not a dreary commitment to mean ambitions or love of comfort.","zh":"他们身上有一股自由的气息，不会令人厌倦地执着于卑微的野心或贪图安逸。","kind":"narration","speaker":"旁白"},{"en":"They are not anxious social climbers, and they have no devotion to material things.","zh":"他们不是急于攀附上流社会的人，也不痴迷于物质。","kind":"narration","speaker":"旁白"},{"en":"All this seems to me to link them with life, and the origins of things.","zh":"在我看来，这一切使他们与生命、与万物的本源相联。","kind":"narration","speaker":"旁白"},{"en":"It’s as if they were, in some sense, cosmic beings in violent and lovely contrast with us suburban creatures.","zh":"仿佛从某种意义上说，他们是宇宙中的生灵，与我们这些蜗居市郊的凡俗之辈形成强烈而可爱的对照。","kind":"narration","speaker":"旁白"},{"en":"All that is in my mind when I meet a young person.","zh":"每当我遇见一个青年，心中想到的就是这些。","kind":"narration","speaker":"旁白"},{"en":"He may be conceited, ill-mannered, presumptuous or fatuous, but I do not turn for protection to dreary clichés about respect for elders—as if mere age were a reason for respect.","zh":"他可能自负、无礼、冒失或愚蠢，但我不会躲到那些乏味的“尊重长辈”之类的套话后面寻求庇护，仿佛年纪大本身就值得尊敬似的。","kind":"narration","speaker":"旁白"},{"en":"I accept that we are equals, and I will argue with him, as an equal, if I think he is wrong.","zh":"我承认我们是平等的；如果我认为他错了，就会以平等的身份和他辩论。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"take leave to","matchedForm":"take leave to","meaning":"恕我冒昧地……","note":"礼貌而带有反驳意味的表达，后接动词原形，此处表示不同意这种说法。","example":"If there is one—which I take leave to doubt—then it is older people who create it, not the young themselves.","exampleZh":"假如确实有这个问题——对此我恕难苟同——制造问题的也是年长者，而不是青年自己。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"get down to","matchedForm":"get down to","meaning":"着手认真讨论","note":"to 是介词，后接名词或动名词；此处指回到基本事实。","example":"Let us get down to fundamentals and agree that the young are after all human beings—people just like their elders.","exampleZh":"让我们从根本说起，承认青年归根到底也是人，是和长辈一样的人。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"where the rub is","matchedForm":"where the rub is","meaning":"症结所在","note":"rub 在这个固定说法里表示困难或障碍，并非摩擦动作。","example":"There is only one difference between an old man and a young one: the young man has a glorious future before him and the old one has a splendid future behind him: and maybe that is where the rub is.","exampleZh":"老人和青年只有一点不同：青年面前有灿烂的未来，老人身后有过往那曾经辉煌的“未来”；也许症结就在这里。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"for one thing","matchedForm":"For one thing","meaning":"首先；其中一个原因是","note":"用于列举理由，不一定必须接 for another thing。","example":"For one thing, being a problem gives you a certain identity, and that is one of the things the young are busily engaged in seeking.","exampleZh":"首先，被当作一个问题能赋予你某种身份，而寻找自己的身份恰恰是青年正忙着做的事之一。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"turn to","matchedForm":"turn for protection to","meaning":"转向……寻求帮助","note":"turn to someone/something for ... 中 for 短语可提前插入，此处有讽刺意味。","example":"He may be conceited, ill-mannered, presumptuous or fatuous, but I do not turn for protection to dreary clichés about respect for elders—as if mere age were a reason for respect.","exampleZh":"他可能自负、无礼、冒失或愚蠢，但我不会躲到那些乏味的“尊重长辈”之类的套话后面寻求庇护，仿佛年纪大本身就值得尊敬似的。","sourceParagraphIndex":2,"sourceSentenceIndex":6,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l006","book":4,"number":6,"title":"The sporting spirit","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"I am always amazed when I hear people saying that sport creates goodwill between the nations, and that if only the common peoples of the world could meet one another at football or cricket, they would have no inclination to meet on the battlefield.","zh":"每当听到有人说体育能增进各国之间的友好，说只要世界各国的普通百姓能在足球场或板球场上相遇，就不会想在战场上相遇，我总是十分惊讶。","kind":"narration","speaker":"旁白"},{"en":"Even if one didn’t know from concrete examples (the 1936 Olympic Games, for instance) that international sporting contests lead to orgies of hatred, one could deduce it from general principles.","zh":"即使我们不知道那些证明国际体育竞赛会引发仇恨狂潮的具体事例——例如一九三六年奥运会——也能从一般原理推导出这一点。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Nearly all the sports practised nowadays are competitive.","zh":"如今开展的体育运动几乎全都有竞争性。","kind":"narration","speaker":"旁白"},{"en":"You play to win, and the game has little meaning unless you do your utmost to win.","zh":"参加比赛就是为了赢；若不竭尽全力争取获胜，比赛便没有多大意义。","kind":"narration","speaker":"旁白"},{"en":"On the village green, where you pick up sides and no feeling of local patriotism is involved, it is possible to play simply for the fun and exercise: but as soon as the question of prestige arises, as soon as you feel that you and some larger unit will be disgraced if you lose, the most savage combative instincts are aroused.","zh":"在村中的公共草地上，大家临时分队，也不牵涉地方荣誉感，完全可以只为娱乐和锻炼而玩；可是一旦关系到声望，一旦你觉得输了会让自己以及某个更大的集体蒙羞，最凶猛好斗的本能就会被激发出来。","kind":"narration","speaker":"旁白"},{"en":"Anyone who has played even in a school football match knows this.","zh":"哪怕只参加过学校足球赛的人，也知道这一点。","kind":"narration","speaker":"旁白"},{"en":"At the international level, sport is frankly mimic warfare.","zh":"坦率地说，国际层面的体育就是模拟战争。","kind":"narration","speaker":"旁白"},{"en":"But the significant thing is not the behaviour of the players but the attitude of the spectators: and, behind the spectators, of the nations who work themselves into furies over these absurd contests, and seriously believe—at any rate for short periods—that running, jumping and kicking a ball are tests of national virtue.","zh":"但关键在于观众的态度，而不在于运动员的表现；观众背后还有各个国家，它们会为这些荒唐的比赛怒不可遏，并且认真地相信——至少在短时间内如此——跑步、跳跃和踢球能检验一个民族的优劣。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"if only","matchedForm":"if only","meaning":"只要……就好了；只要","note":"常表示愿望；此处转述一种带理想色彩的条件设想。","example":"I am always amazed when I hear people saying that sport creates goodwill between the nations, and that if only the common peoples of the world could meet one another at football or cricket, they would have no inclination to meet on the battlefield.","exampleZh":"每当听到有人说体育能增进各国之间的友好，说只要世界各国的普通百姓能在足球场或板球场上相遇，就不会想在战场上相遇，我总是十分惊讶。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"deduce from","matchedForm":"deduce it from","meaning":"从……推断","note":"deduce something from evidence/principles 表示依据证据或原则作推论。","example":"Even if one didn’t know from concrete examples (the 1936 Olympic Games, for instance) that international sporting contests lead to orgies of hatred, one could deduce it from general principles.","exampleZh":"即使我们不知道那些证明国际体育竞赛会引发仇恨狂潮的具体事例——例如一九三六年奥运会——也能从一般原理推导出这一点。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"do one’s utmost","matchedForm":"do your utmost","meaning":"竭尽全力","note":"后常接 to do，utmost 在此是名词，表示最大努力。","example":"You play to win, and the game has little meaning unless you do your utmost to win.","exampleZh":"参加比赛就是为了赢；若不竭尽全力争取获胜，比赛便没有多大意义。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"mimic warfare","matchedForm":"mimic warfare","meaning":"模拟战争","note":"mimic 在这里作形容词，表示模拟的；作者用这一搭配强调国际体育的对抗性质。","example":"At the international level, sport is frankly mimic warfare.","exampleZh":"坦率地说，国际层面的体育就是模拟战争。","sourceParagraphIndex":1,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"at any rate","matchedForm":"at any rate","meaning":"至少；无论如何","note":"此处缩小断言范围，表示至少在短时间内确实如此。","example":"But the significant thing is not the behaviour of the players but the attitude of the spectators: and, behind the spectators, of the nations who work themselves into furies over these absurd contests, and seriously believe—at any rate for short periods—that running, jumping and kicking a ball are tests of national virtue.","exampleZh":"但关键在于观众的态度，而不在于运动员的表现；观众背后还有各个国家，它们会为这些荒唐的比赛怒不可遏，并且认真地相信——至少在短时间内如此——跑步、跳跃和踢球能检验一个民族的优劣。","sourceParagraphIndex":1,"sourceSentenceIndex":5,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l007","book":4,"number":7,"title":"Bats","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Not all sounds made by animals serve as language, and we have only to turn to that extraordinary discovery of echo-location in bats to see a case in which the voice plays a strictly utilitarian role.","zh":"动物发出的声音并非全都起语言的作用；只要看看蝙蝠回声定位这一非凡的发现，我们就能找到声音完全用于实际功用的一个例子。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"To get a full appreciation of what this means we must turn first to some recent human inventions.","zh":"要充分理解这意味着什么，我们必须先看看人类近来的一些发明。","kind":"narration","speaker":"旁白"},{"en":"Everyone knows that if he shouts in the vicinity of a wall or a mountainside, an echo will come back.","zh":"人人都知道，如果在墙壁或山坡附近喊一声，就会传回回声。","kind":"narration","speaker":"旁白"},{"en":"The further off this solid obstruction, the longer time will elapse for the return of the echo.","zh":"这个坚实的障碍物离得越远，回声传回所需的时间就越长。","kind":"narration","speaker":"旁白"},{"en":"A sound made by tapping on the hull of a ship will be reflected from the sea bottom, and by measuring the time interval between the taps and the receipt of the echoes, the depth of the sea at that point can be calculated.","zh":"敲击船体产生的声音会从海底反射回来；测量敲击与接收到回声之间的时间间隔，就能算出该处海水的深度。","kind":"narration","speaker":"旁白"},{"en":"So was born the echo-sounding apparatus, now in general use in ships.","zh":"回声测深仪就是这样诞生的，如今它已在船上普遍使用。","kind":"narration","speaker":"旁白"},{"en":"Every solid object will reflect a sound, varying according to the size and nature of the object.","zh":"任何固体都会反射声音，反射的声音随物体的大小和性质而异。","kind":"narration","speaker":"旁白"},{"en":"A shoal of fish will do this.","zh":"鱼群也会反射声音。","kind":"narration","speaker":"旁白"},{"en":"So it is a comparatively simple step from locating the sea bottom to locating a shoal of fish.","zh":"因此，从探测海底到探测鱼群，是比较容易跨出的一步。","kind":"narration","speaker":"旁白"},{"en":"With experience, and with improved apparatus, it is now possible not only to locate a shoal but to tell if it is herring, cod, or other well-known fish, by the pattern of its echo.","zh":"有了经验和改进后的仪器，如今人们不但能探测到鱼群，还能根据回声的特征判断它是鲱鱼、鳕鱼，还是其他常见鱼类。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"It has been found that certain bats emit squeaks and by receiving the echoes, they can locate and steer clear of obstacles—or locate flying insects on which they feed.","zh":"人们发现，某些蝙蝠会发出尖叫声，并通过接收回声确定障碍物的位置、避开障碍物，或找到它们赖以为食的飞虫。","kind":"narration","speaker":"旁白"},{"en":"This echo-location in bats is often compared with radar, the principle of which is similar.","zh":"蝙蝠的这种回声定位常被拿来与雷达相比，两者原理相似。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"serve as","matchedForm":"serve as","meaning":"充当；起……作用","note":"as 后接名词，说明事物所起的作用或用途。","example":"Not all sounds made by animals serve as language, and we have only to turn to that extraordinary discovery of echo-location in bats to see a case in which the voice plays a strictly utilitarian role.","exampleZh":"动物发出的声音并非全都起语言的作用；只要看看蝙蝠回声定位这一非凡的发现，我们就能找到声音完全用于实际功用的一个例子。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"in the vicinity of","matchedForm":"in the vicinity of","meaning":"在……附近","note":"较正式的地点表达，vicinity 表示周围一带。","example":"Everyone knows that if he shouts in the vicinity of a wall or a mountainside, an echo will come back.","exampleZh":"人人都知道，如果在墙壁或山坡附近喊一声，就会传回回声。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"in general use","matchedForm":"in general use","meaning":"被普遍使用","note":"in use 表示正在使用，general 进一步说明普及程度。","example":"So was born the echo-sounding apparatus, now in general use in ships.","exampleZh":"回声测深仪就是这样诞生的，如今它已在船上普遍使用。","sourceParagraphIndex":1,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"steer clear of","matchedForm":"steer clear of","meaning":"避开","note":"原指操纵方向以避障，也可比喻避开麻烦或某个话题。","example":"It has been found that certain bats emit squeaks and by receiving the echoes, they can locate and steer clear of obstacles—or locate flying insects on which they feed.","exampleZh":"人们发现，某些蝙蝠会发出尖叫声，并通过接收回声确定障碍物的位置、避开障碍物，或找到它们赖以为食的飞虫。","sourceParagraphIndex":2,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"feed on","matchedForm":"on which they feed","meaning":"以……为食","note":"原句将 on 提到关系代词 which 前面；常用结构是 animals feed on insects。","example":"It has been found that certain bats emit squeaks and by receiving the echoes, they can locate and steer clear of obstacles—or locate flying insects on which they feed.","exampleZh":"人们发现，某些蝙蝠会发出尖叫声，并通过接收回声确定障碍物的位置、避开障碍物，或找到它们赖以为食的飞虫。","sourceParagraphIndex":2,"sourceSentenceIndex":0,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l008","book":4,"number":8,"title":"Trading standards","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Chickens slaughtered in the United States, claim officials in Brussels, are not fit to grace European tables.","zh":"布鲁塞尔的官员声称，在美国宰杀的鸡不配登上欧洲人的餐桌。","kind":"speech","speaker":"布鲁塞尔官员"},{"en":"No, say the Americans: our fowl are fine, we simply clean them in a different way.","zh":"美国人却说：不，我们的禽肉很好，我们只是采用了不同的清洗方式。","kind":"speech","speaker":"美国方面"},{"en":"These days, it is differences in national regulations, far more than tariffs, that put sand in the wheels of trade between rich countries.","zh":"如今，阻碍富裕国家之间贸易的，与其说是关税，不如说更多是各国法规的差异。","kind":"narration","speaker":"旁白"},{"en":"It is not just farmers who are complaining.","zh":"抱怨的并不只是农民。","kind":"narration","speaker":"旁白"},{"en":"An electric razor that meets the European Union's safety standards must be approved by American testers before it can be sold in the United States, and an American-made dialysis machine needs the EU’s okay before it hits the market in Europe.","zh":"一把达到欧盟安全标准的电动剃须刀，要先得到美国检测人员的认可才能在美国销售；而一台美国制造的透析机，也须经过欧盟批准才能进入欧洲市场。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"As it happens, a razor that is safe in Europe is unlikely to electrocute Americans.","zh":"事实上，在欧洲使用安全的剃须刀，大概也不至于把美国人电死。","kind":"narration","speaker":"旁白"},{"en":"So, ask businesses on both sides of the Atlantic, why have two lots of tests where one would do?","zh":"所以，大西洋两岸的企业都问：一次检测既然就够了，何必检测两次？","kind":"speech","speaker":"美欧企业"},{"en":"Politicians agree, in principle, so America and the EU have been trying to reach a deal which would eliminate the need to double-test many products.","zh":"政界人士原则上表示赞同，因此美国和欧盟一直试图达成协议，让许多产品不再需要重复检测。","kind":"narration","speaker":"旁白"},{"en":"They hope to finish in time for a trade summit between America and the EU on May 28th.","zh":"他们希望及时完成谈判，赶上五月二十八日的美欧贸易峰会。","kind":"narration","speaker":"旁白"},{"en":"Although negotiators are optimistic, the details are complex enough that they may be hard-pressed to get a deal at all.","zh":"谈判代表虽然乐观，但细节如此复杂，他们最终能否达成任何协议都大有困难。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"Why?","zh":"为什么呢？","kind":"narration","speaker":"旁白"},{"en":"One difficulty is to construct the agreements.","zh":"其中一个难题是如何构建这些协议。","kind":"narration","speaker":"旁白"},{"en":"The Americans would happily reach one accord on standards for medical devices and then hammer out different pacts covering, say, electronic goods and drug manufacturing.","zh":"美国人很乐意先就医疗器械标准达成一项协议，再艰苦协商出其他分别涵盖电子产品、药品制造等领域的协定。","kind":"narration","speaker":"旁白"},{"en":"The EU—following fine continental traditions—wants agreement on general principles, which could be applied to many types of products and perhaps extended to other countries.","zh":"欧盟则遵循欧洲大陆一贯讲究原则的好传统，希望先就总原则达成一致，使之适用于多种产品，也许还能推广到其他国家。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"be fit to","matchedForm":"fit to","meaning":"适合；配得上","note":"fit to do 表示适合做某事；此处与 grace 搭配，带有挑剔和讽刺色彩。","example":"Chickens slaughtered in the United States, claim officials in Brussels, are not fit to grace European tables.","exampleZh":"布鲁塞尔的官员声称，在美国宰杀的鸡不配登上欧洲人的餐桌。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"hit the market","matchedForm":"hits the market","meaning":"上市；进入市场","note":"hit 在此表示到达或出现，不是打击市场。","example":"An electric razor that meets the European Union's safety standards must be approved by American testers before it can be sold in the United States, and an American-made dialysis machine needs the EU’s okay before it hits the market in Europe.","exampleZh":"一把达到欧盟安全标准的电动剃须刀，要先得到美国检测人员的认可才能在美国销售；而一台美国制造的透析机，也须经过欧盟批准才能进入欧洲市场。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"as it happens","matchedForm":"As it happens","meaning":"事实上；恰好","note":"用于引入恰好与讨论有关的事实，有时带反讽意味。","example":"As it happens, a razor that is safe in Europe is unlikely to electrocute Americans.","exampleZh":"事实上，在欧洲使用安全的剃须刀，大概也不至于把美国人电死。","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"in principle","matchedForm":"in principle","meaning":"原则上","note":"表示同意总体想法，未必已对具体执行细节取得一致。","example":"Politicians agree, in principle, so America and the EU have been trying to reach a deal which would eliminate the need to double-test many products.","exampleZh":"政界人士原则上表示赞同，因此美国和欧盟一直试图达成协议，让许多产品不再需要重复检测。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"hammer out","matchedForm":"hammer out","meaning":"反复磋商后敲定","note":"常接 agreement、deal 等，强调协商过程费力。","example":"The Americans would happily reach one accord on standards for medical devices and then hammer out different pacts covering, say, electronic goods and drug manufacturing.","exampleZh":"美国人很乐意先就医疗器械标准达成一项协议，再艰苦协商出其他分别涵盖电子产品、药品制造等领域的协定。","sourceParagraphIndex":2,"sourceSentenceIndex":2,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l009","book":4,"number":9,"title":"Royal espionage","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Alfred the Great acted as his own spy, visiting Danish camps disguised as a minstrel.","zh":"阿尔弗雷德大帝亲自充当间谍，乔装成吟游诗人，探访丹麦人的营地。","kind":"narration","speaker":"旁白"},{"en":"In those days wandering minstrels were welcome everywhere.","zh":"那时候，四处游历的吟游诗人到哪里都受欢迎。","kind":"narration","speaker":"旁白"},{"en":"They were not fighting men, and their harp was their passport.","zh":"他们不是战士，手中的竖琴就是通行证。","kind":"narration","speaker":"旁白"},{"en":"Alfred had learned many of their ballads in his youth, and could vary his programme with acrobatic tricks and simple conjuring.","zh":"阿尔弗雷德年轻时学会了他们的许多歌谣，还能穿插表演杂技和简单的魔术，使节目更加丰富。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"While Alfred’s little army slowly began to gather at Athelney, the king himself set out to penetrate the camp of Guthrum, the commander of the Danish invaders.","zh":"阿尔弗雷德的小股部队在阿瑟尔尼慢慢集结时，国王本人动身潜入丹麦侵略军统帅古斯鲁姆的营地。","kind":"narration","speaker":"旁白"},{"en":"These had settled down for the winter at Chippenham: thither Alfred went.","zh":"丹麦军队已在奇彭纳姆安顿下来过冬，阿尔弗雷德便前往那里。","kind":"narration","speaker":"旁白"},{"en":"He noticed at once that discipline was slack: the Danes had the self-confidence of conquerors, and their security precautions were casual.","zh":"他立刻发现营中纪律松弛：丹麦人有征服者的自信，安全戒备十分随便。","kind":"narration","speaker":"旁白"},{"en":"They lived well, on the proceeds of raids on neighbouring regions.","zh":"他们靠抢掠邻近地区所得的东西过着优裕生活。","kind":"narration","speaker":"旁白"},{"en":"There they collected women as well as food and drink, and a life of ease had made them soft.","zh":"他们在那里不仅掳来食物和酒，还掳来女人；安逸的生活已使他们变得软弱。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"Alfred stayed in the camp a week before he returned to Athelney.","zh":"阿尔弗雷德在敌营待了一周才返回阿瑟尔尼。","kind":"narration","speaker":"旁白"},{"en":"The force there assembled was trivial compared with the Danish horde.","zh":"那里集结的兵力与丹麦大军相比，实在微不足道。","kind":"narration","speaker":"旁白"},{"en":"But Alfred had deduced that the Danes were no longer fit for prolonged battle: and that their commissariat had no organization, but depended on irregular raids.","zh":"但阿尔弗雷德已经推断出，丹麦人再也经不起持久作战；而且他们的军需补给毫无组织，只靠不定时的抢掠。","kind":"narration","speaker":"旁白"}]},{"index":3,"rows":[{"en":"So, faced with the Danish advance, Alfred did not risk open battle but harried the enemy.","zh":"所以，面对丹麦军队的进逼，阿尔弗雷德没有冒险进行正面交战，而是不断袭扰敌人。","kind":"narration","speaker":"旁白"},{"en":"He was constantly on the move, drawing the Danes after him.","zh":"他不停转移，引着丹麦人追赶。","kind":"narration","speaker":"旁白"},{"en":"His patrols halted the raiding parties: hunger assailed the Danish army.","zh":"他的巡逻队拦截了出来抢掠的队伍，饥饿开始侵袭丹麦军队。","kind":"narration","speaker":"旁白"},{"en":"Now Alfred began a long series of skirmishes—and within a month the Danes had surrendered.","zh":"这时，阿尔弗雷德展开了一连串的小规模战斗；不到一个月，丹麦人便投降了。","kind":"narration","speaker":"旁白"},{"en":"The episode could reasonably serve as a unique epic of royal espionage!","zh":"这一段经历，完全可以称得上王者亲自从事谍报活动的一部独特史诗！","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"be disguised as","matchedForm":"disguised as","meaning":"乔装成","note":"常用 be disguised as，as 后接伪装的身份。","example":"Alfred the Great acted as his own spy, visiting Danish camps disguised as a minstrel.","exampleZh":"阿尔弗雷德大帝亲自充当间谍，乔装成吟游诗人，探访丹麦人的营地。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"set out to","matchedForm":"set out to","meaning":"动身去；着手","note":"set out to do 可表示开始有目的的行动，此处兼有启程之意。","example":"While Alfred’s little army slowly began to gather at Athelney, the king himself set out to penetrate the camp of Guthrum, the commander of the Danish invaders.","exampleZh":"阿尔弗雷德的小股部队在阿瑟尔尼慢慢集结时，国王本人动身潜入丹麦侵略军统帅古斯鲁姆的营地。","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"settle down","matchedForm":"settled down","meaning":"安顿下来","note":"此处指军队驻扎过冬，非表示平静或结婚成家。","example":"These had settled down for the winter at Chippenham: thither Alfred went.","exampleZh":"丹麦军队已在奇彭纳姆安顿下来过冬，阿尔弗雷德便前往那里。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"compared with","matchedForm":"compared with","meaning":"与……相比","note":"引出比较对象，常作过去分词短语。","example":"The force there assembled was trivial compared with the Danish horde.","exampleZh":"那里集结的兵力与丹麦大军相比，实在微不足道。","sourceParagraphIndex":2,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"on the move","matchedForm":"on the move","meaning":"不断移动中","note":"be on the move 可指持续转移，也可指忙碌奔波。","example":"He was constantly on the move, drawing the Danes after him.","exampleZh":"他不停转移，引着丹麦人追赶。","sourceParagraphIndex":3,"sourceSentenceIndex":1,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l010","book":4,"number":10,"title":"Silicon valley","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Technology trends may push Silicon Valley back to the future.","zh":"技术发展的潮流，或许会推动硅谷以回归往昔的方式走向未来。","kind":"narration","speaker":"旁白"},{"en":"Carver Mead, a pioneer in integrated circuits and a professor of computer science at the California Institute of Technology, notes there are now workstations that enable engineers to design, test and produce chips right on their desks, much the way an editor creates a newsletter on a Macintosh.","zh":"集成电路先驱、加州理工学院计算机科学教授卡弗·米德指出，如今已有工作站让工程师直接在办公桌上设计、测试和生产芯片，大致就像编辑用麦金塔电脑制作简报一样。","kind":"narration","speaker":"旁白"},{"en":"As the time and cost of making a chip drop to a few days and a few hundred dollars, engineers may soon be free to let their imaginations soar without being penalized by expensive failures.","zh":"当制造一枚芯片所需的时间和费用降到几天、几百美元时，工程师或许很快就能让想象力自由驰骋，而不必因失败代价高昂而受到惩罚。","kind":"narration","speaker":"旁白"},{"en":"Mead predicts that inventors will be able to perfect powerful customized chips over a weekend at the office—spawning a new generation of garage start-ups and giving the U.S. a jump on its foreign rivals in getting new products to market fast.","zh":"米德预言，发明者将能够利用一个周末在办公室里完善性能强大的定制芯片，从而催生新一代从车库起家的初创企业，并使美国在迅速把新产品推向市场方面领先外国对手一步。","kind":"narration","speaker":"旁白"},{"en":"‘We've got more garages with smart people,’ Mead observes.","zh":"米德说：“我们有更多车库，里面有聪明人。”","kind":"speech","speaker":"米德"},{"en":"‘We really thrive on anarchy.’","zh":"“我们确实靠这种自由无序的环境蓬勃发展。”","kind":"speech","speaker":"米德"}]},{"index":1,"rows":[{"en":"And on Asians.","zh":"同样也靠亚洲人。","kind":"narration","speaker":"旁白"},{"en":"Already, orientals and Asian Americans constitute the majority of the engineering staffs at many Valley firms.","zh":"在硅谷的许多公司里，亚洲人和亚裔美国人已占工程技术人员的大多数。","kind":"narration","speaker":"旁白"},{"en":"And Chinese, Korean, Filipino and Indian engineers are graduating in droves from California's colleges.","zh":"而中国、韩国、菲律宾和印度背景的工程师，正一批批从加利福尼亚的大学毕业。","kind":"narration","speaker":"旁白"},{"en":"As the heads of next-generation start-ups, these Asian innovators can draw on customs and languages to forge tighter links with crucial Pacific Rim markets.","zh":"作为下一代初创企业的负责人，这些亚洲创新者能借助自身熟悉的习俗和语言，与至关重要的环太平洋市场建立更紧密的联系。","kind":"narration","speaker":"旁白"},{"en":"For instance, Alex Au, a Stanford Ph.D. from Hong Kong, has set up a Taiwan factory to challenge Japan's near lock on the memory-chip market.","zh":"例如，来自香港的斯坦福大学博士亚历克斯·欧，在台湾设立了一家工厂，挑战日本对存储芯片市场近乎垄断的地位。","kind":"narration","speaker":"旁白"},{"en":"India-born N. Damodar Reddy's tiny California company reopened an AT&T chip plant in Kansas City last spring with financing from the state of Missouri.","zh":"出生于印度的恩·达莫达尔·雷迪，他在加利福尼亚的小公司去年春天获得密苏里州的资金支持，使堪萨斯城一家美国电话电报公司的芯片工厂重新开工。","kind":"narration","speaker":"旁白"},{"en":"Before it becomes a retirement village, Silicon Valley may prove a classroom for building a global business.","zh":"在变成退休者聚居区之前，硅谷或许会先成为人们学习如何创办全球企业的课堂。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"be free to","matchedForm":"be free to","meaning":"可以自由地","note":"后接动词原形，表示有自由或条件去做，而非免费。","example":"As the time and cost of making a chip drop to a few days and a few hundred dollars, engineers may soon be free to let their imaginations soar without being penalized by expensive failures.","exampleZh":"当制造一枚芯片所需的时间和费用降到几天、几百美元时，工程师或许很快就能让想象力自由驰骋，而不必因失败代价高昂而受到惩罚。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"give someone a jump on","matchedForm":"giving the U.S. a jump on","meaning":"让……抢先一步","note":"a jump on someone 表示领先优势，常与 get 或 give 搭配。","example":"Mead predicts that inventors will be able to perfect powerful customized chips over a weekend at the office—spawning a new generation of garage start-ups and giving the U.S. a jump on its foreign rivals in getting new products to market fast.","exampleZh":"米德预言，发明者将能够利用一个周末在办公室里完善性能强大的定制芯片，从而催生新一代从车库起家的初创企业，并使美国在迅速把新产品推向市场方面领先外国对手一步。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"thrive on","matchedForm":"thrive on","meaning":"因……而兴旺；靠……发展","note":"后接促进成长的因素，此处 anarchy 形容缺少束缚的环境。","example":"‘We really thrive on anarchy.’","exampleZh":"“我们确实靠这种自由无序的环境蓬勃发展。”","sourceParagraphIndex":0,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"in droves","matchedForm":"in droves","meaning":"成批地；大量地","note":"常用来描述人群的大批涌入、离开或出现。","example":"And Chinese, Korean, Filipino and Indian engineers are graduating in droves from California's colleges.","exampleZh":"而中国、韩国、菲律宾和印度背景的工程师，正一批批从加利福尼亚的大学毕业。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"draw on","matchedForm":"draw on","meaning":"利用；借助","note":"后接知识、经验或资源，强调调动已有积累。","example":"As the heads of next-generation start-ups, these Asian innovators can draw on customs and languages to forge tighter links with crucial Pacific Rim markets.","exampleZh":"作为下一代初创企业的负责人，这些亚洲创新者能借助自身熟悉的习俗和语言，与至关重要的环太平洋市场建立更紧密的联系。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l011","book":4,"number":11,"title":"How to grow old","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Some old people are oppressed by the fear of death.","zh":"有些老年人被死亡的恐惧所压迫。","kind":"narration","speaker":"旁白"},{"en":"In the young there is a justification for this feeling.","zh":"年轻人有这种感受，是有道理的。","kind":"narration","speaker":"旁白"},{"en":"Young men who have reason to fear that they will be killed in battle may justifiably feel bitter in the thought that they have been cheated of the best things that life has to offer.","zh":"有理由担心自己会战死的青年，想到人生所能给予的最美好的东西竟被夺走，自然有理由感到痛苦不平。","kind":"narration","speaker":"旁白"},{"en":"But in an old man who has known human joys and sorrows, and has achieved whatever work it was in him to do, the fear of death is somewhat abject and ignoble.","zh":"但是，一个已经体验过人间悲欢、完成了自己能力所及的工作的人，到了老年仍然害怕死亡，就显得有些卑怯，有失尊严了。","kind":"narration","speaker":"旁白"},{"en":"The best way to overcome it—so at least it seems to me—is to make your interests gradually wider and more impersonal, until bit by bit the walls of the ego recede, and your life becomes increasingly merged in the universal life.","zh":"克服这种恐惧的最好办法——至少在我看来如此——就是让自己的兴趣逐渐扩大，越来越超越个人，直到自我的围墙一点点退去，自己的生命越来越融入普遍的生命之中。","kind":"narration","speaker":"旁白"},{"en":"An individual human existence should be like a river—small at first, narrowly contained within its banks, and rushing passionately past boulders and over waterfalls.","zh":"一个人的生命应当像一条河：起初很小，紧紧局限在两岸之间，激情奔涌，冲过巨石，跌下瀑布。","kind":"narration","speaker":"旁白"},{"en":"Gradually the river grows wider, the banks recede, the waters flow more quietly, and in the end, without any visible break, they become merged in the sea, and painlessly lose their individual being.","zh":"河流渐渐宽阔，河岸向两侧退去，水流趋于平静，最后在看不出任何断裂的情况下汇入大海，毫无痛苦地失去独立的存在。","kind":"narration","speaker":"旁白"},{"en":"The man who, in old age, can see his life in this way, will not suffer from the fear of death, since the things he cares for will continue.","zh":"人在老年若能这样看待自己的生命，就不会受死亡恐惧的折磨，因为他关心的事物还会继续存在。","kind":"narration","speaker":"旁白"},{"en":"And if, with the decay of vitality, weariness increases, the thought of rest will be not unwelcome.","zh":"如果随着生命力的衰退，倦意日增，那么想到可以休息，也并非不受欢迎。","kind":"narration","speaker":"旁白"},{"en":"I should wish to die while still at work, knowing that others will carry on what I can no longer do, and content in the thought that what was possible has been done.","zh":"我希望去世时自己仍在工作，知道别人会继续做我再也无法做的事情，并欣慰地想到：凡是可能做到的，都已经做了。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"have reason to","matchedForm":"have reason to","meaning":"有理由","note":"reason 在这里通常不加冠词，后接动词原形。","example":"Young men who have reason to fear that they will be killed in battle may justifiably feel bitter in the thought that they have been cheated of the best things that life has to offer.","exampleZh":"有理由担心自己会战死的青年，想到人生所能给予的最美好的东西竟被夺走，自然有理由感到痛苦不平。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"cheat someone of something","matchedForm":"cheated of","meaning":"骗走；剥夺","note":"cheat someone of something 表示以不公的方式使其失去应得之物。","example":"Young men who have reason to fear that they will be killed in battle may justifiably feel bitter in the thought that they have been cheated of the best things that life has to offer.","exampleZh":"有理由担心自己会战死的青年，想到人生所能给予的最美好的东西竟被夺走，自然有理由感到痛苦不平。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"bit by bit","matchedForm":"bit by bit","meaning":"一点一点地","note":"强调变化缓慢而逐步发生。","example":"The best way to overcome it—so at least it seems to me—is to make your interests gradually wider and more impersonal, until bit by bit the walls of the ego recede, and your life becomes increasingly merged in the universal life.","exampleZh":"克服这种恐惧的最好办法——至少在我看来如此——就是让自己的兴趣逐渐扩大，越来越超越个人，直到自我的围墙一点点退去，自己的生命越来越融入普遍的生命之中。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"suffer from","matchedForm":"suffer from","meaning":"遭受……折磨","note":"后接疾病或痛苦处境，此处指受恐惧困扰。","example":"The man who, in old age, can see his life in this way, will not suffer from the fear of death, since the things he cares for will continue.","exampleZh":"人在老年若能这样看待自己的生命，就不会受死亡恐惧的折磨，因为他关心的事物还会继续存在。","sourceParagraphIndex":0,"sourceSentenceIndex":7,"sourceType":"textbook-passage"},{"phrase":"carry on","matchedForm":"carry on","meaning":"继续进行","note":"可接名词或动名词；此处宾语为 what 引导的从句。","example":"I should wish to die while still at work, knowing that others will carry on what I can no longer do, and content in the thought that what was possible has been done.","exampleZh":"我希望去世时自己仍在工作，知道别人会继续做我再也无法做的事情，并欣慰地想到：凡是可能做到的，都已经做了。","sourceParagraphIndex":0,"sourceSentenceIndex":9,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l012","book":4,"number":12,"title":"Banks and their customers","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"When anyone opens a current account at a bank, he is lending the bank money, repayment of which he may demand at any time, either in cash or by drawing a cheque in favour of another person.","zh":"任何人在银行开立活期账户时，都等于把钱借给银行；他随时可以要求偿还，既可以取现金，也可以开一张以他人为收款人的支票。","kind":"narration","speaker":"旁白"},{"en":"Primarily, the banker-customer relationship is that of debtor and creditor—who is which depending on whether the customer's account is in credit or is overdrawn.","zh":"银行与客户的关系，首先是债务人与债权人的关系；究竟谁是哪一方，取决于客户账户上有余额还是已经透支。","kind":"narration","speaker":"旁白"},{"en":"But, in addition to that basically simple concept, the bank and its customer owe a large number of obligations to one another.","zh":"但除了这一基本上很简单的概念，银行和客户还彼此承担着许多义务。","kind":"narration","speaker":"旁白"},{"en":"Many of these obligations can give rise to problems and complications but a bank customer, unlike, say, a buyer of goods, cannot complain that the law is loaded against him.","zh":"其中许多义务可能引起问题和纠纷，不过银行客户不能像例如商品买主那样，抱怨法律偏向对方、不利于自己。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"The bank must obey its customer’s instructions, and not those of anyone else.","zh":"银行必须遵照客户本人的指示，而不能听从其他任何人的指示。","kind":"narration","speaker":"旁白"},{"en":"When, for example, a customer first opens an account, he instructs the bank to debit his account only in respect of cheques drawn by himself.","zh":"例如，客户刚开户时，会指示银行，只能凭他本人签发的支票从其账户扣款。","kind":"narration","speaker":"旁白"},{"en":"He gives the bank specimens of his signature, and there is a very firm rule that the bank has no right or authority to pay out a customer's money on a cheque on which its customer's signature has been forged.","zh":"他向银行提供自己的签名样本；有一条非常明确的规则：如果支票上客户的签名系伪造，银行就没有权利或授权支付客户的存款。","kind":"narration","speaker":"旁白"},{"en":"It makes no difference that the forgery may have been a very skilful one: the bank must recognize its customer's signature.","zh":"即便伪造得非常高明也没有区别：银行必须辨认得出客户的签名。","kind":"narration","speaker":"旁白"},{"en":"For this reason there is no risk to the customer in the practice, adopted by banks, of printing the customer’s name on his cheques.","zh":"因此，银行把客户姓名印在支票上的做法，对客户并没有风险。","kind":"narration","speaker":"旁白"},{"en":"If this facilitates forgery, it is the bank which will lose, not the customer.","zh":"如果这种做法使伪造变得容易，蒙受损失的是银行，而不是客户。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"in favour of","matchedForm":"in favour of","meaning":"以……为收款人","note":"用于支票等金融文本；一般语境也可表示支持或赞成。","example":"When anyone opens a current account at a bank, he is lending the bank money, repayment of which he may demand at any time, either in cash or by drawing a cheque in favour of another person.","exampleZh":"任何人在银行开立活期账户时，都等于把钱借给银行；他随时可以要求偿还，既可以取现金，也可以开一张以他人为收款人的支票。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"in credit","matchedForm":"in credit","meaning":"账户有余额","note":"与 overdrawn 相对，指账户中还有属于客户的可用款项。","example":"Primarily, the banker-customer relationship is that of debtor and creditor—who is which depending on whether the customer's account is in credit or is overdrawn.","exampleZh":"银行与客户的关系，首先是债务人与债权人的关系；究竟谁是哪一方，取决于客户账户上有余额还是已经透支。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"give rise to","matchedForm":"give rise to","meaning":"引起；导致","note":"后接问题、变化或结果，常用于正式书面语。","example":"Many of these obligations can give rise to problems and complications but a bank customer, unlike, say, a buyer of goods, cannot complain that the law is loaded against him.","exampleZh":"其中许多义务可能引起问题和纠纷，不过银行客户不能像例如商品买主那样，抱怨法律偏向对方、不利于自己。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"in respect of","matchedForm":"in respect of","meaning":"就……而言；关于","note":"正式表达，此处限定银行扣款所依据的支票。","example":"When, for example, a customer first opens an account, he instructs the bank to debit his account only in respect of cheques drawn by himself.","exampleZh":"例如，客户刚开户时，会指示银行，只能凭他本人签发的支票从其账户扣款。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"make no difference","matchedForm":"makes no difference","meaning":"没有影响；不改变情况","note":"常用 it makes no difference that/whether，表示某因素不改变结论。","example":"It makes no difference that the forgery may have been a very skilful one: the bank must recognize its customer's signature.","exampleZh":"即便伪造得非常高明也没有区别：银行必须辨认得出客户的签名。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l013","book":4,"number":13,"title":"The search for oil","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"The deepest holes of all are made for oil, and they go down to as much as 25,000 feet.","zh":"所有孔井中最深的是为开采石油而钻的，深度可达二万五千英尺。","kind":"narration","speaker":"旁白"},{"en":"But we do not need to send men down to get the oil out, as we must with other mineral deposits.","zh":"不过，开采石油不必像开采其他矿藏那样，把人送到地下去。","kind":"narration","speaker":"旁白"},{"en":"The holes are only borings, less than a foot in diameter.","zh":"这些井只是钻孔，直径还不到一英尺。","kind":"narration","speaker":"旁白"},{"en":"My particular experience is largely in oil, and the search for oil has done more to improve deep drilling than any other mining activity.","zh":"我本人的专门经验主要在石油领域，而寻找石油对于深井钻探技术的改进，比任何其他采矿活动都贡献更大。","kind":"narration","speaker":"旁白"},{"en":"When it has been decided where we are going to drill, we put up at the surface an oil derrick.","zh":"一旦决定了在哪里钻探，我们便在地面架起一座石油井架。","kind":"narration","speaker":"旁白"},{"en":"It has to be tall because it is like a giant block and tackle, and we have to lower into the ground and haul out of the ground great lengths of drill pipe which are rotated by an engine at the top and are fitted with a cutting bit at the bottom.","zh":"井架必须很高，因为它就像一个巨大的滑轮组；我们必须把很长的钻杆放进地下，再从地下吊上来，钻杆由顶部的发动机带动旋转，底端则装着切削钻头。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"The geologist needs to know what rocks the drill has reached, so every so often a sample is obtained with a coring bit.","zh":"地质学家需要知道钻头已钻到了什么岩石，因此每隔一段时间，就要用取芯钻头采一份样本。","kind":"narration","speaker":"旁白"},{"en":"It cuts a clean cylinder of rock, from which can be seen the strata the drill has been cutting through.","zh":"这种钻头切下一段完整的圆柱形岩芯，从中可以看出钻头已经钻穿的地层。","kind":"narration","speaker":"旁白"},{"en":"Once we get down to the oil, it usually flows to the surface because great pressure, either from gas or water, is pushing it.","zh":"一旦钻到石油层，石油通常会流上地面，因为有气体或水产生的巨大压力在推着它。","kind":"narration","speaker":"旁白"},{"en":"This pressure must be under control, and we control it by means of the mud which we circulate down the drill pipe.","zh":"这股压力必须受到控制，而我们用沿钻杆向下循环输送的泥浆来控制它。","kind":"narration","speaker":"旁白"},{"en":"We endeavour to avoid the old, romantic idea of a gusher, which wastes oil and gas.","zh":"我们力求避免过去那种颇具浪漫色彩的井喷，因为井喷会浪费石油和天然气。","kind":"narration","speaker":"旁白"},{"en":"We want it to stay down the hole until we can lead it off in a controlled manner.","zh":"我们希望让石油留在井下，直到能够以受控的方式将它引出来。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"as much as","matchedForm":"as much as","meaning":"多达；高达","note":"放在数量前强调程度或数量之大，此处修饰深度。","example":"The deepest holes of all are made for oil, and they go down to as much as 25,000 feet.","exampleZh":"所有孔井中最深的是为开采石油而钻的，深度可达二万五千英尺。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"put up","matchedForm":"put up","meaning":"搭建；架起","note":"此处宾语为井架，意为建起设施，不是张贴或忍受。","example":"When it has been decided where we are going to drill, we put up at the surface an oil derrick.","exampleZh":"一旦决定了在哪里钻探，我们便在地面架起一座石油井架。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"every so often","matchedForm":"every so often","meaning":"时不时；每隔一段时间","note":"表示间歇重复，不必有固定频率。","example":"The geologist needs to know what rocks the drill has reached, so every so often a sample is obtained with a coring bit.","exampleZh":"地质学家需要知道钻头已钻到了什么岩石，因此每隔一段时间，就要用取芯钻头采一份样本。","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"under control","matchedForm":"under control","meaning":"受到控制","note":"常与 be、keep、bring 搭配，表示局面或力量受掌控。","example":"This pressure must be under control, and we control it by means of the mud which we circulate down the drill pipe.","exampleZh":"这股压力必须受到控制，而我们用沿钻杆向下循环输送的泥浆来控制它。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"by means of","matchedForm":"by means of","meaning":"借助；通过","note":"后接所用的工具、材料或方法。","example":"This pressure must be under control, and we control it by means of the mud which we circulate down the drill pipe.","exampleZh":"这股压力必须受到控制，而我们用沿钻杆向下循环输送的泥浆来控制它。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l014","book":4,"number":14,"title":"The Butterfly Effect","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Beyond two or three days, the world’s best weather forecasts are speculative, and beyond six or seven they are worthless.","zh":"即使是世界上最好的天气预报，超过两三天也只是推测，超过六七天便毫无价值。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"The Butterfly Effect is the reason.","zh":"原因就在于蝴蝶效应。","kind":"narration","speaker":"旁白"},{"en":"For small pieces of weather — and to a global forecaster, small can mean thunderstorms and blizzards — any prediction deteriorates rapidly.","zh":"对于天气中的小尺度现象——在全球天气预报者眼中，雷暴和暴风雪也可以算小——任何预测都会迅速失准。","kind":"narration","speaker":"旁白"},{"en":"Errors and uncertainties multiply, cascading upward through a chain of turbulent features, from dust devils and squalls up to continent-size eddies that only satellites can see.","zh":"误差与不确定性不断倍增，沿着一连串湍流现象逐级向更大尺度传递，从尘卷风和飑，一直到只有卫星才能观测到的大陆尺度涡旋。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"The modern weather models work with a grid of points of the order of sixty miles apart, and even so, some starting data has to be guessed, since ground stations and satellites cannot see everywhere.","zh":"现代天气模型使用的网格，各点相隔约六十英里；即便如此，有些初始数据仍得靠估计，因为地面观测站和卫星不可能看遍每一处。","kind":"narration","speaker":"旁白"},{"en":"But suppose the earth could be covered with sensors spaced one foot apart, rising at one-foot intervals all the way to the top of the atmosphere.","zh":"不过，假设整个地球都能布满间距一英尺的传感器，并且以一英尺的垂直间隔，一直布设到大气层顶端。","kind":"narration","speaker":"旁白"},{"en":"Suppose every sensor gives perfectly accurate readings of temperature, pressure, humidity, and any other quantity a meteorologist would want.","zh":"再假设每个传感器都能完全准确地测出温度、气压、湿度，以及气象学家想要的任何其他量。","kind":"narration","speaker":"旁白"},{"en":"Precisely at noon an infinitely powerful computer takes all the data and calculates what will happen at each point at 12.01, then 12.02, then 12.03...","zh":"正午十二点整，一台运算能力无限强大的计算机收集全部数据，算出十二点零一分每一点会出现什么情况，接着算十二点零二分、十二点零三分……","kind":"narration","speaker":"旁白"}]},{"index":3,"rows":[{"en":"The computer will still be unable to predict whether Princeton, New Jersey, will have sun or rain on a day one month away.","zh":"这台计算机仍然无法预测，一个月后的某一天，新泽西州普林斯顿究竟是晴天还是雨天。","kind":"narration","speaker":"旁白"},{"en":"At noon the spaces between the sensors will hide fluctuations that the computer will not know about, tiny deviations from the average.","zh":"正午时，传感器之间的空隙中隐藏着计算机无法得知的起伏，也就是偏离平均值的微小波动。","kind":"narration","speaker":"旁白"},{"en":"By 12.01, those fluctuations will already have created small errors one foot away.","zh":"到了十二点零一分，这些起伏就已经在一英尺之外造成了小误差。","kind":"narration","speaker":"旁白"},{"en":"Soon the errors will have multiplied to the ten-foot scale, and so on up to the size of the globe.","zh":"很快，误差就会扩大到十英尺的尺度，然后这样不断扩大，直至遍及整个地球。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"a chain of","matchedForm":"a chain of","meaning":"一连串；一系列相联的","note":"强调环节相互关联，而非毫无联系地并列。","example":"Errors and uncertainties multiply, cascading upward through a chain of turbulent features, from dust devils and squalls up to continent-size eddies that only satellites can see.","exampleZh":"误差与不确定性不断倍增，沿着一连串湍流现象逐级向更大尺度传递，从尘卷风和飑，一直到只有卫星才能观测到的大陆尺度涡旋。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"of the order of","matchedForm":"of the order of","meaning":"大约；在……量级","note":"用于科学或技术语境，表示近似的数量或尺度。","example":"The modern weather models work with a grid of points of the order of sixty miles apart, and even so, some starting data has to be guessed, since ground stations and satellites cannot see everywhere.","exampleZh":"现代天气模型使用的网格，各点相隔约六十英里；即便如此，有些初始数据仍得靠估计，因为地面观测站和卫星不可能看遍每一处。","sourceParagraphIndex":2,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"all the way to","matchedForm":"all the way to","meaning":"一直到","note":"强调空间上延伸到某个终点，也可用于过程。","example":"But suppose the earth could be covered with sensors spaced one foot apart, rising at one-foot intervals all the way to the top of the atmosphere.","exampleZh":"不过，假设整个地球都能布满间距一英尺的传感器，并且以一英尺的垂直间隔，一直布设到大气层顶端。","sourceParagraphIndex":2,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"be unable to","matchedForm":"be unable to","meaning":"无法","note":"后接动词原形，表示能力或条件不足以完成某事。","example":"The computer will still be unable to predict whether Princeton, New Jersey, will have sun or rain on a day one month away.","exampleZh":"这台计算机仍然无法预测，一个月后的某一天，新泽西州普林斯顿究竟是晴天还是雨天。","sourceParagraphIndex":3,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"and so on","matchedForm":"and so on","meaning":"等等；如此继续","note":"表示前述规律或列举还会延续；此处是误差继续扩散。","example":"Soon the errors will have multiplied to the ten-foot scale, and so on up to the size of the globe.","exampleZh":"很快，误差就会扩大到十英尺的尺度，然后这样不断扩大，直至遍及整个地球。","sourceParagraphIndex":3,"sourceSentenceIndex":3,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l015","book":4,"number":15,"title":"Secrecy in industry","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Two factors weigh heavily against the effectiveness of scientific research in industry.","zh":"有两个因素严重妨碍工业科研发挥成效。","kind":"narration","speaker":"旁白"},{"en":"One is the general atmosphere of secrecy in which it is carried out, the other the lack of freedom of the individual research worker.","zh":"一是科研工作普遍在保密气氛下进行，二是科研人员个人缺乏自由。","kind":"narration","speaker":"旁白"},{"en":"In so far as any inquiry is a secret one, it naturally limits all those engaged in carrying it out from effective contact with their fellow scientists either in other countries or in universities, or even, often enough, in other departments of the same firm.","zh":"只要一项研究具有保密性质，自然就会限制所有参与者与同行进行有效交流，不论这些同行是在别国、大学，甚至往往就在同一公司的其他部门。","kind":"narration","speaker":"旁白"},{"en":"The degree of secrecy naturally varies considerably.","zh":"保密程度自然有很大差别。","kind":"narration","speaker":"旁白"},{"en":"Some of the bigger firms are engaged in researches which are of such general and fundamental nature that it is a positive advantage to them not to keep them secret.","zh":"有些大公司进行的研究如此广泛而基础，以至于不予保密反而会给它们带来实实在在的好处。","kind":"narration","speaker":"旁白"},{"en":"Yet a great many processes depending on such research are sought for with complete secrecy until the stage at which patents can be taken out.","zh":"不过，以这类研究为基础的许多工艺，其开发仍完全保密，直至达到能够申请专利的阶段。","kind":"narration","speaker":"旁白"},{"en":"Even more processes are never patented at all but kept as secret processes.","zh":"还有更多工艺根本不申请专利，而是作为秘密工艺保留下来。","kind":"narration","speaker":"旁白"},{"en":"This applies particularly to chemical industries, where chance discoveries play a much larger part than they do in physical and mechanical industries.","zh":"化学工业尤其如此，因为偶然发现所起的作用，比在物理和机械工业中大得多。","kind":"narration","speaker":"旁白"},{"en":"Sometimes the secrecy goes to such an extent that the whole nature of the research cannot be mentioned.","zh":"有时保密竟到了这种地步：连研究本身的性质都不能提及。","kind":"narration","speaker":"旁白"},{"en":"Many firms, for instance, have great difficulty in obtaining technical or scientific books from libraries because they are unwilling to have their names entered as having taken out such and such a book, for fear the agents of other firms should be able to trace the kind of research they are likely to be undertaking.","zh":"例如，许多公司从图书馆借取技术或科学书籍都非常困难，因为它们不愿留下借过某某书的公司名称记录，唯恐其他公司的探子据此追查出它们可能正在进行哪类研究。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"weigh against","matchedForm":"weigh heavily against","meaning":"严重不利于","note":"weigh against 表示构成不利因素，heavily 加重影响程度。","example":"Two factors weigh heavily against the effectiveness of scientific research in industry.","exampleZh":"有两个因素严重妨碍工业科研发挥成效。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"in so far as","matchedForm":"In so far as","meaning":"就……而言；在……范围内","note":"限定论述成立的条件或程度，此处指研究具有保密性质这一点。","example":"In so far as any inquiry is a secret one, it naturally limits all those engaged in carrying it out from effective contact with their fellow scientists either in other countries or in universities, or even, often enough, in other departments of the same firm.","exampleZh":"只要一项研究具有保密性质，自然就会限制所有参与者与同行进行有效交流，不论这些同行是在别国、大学，甚至往往就在同一公司的其他部门。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"take out a patent","matchedForm":"patents can be taken out","meaning":"申请取得专利","note":"take out 可搭配 patent、insurance 等，表示办理或取得正式权利。","example":"Yet a great many processes depending on such research are sought for with complete secrecy until the stage at which patents can be taken out.","exampleZh":"不过，以这类研究为基础的许多工艺，其开发仍完全保密，直至达到能够申请专利的阶段。","sourceParagraphIndex":0,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"go to such an extent","matchedForm":"goes to such an extent","meaning":"达到如此程度","note":"常与 that 结果从句连用，说明做法发展到某种极端程度。","example":"Sometimes the secrecy goes to such an extent that the whole nature of the research cannot be mentioned.","exampleZh":"有时保密竟到了这种地步：连研究本身的性质都不能提及。","sourceParagraphIndex":0,"sourceSentenceIndex":8,"sourceType":"textbook-passage"},{"phrase":"for fear","matchedForm":"for fear","meaning":"唯恐；生怕","note":"后可接 that 从句；原文省略 that，并用 should 表示所担心的可能。","example":"Many firms, for instance, have great difficulty in obtaining technical or scientific books from libraries because they are unwilling to have their names entered as having taken out such and such a book, for fear the agents of other firms should be able to trace the kind of research they are likely to be undertaking.","exampleZh":"例如，许多公司从图书馆借取技术或科学书籍都非常困难，因为它们不愿留下借过某某书的公司名称记录，唯恐其他公司的探子据此追查出它们可能正在进行哪类研究。","sourceParagraphIndex":0,"sourceSentenceIndex":9,"sourceType":"textbook-passage"},{"phrase":"not at all","matchedForm":"at all","meaning":"根本不；丝毫不","note":"at all 在否定句中加强否定；本句由 never 提供否定，意为从来不申请专利。","example":"Even more processes are never patented at all but kept as secret processes.","exampleZh":"还有更多工艺根本不申请专利，而是作为秘密工艺保留下来。","sourceParagraphIndex":0,"sourceSentenceIndex":6,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l016","book":4,"number":16,"title":"The modern city","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"In the organization of industrial life the influence of the factory upon the physiological and mental state of the workers has been completely neglected.","zh":"在组织工业生活时，工厂对工人生理与心理状态的影响一直完全遭到忽视。","kind":"narration","speaker":"旁白"},{"en":"Modern industry is based on the conception of the maximum production at lowest cost, in order that an individual or a group of individuals may earn as much money as possible.","zh":"现代工业立足于以最低成本获得最大产量的观念，目的是让个人或某个群体赚到尽可能多的钱。","kind":"narration","speaker":"旁白"},{"en":"It has expanded without any idea of the true nature of the human beings who run the machines, and without giving any consideration to the effects produced on the individuals and on their descendants by the artificial mode of existence imposed by the factory.","zh":"它的发展既没有认识操作机器者的真实人性，也完全没有考虑工厂强加的这种人为生活方式，会对个人及其后代产生什么影响。","kind":"narration","speaker":"旁白"},{"en":"The great cities have been built with no regard for us.","zh":"大城市的建造丝毫没有顾及我们。","kind":"narration","speaker":"旁白"},{"en":"The shape and dimensions of the skyscrapers depend entirely on the necessity of obtaining the maximum income per square foot of ground, and of offering to the tenants offices and apartments that please them.","zh":"摩天楼的形状和尺寸，完全取决于两种需要：让每平方英尺土地带来最大收入，以及为租户提供使他们满意的办公室和公寓。","kind":"narration","speaker":"旁白"},{"en":"This caused the construction of gigantic buildings where too large masses of human beings are crowded together.","zh":"这就造成了庞大建筑的兴建，里面挤着过于密集的人群。","kind":"narration","speaker":"旁白"},{"en":"Civilized men like such a way of living.","zh":"文明社会的人们喜欢这样的生活方式。","kind":"narration","speaker":"旁白"},{"en":"While they enjoy the comfort and banal luxury of their dwelling, they do not realize that they are deprived of the necessities of life.","zh":"他们享受住所的舒适和庸俗的奢华，却没有意识到自己被剥夺了生活中必不可少的东西。","kind":"narration","speaker":"旁白"},{"en":"The modern city consists of monstrous edifices and of dark, narrow streets full of petrol fumes and toxic gases, torn by the noise of the taxicabs, lorries and buses, and thronged ceaselessly by great crowds.","zh":"现代城市由巨兽般的建筑物和阴暗狭窄的街道构成；街上充满汽油烟气和有毒气体，出租车、卡车和公共汽车的噪声刺耳不断，拥挤的人潮川流不息。","kind":"narration","speaker":"旁白"},{"en":"Obviously, it has not been planned for the good of its inhabitants.","zh":"显然，这样的城市并非为居民的福祉而规划。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"be based on","matchedForm":"is based on","meaning":"以……为基础","note":"常用被动结构，指出制度、观点或行动的依据。","example":"Modern industry is based on the conception of the maximum production at lowest cost, in order that an individual or a group of individuals may earn as much money as possible.","exampleZh":"现代工业立足于以最低成本获得最大产量的观念，目的是让个人或某个群体赚到尽可能多的钱。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"with no regard for","matchedForm":"with no regard for","meaning":"丝毫不顾及","note":"regard for 表示对某人或其利益的重视；no 加强否定。","example":"The great cities have been built with no regard for us.","exampleZh":"大城市的建造丝毫没有顾及我们。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"be deprived of","matchedForm":"are deprived of","meaning":"被剥夺","note":"deprive someone of something 的被动式，of 后接被夺去的东西。","example":"While they enjoy the comfort and banal luxury of their dwelling, they do not realize that they are deprived of the necessities of life.","exampleZh":"他们享受住所的舒适和庸俗的奢华，却没有意识到自己被剥夺了生活中必不可少的东西。","sourceParagraphIndex":0,"sourceSentenceIndex":7,"sourceType":"textbook-passage"},{"phrase":"consist of","matchedForm":"consists of","meaning":"由……组成","note":"主语是整体，of 后列出组成部分，一般不用被动语态。","example":"The modern city consists of monstrous edifices and of dark, narrow streets full of petrol fumes and toxic gases, torn by the noise of the taxicabs, lorries and buses, and thronged ceaselessly by great crowds.","exampleZh":"现代城市由巨兽般的建筑物和阴暗狭窄的街道构成；街上充满汽油烟气和有毒气体，出租车、卡车和公共汽车的噪声刺耳不断，拥挤的人潮川流不息。","sourceParagraphIndex":0,"sourceSentenceIndex":8,"sourceType":"textbook-passage"},{"phrase":"for the good of","matchedForm":"for the good of","meaning":"为了……的利益","note":"good 在此作名词，表示福祉或益处。","example":"Obviously, it has not been planned for the good of its inhabitants.","exampleZh":"显然，这样的城市并非为居民的福祉而规划。","sourceParagraphIndex":0,"sourceSentenceIndex":9,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l017","book":4,"number":17,"title":"A man-made disease","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"In the early days of the settlement of Australia, enterprising settlers unwisely introduced the European rabbit.","zh":"在澳大利亚殖民定居的早期，有些富于进取心的定居者做了一件不明智的事：引进欧洲兔。","kind":"narration","speaker":"旁白"},{"en":"This rabbit had no natural enemies in the Antipodes, so that it multiplied with that promiscuous abandon characteristic of rabbits.","zh":"这种兔子在南半球这片土地上没有天敌，便以兔类特有的那种毫无节制的滥交方式大肆繁殖。","kind":"narration","speaker":"旁白"},{"en":"It overran a whole continent.","zh":"它们泛滥了整个大陆。","kind":"narration","speaker":"旁白"},{"en":"It caused devastation by burrowing and by devouring the herbage which might have maintained millions of sheep and cattle.","zh":"它们挖洞，又吃掉本可养活数百万只牛羊的牧草，造成严重破坏。","kind":"narration","speaker":"旁白"},{"en":"Scientists discovered that this particular variety of rabbit (and apparently no other animal) was susceptible to a fatal virus disease, myxomatosis.","zh":"科学家发现，这一种兔子——而且看来没有别的动物——很容易感染一种致命的病毒病：黏液瘤病。","kind":"narration","speaker":"旁白"},{"en":"By infecting animals and letting them loose in the burrows, local epidemics of this disease could be created.","zh":"把动物感染后放入兔穴，就能在局部造成这种疾病的流行。","kind":"narration","speaker":"旁白"},{"en":"Later it was found that there was a type of mosquito which acted as the carrier of this disease and passed it on to the rabbits.","zh":"后来人们发现，有一种蚊子能携带这种病，并把它传给兔子。","kind":"narration","speaker":"旁白"},{"en":"So while the rest of the world was trying to get rid of mosquitoes, Australia was encouraging this one.","zh":"于是，世界其他地方都在努力消灭蚊子时，澳大利亚却在鼓励这种蚊子繁殖。","kind":"narration","speaker":"旁白"},{"en":"It effectively spread the disease all over the continent and drastically reduced the rabbit population.","zh":"它有效地把疾病传播到整个大陆，使兔子的数量大幅减少。","kind":"narration","speaker":"旁白"},{"en":"It later became apparent that rabbits were developing a degree of resistance to this disease, so that the rabbit population was unlikely to be completely exterminated.","zh":"后来，人们逐渐发现兔子正在对这种病产生一定抵抗力，因此不大可能把兔群彻底消灭。","kind":"narration","speaker":"旁白"},{"en":"There were hopes, however, that the problem of the rabbit would become manageable.","zh":"不过，人们仍希望兔患能变得可控制。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Ironically, Europe, which had bequeathed the rabbit as a pest to Australia, acquired this man-made disease as a pestilence.","zh":"具有讽刺意味的是，原先把兔子这一祸害送给澳大利亚的欧洲，自己却遭受了这种人为传播疾病的瘟疫之灾。","kind":"narration","speaker":"旁白"},{"en":"A French physician decided to get rid of the wild rabbits on his own estate and introduced myxomatosis.","zh":"一位法国医生决定清除自己庄园上的野兔，便引入了黏液瘤病。","kind":"narration","speaker":"旁白"},{"en":"It did not, however, remain within the confines of his estate.","zh":"然而，疾病并没有局限在他的庄园之内。","kind":"narration","speaker":"旁白"},{"en":"It spread through France, where wild rabbits are not generally regarded as a pest but as a sport and a useful food supply, and it spread to Britain where wild rabbits are regarded as a pest but where domesticated rabbits, equally susceptible to the disease, are the basis of a profitable fur industry.","zh":"它蔓延到法国各地；在那里，野兔一般不被看作害兽，而被视为狩猎对象和一种有用的食物来源；疾病还传到了英国，那里虽把野兔视为害兽，但同样容易染病的家兔却是利润可观的毛皮业的基础。","kind":"narration","speaker":"旁白"},{"en":"The question became one of whether Man could control the disease he had invented.","zh":"问题于是变成：人类究竟能不能控制自己制造出来的疾病。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"be susceptible to","matchedForm":"was susceptible to","meaning":"易受……感染","note":"to 为介词，可接疾病或影响；此处讲动物对病毒病的易感性。","example":"Scientists discovered that this particular variety of rabbit (and apparently no other animal) was susceptible to a fatal virus disease, myxomatosis.","exampleZh":"科学家发现，这一种兔子——而且看来没有别的动物——很容易感染一种致命的病毒病：黏液瘤病。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"let loose","matchedForm":"letting them loose","meaning":"放开；释放","note":"let 后接宾语和形容词 loose；此处指放回兔穴。","example":"By infecting animals and letting them loose in the burrows, local epidemics of this disease could be created.","exampleZh":"把动物感染后放入兔穴，就能在局部造成这种疾病的流行。","sourceParagraphIndex":0,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"pass on to","matchedForm":"passed it on to","meaning":"把……传给","note":"代词宾语放在 pass 与 on 之间；此处传递的是疾病。","example":"Later it was found that there was a type of mosquito which acted as the carrier of this disease and passed it on to the rabbits.","exampleZh":"后来人们发现，有一种蚊子能携带这种病，并把它传给兔子。","sourceParagraphIndex":0,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"get rid of","matchedForm":"get rid of","meaning":"清除；摆脱","note":"后接不想保留的人或事物，此处表示消灭蚊子。","example":"So while the rest of the world was trying to get rid of mosquitoes, Australia was encouraging this one.","exampleZh":"于是，世界其他地方都在努力消灭蚊子时，澳大利亚却在鼓励这种蚊子繁殖。","sourceParagraphIndex":0,"sourceSentenceIndex":7,"sourceType":"textbook-passage"},{"phrase":"within the confines of","matchedForm":"within the confines of","meaning":"在……范围之内","note":"confines 常用复数，指界限；可描述具体疆界或抽象范围。","example":"It did not, however, remain within the confines of his estate.","exampleZh":"然而，疾病并没有局限在他的庄园之内。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l018","book":4,"number":18,"title":"Porpoises","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"There has long been a superstition among mariners that porpoises will save drowning men by pushing them to the surface, or protect them from sharks by surrounding them in defensive formation.","zh":"水手们长期以来有一种迷信，认为鼠海豚会把溺水的人推到水面上救活，或围成防御阵形，保护他们免受鲨鱼袭击。","kind":"narration","speaker":"旁白"},{"en":"Marine Studio biologists have pointed out that, however intelligent they may be, it is probably a mistake to credit dolphins with any motive of lifesaving.","zh":"海洋摄影场的生物学家指出，不管海豚多么聪明，认为它们具有救人的动机，大概都是误解。","kind":"narration","speaker":"旁白"},{"en":"On the occasions when they have pushed to shore an unconscious human being they have much more likely done it out of curiosity or for sport, as in riding the bow waves of a ship.","zh":"它们有时把失去知觉的人推到岸边，更可能是出于好奇或为了玩耍，就像它们追逐船首的波浪一样。","kind":"narration","speaker":"旁白"},{"en":"In 1928 some porpoises were photographed working like beavers to push ashore a waterlogged mattress.","zh":"一九二八年，有人拍到几只鼠海豚拼命把一张浸透水的床垫推上岸。","kind":"narration","speaker":"旁白"},{"en":"If, as has been reported, they have protected humans from sharks, it may have been because curiosity attracted them and because the scent of a possible meal attracted the sharks.","zh":"如果它们确实像报道所说的那样保护过人类，使人免遭鲨鱼袭击，那么可能是好奇心吸引了它们，而潜在猎物的气味又引来了鲨鱼。","kind":"narration","speaker":"旁白"},{"en":"Porpoises and sharks are natural enemies.","zh":"鼠海豚和鲨鱼是天敌。","kind":"narration","speaker":"旁白"},{"en":"It is possible that upon such an occasion a battle ensued, with the sharks being driven away or killed.","zh":"在这种场合下，也许发生了一场搏斗，鲨鱼被赶走或杀死了。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Whether it be bird, fish or beast, the porpoise is intrigued with anything that is alive.","zh":"不论是鸟、鱼还是兽，鼠海豚对任何活物都感兴趣。","kind":"narration","speaker":"旁白"},{"en":"They are constantly after the turtles, who peacefully submit to all sorts of indignities.","zh":"它们总是追着海龟不放，而海龟对各种欺负都温顺地忍受。","kind":"narration","speaker":"旁白"},{"en":"One young calf especially enjoyed raising a turtle to the surface with his snout and then shoving him across the tank like an aquaplane.","zh":"一只幼豚尤其喜欢用吻部把海龟顶到水面，然后像推滑水板一样推着它横过水池。","kind":"narration","speaker":"旁白"},{"en":"Almost any day a young porpoise may be seen trying to turn a 300-pound sea turtle over by sticking his snout under the edge of his shell and pushing up for dear life.","zh":"几乎每天都能看到幼豚把吻部伸到一只三百磅重的海龟的甲壳边缘下面，拼命往上顶，想把海龟翻过来。","kind":"narration","speaker":"旁白"},{"en":"This is not easy, and may require two porpoises working together.","zh":"这并不容易，可能需要两只鼠海豚一起干。","kind":"narration","speaker":"旁白"},{"en":"In another game, as the turtle swims across the oceanarium, the first porpoise swoops down from above and butts his shell with his belly.","zh":"另一种游戏是，海龟游过海洋水族馆的水池时，第一只鼠海豚从上方向下猛冲，用肚子撞它的甲壳。","kind":"narration","speaker":"旁白"},{"en":"This knocks the turtle down several feet.","zh":"这一撞就把海龟撞沉好几英尺。","kind":"narration","speaker":"旁白"},{"en":"He no sooner recovers his equilibrium than the next porpoise comes along and hits him another crack.","zh":"它刚刚恢复平衡，下一只鼠海豚就过来再撞它一下。","kind":"narration","speaker":"旁白"},{"en":"Eventually the turtle has been butted all the way down to the floor of the tank.","zh":"最后，海龟就这样一路被撞到池底。","kind":"narration","speaker":"旁白"},{"en":"He is now satisfied merely to try to stand up, but as soon as he does so a porpoise knocks him flat.","zh":"这时它只求能站起来，但它一站起来，就有一只鼠海豚把它撞得平躺下去。","kind":"narration","speaker":"旁白"},{"en":"The turtle at last gives up by pulling his feet under his shell and the game is over.","zh":"海龟终于把脚缩进甲壳，认了输，游戏也就结束了。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"credit with","matchedForm":"credit dolphins with","meaning":"认为……具有","note":"credit someone with a quality/motive 是把某种品质或动机归于某人。","example":"Marine Studio biologists have pointed out that, however intelligent they may be, it is probably a mistake to credit dolphins with any motive of lifesaving.","exampleZh":"海洋摄影场的生物学家指出，不管海豚多么聪明，认为它们具有救人的动机，大概都是误解。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"out of curiosity","matchedForm":"out of curiosity","meaning":"出于好奇","note":"out of 加感情或动机名词，说明行为的驱动力。","example":"On the occasions when they have pushed to shore an unconscious human being they have much more likely done it out of curiosity or for sport, as in riding the bow waves of a ship.","exampleZh":"它们有时把失去知觉的人推到岸边，更可能是出于好奇或为了玩耍，就像它们追逐船首的波浪一样。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"submit to","matchedForm":"submit to","meaning":"忍受；屈从于","note":"to 为介词，后接不得不接受的待遇、权威等。","example":"They are constantly after the turtles, who peacefully submit to all sorts of indignities.","exampleZh":"它们总是追着海龟不放，而海龟对各种欺负都温顺地忍受。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"for dear life","matchedForm":"for dear life","meaning":"拼命地","note":"表示用尽力气，未必真的处在生命危险之中。","example":"Almost any day a young porpoise may be seen trying to turn a 300-pound sea turtle over by sticking his snout under the edge of his shell and pushing up for dear life.","exampleZh":"几乎每天都能看到幼豚把吻部伸到一只三百磅重的海龟的甲壳边缘下面，拼命往上顶，想把海龟翻过来。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"no sooner ... than","matchedForm":"no sooner recovers his equilibrium than","meaning":"刚……就……","note":"用于强调两事紧接着发生；no sooner 放句首时通常需要倒装。","example":"He no sooner recovers his equilibrium than the next porpoise comes along and hits him another crack.","exampleZh":"它刚刚恢复平衡，下一只鼠海豚就过来再撞它一下。","sourceParagraphIndex":1,"sourceSentenceIndex":7,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l019","book":4,"number":19,"title":"The stuff of dreams","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"It is fairly clear that the sleeping period must have some function, and because there is so much of it the function would seem to be important.","zh":"睡眠这段时间必定有某种功能，这一点相当清楚；而且它占据的时间如此之多，这种功能似乎应当很重要。","kind":"narration","speaker":"旁白"},{"en":"Speculations about its nature have been going on for literally thousands of years, and one odd finding that makes the problem puzzling is that it looks very much as if sleeping is not simply a matter of giving the body a rest.","zh":"关于它究竟有何功能，人们确实已猜测了数千年；有一个奇特的发现使问题令人困惑：睡眠看来很可能不只是让身体休息那么简单。","kind":"narration","speaker":"旁白"},{"en":"‘Rest’, in terms of muscle relaxation and so on, can be achieved by a brief period lying, or even sitting down.","zh":"从肌肉放松等意义上说，只要躺一小会儿，甚至坐一会儿，就能得到“休息”。","kind":"narration","speaker":"旁白"},{"en":"The body's tissues are self-repairing and self-restoring to a degree, and function best when more or less continuously active.","zh":"身体组织在一定程度上能自行修复、自行恢复，而且在差不多持续活动时运转得最好。","kind":"narration","speaker":"旁白"},{"en":"In fact a basic amount of movement occurs during sleep which is specifically concerned with preventing muscle inactivity.","zh":"事实上，睡眠中也存在一定的基本活动，这些活动正是为了防止肌肉处于不活动的状态。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"If it is not a question of resting the body, then perhaps it is the brain that needs resting?","zh":"如果睡眠不是为了让身体休息，那么也许是大脑需要休息？","kind":"narration","speaker":"旁白"},{"en":"This might be a plausible hypothesis were it not for two factors.","zh":"若非有两个因素，这倒可能是个说得通的假说。","kind":"narration","speaker":"旁白"},{"en":"First the electroencephalograph (which is simply a device for recording the electrical activity of the brain by attaching electrodes to the scalp) shows that while there is a change in the pattern of activity during sleep, there is no evidence that the total amount of activity is any less.","zh":"首先，脑电图仪——不过是一种把电极贴在头皮上来记录脑部电活动的装置——表明，睡眠时脑部活动的模式虽然有变化，却没有证据说明其活动总量有所减少。","kind":"narration","speaker":"旁白"},{"en":"The second factor is more interesting and more fundamental.","zh":"第二个因素更有趣，也更根本。","kind":"narration","speaker":"旁白"},{"en":"Some years ago an American psychiatrist named William Dement published experiments dealing with the recording of eye-movements during sleep.","zh":"几年前，一位名叫威廉·德门特的美国精神科医生公布了一些记录睡眠期间眼球运动的实验。","kind":"narration","speaker":"旁白"},{"en":"He showed that the average individual's sleep cycle is punctuated with peculiar bursts of eye-movements, some drifting and slow, others jerky and rapid.","zh":"他证明，一般人的睡眠周期会不时插入一阵阵奇特的眼球运动，有的缓慢游移，有的急促跳动。","kind":"narration","speaker":"旁白"},{"en":"People woken during these periods of eye-movements generally reported that they had been dreaming.","zh":"在这些眼球运动时段被叫醒的人，通常报告说自己刚才正在做梦。","kind":"narration","speaker":"旁白"},{"en":"When woken at other times they reported no dreams.","zh":"在其他时间被叫醒的人则报告说没有做梦。","kind":"narration","speaker":"旁白"},{"en":"If one group of people were disturbed from their eye-movement sleep for several nights on end, and another group were disturbed for an equal period of time but when they were not exhibiting eye-movements, the first group began to show some personality disorders while the others seemed more or less unaffected.","zh":"如果连续几个晚上都在一组人出现眼球运动的睡眠阶段干扰他们，而对另一组人也干扰同样长的时间，却选在他们没有眼球运动时进行，那么第一组人就开始出现某些人格方面的失常，另一组人则似乎大体不受影响。","kind":"narration","speaker":"旁白"},{"en":"The implications of all this were that it was not the disturbance of sleep that mattered, but the disturbance of dreaming.","zh":"这一切所暗示的是，真正要紧的不是睡眠受到干扰，而是做梦受到干扰。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"a matter of","matchedForm":"a matter of","meaning":"是……的问题","note":"a matter of 后接名词或动名词，用于界定事情的性质。","example":"Speculations about its nature have been going on for literally thousands of years, and one odd finding that makes the problem puzzling is that it looks very much as if sleeping is not simply a matter of giving the body a rest.","exampleZh":"关于它究竟有何功能，人们确实已猜测了数千年；有一个奇特的发现使问题令人困惑：睡眠看来很可能不只是让身体休息那么简单。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"in terms of","matchedForm":"in terms of","meaning":"从……方面来说","note":"用来说明衡量或理解事物的角度。","example":"‘Rest’, in terms of muscle relaxation and so on, can be achieved by a brief period lying, or even sitting down.","exampleZh":"从肌肉放松等意义上说，只要躺一小会儿，甚至坐一会儿，就能得到“休息”。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"to a degree","matchedForm":"to a degree","meaning":"在一定程度上","note":"限制判断的强度，避免被理解为完全如此。","example":"The body's tissues are self-repairing and self-restoring to a degree, and function best when more or less continuously active.","exampleZh":"身体组织在一定程度上能自行修复、自行恢复，而且在差不多持续活动时运转得最好。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"were it not for","matchedForm":"were it not for","meaning":"要不是","note":"if it were not for 的倒装形式，表达与现实相反的假设。","example":"This might be a plausible hypothesis were it not for two factors.","exampleZh":"若非有两个因素，这倒可能是个说得通的假说。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"on end","matchedForm":"on end","meaning":"连续地","note":"接在时间段之后，如 several nights on end，强调不间断地持续。","example":"If one group of people were disturbed from their eye-movement sleep for several nights on end, and another group were disturbed for an equal period of time but when they were not exhibiting eye-movements, the first group began to show some personality disorders while the others seemed more or less unaffected.","exampleZh":"如果连续几个晚上都在一组人出现眼球运动的睡眠阶段干扰他们，而对另一组人也干扰同样长的时间，却选在他们没有眼球运动时进行，那么第一组人就开始出现某些人格方面的失常，另一组人则似乎大体不受影响。","sourceParagraphIndex":1,"sourceSentenceIndex":8,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l020","book":4,"number":20,"title":"Snake poison","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"How it came about that snakes manufactured poison is a mystery.","zh":"蛇究竟是怎样产生毒液的，至今是个谜。","kind":"narration","speaker":"旁白"},{"en":"Over the periods their saliva, a mild, digestive juice like our own, was converted into a poison that defies analysis even today.","zh":"在漫长岁月中，它们原本像我们的唾液一样温和、用于消化的唾液，变成了一种直到今天仍难以分析清楚的毒液。","kind":"narration","speaker":"旁白"},{"en":"It was not forced upon them by the survival competition; they could have caught and lived on prey without using poison, just as the thousands of non-poisonous snakes still do.","zh":"这并不是生存竞争逼迫它们获得的本领；它们本来完全可以不用毒液就捕获猎物并以之为生，正如成千上万条无毒蛇如今仍在做的那样。","kind":"narration","speaker":"旁白"},{"en":"Poison to a snake is merely a luxury; it enables it to get its food with very little effort, no more effort than one bite.","zh":"对蛇来说，毒液不过是一件奢侈品；它使蛇几乎不费力就能获得食物，所费的力气不过是咬上一口。","kind":"narration","speaker":"旁白"},{"en":"And why only snakes?","zh":"而为什么偏偏只有蛇呢？","kind":"narration","speaker":"旁白"},{"en":"Cats, for instance, would be greatly helped; no running fights with large, fierce rats or tussles with grown rabbits—just a bite and no more effort needed.","zh":"例如，猫若有毒液会大为受益；不必边跑边与凶猛的大老鼠搏斗，也不必跟成年兔子厮打，只需咬一口，再不必费劲。","kind":"narration","speaker":"旁白"},{"en":"In fact, it would be an assistance to all carnivores though it would be a two-edged weapon when they fought each other.","zh":"事实上，所有食肉动物若有毒液都会受益，不过它们互相争斗时，这又会成为一件双刃武器。","kind":"narration","speaker":"旁白"},{"en":"But, of the vertebrates, unpredictable Nature selected only snakes (and one lizard).","zh":"但在脊椎动物中，变幻莫测的大自然偏偏只选择了蛇（还有一种蜥蜴）。","kind":"narration","speaker":"旁白"},{"en":"One wonders also why Nature, with some snakes, concocted poison of such extreme potency.","zh":"人们也不禁奇怪，大自然为什么在某些蛇身上调制出了如此剧烈的毒液。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"In the conversion of saliva into poison, one might suppose that a fixed process took place.","zh":"人们可能以为，唾液转变为毒液遵循的是某种固定过程。","kind":"narration","speaker":"旁白"},{"en":"It did not; some snakes manufactured a poison different in every respect from that of others, as different as arsenic is from strychnine, and having different effects.","zh":"其实不然；有些蛇产生的毒液与其他蛇的毒液在各方面都不同，就像砒霜和士的宁截然不同一样，其作用也不同。","kind":"narration","speaker":"旁白"},{"en":"One poison acts on the nerves, the other on the blood.","zh":"一种毒液作用于神经，另一种则作用于血液。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"The makers of the nerve poison include the mambas and the cobras and their venom is called neurotoxic.","zh":"产生神经毒液的蛇包括曼巴蛇和眼镜蛇，它们的毒液称为神经毒素。","kind":"narration","speaker":"旁白"},{"en":"Vipers (adders) and rattlesnakes manufacture the blood poison, which is known as haemolytic.","zh":"蝰蛇（蝮蛇）和响尾蛇产生的是血液毒液，称为溶血性毒液。","kind":"narration","speaker":"旁白"},{"en":"Both poisons are unpleasant, but by far the more unpleasant is the blood poison.","zh":"两种毒液都令人难受，但血液毒液要可怕得多。","kind":"narration","speaker":"旁白"},{"en":"It is said that the nerve poison is the more primitive of the two, that the blood poison is, so to speak, a newer product from an improved formula.","zh":"据说两者之中神经毒液比较原始，而血液毒液可以说是一种采用改良配方制出的较新产品。","kind":"narration","speaker":"旁白"},{"en":"Be that as it may, the nerve poison does its business with man far more quickly than the blood poison.","zh":"不论事实如何，神经毒液在人身上发挥作用，比血液毒液快得多。","kind":"narration","speaker":"旁白"},{"en":"This, however, means nothing.","zh":"不过，这一点并不能说明什么。","kind":"narration","speaker":"旁白"},{"en":"Snakes did not acquire their poison for use against man but for use against prey such as rats and mice, and the effects on these of viperine poison is almost immediate.","zh":"蛇获得毒液并不是为了对付人，而是为了对付大鼠、小鼠之类的猎物；蝰蛇毒液对这些动物几乎立刻就会起作用。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"come about","matchedForm":"came about","meaning":"发生；产生","note":"常问 how something came about，探究某种结果如何形成。","example":"How it came about that snakes manufactured poison is a mystery.","exampleZh":"蛇究竟是怎样产生毒液的，至今是个谜。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"live on","matchedForm":"lived on","meaning":"靠……为生","note":"on 后接食物或生活来源；此处不是继续活下去之意。","example":"It was not forced upon them by the survival competition; they could have caught and lived on prey without using poison, just as the thousands of non-poisonous snakes still do.","exampleZh":"这并不是生存竞争逼迫它们获得的本领；它们本来完全可以不用毒液就捕获猎物并以之为生，正如成千上万条无毒蛇如今仍在做的那样。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"in every respect","matchedForm":"in every respect","meaning":"在各个方面","note":"respect 在此指方面，常与 different、similar 等形容词搭配。","example":"It did not; some snakes manufactured a poison different in every respect from that of others, as different as arsenic is from strychnine, and having different effects.","exampleZh":"其实不然；有些蛇产生的毒液与其他蛇的毒液在各方面都不同，就像砒霜和士的宁截然不同一样，其作用也不同。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"so to speak","matchedForm":"so to speak","meaning":"可以说；打个比方说","note":"标示接下来的措辞并非严格字面意义，常用于比喻。","example":"It is said that the nerve poison is the more primitive of the two, that the blood poison is, so to speak, a newer product from an improved formula.","exampleZh":"据说两者之中神经毒液比较原始，而血液毒液可以说是一种采用改良配方制出的较新产品。","sourceParagraphIndex":2,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"be that as it may","matchedForm":"Be that as it may","meaning":"即便如此；不论事实如何","note":"让步性的固定说法，表示暂不争论前述说法，转谈另一点。","example":"Be that as it may, the nerve poison does its business with man far more quickly than the blood poison.","exampleZh":"不论事实如何，神经毒液在人身上发挥作用，比血液毒液快得多。","sourceParagraphIndex":2,"sourceSentenceIndex":4,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l021","book":4,"number":21,"title":"William S. Hart and the early ‘Western’ film","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"William S. Hart was, perhaps, the greatest of all Western stars, for unlike Gary Cooper and John Wayne he appeared in nothing but Westerns.","zh":"威廉·S.哈特也许是所有西部片明星中最杰出的一位，因为他与加里·库珀和约翰·韦恩不同，出演的全都是西部片。","kind":"narration","speaker":"旁白"},{"en":"From 1914 to 1924 he was supreme and unchallenged.","zh":"从一九一四年到一九二四年，他的地位至高无上，无人能挑战。","kind":"narration","speaker":"旁白"},{"en":"It was Hart who created the basic formula of the Western film, and devised the protagonist he played in every film he made, the good-bad man, the accidental-noble outlaw, or the honest-but-framed cowboy, or the sheriff made suspect by vicious gossip; in short, the individual in conflict with himself and his frontier environment.","zh":"正是哈特创造了西部片的基本模式，并设计出他在自己每一部影片中扮演的主角：亦正亦邪的人物、本性高尚却因意外境遇沦为逃犯的人、诚实却遭人陷害的牛仔，或因恶毒流言而受到怀疑的治安官；总之，是一个既与自己冲突、又与边疆环境冲突的人。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Unlike most of his contemporaries in Hollywood, Hart actually knew something of the old West.","zh":"哈特与好莱坞同时代的大多数人不同，他确实了解一些昔日的西部。","kind":"narration","speaker":"旁白"},{"en":"He had lived in it as a child when it was already disappearing, and his hero was firmly rooted in his memories and experiences, and in both the history and the mythology of the vanished frontier.","zh":"他小时候曾住在那里，而那时旧西部就已经在消失；他塑造的英雄牢牢扎根于自己的记忆和经历，也扎根于那片已经消逝的边疆的历史和传说。","kind":"narration","speaker":"旁白"},{"en":"And although no period or place in American history has been more absurdly romanticized, myth and reality did join hands in at least one arena, the conflict between the individual and encroaching civilization.","zh":"美国历史上没有哪个时代、哪个地方曾被如此荒唐地浪漫化；然而，神话和现实至少在一个领域确实携起了手，那就是个人与不断推进的文明之间的冲突。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"Men accustomed to struggling for survival against the elements and Indians were bewildered by politicians, bankers and businessmen, and unhorsed by fences, laws and alien taboos.","zh":"那些习惯于同自然力量和印第安人搏斗以求生存的男子，面对政客、银行家和商人却感到茫然，又被围栏、法律和陌生的禁忌打落马下。","kind":"narration","speaker":"旁白"},{"en":"Hart’s good-bad man was always an outsider, always one of the disinherited, and if he found it necessary to shoot a sheriff or rob a bank along the way, his early audiences found it easy to understand and forgive, especially when it was Hart who, in the end, overcame the attacking Indians.","zh":"哈特扮演的亦正亦邪者总是局外人，总是被剥夺了应有权利的那群人之一；如果他一路上觉得非枪杀一个治安官或抢劫一家银行不可，早期观众也很容易理解并宽恕他，尤其是当最终击退来袭印第安人的正是哈特时。","kind":"narration","speaker":"旁白"}]},{"index":3,"rows":[{"en":"Audiences in the second decade of the twentieth century found it pleasant to escape to a time when life, though hard, was relatively simple.","zh":"二十世纪第二个十年间的观众，觉得逃回那个生活虽苦却相对简单的时代，是一种享受。","kind":"narration","speaker":"旁白"},{"en":"We still do; living in a world in which undeclared aggression, war, hypocrisy, chicanery, anarchy and impending immolation are part of our daily lives, we all want a code to live by.","zh":"我们现在仍然如此；在我们生活的世界里，不宣而行的侵略、战争、虚伪、欺诈、无政府状态和迫近的毁灭，已是日常生活的一部分，所以我们都想要一套可以遵循的行为准则。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"nothing but","matchedForm":"nothing but","meaning":"只有；全是","note":"常表示仅限某类事物，此处强调他只演西部片。","example":"William S. Hart was, perhaps, the greatest of all Western stars, for unlike Gary Cooper and John Wayne he appeared in nothing but Westerns.","exampleZh":"威廉·S.哈特也许是所有西部片明星中最杰出的一位，因为他与加里·库珀和约翰·韦恩不同，出演的全都是西部片。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"in conflict with","matchedForm":"in conflict with","meaning":"与……冲突","note":"既可指内心矛盾，也可指与外界不相容。","example":"It was Hart who created the basic formula of the Western film, and devised the protagonist he played in every film he made, the good-bad man, the accidental-noble outlaw, or the honest-but-framed cowboy, or the sheriff made suspect by vicious gossip; in short, the individual in conflict with himself and his frontier environment.","exampleZh":"正是哈特创造了西部片的基本模式，并设计出他在自己每一部影片中扮演的主角：亦正亦邪的人物、本性高尚却因意外境遇沦为逃犯的人、诚实却遭人陷害的牛仔，或因恶毒流言而受到怀疑的治安官；总之，是一个既与自己冲突、又与边疆环境冲突的人。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"be rooted in","matchedForm":"was firmly rooted in","meaning":"根植于","note":"用于说明观点、形象等产生的根源；firmly 加强其稳固程度。","example":"He had lived in it as a child when it was already disappearing, and his hero was firmly rooted in his memories and experiences, and in both the history and the mythology of the vanished frontier.","exampleZh":"他小时候曾住在那里，而那时旧西部就已经在消失；他塑造的英雄牢牢扎根于自己的记忆和经历，也扎根于那片已经消逝的边疆的历史和传说。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"join hands","matchedForm":"join hands","meaning":"携手；相互结合","note":"可指合作，此处比喻神话与现实在同一主题上重合。","example":"And although no period or place in American history has been more absurdly romanticized, myth and reality did join hands in at least one arena, the conflict between the individual and encroaching civilization.","exampleZh":"美国历史上没有哪个时代、哪个地方曾被如此荒唐地浪漫化；然而，神话和现实至少在一个领域确实携起了手，那就是个人与不断推进的文明之间的冲突。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"live by","matchedForm":"live by","meaning":"依照……生活","note":"by 在此表示遵循，a code to live by 即供人生遵守的准则。","example":"We still do; living in a world in which undeclared aggression, war, hypocrisy, chicanery, anarchy and impending immolation are part of our daily lives, we all want a code to live by.","exampleZh":"我们现在仍然如此；在我们生活的世界里，不宣而行的侵略、战争、虚伪、欺诈、无政府状态和迫近的毁灭，已是日常生活的一部分，所以我们都想要一套可以遵循的行为准则。","sourceParagraphIndex":3,"sourceSentenceIndex":1,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l022","book":4,"number":22,"title":"Knowledge and progress","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Why does the idea of progress loom so large in the modern world?","zh":"为什么进步的观念在现代世界中占据如此突出的位置？","kind":"narration","speaker":"旁白"},{"en":"Surely because progress of a particular kind is actually taking place around us and is becoming more and more manifest.","zh":"无疑是因为，某一种进步确实正在我们周围发生，而且变得越来越明显。","kind":"narration","speaker":"旁白"},{"en":"Although mankind has undergone no general improvement in intelligence or morality, it has made extraordinary progress in the accumulation of knowledge.","zh":"人类的智力或道德虽然没有普遍提高，但在知识积累方面却取得了非凡的进展。","kind":"narration","speaker":"旁白"},{"en":"Knowledge began to increase as soon as the thoughts of one individual could be communicated to another by means of speech.","zh":"一旦个人的思想能够通过言语传递给他人，知识就开始增长了。","kind":"narration","speaker":"旁白"},{"en":"With the invention of writing, a great advance was made, for knowledge could then be not only communicated but also stored.","zh":"文字的发明带来了重大的进步，因为此后知识不仅能传播，还能储存。","kind":"narration","speaker":"旁白"},{"en":"Libraries made education possible, and education in its turn added to libraries: the growth of knowledge followed a kind of compound interest law, which was greatly enhanced by the invention of printing.","zh":"图书馆使教育成为可能，教育反过来又充实了图书馆：知识的增长遵循着某种复利规律，而印刷术的发明大大加强了这一过程。","kind":"narration","speaker":"旁白"},{"en":"All this was comparatively slow until, with the coming of science, the tempo was suddenly raised.","zh":"这一切原先都进展得比较缓慢，直到科学出现，步伐才突然加快。","kind":"narration","speaker":"旁白"},{"en":"Then knowledge began to be accumulated according to a systematic plan.","zh":"此后，知识开始按系统的计划积累起来。","kind":"narration","speaker":"旁白"},{"en":"The trickle became a stream; the stream has now become a torrent.","zh":"细流变成了溪流，而如今溪流又变成了洪流。","kind":"narration","speaker":"旁白"},{"en":"Moreover, as soon as new knowledge is acquired, it is now turned to practical account.","zh":"而且，现在新知识一旦获得，便立刻被用于实际。","kind":"narration","speaker":"旁白"},{"en":"What is called ‘modern civilization’ is not the result of a balanced development of all man’s nature, but of accumulated knowledge applied to practical life.","zh":"所谓“现代文明”，并不是人性各方面均衡发展的结果，而是积累的知识被应用于实际生活的结果。","kind":"narration","speaker":"旁白"},{"en":"The problem now facing humanity is: What is going to be done with all this knowledge?","zh":"人类如今面临的问题是：要拿这些知识做什么？","kind":"narration","speaker":"旁白"},{"en":"As is so often pointed out, knowledge is a two-edged weapon which can be used equally for good or evil.","zh":"正如人们常常指出的，知识是一件双刃武器，既能用于行善，也能用于作恶。","kind":"narration","speaker":"旁白"},{"en":"It is now being used indifferently for both.","zh":"如今，人们正不加区分地把它用于这两个方面。","kind":"narration","speaker":"旁白"},{"en":"Could any spectacle, for instance, be more grimly whimsical than that of gunners using science to shatter men’s bodies while, close at hand, surgeons use it to restore them?","zh":"譬如，炮手利用科学把人的身体炸得血肉横飞，而就在附近，外科医生却用科学来修复这些身体；还有什么景象能比这更残酷而荒诞吗？","kind":"narration","speaker":"旁白"},{"en":"We have to ask ourselves very seriously what will happen if this twofold use of knowledge, with its ever-increasing power, continues.","zh":"我们必须非常严肃地问自己：如果知识的力量不断增长，同时又继续被这样用于两个相反方面，将会发生什么？","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"loom large","matchedForm":"loom so large","meaning":"显得突出；占重要地位","note":"常用于问题或观念在思想、讨论中占很大分量的语境。","example":"Why does the idea of progress loom so large in the modern world?","exampleZh":"为什么进步的观念在现代世界中占据如此突出的位置？","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"in one’s turn","matchedForm":"in its turn","meaning":"反过来；轮到其发挥作用时","note":"强调前后事物相互促动，此处教育又促进馆藏增长。","example":"Libraries made education possible, and education in its turn added to libraries: the growth of knowledge followed a kind of compound interest law, which was greatly enhanced by the invention of printing.","exampleZh":"图书馆使教育成为可能，教育反过来又充实了图书馆：知识的增长遵循着某种复利规律，而印刷术的发明大大加强了这一过程。","sourceParagraphIndex":0,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"turn to account","matchedForm":"turned to practical account","meaning":"利用；使发挥效用","note":"turn something to account 表示把某物加以利用；practical 强调实际用途。","example":"Moreover, as soon as new knowledge is acquired, it is now turned to practical account.","exampleZh":"而且，现在新知识一旦获得，便立刻被用于实际。","sourceParagraphIndex":0,"sourceSentenceIndex":9,"sourceType":"textbook-passage"},{"phrase":"a two-edged weapon","matchedForm":"a two-edged weapon","meaning":"双刃武器","note":"比喻既可能有益也可能有害的事物，不能只理解为带来好处。","example":"As is so often pointed out, knowledge is a two-edged weapon which can be used equally for good or evil.","exampleZh":"正如人们常常指出的，知识是一件双刃武器，既能用于行善，也能用于作恶。","sourceParagraphIndex":0,"sourceSentenceIndex":12,"sourceType":"textbook-passage"},{"phrase":"close at hand","matchedForm":"close at hand","meaning":"就在附近","note":"at hand 可指空间上很近，也可指时间上即将到来；此处是地点。","example":"Could any spectacle, for instance, be more grimly whimsical than that of gunners using science to shatter men’s bodies while, close at hand, surgeons use it to restore them?","exampleZh":"譬如，炮手利用科学把人的身体炸得血肉横飞，而就在附近，外科医生却用科学来修复这些身体；还有什么景象能比这更残酷而荒诞吗？","sourceParagraphIndex":0,"sourceSentenceIndex":14,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l023","book":4,"number":23,"title":"Bird flight","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"No two sorts of birds practise quite the same sort of flight; the varieties are infinite; but two classes may be roughly seen.","zh":"没有哪两类鸟的飞行方式完全相同，变化可谓无穷；不过大致可以分为两类。","kind":"narration","speaker":"旁白"},{"en":"Any ship that crosses the Pacific is accompanied for many days by the smaller albatross, which may keep company with the vessel for an hour without visible or more than occasional movement of wing.","zh":"任何横渡太平洋的船，都会有体型较小的信天翁相伴多日；它可以跟着船飞一个小时，期间看不见它振翅，或至多偶尔振一下。","kind":"narration","speaker":"旁白"},{"en":"The currents of air that the walls of the ship direct upwards, as well as in the line of its course, are enough to give the great bird with its immense wings sufficient sustenance and progress.","zh":"船体两侧使气流向上、同时沿着航向流动，这些气流就足以给这只双翼巨大的大鸟提供充分的升力和前进动力。","kind":"narration","speaker":"旁白"},{"en":"The albatross is the king of the gliders, the class of fliers which harness the air to their purpose, but must yield to its opposition.","zh":"信天翁是滑翔鸟类之王；这一类飞行者利用空气来达到自己的目的，却必须在逆风面前让步。","kind":"narration","speaker":"旁白"},{"en":"In the contrary school, the duck is supreme.","zh":"在相反的另一派中，鸭子最出色。","kind":"narration","speaker":"旁白"},{"en":"It comes nearer to the engines with which man has ‘conquered’ the air, as he boasts.","zh":"它更接近人类自夸用来“征服”天空的那些发动机。","kind":"narration","speaker":"旁白"},{"en":"Duck, and like them the pigeons, are endowed with steel-like muscles, that are a good part of the weight of the bird, and these will ply the short wings with such irresistible power that they can bore for long distances through an opposing gale before exhaustion follows.","zh":"鸭子和与之相似的鸽子，都有钢铁般的肌肉，肌肉占了体重的相当一部分；这些肌肉以不可阻挡的力量振动短翼，使它们能顶着强劲逆风钻行很远之后，才感到疲惫。","kind":"narration","speaker":"旁白"},{"en":"Their humbler followers, such as partridges, have a like power of strong propulsion, but soon tire.","zh":"比它们稍逊一筹的同类，例如鹧鸪，也有类似的强劲推进力，不过很快就累了。","kind":"narration","speaker":"旁白"},{"en":"You may pick them up in utter exhaustion, if wind over the sea has driven them to a long journey.","zh":"如果海上的风逼着它们长途飞行，你便可能在它们精疲力尽时将其捡起来。","kind":"narration","speaker":"旁白"},{"en":"The swallow shares the virtues of both schools in highest measure.","zh":"燕子则把两派的优点发挥到了极致。","kind":"narration","speaker":"旁白"},{"en":"It tires not, nor does it boast of its power; but belongs to the air, travelling it may be six thousand miles to and from its northern nesting home, feeding its flown young as it flies, and slipping through a medium that seems to help its passage even when the wind is adverse.","zh":"它不会疲倦，也不炫耀自己的力量；它属于天空，往返北方筑巢地的旅程可能长达六千英里，一边飞一边喂养已经离巢的幼鸟，轻捷地穿过空气；即使风向相反，这种介质似乎也在助它前行。","kind":"narration","speaker":"旁白"},{"en":"Such birds do us good, though we no longer take omens from their flight on this side and that; and even the most superstitious villagers no longer take off their hats to the magpie and wish it good-morning.","zh":"这样的鸟使我们受益，尽管我们早已不再从它们忽而向这边、忽而向那边的飞行中占卜吉凶，就连最迷信的村民也不再向喜鹊脱帽，祝它早安了。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"keep company with","matchedForm":"keep company with","meaning":"陪伴；与……同行","note":"此处指信天翁跟随船只飞行，不只限于人的交往。","example":"Any ship that crosses the Pacific is accompanied for many days by the smaller albatross, which may keep company with the vessel for an hour without visible or more than occasional movement of wing.","exampleZh":"任何横渡太平洋的船，都会有体型较小的信天翁相伴多日；它可以跟着船飞一个小时，期间看不见它振翅，或至多偶尔振一下。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"as well as","matchedForm":"as well as","meaning":"也；以及","note":"连接补充成分，此处是两种气流方向：向上与沿航线。","example":"The currents of air that the walls of the ship direct upwards, as well as in the line of its course, are enough to give the great bird with its immense wings sufficient sustenance and progress.","exampleZh":"船体两侧使气流向上、同时沿着航向流动，这些气流就足以给这只双翼巨大的大鸟提供充分的升力和前进动力。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"yield to","matchedForm":"yield to","meaning":"向……让步；屈服于","note":"to 后接阻力或对手，此处指逆向气流使滑翔受限。","example":"The albatross is the king of the gliders, the class of fliers which harness the air to their purpose, but must yield to its opposition.","exampleZh":"信天翁是滑翔鸟类之王；这一类飞行者利用空气来达到自己的目的，却必须在逆风面前让步。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"be endowed with","matchedForm":"are endowed with","meaning":"天生具有","note":"常用于天赋、能力或自然特征，语体较正式。","example":"Duck, and like them the pigeons, are endowed with steel-like muscles, that are a good part of the weight of the bird, and these will ply the short wings with such irresistible power that they can bore for long distances through an opposing gale before exhaustion follows.","exampleZh":"鸭子和与之相似的鸽子，都有钢铁般的肌肉，肌肉占了体重的相当一部分；这些肌肉以不可阻挡的力量振动短翼，使它们能顶着强劲逆风钻行很远之后，才感到疲惫。","sourceParagraphIndex":0,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"in utter exhaustion","matchedForm":"in utter exhaustion","meaning":"在精疲力尽的状态下","note":"utter 加强 exhaustion，强调体力完全耗尽。","example":"You may pick them up in utter exhaustion, if wind over the sea has driven them to a long journey.","exampleZh":"如果海上的风逼着它们长途飞行，你便可能在它们精疲力尽时将其捡起来。","sourceParagraphIndex":0,"sourceSentenceIndex":8,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l024","book":4,"number":24,"title":"Beauty","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"A young man sees a sunset and, unable to understand or to express the emotion that it rouses in him, concludes that it must be the gateway to a world that lies beyond.","zh":"一个青年看见落日，既无法理解也无法表达它在心中唤起的感情，便认定它必是通往彼岸世界的大门。","kind":"narration","speaker":"旁白"},{"en":"It is difficult for any of us in moments of intense aesthetic experience to resist the suggestion that we are catching a glimpse of a light that shines down to us from a different realm of existence, different and, because the experience is intensely moving, in some way higher.","zh":"在强烈的审美体验中，我们任何人都很难不产生这样的感觉：自己正在瞥见一道从另一个存在境界照向我们的光；那个境界与此间不同，而且由于这种体验深深震撼人心，似乎在某种意义上也更高。","kind":"narration","speaker":"旁白"},{"en":"And, though the gleams blind and dazzle, yet do they convey a hint of beauty and serenity greater than we have known or imagined.","zh":"那些闪光虽使人目眩眼花，却仍向我们传递了一丝美与宁静，其程度超越了我们曾经认识或想象过的一切。","kind":"narration","speaker":"旁白"},{"en":"Greater too than we can describe; for language, which was invented to convey the meanings of this world, cannot readily be fitted to the uses of another.","zh":"也超越了我们所能描述的程度；因为语言被创造出来，是为了传达这个世界的意义，无法轻易调整来满足另一个世界的用途。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"That all great art has this power of suggesting a world beyond is undeniable.","zh":"一切伟大艺术都有这种使人联想到彼岸世界的力量，这是不可否认的。","kind":"narration","speaker":"旁白"},{"en":"In some moods, Nature shares it.","zh":"在某些心境下，自然也拥有这种力量。","kind":"narration","speaker":"旁白"},{"en":"There is no sky in June so blue that it does not point forward to a bluer, no sunset so beautiful that it does not waken the vision of a greater beauty, a vision which passes before it is fully glimpsed, and in passing leaves an indefinable longing and regret.","zh":"六月的天空无论多么湛蓝，都指向一片更蓝的天空；落日无论多么美丽，都会唤起一种更伟大的美的幻象；那幻象尚未被看真切便已消逝，消逝时留下一种无法言明的向往与惋惜。","kind":"narration","speaker":"旁白"},{"en":"But, if this world is not merely a bad joke, life a vulgar flare amid the cool radiance of the stars, and existence an empty laugh braying across the mysteries; if these intimations of a something behind and beyond are not evil humour born of indigestion, or whimsies sent by the devil to mock and madden us, if, in a word, beauty means something, yet we must not seek to interpret the meaning.","zh":"但是，如果这个世界并非只是个恶劣的玩笑，生命并非群星清冷光辉中一团粗俗的火光，存在也并非穿越重重奥秘的一声空洞狂笑；如果这些关于背后和彼岸某种事物的暗示，不是消化不良引起的恶劣心绪，也不是魔鬼送来嘲弄我们、使我们发狂的怪念；总之，如果美确有意义，我们却仍不应企图解释这种意义。","kind":"narration","speaker":"旁白"},{"en":"If we glimpse the unutterable, it is unwise to try to utter it, nor should we seek to invest with significance that which we cannot grasp.","zh":"如果我们瞥见了不可言说之物，硬要说出它是不明智的；我们也不该试图赋予自己无法理解的东西某种意义。","kind":"narration","speaker":"旁白"},{"en":"Beauty in terms of our human meanings is meaningless.","zh":"用人类的意义体系来衡量，美是没有意义的。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"the gateway to","matchedForm":"the gateway to","meaning":"通往……的门户","note":"gateway 既可指实体入口，也可比喻通往另一领域的途径。","example":"A young man sees a sunset and, unable to understand or to express the emotion that it rouses in him, concludes that it must be the gateway to a world that lies beyond.","exampleZh":"一个青年看见落日，既无法理解也无法表达它在心中唤起的感情，便认定它必是通往彼岸世界的大门。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"catch a glimpse of","matchedForm":"catching a glimpse of","meaning":"瞥见","note":"强调短暂而不完整的看见，glimpse 常用单数。","example":"It is difficult for any of us in moments of intense aesthetic experience to resist the suggestion that we are catching a glimpse of a light that shines down to us from a different realm of existence, different and, because the experience is intensely moving, in some way higher.","exampleZh":"在强烈的审美体验中，我们任何人都很难不产生这样的感觉：自己正在瞥见一道从另一个存在境界照向我们的光；那个境界与此间不同，而且由于这种体验深深震撼人心，似乎在某种意义上也更高。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"point forward to","matchedForm":"point forward to","meaning":"指向；预示","note":"强调眼前之物使人联想到尚未出现或更进一步的事物，此处是更蓝的天空。","example":"There is no sky in June so blue that it does not point forward to a bluer, no sunset so beautiful that it does not waken the vision of a greater beauty, a vision which passes before it is fully glimpsed, and in passing leaves an indefinable longing and regret.","exampleZh":"六月的天空无论多么湛蓝，都指向一片更蓝的天空；落日无论多么美丽，都会唤起一种更伟大的美的幻象；那幻象尚未被看真切便已消逝，消逝时留下一种无法言明的向往与惋惜。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"in a word","matchedForm":"in a word","meaning":"总之；一句话","note":"用于概括前面的较长论述。","example":"But, if this world is not merely a bad joke, life a vulgar flare amid the cool radiance of the stars, and existence an empty laugh braying across the mysteries; if these intimations of a something behind and beyond are not evil humour born of indigestion, or whimsies sent by the devil to mock and madden us, if, in a word, beauty means something, yet we must not seek to interpret the meaning.","exampleZh":"但是，如果这个世界并非只是个恶劣的玩笑，生命并非群星清冷光辉中一团粗俗的火光，存在也并非穿越重重奥秘的一声空洞狂笑；如果这些关于背后和彼岸某种事物的暗示，不是消化不良引起的恶劣心绪，也不是魔鬼送来嘲弄我们、使我们发狂的怪念；总之，如果美确有意义，我们却仍不应企图解释这种意义。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"invest with","matchedForm":"invest with significance","meaning":"赋予……意义","note":"invest something with significance/authority 是正式结构，不能译成资金投资。","example":"If we glimpse the unutterable, it is unwise to try to utter it, nor should we seek to invest with significance that which we cannot grasp.","exampleZh":"如果我们瞥见了不可言说之物，硬要说出它是不明智的；我们也不该试图赋予自己无法理解的东西某种意义。","sourceParagraphIndex":1,"sourceSentenceIndex":4,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l025","book":4,"number":25,"title":"Non-auditory effects of noise","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Many people in industry and the Services, who have practical experience of noise, regard any investigation of this question as a waste of time; they are not prepared even to admit the possibility that noise affects people.","zh":"工业界和军队中许多亲身接触过噪声的人，认为对这个问题作任何调查都是浪费时间；他们甚至不愿承认噪声有可能影响人。","kind":"narration","speaker":"旁白"},{"en":"On the other hand, those who dislike noise will sometimes use most inadequate evidence to support their pleas for a quieter society.","zh":"另一方面，厌恶噪声的人有时又会用极不充分的证据，来支持他们要求社会更安静的呼吁。","kind":"narration","speaker":"旁白"},{"en":"This is a pity, because noise abatement really is a good cause, and it is likely to be discredited if it gets to be associated with bad science.","zh":"这很可惜，因为减轻噪声确实是一项有益的事业；一旦与不严谨的科学牵扯在一起，它就很可能失去信誉。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"One allegation often made is that noise produces mental illness.","zh":"人们经常提出的一种说法是：噪声会引起精神疾病。","kind":"narration","speaker":"旁白"},{"en":"A recent article in a weekly newspaper, for instance, was headed with a striking illustration of a lady in a state of considerable distress, with the caption ‘She was yet another victim, reduced to a screaming wreck’.","zh":"例如，最近一家周报的一篇文章，开头配了一幅引人注目的插图，画的是一位陷于极度痛苦的女士，图注写着：“她又成了一个受害者，精神垮掉，只会尖叫。”","kind":"mixed","speaker":"旁白 / 报纸图注"},{"en":"On turning eagerly to the text, one learns that the lady was a typist who found the sound of office typewriters worried her more and more until eventually she had to go into a mental hospital.","zh":"急切地转看正文后才知道，这位女士是名打字员，办公室打字机的声音使她越来越不安，最后不得不住进精神病院。","kind":"narration","speaker":"旁白"},{"en":"Now the snag in this sort of anecdote is of course that one cannot distinguish cause and effect.","zh":"当然，这类轶事的问题在于，我们分不清因果。","kind":"narration","speaker":"旁白"},{"en":"Was the noise a cause of the illness, or were the complaints about noise merely a symptom?","zh":"究竟噪声是致病原因，还是抱怨噪声仅仅是一个症状？","kind":"narration","speaker":"旁白"},{"en":"Another patient might equally well complain that her neighbours were combining to slander her and persecute her, and yet one might be cautious about believing this statement.","zh":"另一名病人也完全可能抱怨邻居们合伙诽谤和迫害她，但对于这种说法，人们恐怕就会谨慎，不会轻信。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"What is needed in the case of noise is a study of large numbers of people living under noisy conditions, to discover whether they are mentally ill more often than other people are.","zh":"对于噪声问题，所需要的是研究大量生活在嘈杂环境中的人，查明他们是否比其他人更经常患精神疾病。","kind":"narration","speaker":"旁白"},{"en":"Some time ago the United States Navy, for instance, examined a very large number of men working on aircraft carriers: the study was known as Project Anehin.","zh":"例如，不久前美国海军对大量在航空母舰上工作的人员进行了检查，这项研究名叫“阿内欣计划”。","kind":"narration","speaker":"旁白"},{"en":"It can be unpleasant to live even several miles from an aerodrome; if you think what it must be like to share the deck of a ship with several squadrons of jet aircraft, you will realize that a modern navy is a good place to study noise.","zh":"即使住在离机场几英里的地方，也可能令人不快；如果想想与好几个中队的喷气式飞机共处一艘军舰甲板会是什么滋味，你就会明白，现代海军是研究噪声的好地方。","kind":"narration","speaker":"旁白"},{"en":"But neither psychiatric interviews nor objective tests were able to show any effects upon these American sailors.","zh":"然而，无论精神科访谈还是客观测试，都没能显示出这些美国水兵受到任何影响。","kind":"narration","speaker":"旁白"},{"en":"This result merely confirms earlier American and British studies: if there is any effect of noise upon mental health, it must be so small that present methods of psychiatric diagnosis cannot find it.","zh":"这一结果不过是证实了美国和英国早先的研究：如果噪声对心理健康真有影响，那也一定小到现有精神科诊断方法无法发现的程度。","kind":"narration","speaker":"旁白"},{"en":"That does not prove that it does not exist; but it does mean that noise is less dangerous than, say, being brought up in an orphanage — which really is a mental health hazard.","zh":"这并不能证明这种影响不存在；但确实意味着，噪声的危险性低于例如在孤儿院长大——后者确实是心理健康的一项危险因素。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"on the other hand","matchedForm":"On the other hand","meaning":"另一方面","note":"引入另一角度或相反倾向，常与前文形成对照。","example":"On the other hand, those who dislike noise will sometimes use most inadequate evidence to support their pleas for a quieter society.","exampleZh":"另一方面，厌恶噪声的人有时又会用极不充分的证据，来支持他们要求社会更安静的呼吁。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"in a state of","matchedForm":"in a state of","meaning":"处于……状态","note":"后接 distress 等状态名词，常用于较正式的描述。","example":"A recent article in a weekly newspaper, for instance, was headed with a striking illustration of a lady in a state of considerable distress, with the caption ‘She was yet another victim, reduced to a screaming wreck’.","exampleZh":"例如，最近一家周报的一篇文章，开头配了一幅引人注目的插图，画的是一位陷于极度痛苦的女士，图注写着：“她又成了一个受害者，精神垮掉，只会尖叫。”","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"might equally well","matchedForm":"might equally well","meaning":"也完全可能","note":"用于说明另一种说法或情况同样说得通，不能理解为做得同样好。","example":"Another patient might equally well complain that her neighbours were combining to slander her and persecute her, and yet one might be cautious about believing this statement.","exampleZh":"另一名病人也完全可能抱怨邻居们合伙诽谤和迫害她，但对于这种说法，人们恐怕就会谨慎，不会轻信。","sourceParagraphIndex":1,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"so ... that","matchedForm":"so small that","meaning":"如此……以至于","note":"that 引出结果，small 表明影响微弱到无法检出的程度。","example":"This result merely confirms earlier American and British studies: if there is any effect of noise upon mental health, it must be so small that present methods of psychiatric diagnosis cannot find it.","exampleZh":"这一结果不过是证实了美国和英国早先的研究：如果噪声对心理健康真有影响，那也一定小到现有精神科诊断方法无法发现的程度。","sourceParagraphIndex":2,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"bring up","matchedForm":"being brought up","meaning":"抚养长大","note":"原文是被动动名词结构；地点状语说明成长环境。","example":"That does not prove that it does not exist; but it does mean that noise is less dangerous than, say, being brought up in an orphanage — which really is a mental health hazard.","exampleZh":"这并不能证明这种影响不存在；但确实意味着，噪声的危险性低于例如在孤儿院长大——后者确实是心理健康的一项危险因素。","sourceParagraphIndex":2,"sourceSentenceIndex":5,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l026","book":4,"number":26,"title":"The past life of the earth","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"It is animals and plants which lived in or near water whose remains are most likely to be preserved, for one of the necessary conditions of preservation is quick burial, and it is only in the seas and rivers, and sometimes lakes, where mud and silt have been continuously deposited, that bodies and the like can be rapidly covered over and preserved.","zh":"最有可能保存下遗骸的，是生活在水中或水边的动植物，因为迅速掩埋是保存所必需的条件之一；只有在泥沙不断沉积的海洋、河流，以及有时的湖泊里，尸体之类的东西才能迅速被覆盖并保存下来。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"But even in the most favourable circumstances only a small fraction of the creatures that die are preserved in this way before decay sets in or, even more likely, before scavengers eat them.","zh":"但即使条件最有利，在腐烂开始之前，或更可能在被食腐动物吃掉之前，死去的生物也只有一小部分能这样保存下来。","kind":"narration","speaker":"旁白"},{"en":"After all, all living creatures live by feeding on something else, whether it be plant or animal, dead or alive, and it is only by chance that such a fate is avoided.","zh":"毕竟，一切生物都靠吃别的东西为生，不管那是植物还是动物、死物还是活物；能逃过这种命运，只能靠偶然。","kind":"narration","speaker":"旁白"},{"en":"The remains of plants and animals that lived on land are much more rarely preserved, for there is seldom anything to cover them over.","zh":"生活在陆地上的动植物遗骸更难保存，因为很少有东西将它们盖住。","kind":"narration","speaker":"旁白"},{"en":"When you think of the innumerable birds that one sees flying about, not to mention the equally numerous small animals like field mice and voles which you do not see, it is very rarely that one comes across a dead body, except, of course, on the roads.","zh":"想想我们看见的无数飞来飞去的鸟，还不必提那些同样众多、却看不见的田鼠、䶄鼠等小动物，我们却很少碰到尸体——当然，马路上的除外。","kind":"narration","speaker":"旁白"},{"en":"They decompose and are quickly destroyed by the weather or eaten by some other creature.","zh":"它们会腐烂，很快被风吹雨淋毁坏，或被别的生物吃掉。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"It is almost always due to some very special circumstances that traces of land animals survive, as by falling into inaccessible caves, or into an ice crevasse, like the Siberian mammoths, when the whole animal is sometimes preserved, as in a refrigerator.","zh":"陆地动物的遗迹能留存下来，几乎总是因为某些十分特殊的情形，例如掉进难以进入的洞穴，或像西伯利亚猛犸象那样落入冰缝；这时有时整个动物都能保存，仿佛放在冰箱里一样。","kind":"narration","speaker":"旁白"},{"en":"This is what happened to the famous Beresovka mammoth which was found preserved and in good condition.","zh":"著名的别列佐夫卡猛犸象就是如此，它被发现时保存得相当完好。","kind":"narration","speaker":"旁白"},{"en":"In his mouth were the remains of fir trees—the last meal that he had before he fell into the crevasse and broke his back.","zh":"它嘴里还有冷杉的残屑——这是它跌入冰缝、摔断脊背之前的最后一餐。","kind":"narration","speaker":"旁白"},{"en":"The mammoth has now been restored in the Palaeontological Museum in St. Petersburg.","zh":"如今，这头猛犸象已在圣彼得堡的古生物博物馆里复原陈列。","kind":"narration","speaker":"旁白"},{"en":"Other animals were trapped in tar pits, like the elephants, sabre-toothed cats, and numerous other creatures that are found at Rancho la Brea, which is now just a suburb of Los Angeles.","zh":"还有些动物被困在沥青坑中，例如在拉布雷亚牧场发现的大象、剑齿猫和许多其他生物；那里如今只是洛杉矶的一个郊区。","kind":"narration","speaker":"旁白"},{"en":"Apparently what happened was that water collected on these tar pits, and the bigger animals like the elephants ventured out on to the apparently firm surface to drink, and were promptly bogged in the tar.","zh":"事情显然是这样发生的：沥青坑上积了水，大象等大型动物冒险走上看似坚实的表面去喝水，立刻便陷进沥青里。","kind":"narration","speaker":"旁白"},{"en":"And then, when they were dead, the carnivores, like the sabre-toothed cats and the giant wolves, came out to feed and suffered exactly the same fate.","zh":"等它们死后，剑齿猫、巨狼等食肉动物出来取食，也遭遇了完全相同的命运。","kind":"narration","speaker":"旁白"},{"en":"There are also endless numbers of birds in the tar as well.","zh":"沥青里还有数不清的鸟。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"set in","matchedForm":"sets in","meaning":"开始发生；到来","note":"常用于腐败、恶劣天气等不利状况的开始。","example":"But even in the most favourable circumstances only a small fraction of the creatures that die are preserved in this way before decay sets in or, even more likely, before scavengers eat them.","exampleZh":"但即使条件最有利，在腐烂开始之前，或更可能在被食腐动物吃掉之前，死去的生物也只有一小部分能这样保存下来。","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"by chance","matchedForm":"by chance","meaning":"偶然；碰巧","note":"表示并非出于计划或必然。","example":"After all, all living creatures live by feeding on something else, whether it be plant or animal, dead or alive, and it is only by chance that such a fate is avoided.","exampleZh":"毕竟，一切生物都靠吃别的东西为生，不管那是植物还是动物、死物还是活物；能逃过这种命运，只能靠偶然。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"not to mention","matchedForm":"not to mention","meaning":"更不用说","note":"引入进一步补充或更有分量的事例。","example":"When you think of the innumerable birds that one sees flying about, not to mention the equally numerous small animals like field mice and voles which you do not see, it is very rarely that one comes across a dead body, except, of course, on the roads.","exampleZh":"想想我们看见的无数飞来飞去的鸟，还不必提那些同样众多、却看不见的田鼠、䶄鼠等小动物，我们却很少碰到尸体——当然，马路上的除外。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"come across","matchedForm":"comes across","meaning":"偶然发现；碰见","note":"强调无意中遇到，不是有目标地查找。","example":"When you think of the innumerable birds that one sees flying about, not to mention the equally numerous small animals like field mice and voles which you do not see, it is very rarely that one comes across a dead body, except, of course, on the roads.","exampleZh":"想想我们看见的无数飞来飞去的鸟，还不必提那些同样众多、却看不见的田鼠、䶄鼠等小动物，我们却很少碰到尸体——当然，马路上的除外。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"suffer the same fate","matchedForm":"suffered exactly the same fate","meaning":"遭受相同的命运","note":"suffer 与不幸的结果搭配；exactly 强调结局完全一样。","example":"And then, when they were dead, the carnivores, like the sabre-toothed cats and the giant wolves, came out to feed and suffered exactly the same fate.","exampleZh":"等它们死后，剑齿猫、巨狼等食肉动物出来取食，也遭遇了完全相同的命运。","sourceParagraphIndex":2,"sourceSentenceIndex":6,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l027","book":4,"number":27,"title":"The ‘Vasa’","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"From the seventeenth-century empire of Sweden, the story of a galleon that sank at the start of her maiden voyage in 1628 must be one of the strangest tales of the sea.","zh":"在十七世纪瑞典帝国的历史中，一艘大型帆船于一六二八年首航刚开始便沉没的故事，一定算得上海上最离奇的传说之一。","kind":"narration","speaker":"旁白"},{"en":"For nearly three and a half centuries she lay at the bottom of Stockholm harbour until her discovery in 1956.","zh":"它在斯德哥尔摩港底躺了将近三个半世纪，直到一九五六年被发现。","kind":"narration","speaker":"旁白"},{"en":"This was the Vasa, royal flagship of the great imperial fleet.","zh":"这就是“瓦萨号”，庞大的帝国舰队的皇家旗舰。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"King Gustavus Adolphus, ‘The Northern Hurricane’, then at the height of his military success in the Thirty Years’ War, had dictated her measurements and armament.","zh":"国王古斯塔夫·阿道夫号称“北方飓风”，当时在三十年战争中的军事成就正值顶峰；船的尺寸和武器配备都是由他亲自规定的。","kind":"narration","speaker":"旁白"},{"en":"Triple gun-decks mounted sixty-four bronze cannon.","zh":"三层火炮甲板装有六十四门青铜炮。","kind":"narration","speaker":"旁白"},{"en":"She was intended to play a leading role in the growing might of Sweden.","zh":"这艘船原本要在瑞典不断增强的国力中扮演主角。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"As she was prepared for her maiden voyage on August 10, 1628, Stockholm was in a ferment.","zh":"一六二八年八月十日，当它准备首航时，整个斯德哥尔摩都沸腾了。","kind":"narration","speaker":"旁白"},{"en":"From the Skeppsbron and surrounding islands the people watched this thing of beauty begin to spread her sails and catch the wind.","zh":"人们从斯凯普斯布隆码头和周围岛屿上，望着这件美丽的造物开始扬帆迎风。","kind":"narration","speaker":"旁白"},{"en":"They had laboured for three years to produce this floating work of art; she was more richly carved and ornamented than any previous ship.","zh":"他们辛劳了三年才造出这件浮动的艺术品；它的雕刻和装饰之华丽，胜过此前任何一艘船。","kind":"narration","speaker":"旁白"},{"en":"The high stern castle was a riot of carved gods, demons, knights, kings, warriors, mermaids, cherubs; and zoomorphic animal shapes ablaze with red and gold and blue, symbols of courage, power, and cruelty, were portrayed to stir the imaginations of the superstitious sailors of the day.","zh":"高高的艉楼上，各种神祇、恶魔、骑士、国王、武士、美人鱼和小天使雕像纷繁夺目；还有红、金、蓝色灿烂耀眼的兽形图像，象征勇气、力量和残酷，用来激起那个时代迷信水手的想象。","kind":"narration","speaker":"旁白"}]},{"index":3,"rows":[{"en":"Then the cannons of the anchored warships thundered a salute to which the Vasa fired in reply.","zh":"接着，停泊的军舰鸣炮致敬，“瓦萨号”也鸣炮回礼。","kind":"narration","speaker":"旁白"},{"en":"As she emerged from her drifting cloud of gun smoke with the water churned to foam beneath her bow, her flags flying, pennants waving, sails filling in the breeze, and the red and gold of her superstructure ablaze with colour, she presented a more majestic spectacle than Stockholmers had ever seen before.","zh":"它从自己漂浮的炮烟中驶出，船首下海水翻成白沫，旗帜飞扬，长旗飘动，船帆被微风鼓满，上层建筑红金交映，色彩灿烂；它展现的雄伟景象，是斯德哥尔摩人此前从未见过的。","kind":"narration","speaker":"旁白"},{"en":"All gun-ports were open and the muzzles peeped wickedly from them.","zh":"所有炮门都敞着，炮口从中探出，显得凶险逼人。","kind":"narration","speaker":"旁白"}]},{"index":4,"rows":[{"en":"As the wind freshened there came a sudden squall and the ship made a strange movement, listing to port.","zh":"风渐渐加大，突然一阵狂风袭来，船出现了奇怪的晃动，向左舷倾斜。","kind":"narration","speaker":"旁白"},{"en":"The Ordnance Officer ordered all the port cannon to be heaved to starboard to counteract the list, but the steepening angle of the decks increased.","zh":"军械官命令把左舷全部大炮拖到右舷，以抵消船身倾斜，但甲板的倾角却继续增大。","kind":"narration","speaker":"旁白"},{"en":"Then the sound of rumbling thunder reached the watchers on the shore, as cargo, ballast, ammunition and 400 people went sliding and crashing down to the port side of the steeply listing ship.","zh":"随后，岸上观众听到雷鸣般的轰隆声，货物、压舱物、弹药和四百个人一起滑落，猛撞向这艘严重倾斜的船的左舷。","kind":"narration","speaker":"旁白"},{"en":"The lower gun-ports were now below water and the inrush sealed the ship’s fate.","zh":"下层炮门此时已没入水下，涌入的海水决定了这艘船的厄运。","kind":"narration","speaker":"旁白"},{"en":"In that first glorious hour, the mighty Vasa, which was intended to rule the Baltic, sank with all flags flying—in the harbour of her birth.","zh":"就在最初那辉煌的一小时里，本打算称霸波罗的海的强大“瓦萨号”，旗帜依旧飘扬，却沉没在了它诞生的港湾。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"maiden voyage","matchedForm":"maiden voyage","meaning":"首航","note":"专指船只第一次正式航行，maiden 在此意为首次的。","example":"From the seventeenth-century empire of Sweden, the story of a galleon that sank at the start of her maiden voyage in 1628 must be one of the strangest tales of the sea.","exampleZh":"在十七世纪瑞典帝国的历史中，一艘大型帆船于一六二八年首航刚开始便沉没的故事，一定算得上海上最离奇的传说之一。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"at the height of","matchedForm":"at the height of","meaning":"在……的顶峰","note":"描述事业、力量、活动等最盛的时期。","example":"King Gustavus Adolphus, ‘The Northern Hurricane’, then at the height of his military success in the Thirty Years’ War, had dictated her measurements and armament.","exampleZh":"国王古斯塔夫·阿道夫号称“北方飓风”，当时在三十年战争中的军事成就正值顶峰；船的尺寸和武器配备都是由他亲自规定的。","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"play a leading role","matchedForm":"play a leading role","meaning":"起主导作用","note":"常接 in，leading 表示主要或领头的地位。","example":"She was intended to play a leading role in the growing might of Sweden.","exampleZh":"这艘船原本要在瑞典不断增强的国力中扮演主角。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"in a ferment","matchedForm":"in a ferment","meaning":"处于激动或骚动之中","note":"ferment 这里比喻群体情绪沸腾，而非实际发酵。","example":"As she was prepared for her maiden voyage on August 10, 1628, Stockholm was in a ferment.","exampleZh":"一六二八年八月十日，当它准备首航时，整个斯德哥尔摩都沸腾了。","sourceParagraphIndex":2,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"seal one’s fate","matchedForm":"sealed the ship’s fate","meaning":"决定……的命运","note":"通常指使坏结局不可避免；所有格可换成具体对象。","example":"The lower gun-ports were now below water and the inrush sealed the ship’s fate.","exampleZh":"下层炮门此时已没入水下，涌入的海水决定了这艘船的厄运。","sourceParagraphIndex":4,"sourceSentenceIndex":3,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l028","book":4,"number":28,"title":"Patients and doctors","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"This is a sceptical age, but although our faith in many of the things in which our forefathers fervently believed has weakened, our confidence in the curative properties of the bottle of medicine remains the same as theirs.","zh":"这是一个怀疑的时代；虽然我们对祖先曾热烈信奉的许多事物已减弱了信仰，但对那一瓶药的疗效，我们仍然和他们一样充满信心。","kind":"narration","speaker":"旁白"},{"en":"This modern faith in medicines is proved by the fact that the annual drug bill of the Health Services is mounting to astronomical figures and shows no signs at present of ceasing to rise.","zh":"卫生服务部门每年的药费已攀升到天文数字，而且目前毫无停止上涨的迹象，这一事实证明了现代人对药物的这种信仰。","kind":"narration","speaker":"旁白"},{"en":"The majority of the patients attending the medical out-patients departments of our hospitals feel that they have not received adequate treatment unless they are able to carry home with them some tangible remedy in the shape of a bottle of medicine, a box of pills, or a small jar of ointment, and the doctor in charge of the department is only too ready to provide them with these requirements.","zh":"到我们医院内科门诊就诊的多数病人，除非能带回家一些看得见摸得着的药物，比如一瓶药水、一盒药片或一小罐药膏，否则便觉得自己没有受到充分治疗；而科室负责的医生也极愿意满足这些要求。","kind":"narration","speaker":"旁白"},{"en":"There is no quicker method of disposing of patients than by giving them what they are asking for, and since most medical men in the Health Services are overworked and have little time for offering time-consuming and little-appreciated advice on such subjects as diet, right living, and the need for abandoning bad habits etc., the bottle, the box, and the jar are almost always granted them.","zh":"要尽快打发病人，没有什么办法比给他们想要的东西更快；卫生服务部门的大多数医生又都工作过量，几乎没时间提供那些费时却不太受重视的忠告，例如饮食、正确的生活方式、戒除坏习惯的必要性等等，因此病人几乎总能拿到那瓶药、那盒药片和那罐药膏。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Nor is it only the ignorant and ill-educated person who has such faith in the bottle of medicine.","zh":"对药瓶抱有这种信念的，也并非只有无知和受教育少的人。","kind":"narration","speaker":"旁白"},{"en":"It is recounted of Thomas Carlyle that when he heard of the illness of his friend, Henry Taylor, he went off immediately to visit him, carrying with him in his pocket what remained of a bottle of medicine formerly prescribed for an indisposition of Mrs. Carlyle’s.","zh":"据说托马斯·卡莱尔听到朋友亨利·泰勒生病后，立刻动身去看他，口袋里带着一瓶剩药；那原是医生早先为卡莱尔夫人的一次小病开的。","kind":"narration","speaker":"旁白"},{"en":"Carlyle was entirely ignorant of what the bottle in his pocket contained, of the nature of the illness from which his friend was suffering, and of what had previously been wrong with his wife, but a medicine that had worked so well in one form of illness would surely be of equal benefit in another, and comforted by the thought of the help he was bringing to his friend, he hastened to Henry Taylor's house.","zh":"卡莱尔全然不知道口袋里的瓶子装着什么药，不知道朋友患的是什么病，也不知道妻子先前哪里不舒服；但他觉得，既然一种药对某种病如此有效，对另一种病肯定同样有益，于是想到自己正给朋友送去帮助，心中甚感宽慰，便急忙赶往亨利·泰勒家。","kind":"mixed","speaker":"旁白 / 卡莱尔的想法"},{"en":"History does not relate whether his friend accepted his medical help, but in all probability he did.","zh":"历史没有记载他的朋友是否接受了这番医药帮助，但他十之八九接受了。","kind":"narration","speaker":"旁白"},{"en":"The great advantage of taking medicine is that it makes no demands on the taker beyond that of putting up for a moment with a disgusting taste, and that is what all patients demand of their doctors—to be cured at no inconvenience to themselves.","zh":"吃药最大的好处是，除了短暂忍受一点恶心的味道，对吃药者没有别的要求；而这正是所有病人向医生提出的要求——自己不受任何麻烦，病就能治好。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"show no signs of","matchedForm":"shows no signs at present of","meaning":"没有……的迹象","note":"signs of 后可接动名词；原句在 signs 与 of 之间插入 at present。","example":"This modern faith in medicines is proved by the fact that the annual drug bill of the Health Services is mounting to astronomical figures and shows no signs at present of ceasing to rise.","exampleZh":"卫生服务部门每年的药费已攀升到天文数字，而且目前毫无停止上涨的迹象，这一事实证明了现代人对药物的这种信仰。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"in the shape of","matchedForm":"in the shape of","meaning":"以……的形式","note":"此处表示具体呈现形式，不限于物体外形。","example":"The majority of the patients attending the medical out-patients departments of our hospitals feel that they have not received adequate treatment unless they are able to carry home with them some tangible remedy in the shape of a bottle of medicine, a box of pills, or a small jar of ointment, and the doctor in charge of the department is only too ready to provide them with these requirements.","exampleZh":"到我们医院内科门诊就诊的多数病人，除非能带回家一些看得见摸得着的药物，比如一瓶药水、一盒药片或一小罐药膏，否则便觉得自己没有受到充分治疗；而科室负责的医生也极愿意满足这些要求。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"only too ready to","matchedForm":"only too ready to","meaning":"非常乐意","note":"only too 加形容词在此加强肯定，不是否定意为过分。","example":"The majority of the patients attending the medical out-patients departments of our hospitals feel that they have not received adequate treatment unless they are able to carry home with them some tangible remedy in the shape of a bottle of medicine, a box of pills, or a small jar of ointment, and the doctor in charge of the department is only too ready to provide them with these requirements.","exampleZh":"到我们医院内科门诊就诊的多数病人，除非能带回家一些看得见摸得着的药物，比如一瓶药水、一盒药片或一小罐药膏，否则便觉得自己没有受到充分治疗；而科室负责的医生也极愿意满足这些要求。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"in all probability","matchedForm":"in all probability","meaning":"极有可能；十之八九","note":"表示很有把握的推测，仍不等于已获证实。","example":"History does not relate whether his friend accepted his medical help, but in all probability he did.","exampleZh":"历史没有记载他的朋友是否接受了这番医药帮助，但他十之八九接受了。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"put up with","matchedForm":"putting up for a moment with","meaning":"忍受","note":"put up with 的宾语在 with 后；原句插入 for a moment，限定忍受的时间。","example":"The great advantage of taking medicine is that it makes no demands on the taker beyond that of putting up for a moment with a disgusting taste, and that is what all patients demand of their doctors—to be cured at no inconvenience to themselves.","exampleZh":"吃药最大的好处是，除了短暂忍受一点恶心的味道，对吃药者没有别的要求；而这正是所有病人向医生提出的要求——自己不受任何麻烦，病就能治好。","sourceParagraphIndex":1,"sourceSentenceIndex":4,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l029","book":4,"number":29,"title":"The hovercraft","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Many strange new means of transport have been developed in our century, the strangest of them being perhaps the hovercraft.","zh":"本世纪已开发出许多奇特的新交通工具，其中最奇特的也许是气垫船。","kind":"narration","speaker":"旁白"},{"en":"In 1953, a former electronics engineer in his fifties, Christopher Cockerell, who had turned to boat-building on the Norfolk Broads, suggested an idea on which he had been working for many years to the British Government and industrial circles.","zh":"一九五三年，五十多岁的克里斯托弗·科克雷尔原是一名电子工程师，后来在诺福克湖区转行造船；他向英国政府和工业界提出了一个自己钻研多年的构想。","kind":"narration","speaker":"旁白"},{"en":"It was the idea of supporting a craft on a ‘pad’, or cushion, of low-pressure air, ringed with a curtain of higher pressure air.","zh":"这个构想是让船体由一层低压空气“垫子”，也就是气垫支撑起来，四周再围以较高压力的空气帘。","kind":"narration","speaker":"旁白"},{"en":"Ever since, people have had difficulty in deciding whether the craft should be ranged among ships, planes, or land vehicles—for it is something in between a boat and an aircraft.","zh":"自那以后，人们一直难以确定，这种交通工具应归入船舶、飞机，还是陆上车辆，因为它是介于船与飞机之间的东西。","kind":"narration","speaker":"旁白"},{"en":"As a shipbuilder, Cockerell was trying to find a solution to the problem of the wave resistance which wastes a good deal of a surface ship’s power and limits its speed.","zh":"作为造船者，科克雷尔一直试图解决兴波阻力的问题；这种阻力耗费水面船舶的大量动力，并限制船速。","kind":"narration","speaker":"旁白"},{"en":"His answer was to lift the vessel out of the water by making it ride on a cushion of air, no more than one or two feet thick.","zh":"他的办法是让船乘在一层仅一两英尺厚的气垫上，从而离开水面。","kind":"narration","speaker":"旁白"},{"en":"This is done by a great number of ring-shaped air jets on the bottom of the craft.","zh":"船底大量环形空气喷口实现了这一点。","kind":"narration","speaker":"旁白"},{"en":"It ‘flies’, therefore, but it cannot fly higher—its action depends on the surface, water or ground, over which it rides.","zh":"因此它是在“飞行”，却又飞不高，因为它的运行依赖于所乘行的水面或地面。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"The first tests on the Solent in 1959 caused a sensation.","zh":"一九五九年在索伦特海峡进行的首次试验轰动一时。","kind":"narration","speaker":"旁白"},{"en":"The hovercraft travelled first over the water, then mounted the beach, climbed up the dunes, and sat down on a road.","zh":"气垫船先驶过水面，然后登上海滩，爬上沙丘，落到一条公路上。","kind":"narration","speaker":"旁白"},{"en":"Later it crossed the Channel, riding smoothly over the waves, which presented no problem.","zh":"后来它又横渡了英吉利海峡，平稳地越过波浪，海浪没有造成任何问题。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"Since that time, various types of hovercraft have appeared and taken up regular service.","zh":"从那以后，各种型号的气垫船陆续出现，并开始定期运营。","kind":"narration","speaker":"旁白"},{"en":"The hovercraft is particularly useful in large areas with poor communications such as Africa or Australia; it can become a ‘flying fruit-bowl’, carrying bananas from the plantations to the ports; giant hovercraft liners could span the Atlantic; and the railway of the future may well be the ‘hovertrain’, riding on its air cushion over a single rail, which it never touches, at speeds up to 300 m.p.h.—the possibilities appear unlimited.","zh":"气垫船特别适用于非洲或澳大利亚这类交通不便的广大地区；它可以成为“飞行的果盘”，把香蕉从种植园运到港口；巨型气垫客轮可以横跨大西洋；未来的铁路很可能采用“气垫列车”，让它乘着气垫在从不接触的单轨上方运行，时速可达三百英里——种种可能性似乎没有尽头。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"in one’s fifties","matchedForm":"in his fifties","meaning":"在某人五十多岁时","note":"用 in 加物主代词和整十数的复数，表示年龄段。","example":"In 1953, a former electronics engineer in his fifties, Christopher Cockerell, who had turned to boat-building on the Norfolk Broads, suggested an idea on which he had been working for many years to the British Government and industrial circles.","exampleZh":"一九五三年，五十多岁的克里斯托弗·科克雷尔原是一名电子工程师，后来在诺福克湖区转行造船；他向英国政府和工业界提出了一个自己钻研多年的构想。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"ever since","matchedForm":"Ever since","meaning":"从那以后一直","note":"强调由过去延续到说话时，常与现在完成时搭配。","example":"Ever since, people have had difficulty in deciding whether the craft should be ranged among ships, planes, or land vehicles—for it is something in between a boat and an aircraft.","exampleZh":"自那以后，人们一直难以确定，这种交通工具应归入船舶、飞机，还是陆上车辆，因为它是介于船与飞机之间的东西。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"a solution to","matchedForm":"a solution to","meaning":"……的解决办法","note":"solution 后用介词 to，而通常不用 of 来引出待解决的问题。","example":"As a shipbuilder, Cockerell was trying to find a solution to the problem of the wave resistance which wastes a good deal of a surface ship’s power and limits its speed.","exampleZh":"作为造船者，科克雷尔一直试图解决兴波阻力的问题；这种阻力耗费水面船舶的大量动力，并限制船速。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"cause a sensation","matchedForm":"caused a sensation","meaning":"引起轰动","note":"sensation 在这里指公众的强烈关注和惊奇。","example":"The first tests on the Solent in 1959 caused a sensation.","exampleZh":"一九五九年在索伦特海峡进行的首次试验轰动一时。","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"may well","matchedForm":"may well","meaning":"很可能","note":"well 加强可能性判断，此处仍是对未来的预测。","example":"The hovercraft is particularly useful in large areas with poor communications such as Africa or Australia; it can become a ‘flying fruit-bowl’, carrying bananas from the plantations to the ports; giant hovercraft liners could span the Atlantic; and the railway of the future may well be the ‘hovertrain’, riding on its air cushion over a single rail, which it never touches, at speeds up to 300 m.p.h.—the possibilities appear unlimited.","exampleZh":"气垫船特别适用于非洲或澳大利亚这类交通不便的广大地区；它可以成为“飞行的果盘”，把香蕉从种植园运到港口；巨型气垫客轮可以横跨大西洋；未来的铁路很可能采用“气垫列车”，让它乘着气垫在从不接触的单轨上方运行，时速可达三百英里——种种可能性似乎没有尽头。","sourceParagraphIndex":2,"sourceSentenceIndex":1,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l030","book":4,"number":30,"title":"Exploring the sea-floor","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Our knowledge of the oceans a hundred years ago was confined to the two-dimensional shape of the sea surface and the hazards of navigation presented by the irregularities in depth of the shallow water close to the land.","zh":"一百年前，我们对海洋的认识，仅限于海面的二维形状，以及近岸浅水区深浅不一给航行带来的危险。","kind":"narration","speaker":"旁白"},{"en":"The open sea was deep and mysterious, and anyone who gave more than a passing thought to the bottom confines of the oceans probably assumed that the sea bed was flat.","zh":"外海深邃而神秘；凡对海洋底部不止略微想过一下的人，多半都以为海床是平的。","kind":"narration","speaker":"旁白"},{"en":"Sir James Clark Ross had obtained a sounding of over 2,400 fathoms in 1839, but it was not until 1869, when H. M. S. Porcupine was put at the disposal of the Royal Society for several cruises, that a series of deep soundings was obtained in the Atlantic and the first samples were collected by dredging the bottom.","zh":"詹姆斯·克拉克·罗斯爵士在一八三九年已测得超过二千四百英寻的深度，但直到一八六九年，英国皇家海军“豪猪号”被交给皇家学会使用、进行了数次考察航行之后，人们才取得大西洋的一系列深海测深数据，并通过在海底拖捞采到了第一批样本。","kind":"narration","speaker":"旁白"},{"en":"Shortly after this the famous H. M. S. Challenger expedition established the study of the sea-floor as a subject worthy of the most qualified physicists and geologists.","zh":"此后不久，著名的皇家海军“挑战者号”考察，使海底研究确立为一个值得最优秀的物理学家和地质学家投入的课题。","kind":"narration","speaker":"旁白"},{"en":"A burst of activity associated with the laying of submarine cables soon confirmed the Challenger’s observation that many parts of the ocean were two to three miles deep, and the existence of underwater features of considerable magnitude.","zh":"铺设海底电缆带来的一阵活跃工作，很快证实了“挑战者号”的观测：海洋许多地方深达两三英里，而且存在规模相当可观的水下地形。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Today, enough soundings are available to enable a relief map of the Atlantic to be drawn and we know something of the great variety of the sea bed’s topography.","zh":"如今已有足够的测深数据，可以绘出大西洋的地形起伏图，我们也对海床地形的丰富多样有所了解。","kind":"narration","speaker":"旁白"},{"en":"Since the sea covers the greater part of the earth’s surface, it is quite reasonable to regard the sea floor as the basic form of the crust of the earth, with, superimposed upon it the continents, together with the islands and other features of the oceans.","zh":"海洋覆盖着地球表面的大部分，因此把海底看作地壳的基本形态，是很合理的；大陆以及海洋中的岛屿和其他地形，都叠置在这个基本形态之上。","kind":"narration","speaker":"旁白"},{"en":"The continents form rugged tablelands which stand nearly three miles above the floor of the open ocean.","zh":"大陆形成崎岖的高台地，耸立在外海海底之上，高出将近三英里。","kind":"narration","speaker":"旁白"},{"en":"From the shore line, out to a distance which may be anywhere from a few miles to a few hundred miles, runs the gentle slope of the continental shelf, geologically part of the continents.","zh":"从海岸线向外延伸几英里到几百英里不等，是大陆架的缓坡；从地质上说，它属于大陆的一部分。","kind":"narration","speaker":"旁白"},{"en":"The real dividing line between continents and oceans occurs at the foot of a steeper slope.","zh":"大陆与海洋真正的分界线，位于一段更陡的坡的坡脚。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"This continental slope usually starts at a place somewhere near the 100-fathom mark and in the course of a few hundred miles reaches the true ocean floor at 2,500-3,500 fathoms.","zh":"这种大陆坡通常从约一百英寻深处开始，延伸几百英里后，到达深二千五百至三千五百英寻的真正洋底。","kind":"narration","speaker":"旁白"},{"en":"The slope averages about 1 in 30, but contains steep, probably vertical, cliffs, and gentle sediment-covered terraces, and near its lower reaches there is a long tailing-off which is almost certainly the result of material transported out to deep water after being eroded from the continental masses.","zh":"其坡度平均约为三十分之一，但其中有陡峭、很可能垂直的断崖，也有覆盖沉积物的平缓台阶；在较低地段附近，坡势又有很长一段逐渐变缓，这几乎肯定是大陆块体遭侵蚀后，物质被搬运到深水处所造成的。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"be confined to","matchedForm":"was confined to","meaning":"局限于","note":"to 是介词，后接认识、活动等被限制在的范围。","example":"Our knowledge of the oceans a hundred years ago was confined to the two-dimensional shape of the sea surface and the hazards of navigation presented by the irregularities in depth of the shallow water close to the land.","exampleZh":"一百年前，我们对海洋的认识，仅限于海面的二维形状，以及近岸浅水区深浅不一给航行带来的危险。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"a passing thought","matchedForm":"a passing thought","meaning":"一闪而过的念头","note":"give something more than a passing thought 指对某事稍作认真考虑。","example":"The open sea was deep and mysterious, and anyone who gave more than a passing thought to the bottom confines of the oceans probably assumed that the sea bed was flat.","exampleZh":"外海深邃而神秘；凡对海洋底部不止略微想过一下的人，多半都以为海床是平的。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"at the disposal of","matchedForm":"at the disposal of","meaning":"供……使用或支配","note":"常用 put something at someone’s disposal，表示提供资源。","example":"Sir James Clark Ross had obtained a sounding of over 2,400 fathoms in 1839, but it was not until 1869, when H. M. S. Porcupine was put at the disposal of the Royal Society for several cruises, that a series of deep soundings was obtained in the Atlantic and the first samples were collected by dredging the bottom.","exampleZh":"詹姆斯·克拉克·罗斯爵士在一八三九年已测得超过二千四百英寻的深度，但直到一八六九年，英国皇家海军“豪猪号”被交给皇家学会使用、进行了数次考察航行之后，人们才取得大西洋的一系列深海测深数据，并通过在海底拖捞采到了第一批样本。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"worthy of","matchedForm":"worthy of","meaning":"值得……的","note":"of 后接名词；此处表示值得最优秀学者研究。","example":"Shortly after this the famous H. M. S. Challenger expedition established the study of the sea-floor as a subject worthy of the most qualified physicists and geologists.","exampleZh":"此后不久，著名的皇家海军“挑战者号”考察，使海底研究确立为一个值得最优秀的物理学家和地质学家投入的课题。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"in the course of","matchedForm":"in the course of","meaning":"在……过程中；经过……","note":"通常指时间过程，原文用于延伸几百英里的空间过程。","example":"This continental slope usually starts at a place somewhere near the 100-fathom mark and in the course of a few hundred miles reaches the true ocean floor at 2,500-3,500 fathoms.","exampleZh":"这种大陆坡通常从约一百英寻深处开始，延伸几百英里后，到达深二千五百至三千五百英寻的真正洋底。","sourceParagraphIndex":2,"sourceSentenceIndex":0,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l031","book":4,"number":31,"title":"The sculptor speaks","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Appreciation of sculpture depends upon the ability to respond to form in three dimensions.","zh":"欣赏雕塑，有赖于对三维形体作出感受和反应的能力。","kind":"narration","speaker":"旁白"},{"en":"That is perhaps why sculpture has been described as the most difficult of all arts; certainly it is more difficult than the arts which involve appreciation of flat forms, shape in only two dimensions.","zh":"这也许就是雕塑被称为所有艺术中最难的一门的原因；可以肯定，它比那些欣赏平面形态、只涉及二维形状的艺术更难。","kind":"narration","speaker":"旁白"},{"en":"Many more people are ‘form-blind’ than colour-blind.","zh":"“形盲”的人远比色盲的人多。","kind":"narration","speaker":"旁白"},{"en":"The child learning to see, first distinguishes only two-dimensional shape; it cannot judge distances, depths.","zh":"儿童学习看东西时，最初只能分辨二维形状，还不能判断远近和深浅。","kind":"narration","speaker":"旁白"},{"en":"Later, for its personal safety and practical needs, it has to develop (partly by means of touch) the ability to judge roughly three-dimensional distances.","zh":"后来，为了自身安全和实际需要，他必须发展出粗略判断三维距离的能力，其中一部分要借助触摸。","kind":"narration","speaker":"旁白"},{"en":"But having satisfied the requirements of practical necessity, most people go no further.","zh":"然而，大多数人在满足实际需要之后，就不再向前发展了。","kind":"narration","speaker":"旁白"},{"en":"Though they may attain considerable accuracy in the perception of flat form, they do not make the further intellectual and emotional effort needed to comprehend form in its full spatial existence.","zh":"他们对平面形态的感知也许相当准确，却不再付出进一步的智力与情感努力，去理解形体完整的空间存在。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"This is what the sculptor must do.","zh":"而雕塑家必须做到这一点。","kind":"narration","speaker":"旁白"},{"en":"He must strive continually to think of, and use, form in its full spatial completeness.","zh":"他必须不断努力，从形体完整的空间形态出发来思考和运用它。","kind":"narration","speaker":"旁白"},{"en":"He gets the solid shape, as it were, inside his head—he thinks of it, whatever its size, as if he were holding it completely enclosed in the hollow of his hand.","zh":"可以说，他把实体形状放进了脑子里；不论它有多大，他在思考它时，都仿佛将它完整地握在自己的掌心中。","kind":"narration","speaker":"旁白"},{"en":"He mentally visualizes a complex form from all round itself; he knows while he looks at one side what the other side is like; he identifies himself with its centre of gravity, its mass, its weight; he realizes its volume, as the space that the shape displaces in the air.","zh":"他在心中从四面八方呈现一个复杂形体；看着一面时，就知道另一面是什么样；他把自己融入它的重心、体量和重量之中，把它的体积理解为这个形状在空气中所占据的空间。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"And the sensitive observer of sculpture must also learn to feel shape simply as shape, not as description or reminiscence.","zh":"同样，对雕塑敏感的观赏者也必须学会，只把形状当作形状来感受，不把它当作某种描摹或记忆的唤起。","kind":"narration","speaker":"旁白"},{"en":"He must, for example, perceive an egg as a simple single solid shape, quite apart from its significance as food, or from the literary idea that it will become a bird.","zh":"例如，他必须把鸡蛋看成一个简单、单一的实体形状，完全撇开它作为食物的意义，也撇开“它将变成一只鸟”这种文学性的联想。","kind":"narration","speaker":"旁白"},{"en":"And so with solids such as a shell, a nut, a plum, a pear, a tadpole, a mushroom, a mountain peak, a kidney, a carrot, a tree-trunk, a bird, a bud, a lark, a ladybird, a bulrush, a bone.","zh":"对其他实体也应如此，例如贝壳、坚果、李子、梨、蝌蚪、蘑菇、山峰、肾脏、胡萝卜、树干、鸟、花蕾、云雀、瓢虫、芦苇和骨头。","kind":"narration","speaker":"旁白"},{"en":"From these he can go on to appreciate more complex forms or combinations of several forms.","zh":"由此，他就能进而欣赏更复杂的形体，或几个形体的组合。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"in three dimensions","matchedForm":"in three dimensions","meaning":"在三维空间中","note":"dimension 指空间维度；three dimensions 涉及长、宽、高。","example":"Appreciation of sculpture depends upon the ability to respond to form in three dimensions.","exampleZh":"欣赏雕塑，有赖于对三维形体作出感受和反应的能力。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"go no further","matchedForm":"go no further","meaning":"不再进一步","note":"表示发展或行动就此停止，further 在此是副词。","example":"But having satisfied the requirements of practical necessity, most people go no further.","exampleZh":"然而，大多数人在满足实际需要之后，就不再向前发展了。","sourceParagraphIndex":0,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"as it were","matchedForm":"as it were","meaning":"可以说；仿佛","note":"插入语，提示表达是比喻或并不完全按字面理解。","example":"He gets the solid shape, as it were, inside his head—he thinks of it, whatever its size, as if he were holding it completely enclosed in the hollow of his hand.","exampleZh":"可以说，他把实体形状放进了脑子里；不论它有多大，他在思考它时，都仿佛将它完整地握在自己的掌心中。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"quite apart from","matchedForm":"quite apart from","meaning":"完全撇开","note":"apart from 此处不是此外还有，而是排除其他意义，只看形体。","example":"He must, for example, perceive an egg as a simple single solid shape, quite apart from its significance as food, or from the literary idea that it will become a bird.","exampleZh":"例如，他必须把鸡蛋看成一个简单、单一的实体形状，完全撇开它作为食物的意义，也撇开“它将变成一只鸟”这种文学性的联想。","sourceParagraphIndex":2,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"go on to","matchedForm":"go on to","meaning":"接着做；进而","note":"后接动词原形，表示完成前一步后转入下一步。","example":"From these he can go on to appreciate more complex forms or combinations of several forms.","exampleZh":"由此，他就能进而欣赏更复杂的形体，或几个形体的组合。","sourceParagraphIndex":2,"sourceSentenceIndex":3,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l032","book":4,"number":32,"title":"Galileo reborn","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"In his own lifetime Galileo was the centre of violent controversy; but the scientific dust has long since settled, and today we can see even his famous clash with the Inquisition in something like its proper perspective.","zh":"伽利略在世时曾是激烈争论的中心；但科学争论的尘埃早已落定，如今即使是他与宗教裁判所那场著名的冲突，我们也能够以近乎恰当的视角来看待。","kind":"narration","speaker":"旁白"},{"en":"But, in contrast, it is only in modern times that Galileo has become a problem child for historians of science.","zh":"可形成对照的是，直到近代，伽利略才成了让科学史家头疼的“问题孩子”。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"The old view of Galileo was delightfully uncomplicated.","zh":"过去对伽利略的看法，简单得令人愉快。","kind":"narration","speaker":"旁白"},{"en":"He was, above all, a man who experimented: who despised the prejudices and book learning of the Aristotelians, who put his questions to nature instead of to the ancients, and who drew his conclusions fearlessly.","zh":"他首先是一个实验者：鄙视亚里士多德学派的偏见和书本知识，向自然发问而不向古人讨教，并且无所畏惧地得出自己的结论。","kind":"narration","speaker":"旁白"},{"en":"He had been the first to turn a telescope to the sky, and he had seen there evidence enough to overthrow Aristotle and Ptolemy together.","zh":"他第一个把望远镜指向天空，并在那里看到了足以把亚里士多德和托勒密一并推翻的证据。","kind":"narration","speaker":"旁白"},{"en":"He was the man who climbed the Leaning Tower of Pisa and dropped various weights from the top, who rolled balls down inclined planes, and then generalized the results of his many experiments into the famous law of free fall.","zh":"他就是那个登上比萨斜塔、从塔顶放下各种重物的人，也是那个让球沿斜面滚下，然后把许多实验的结果概括成著名的自由落体定律的人。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"But a closer study of the evidence, supported by a deeper sense of the period, and particularly by a new consciousness of the philosophical undercurrents in the scientific revolution, has profoundly modified this view of Galileo.","zh":"然而，对证据作更仔细的研究，加上对那个时代更深的理解，特别是重新意识到科学革命背后的哲学暗流，已经深刻地改变了这种伽利略观。","kind":"narration","speaker":"旁白"},{"en":"Today, although the old Galileo lives on in many popular writings, among historians of science a new and more sophisticated picture has emerged.","zh":"如今，旧的伽利略形象虽仍活在许多通俗著作中，但在科学史家中，一个崭新而更复杂精细的形象已经出现。","kind":"narration","speaker":"旁白"},{"en":"At the same time our sympathy for Galileo's opponents has grown somewhat.","zh":"与此同时，我们对伽利略的反对者也多了几分同情。","kind":"narration","speaker":"旁白"},{"en":"His telescopic observations are justly immortal; they aroused great interest at the time, they had important theoretical consequences, and they provided a striking demonstration of the potentialities hidden in instruments and apparatus.","zh":"他的望远镜观测理当不朽；这些观测在当时引起了极大兴趣，产生了重要的理论影响，也鲜明地展示了仪器和设备中潜藏的种种可能。","kind":"narration","speaker":"旁白"},{"en":"But can we blame those who looked and failed to see what Galileo saw, if we remember that to use a telescope at the limit of its powers calls for long experience and intimate familiarity with one’s instrument?","zh":"不过，如果想到把望远镜的性能发挥到极限，需要长期经验和对仪器的深入熟悉，我们还能责怪那些看了却看不出伽利略所见之物的人吗？","kind":"narration","speaker":"旁白"},{"en":"Was the philosopher who refused to look through Galileo's telescope more culpable than those who alleged that the spiral nebulae observed with Lord Rosse’s great telescope in the eighteen-forties were scratches left by the grinder?","zh":"那个拒绝透过伽利略望远镜观看的哲学家，难道比另一些人更应受责备吗？后者曾宣称，十九世纪四十年代用罗斯勋爵的大望远镜观测到的旋涡星云，不过是磨镜人留下的划痕。","kind":"narration","speaker":"旁白"},{"en":"We can perhaps forgive those who said the moons of Jupiter were produced by Galileo's spyglass if we recall that in his day, as for centuries before, curved glass was the popular contrivance for producing not truth but illusion, untruth; and if a single curved glass would distort nature, how much more would a pair of them?","zh":"如果我们想起，在伽利略的时代以及此前几个世纪，曲面玻璃一向是用来制造幻象和假象、而非揭示真相的常见工具，我们也许就能原谅那些说木星卫星是伽利略的望远镜制造出来的人；既然一片曲面玻璃就会使自然景物变形，两片岂不会更严重？","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"long since","matchedForm":"long since","meaning":"早已","note":"通常与完成时或过去时连用，强调很久以前就已发生。","example":"In his own lifetime Galileo was the centre of violent controversy; but the scientific dust has long since settled, and today we can see even his famous clash with the Inquisition in something like its proper perspective.","exampleZh":"伽利略在世时曾是激烈争论的中心；但科学争论的尘埃早已落定，如今即使是他与宗教裁判所那场著名的冲突，我们也能够以近乎恰当的视角来看待。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"in perspective","matchedForm":"in something like its proper perspective","meaning":"以恰当视角看待","note":"put/see something in perspective 指结合背景衡量；something like 表示近似而非完全。","example":"In his own lifetime Galileo was the centre of violent controversy; but the scientific dust has long since settled, and today we can see even his famous clash with the Inquisition in something like its proper perspective.","exampleZh":"伽利略在世时曾是激烈争论的中心；但科学争论的尘埃早已落定，如今即使是他与宗教裁判所那场著名的冲突，我们也能够以近乎恰当的视角来看待。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"above all","matchedForm":"above all","meaning":"首先；最重要的是","note":"用于突出核心特征，不是空间上在所有东西之上。","example":"He was, above all, a man who experimented: who despised the prejudices and book learning of the Aristotelians, who put his questions to nature instead of to the ancients, and who drew his conclusions fearlessly.","exampleZh":"他首先是一个实验者：鄙视亚里士多德学派的偏见和书本知识，向自然发问而不向古人讨教，并且无所畏惧地得出自己的结论。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"call for","matchedForm":"calls for","meaning":"需要","note":"后接实现某事所必需的条件、能力或行动。","example":"But can we blame those who looked and failed to see what Galileo saw, if we remember that to use a telescope at the limit of its powers calls for long experience and intimate familiarity with one’s instrument?","exampleZh":"不过，如果想到把望远镜的性能发挥到极限，需要长期经验和对仪器的深入熟悉，我们还能责怪那些看了却看不出伽利略所见之物的人吗？","sourceParagraphIndex":2,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"how much more","matchedForm":"how much more","meaning":"岂不更……","note":"从较小情况推到更强情况的反问结构，常省略可从前文恢复的内容。","example":"We can perhaps forgive those who said the moons of Jupiter were produced by Galileo's spyglass if we recall that in his day, as for centuries before, curved glass was the popular contrivance for producing not truth but illusion, untruth; and if a single curved glass would distort nature, how much more would a pair of them?","exampleZh":"如果我们想起，在伽利略的时代以及此前几个世纪，曲面玻璃一向是用来制造幻象和假象、而非揭示真相的常见工具，我们也许就能原谅那些说木星卫星是伽利略的望远镜制造出来的人；既然一片曲面玻璃就会使自然景物变形，两片岂不会更严重？","sourceParagraphIndex":2,"sourceSentenceIndex":6,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l033","book":4,"number":33,"title":"Education","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Education is one of the key words of our time.","zh":"教育是我们时代的关键词之一。","kind":"narration","speaker":"旁白"},{"en":"A man without an education, many of us believe, is an unfortunate victim of adverse circumstances, deprived of one of the greatest twentieth-century opportunities.","zh":"我们许多人认为，一个没有受过教育的人，是恶劣环境的不幸牺牲者，被剥夺了二十世纪最重要的机会之一。","kind":"narration","speaker":"旁白"},{"en":"Convinced of the importance of education, modern states ‘invest’ in institutions of learning to get back ‘interest’ in the form of a large group of enlightened young men and women who are potential leaders.","zh":"现代国家确信教育的重要性，于是向教育机构“投资”，以一大批思想开明、具有领导潜能的青年男女作为收回的“利息”。","kind":"narration","speaker":"旁白"},{"en":"Education, with its cycles of instruction so carefully worked out, punctuated by textbooks—those purchasable wells of wisdom—what would civilization be like without its benefits?","zh":"教育有着精心安排的教学阶段，阶段之间又配置着教科书——那些花钱就能买到的智慧之泉；倘若没有教育的种种益处，文明会是什么样子呢？","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"So much is certain: that we would have doctors and preachers, lawyers and defendants, marriages and births—but our spiritual outlook would be different.","zh":"有一点是肯定的：我们仍会有医生和传教士、律师和被告，仍会有婚嫁和生育，但我们的精神面貌会不同。","kind":"narration","speaker":"旁白"},{"en":"We would lay less stress on ‘facts and figures’ and more on a good memory, on applied psychology, and on the capacity of a man to get along with his fellow-citizens.","zh":"我们会较少重视“事实和数字”，而更重视良好的记忆力、实用心理知识，以及人与其他公民和睦相处的能力。","kind":"narration","speaker":"旁白"},{"en":"If our educational system were fashioned after its bookless past we would have the most democratic form of ‘college’ imaginable.","zh":"假如我们的教育制度仿照从前没有书本的模式来构建，我们就会拥有想象得到的最民主的“学院”。","kind":"narration","speaker":"旁白"},{"en":"Among tribal people all knowledge inherited by tradition is shared by all; it is taught to every member of the tribe so that in this respect everybody is equally equipped for life.","zh":"在部落民族中，所有依靠传统继承下来的知识都是人人共享的；每个部落成员都会接受这些知识的传授，所以在这一点上，每个人都同样做好了生活的准备。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"It is the ideal condition of the ‘equal start’ which only our most progressive forms of modern education try to regain.","zh":"这正是“起点平等”的理想状态，而现代教育中只有最进步的形式，才试图重新获得它。","kind":"narration","speaker":"旁白"},{"en":"In primitive cultures the obligation to seek and to receive the traditional instruction is binding to all.","zh":"在原始文化中，寻求和接受传统教育是对所有人都有约束力的义务。","kind":"narration","speaker":"旁白"},{"en":"There are no ‘illiterates’—if the term can be applied to peoples without a script—while our own compulsory school attendance became law in Germany in 1642, in France in 1806, and in England in 1876, and is still non-existent in a number of ‘civilized’ nations.","zh":"那里没有“文盲”——假如这个词可以用来称呼没有文字的民族中的人——而我们自己的强制入学制度，直到德国的一六四二年、法国的一八〇六年、英国的一八七六年才成为法律，在许多“文明”国家甚至至今仍不存在。","kind":"narration","speaker":"旁白"},{"en":"This shows how long it was before we deemed it necessary to make sure that all our children could share in the knowledge accumulated by the ‘happy few’ during the past centuries.","zh":"这表明，过了何等漫长的岁月，我们才认为有必要确保所有孩子都能分享过去几个世纪里“幸运的少数人”积累的知识。","kind":"narration","speaker":"旁白"}]},{"index":3,"rows":[{"en":"Education in the wilderness is not a matter of monetary means.","zh":"荒野中的教育，不是钱财多寡的问题。","kind":"narration","speaker":"旁白"},{"en":"All are entitled to an equal start.","zh":"所有人都有权享有平等的起点。","kind":"narration","speaker":"旁白"},{"en":"There is none of the hurry which, in our society, often hampers the full development of a growing personality.","zh":"那里没有我们社会中的那种催赶，而这种催赶往往妨碍成长中的人格得到充分发展。","kind":"narration","speaker":"旁白"},{"en":"There, a child grows up under the ever-present attention of his parents; therefore the jungles and the savannahs know of no ‘juvenile delinquency’.","zh":"在那里，孩子在父母始终如一的关照下成长；所以，丛林和草原上没有“青少年犯罪”。","kind":"narration","speaker":"旁白"},{"en":"No necessity of making a living away from home results in neglect of children, and no father is confronted with his inability to ‘buy’ an education for his child.","zh":"父母不必因外出谋生而疏于照顾孩子，也没有哪个父亲会面对自己无力为孩子“买”教育的困境。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"in the form of","matchedForm":"in the form of","meaning":"以……的形式","note":"用于说明回报、帮助等具体采取的形式。","example":"Convinced of the importance of education, modern states ‘invest’ in institutions of learning to get back ‘interest’ in the form of a large group of enlightened young men and women who are potential leaders.","exampleZh":"现代国家确信教育的重要性，于是向教育机构“投资”，以一大批思想开明、具有领导潜能的青年男女作为收回的“利息”。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"lay stress on","matchedForm":"lay less stress on","meaning":"重视；强调","note":"stress 此处是名词，less/more 表示重视程度。","example":"We would lay less stress on ‘facts and figures’ and more on a good memory, on applied psychology, and on the capacity of a man to get along with his fellow-citizens.","exampleZh":"我们会较少重视“事实和数字”，而更重视良好的记忆力、实用心理知识，以及人与其他公民和睦相处的能力。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"get along with","matchedForm":"get along with","meaning":"与……相处","note":"后接人，通常指能和睦交往；也可加 well 表示相处融洽。","example":"We would lay less stress on ‘facts and figures’ and more on a good memory, on applied psychology, and on the capacity of a man to get along with his fellow-citizens.","exampleZh":"我们会较少重视“事实和数字”，而更重视良好的记忆力、实用心理知识，以及人与其他公民和睦相处的能力。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"make sure","matchedForm":"make sure","meaning":"确保","note":"可直接接 that 从句，此处省略 that。","example":"This shows how long it was before we deemed it necessary to make sure that all our children could share in the knowledge accumulated by the ‘happy few’ during the past centuries.","exampleZh":"这表明，过了何等漫长的岁月，我们才认为有必要确保所有孩子都能分享过去几个世纪里“幸运的少数人”积累的知识。","sourceParagraphIndex":2,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"be entitled to","matchedForm":"are entitled to","meaning":"有权享有","note":"to 后接名词或动词原形，此处后接 equal start。","example":"All are entitled to an equal start.","exampleZh":"所有人都有权享有平等的起点。","sourceParagraphIndex":3,"sourceSentenceIndex":1,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l034","book":4,"number":34,"title":"Adolescence","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Parents are often upset when their children praise the homes of their friends and regard it as a slur on their own cooking, or cleaning, or furniture, and often are foolish enough to let the adolescents see that they are annoyed.","zh":"孩子赞美朋友家时，父母往往感到不快，认为这是在贬低自家的饭菜、清洁或家具，而且常常愚蠢到让这些青春期孩子看出自己生气了。","kind":"narration","speaker":"旁白"},{"en":"They may even accuse them of disloyalty, or make some spiteful remark about the friends’ parents.","zh":"他们甚至可能责怪孩子不忠于自家，或对朋友的父母说些刻薄话。","kind":"narration","speaker":"旁白"},{"en":"Such a loss of dignity and descent into childish behaviour on the part of the adults deeply shocks the adolescents, and makes them resolve that in future they will not talk to their parents about the places or people they visit.","zh":"成年人如此丧失尊严，退而作出幼稚举动，会使青少年大为震惊，并决心今后不再向父母谈起自己到过的地方或见过的人。","kind":"narration","speaker":"旁白"},{"en":"Before very long the parents will be complaining that the child is so secretive and never tells them anything, but they seldom realize that they have brought this on themselves.","zh":"没过多久，父母就会抱怨孩子过分保密，什么都不告诉他们，却很少意识到这是他们自己招来的。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Disillusionment with the parents, however good and adequate they may be both as parents and as individuals, is to some degree inevitable.","zh":"不论父母作为家长和个人多么优秀、称职，孩子对他们的理想化信念破灭，在某种程度上仍是不可避免的。","kind":"narration","speaker":"旁白"},{"en":"Most children have such a high ideal of their parents, unless the parents themselves have been unsatisfactory, that it can hardly hope to stand up to a realistic evaluation.","zh":"除非父母本身表现得不尽如人意，多数孩子都会把父母想得极其完美，以至于这种理想化形象几乎不可能经得住现实的评价。","kind":"narration","speaker":"旁白"},{"en":"Parents would be greatly surprised and deeply touched if they realized how much belief their children usually have in their character and infallibility, and how much this faith means to a child.","zh":"如果父母意识到，孩子通常多么相信他们的品格与永不犯错，又意识到这种信念对孩子有多重要，父母一定会十分惊讶，深受感动。","kind":"narration","speaker":"旁白"},{"en":"If parents were prepared for this adolescent reaction, and realized that it was a sign that the child was growing up and developing valuable powers of observation and independent judgment, they would not be so hurt, and therefore would not drive the child into opposition by resenting and resisting it.","zh":"假如父母对青春期的这种反应有所准备，并明白这是孩子正在长大、正在培养宝贵的观察能力和独立判断力的迹象，他们便不会如此受伤，也就不会因愤恨和抵制这种反应，而把孩子推到对立面去。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"The adolescent, with his passion for sincerity, always respects a parent who admits that he is wrong, or ignorant, or even that he has been unfair or unjust.","zh":"青少年热切地追求真诚；对于肯承认自己犯错、无知，甚至曾经不公平、不公正的父母，他们总是尊重的。","kind":"narration","speaker":"旁白"},{"en":"What the child cannot forgive is the parents’ refusal to admit these charges if the child knows them to be true.","zh":"孩子不能原谅的是，当他明知这些指责属实，父母却拒绝承认。","kind":"narration","speaker":"旁白"}]},{"index":3,"rows":[{"en":"Victorian parents believed that they kept their dignity by retreating behind an unreasoning authoritarian attitude; in fact they did nothing of the kind, but children were then too cowed to let them know how they really felt.","zh":"维多利亚时代的父母相信，退到不讲道理的专制态度后面就能保住尊严；其实完全没有做到，但当时的孩子吓得太厉害，不敢让父母知道自己的真实感受。","kind":"narration","speaker":"旁白"},{"en":"Today we tend to go to the other extreme, but on the whole this is a healthier attitude both for the child and the parent.","zh":"如今我们往往走向另一个极端，不过总的说来，这种态度对孩子和父母都更健康。","kind":"narration","speaker":"旁白"},{"en":"It is always wiser and safer to face up to reality, however painful it may be at the moment.","zh":"直面现实总是更明智、更稳妥的，哪怕当下会感到痛苦。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"on the part of","matchedForm":"on the part of","meaning":"由……作出的；……方面的","note":"用于指出某行为或态度来自哪一方。","example":"Such a loss of dignity and descent into childish behaviour on the part of the adults deeply shocks the adolescents, and makes them resolve that in future they will not talk to their parents about the places or people they visit.","exampleZh":"成年人如此丧失尊严，退而作出幼稚举动，会使青少年大为震惊，并决心今后不再向父母谈起自己到过的地方或见过的人。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"bring on oneself","matchedForm":"brought this on themselves","meaning":"自己招来","note":"常指因自己的行为造成不好的后果，宾语放在 bring 与 on 之间。","example":"Before very long the parents will be complaining that the child is so secretive and never tells them anything, but they seldom realize that they have brought this on themselves.","exampleZh":"没过多久，父母就会抱怨孩子过分保密，什么都不告诉他们，却很少意识到这是他们自己招来的。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"stand up to","matchedForm":"stand up to","meaning":"经得住","note":"此处指承受检验或评价，不是起身面对某人。","example":"Most children have such a high ideal of their parents, unless the parents themselves have been unsatisfactory, that it can hardly hope to stand up to a realistic evaluation.","exampleZh":"除非父母本身表现得不尽如人意，多数孩子都会把父母想得极其完美，以至于这种理想化形象几乎不可能经得住现实的评价。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"on the whole","matchedForm":"on the whole","meaning":"总的来说","note":"综合考虑后作总体判断，容许个别例外。","example":"Today we tend to go to the other extreme, but on the whole this is a healthier attitude both for the child and the parent.","exampleZh":"如今我们往往走向另一个极端，不过总的说来，这种态度对孩子和父母都更健康。","sourceParagraphIndex":3,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"face up to","matchedForm":"face up to","meaning":"正视；勇敢面对","note":"比 face 更强调承认并应对困难的现实。","example":"It is always wiser and safer to face up to reality, however painful it may be at the moment.","exampleZh":"直面现实总是更明智、更稳妥的，哪怕当下会感到痛苦。","sourceParagraphIndex":3,"sourceSentenceIndex":2,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l035","book":4,"number":35,"title":"Space odyssey","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"The Moon is likely to become the industrial hub of the Solar System, supplying the rocket fuels for its ships, easily obtainable from the lunar rocks in the form of liquid oxygen.","zh":"月球很可能成为太阳系的工业中心，为宇宙飞船供应火箭燃料；这种燃料就是容易从月岩中获得的液态氧。","kind":"narration","speaker":"旁白"},{"en":"The reason lies in its gravity.","zh":"原因在于月球的引力。","kind":"narration","speaker":"旁白"},{"en":"Because the Moon has only an eightieth of the Earth’s mass, it requires 97 per cent less energy to travel the quarter of a million miles from the Moon to Earth-orbit than the 200 mile-journey from Earth's surface into orbit!","zh":"月球的质量只有地球的八十分之一，因此，从月球飞行二十五万英里到达地球轨道，所需能量竟比从地球表面飞行二百英里进入轨道少百分之九十七！","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"This may sound fantastic, but it is easily calculated.","zh":"这听来可能不可思议，但很容易计算出来。","kind":"narration","speaker":"旁白"},{"en":"To escape from the Earth in a rocket, one must travel at seven miles per second.","zh":"要乘火箭摆脱地球引力，必须达到每秒七英里的速度。","kind":"narration","speaker":"旁白"},{"en":"The comparable speed from the Moon is only 1.5 miles per second.","zh":"在月球上，相应的速度仅为每秒一点五英里。","kind":"narration","speaker":"旁白"},{"en":"Because the gravity on the Moon's surface is only a sixth of Earth’s (remember how easily the Apollo astronauts bounded along), it takes much less energy to accelerate to that 1.5 miles per second than it does on Earth.","zh":"月表引力只有地球的六分之一——想想阿波罗宇航员当年轻松跳跃前进的样子——因此，加速到每秒一点五英里所需的能量，比在地球上少得多。","kind":"narration","speaker":"旁白"},{"en":"Moon-dwellers will be able to fly in space at only three per cent of the cost of similar journeys by their terrestrial cousins.","zh":"月球居民进行太空飞行的费用，将仅为地球上的同胞进行类似旅行所需费用的百分之三。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"Arthur C. Clark once suggested a revolutionary idea passes through three phases:","zh":"阿瑟·C.克拉克曾提出，一个革命性构想会经历三个阶段：","kind":"narration","speaker":"旁白"}]},{"index":3,"rows":[{"en":"1 ‘It’s impossible — don’t waste my time.’","zh":"一、“不可能——别浪费我的时间。”","kind":"speech","speaker":"假想的公众反应"}]},{"index":4,"rows":[{"en":"2 ‘It’s possible, but not worth doing.’","zh":"二、“有可能，但不值得做。”","kind":"speech","speaker":"假想的公众反应"}]},{"index":5,"rows":[{"en":"3 ‘I said it was a good idea all along.’","zh":"三、“我一直就说这是个好主意。”","kind":"speech","speaker":"假想的公众反应"}]},{"index":6,"rows":[{"en":"The idea of colonising Mars — a world 160 times more distant than the Moon — will move decisively from the second phase to the third, when a significant number of people are living permanently in space.","zh":"火星的距离是月球的一百六十倍；当有相当数量的人永久居住在太空时，移居火星的构想就会明确地从第二阶段转入第三阶段。","kind":"narration","speaker":"旁白"},{"en":"Mars has an extraordinary fascination for would-be voyagers.","zh":"对于那些想去远航的人，火星有着非同寻常的吸引力。","kind":"narration","speaker":"旁白"},{"en":"America, Russia and Europe are filled with enthusiasts — many of them serious and senior scientists — who dream of sending people to it.","zh":"美国、俄罗斯和欧洲都有大量怀抱热情的人，其中许多是严谨而资深的科学家，梦想着把人送到火星。","kind":"narration","speaker":"旁白"},{"en":"Their aim is understandable.","zh":"他们的目标可以理解。","kind":"narration","speaker":"旁白"},{"en":"It is the one world in the Solar System that is most like the Earth.","zh":"在太阳系各个世界中，火星与地球最为相似。","kind":"narration","speaker":"旁白"},{"en":"It is a world of red sandy deserts (hence its name — the Red Planet), cloudless skies, savage sandstorms, chasms wider than the Grand Canyon and at least one mountain more than twice as tall as Everest.","zh":"那是一个有着红色沙漠、无云天空、猛烈沙暴、比大峡谷更宽的深渊，以及至少一座高度超过珠穆朗玛峰两倍的山峰的世界——也正因那红色沙漠，它才被称为“红色行星”。","kind":"narration","speaker":"旁白"},{"en":"It seems ideal for settlement.","zh":"它似乎是理想的定居之地。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"lie in","matchedForm":"lies in","meaning":"在于","note":"常用于指出原因、问题或价值所在，后接关键因素。","example":"The reason lies in its gravity.","exampleZh":"原因在于月球的引力。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"escape from","matchedForm":"escape from","meaning":"逃离；摆脱","note":"from 引出离开的地方或摆脱的力量；这里指火箭摆脱地球引力。","example":"To escape from the Earth in a rocket, one must travel at seven miles per second.","exampleZh":"要乘火箭摆脱地球引力，必须达到每秒七英里的速度。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"all along","matchedForm":"all along","meaning":"一直；从一开始就","note":"强调某事贯穿整个过程，此处带有事后自称先见之明的讽刺。","example":"3 ‘I said it was a good idea all along.’","exampleZh":"三、“我一直就说这是个好主意。”","sourceParagraphIndex":5,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"would-be voyagers","matchedForm":"would-be voyagers","meaning":"想成为远航者的人","note":"would-be 作定语表示怀有某种志向，不保证已经实现。","example":"Mars has an extraordinary fascination for would-be voyagers.","exampleZh":"对于那些想去远航的人，火星有着非同寻常的吸引力。","sourceParagraphIndex":6,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"dream of","matchedForm":"dream of","meaning":"梦想","note":"of 后接名词或动名词，表示渴望实现某事。","example":"America, Russia and Europe are filled with enthusiasts — many of them serious and senior scientists — who dream of sending people to it.","exampleZh":"美国、俄罗斯和欧洲都有大量怀抱热情的人，其中许多是严谨而资深的科学家，梦想着把人送到火星。","sourceParagraphIndex":6,"sourceSentenceIndex":2,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l036","book":4,"number":36,"title":"The cost of government","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"If a nation is essentially disunited, it is left to the government to hold it together.","zh":"如果一个国家根本上缺乏团结，维系它的任务便落在政府身上。","kind":"narration","speaker":"旁白"},{"en":"This increases the expense of government, and reduces correspondingly the amount of economic resources that could be used for developing the country.","zh":"这会增加政府的开支，并相应减少本可用于国家发展的经济资源。","kind":"narration","speaker":"旁白"},{"en":"And it should not be forgotten how small those resources are in a poor and backward country.","zh":"而且，我们不应忘记，在一个贫穷落后的国家，这些资源原本就少得可怜。","kind":"narration","speaker":"旁白"},{"en":"Where the cost of government is high, resources for development are correspondingly low.","zh":"政府开支高，用于发展的资源就相应少。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"This may be illustrated by comparing the position of a nation with that of a private business enterprise.","zh":"把国家的处境与私人企业作比较，可以说明这一点。","kind":"narration","speaker":"旁白"},{"en":"An enterprise has to incur certain costs and expenses in order to stay in business.","zh":"企业为了继续经营，必须承担一定的成本和费用。","kind":"narration","speaker":"旁白"},{"en":"For our purposes, we are concerned only with one kind of cost—the cost of managing and administering the business.","zh":"就这里的讨论而言，我们只关心一种费用——经营管理企业的费用。","kind":"narration","speaker":"旁白"},{"en":"Such administrative overheads in a business are analogous to the cost of government in a nation.","zh":"企业的这种行政管理间接费用，与国家的政府开支相类似。","kind":"narration","speaker":"旁白"},{"en":"The administrative overheads of a business are low to the extent that everyone working in the business can be trusted to behave in a way that best promotes the interests of the firm.","zh":"企业里每个人越是值得信任，能够以最有利于公司利益的方式行事，企业的行政管理费用就越低。","kind":"narration","speaker":"旁白"},{"en":"If they can each be trusted to take such responsibilities, and to exercise such initiative as falls within their sphere, then administrative overheads will be low.","zh":"如果可以相信每个人都会在自己的职责范围内承担责任、发挥主动性，行政管理费用就会低。","kind":"narration","speaker":"旁白"},{"en":"It will be low because it will be necessary to have only one man looking after each job, without having another man to check upon what he is doing, keep him in line, and report on him to someone else.","zh":"之所以低，是因为每项工作只需一个人负责，不必再安排另一个人检查他的所作所为，管束他，并向其他人汇报他的情况。","kind":"narration","speaker":"旁白"},{"en":"But if no one can be trusted to act in a loyal and responsible manner towards his job, then the business will require armies of administrators, checkers, and foremen, and administrative overheads will rise correspondingly.","zh":"但如果没有人能够在工作上忠诚而负责地行事，企业就会需要大批管理员、检查员和领班，行政管理费用也会随之上涨。","kind":"narration","speaker":"旁白"},{"en":"As administrative overheads rise, so the earnings of the business after meeting the expense of administration, will fall; and the business will have less money to distribute as dividends or invest directly in its future progress and development.","zh":"随着行政管理费用上涨，企业扣除管理支出后的收益便会下降，可用于发放股息或直接投资于未来进步与发展的资金也就减少。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"It is precisely the same with a nation.","zh":"国家的情况完全相同。","kind":"narration","speaker":"旁白"},{"en":"To the extent that the people can be relied upon to behave in a loyal and responsible manner, the government does not require armies of police and civil servants to keep them in order.","zh":"只要人民值得信赖，能忠诚而负责地行事，政府就不需要大批警察和公务员来维持秩序。","kind":"narration","speaker":"旁白"},{"en":"But if a nation is disunited, the government cannot be sure that the actions of the people will be in the interests of the nation; and it will have to watch, check, and control the people accordingly.","zh":"但如果国家不团结，政府就无法确信人民的行为会符合国家利益，于是便不得不相应地监视、检查和控制人民。","kind":"narration","speaker":"旁白"},{"en":"A disunited nation therefore has to incur unduly high costs of government.","zh":"因此，一个不团结的国家必定要承担过高的政府开支。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"stay in business","matchedForm":"stay in business","meaning":"维持经营","note":"强调企业继续运转、未退出市场的状态。","example":"An enterprise has to incur certain costs and expenses in order to stay in business.","exampleZh":"企业为了继续经营，必须承担一定的成本和费用。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"be analogous to","matchedForm":"are analogous to","meaning":"与……类似","note":"正式表达，说明两个事物在结构或关系上可作类比。","example":"Such administrative overheads in a business are analogous to the cost of government in a nation.","exampleZh":"企业的这种行政管理间接费用，与国家的政府开支相类似。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"to the extent that","matchedForm":"to the extent that","meaning":"在……程度上；越是……越……","note":"将结果与条件成立的程度相联，此处信任程度决定管理成本。","example":"The administrative overheads of a business are low to the extent that everyone working in the business can be trusted to behave in a way that best promotes the interests of the firm.","exampleZh":"企业里每个人越是值得信任，能够以最有利于公司利益的方式行事，企业的行政管理费用就越低。","sourceParagraphIndex":1,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"keep in line","matchedForm":"keep him in line","meaning":"管束；使守规矩","note":"keep someone in line 表示监督其遵守要求。","example":"It will be low because it will be necessary to have only one man looking after each job, without having another man to check upon what he is doing, keep him in line, and report on him to someone else.","exampleZh":"之所以低，是因为每项工作只需一个人负责，不必再安排另一个人检查他的所作所为，管束他，并向其他人汇报他的情况。","sourceParagraphIndex":1,"sourceSentenceIndex":6,"sourceType":"textbook-passage"},{"phrase":"in the interests of","matchedForm":"in the interests of","meaning":"符合……利益；为了……利益","note":"interests 常用复数，表示某人或群体的利益。","example":"But if a nation is disunited, the government cannot be sure that the actions of the people will be in the interests of the nation; and it will have to watch, check, and control the people accordingly.","exampleZh":"但如果国家不团结，政府就无法确信人民的行为会符合国家利益，于是便不得不相应地监视、检查和控制人民。","sourceParagraphIndex":2,"sourceSentenceIndex":2,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l037","book":4,"number":37,"title":"The process of ageing","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"At the age of twelve years, the human body is at its most vigorous.","zh":"十二岁时，人体的生命力最旺盛。","kind":"narration","speaker":"旁白"},{"en":"It has yet to reach its full size and strength, and its owner his or her full intelligence; but at this age the likelihood of death is least.","zh":"身体的大小与力量尚未完全长成，人的智力也尚未充分发展，但这个年龄死亡的可能性最低。","kind":"narration","speaker":"旁白"},{"en":"Earlier, we were infants and young children, and consequently more vulnerable; later, we shall undergo a progressive loss of our vigour and resistance which, though imperceptible at first, will finally become so steep that we can live no longer, however well we look after ourselves, and however well society, and our doctors, look after us.","zh":"此前，我们是婴儿和幼童，因此更加脆弱；此后，我们的活力和抵抗力便会逐步衰退，起初虽然察觉不到，最终却会急剧衰退到无法继续生存的程度，无论我们自己多么精心保养，也无论社会和医生如何周到地照料我们。","kind":"narration","speaker":"旁白"},{"en":"This decline in vigour with the passing of time is called ageing.","zh":"这种随时间流逝而出现的活力衰退，就叫衰老。","kind":"narration","speaker":"旁白"},{"en":"It is one of the most unpleasant discoveries which we all make that we must decline in this way, that if we escape wars, accidents and diseases we shall eventually ‘die of old age’, and that this happens at a rate which differs little from person to person, so that there are heavy odds in favour of our dying between the ages of sixty-five and eighty.","zh":"我们都会发现一个极其令人不快的事实：自己必定会这样衰退，即使躲过战争、意外和疾病，最终也会“老死”；而这种过程的速度在人与人之间相差很小，因此我们很有可能在六十五岁到八十岁之间去世。","kind":"narration","speaker":"旁白"},{"en":"Some of us will die sooner, a few will live longer—on into a ninth or tenth decade.","zh":"我们有些人会早些去世，少数会活得更久，活到八九十岁。","kind":"narration","speaker":"旁白"},{"en":"But the chances are against it, and there is a virtual limit on how long we can hope to remain alive, however lucky and robust we are.","zh":"不过，这种长寿的机会并不大；无论我们多么幸运、健壮，能够期望活多久，实际上总有一个限度。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Normal people tend to forget this process unless and until they are reminded of it.","zh":"一般人往往会忘记这个过程，除非有人提醒，才会想起来。","kind":"narration","speaker":"旁白"},{"en":"We are so familiar with the fact that man ages, that people have for years assumed that the process of losing vigour with time, of becoming more likely to die the older we get, was something self-evident, like the cooling of a hot kettle or the wearing-out of a pair of shoes.","zh":"人会衰老这个事实，我们实在太熟悉了，以至于多年来人们一直以为，活力随时间衰退、年纪越大越容易死亡的过程，是不言自明的，就像热水壶冷却或鞋子穿坏一样。","kind":"narration","speaker":"旁白"},{"en":"They have also assumed that all animals, and probably other organisms such as trees, or even the universe itself, must in the nature of things ‘wear out’.","zh":"人们也以为，一切动物，或许还有树木等其他生物，甚至宇宙本身，都必然会依事物的本性而“耗损殆尽”。","kind":"narration","speaker":"旁白"},{"en":"Most animals we commonly observe do in fact age as we do, if given the chance to live long enough; and mechanical systems like a wound watch, or the sun, do in fact run out of energy in accordance with the second law of thermodynamics (whether the whole universe does so is a moot point at present).","zh":"我们通常见到的大多数动物，如果有机会活得足够长，确实也像我们一样衰老；上了发条的表或太阳这样的机械性系统，也确实会依照热力学第二定律耗尽能量（整个宇宙是否如此，目前仍有争议）。","kind":"narration","speaker":"旁白"},{"en":"But these are not analogous to what happens when man ages.","zh":"但这些与人衰老时发生的情况并不相同。","kind":"narration","speaker":"旁白"},{"en":"A run-down watch is still a watch and can be rewound.","zh":"发条走尽的表仍然是一只表，还可以重新上弦。","kind":"narration","speaker":"旁白"},{"en":"An old watch, by contrast, becomes so worn and unreliable that it eventually is not worth mending.","zh":"相比之下，旧表会磨损得如此严重、运行如此不可靠，最终不值得再修。","kind":"narration","speaker":"旁白"},{"en":"But a watch could never repair itself—it does not consist of living parts, only of metal, which wears away by friction.","zh":"不过，表永远不会自我修复；它不是由活的部件组成的，而只是由金属构成，金属会因摩擦而磨损。","kind":"narration","speaker":"旁白"},{"en":"We could, at one time, repair ourselves—well enough, at least, to overcome all but the most instantly fatal illnesses and accidents.","zh":"我们曾经能够自我修复，至少修复能力足以克服除了那些极其迅速致命的疾病和意外之外的一切病伤。","kind":"narration","speaker":"旁白"},{"en":"Between twelve and eighty years we gradually lose this power; an illness which at twelve would knock us over, at eighty can knock us out, and into our grave.","zh":"从十二岁到八十岁，我们渐渐失去这种能力；一种病在十二岁时只会使我们病倒，到了八十岁却可能把我们彻底击垮，送进坟墓。","kind":"narration","speaker":"旁白"},{"en":"If we could stay as vigorous as we are at twelve, it would take about 700 years for half of us to die, and another 700 for the survivors to be reduced by half again.","zh":"假如我们能一直保持十二岁时的旺盛活力，那么大约要经过七百年，我们当中才会有一半人死去；再过七百年，幸存者才会再减少一半。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"have yet to","matchedForm":"has yet to","meaning":"尚未","note":"后接动词原形，表示预期会发生但截至目前还未发生。","example":"It has yet to reach its full size and strength, and its owner his or her full intelligence; but at this age the likelihood of death is least.","exampleZh":"身体的大小与力量尚未完全长成，人的智力也尚未充分发展，但这个年龄死亡的可能性最低。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"die of old age","matchedForm":"die of old age","meaning":"因年老而去世","note":"die of 后接死亡原因；保留原文引号，表示对这一惯常说法的引用。","example":"It is one of the most unpleasant discoveries which we all make that we must decline in this way, that if we escape wars, accidents and diseases we shall eventually ‘die of old age’, and that this happens at a rate which differs little from person to person, so that there are heavy odds in favour of our dying between the ages of sixty-five and eighty.","exampleZh":"我们都会发现一个极其令人不快的事实：自己必定会这样衰退，即使躲过战争、意外和疾病，最终也会“老死”；而这种过程的速度在人与人之间相差很小，因此我们很有可能在六十五岁到八十岁之间去世。","sourceParagraphIndex":0,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"in the nature of things","matchedForm":"in the nature of things","meaning":"按事物本性；自然而然地","note":"表示认为某结果出于事物固有规律。","example":"They have also assumed that all animals, and probably other organisms such as trees, or even the universe itself, must in the nature of things ‘wear out’.","exampleZh":"人们也以为，一切动物，或许还有树木等其他生物，甚至宇宙本身，都必然会依事物的本性而“耗损殆尽”。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"run out of","matchedForm":"run out of","meaning":"耗尽","note":"主语是消耗者，of 后接能量、资源等。","example":"Most animals we commonly observe do in fact age as we do, if given the chance to live long enough; and mechanical systems like a wound watch, or the sun, do in fact run out of energy in accordance with the second law of thermodynamics (whether the whole universe does so is a moot point at present).","exampleZh":"我们通常见到的大多数动物，如果有机会活得足够长，确实也像我们一样衰老；上了发条的表或太阳这样的机械性系统，也确实会依照热力学第二定律耗尽能量（整个宇宙是否如此，目前仍有争议）。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"a moot point","matchedForm":"a moot point","meaning":"尚有争议的问题","note":"moot 表示可争论、尚无定论，并非已经证实。","example":"Most animals we commonly observe do in fact age as we do, if given the chance to live long enough; and mechanical systems like a wound watch, or the sun, do in fact run out of energy in accordance with the second law of thermodynamics (whether the whole universe does so is a moot point at present).","exampleZh":"我们通常见到的大多数动物，如果有机会活得足够长，确实也像我们一样衰老；上了发条的表或太阳这样的机械性系统，也确实会依照热力学第二定律耗尽能量（整个宇宙是否如此，目前仍有争议）。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l038","book":4,"number":38,"title":"Water and the traveller","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Contamination of water supplies is usually due to poor sanitation close to water sources, sewage disposal into the sources themselves, leakage of sewage into distribution systems or contamination with industrial or farm waste.","zh":"供水受到污染，通常是因为水源附近卫生条件差、污水直接排入水源、污水渗漏进输配水系统，或被工业和农业废弃物污染。","kind":"narration","speaker":"旁白"},{"en":"Even if a piped water supply is safe at its source, it is not always safe by the time it reaches the tap.","zh":"即使管道供水在源头是安全的，到达水龙头时也未必仍然安全。","kind":"narration","speaker":"旁白"},{"en":"Intermittent tap-water supplies should be regarded as particularly suspect.","zh":"供水时断时续的自来水尤其应被视为可疑。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Travellers on short trips to areas with water supplies of uncertain quality should avoid drinking tap-water, or untreated water from any other source.","zh":"短期前往水质不确定地区的旅行者，应避免饮用自来水，也不要喝任何其他来源的未经处理的水。","kind":"narration","speaker":"旁白"},{"en":"It is best to keep to hot drinks, bottled or canned drinks of well-known brand names—international standards of water treatment are usually followed at bottling plants.","zh":"最好只喝热饮和知名品牌的瓶装或罐装饮料，因为装瓶厂通常遵循国际水处理标准。","kind":"narration","speaker":"旁白"},{"en":"Carbonated drinks are acidic, and slightly safer.","zh":"碳酸饮料呈酸性，稍微安全一些。","kind":"narration","speaker":"旁白"},{"en":"Make sure that all bottles are opened in your presence, and that their rims are clean and dry.","zh":"要确保所有瓶子都当着你的面打开，而且瓶口清洁、干燥。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"Boiling is always a good way of treating water.","zh":"把水煮沸始终是一种很好的处理办法。","kind":"narration","speaker":"旁白"},{"en":"Some hotels supply boiled water on request and this can be used for drinking, or for brushing teeth.","zh":"有些旅馆可应要求提供开水，这些水可用于饮用或刷牙。","kind":"narration","speaker":"旁白"},{"en":"Portable boiling elements that can boil small quantities of water are useful when the right voltage of electricity is available.","zh":"如果能获得电压合适的电源，可煮沸少量水的便携式加热器很有用。","kind":"narration","speaker":"旁白"},{"en":"Refuse politely any cold drink from an unknown source.","zh":"对于任何来源不明的冷饮，都应礼貌地谢绝。","kind":"narration","speaker":"旁白"}]},{"index":3,"rows":[{"en":"Ice is only as safe as the water from which it is made, and should not be put in drinks unless it is known to be safe.","zh":"冰的安全程度只与制冰用水相当，除非确定安全，否则不应放进饮料里。","kind":"narration","speaker":"旁白"},{"en":"Drinks can be cooled by placing them on ice rather than adding ice to them.","zh":"可以把饮料放在冰上降温，而不是把冰加进饮料。","kind":"narration","speaker":"旁白"}]},{"index":4,"rows":[{"en":"Alcohol may be a medical disinfectant, but should not be relied upon to sterilize water.","zh":"酒精虽可作医用消毒剂，却不应被用来保证水的灭菌。","kind":"narration","speaker":"旁白"},{"en":"Ethanol is more effective at a concentration of 50-70 per cent; below 20 per cent, its bactericidal action is negligible.","zh":"乙醇在浓度为百分之五十至七十时更有效；低于百分之二十时，其杀菌作用微乎其微。","kind":"narration","speaker":"旁白"},{"en":"Spirits labelled 95 proof contain only about 47 per cent alcohol.","zh":"标为九十五 proof 的烈酒，酒精含量其实只有约百分之四十七。","kind":"narration","speaker":"旁白"},{"en":"Beware of methylated alcohol, which is very poisonous, and should never be added to drinking water.","zh":"要提防变性酒精，它毒性很强，绝不能加入饮用水中。","kind":"narration","speaker":"旁白"}]},{"index":5,"rows":[{"en":"If no other safe water supply can be obtained, tap water that is too hot to touch can be left to cool and is generally safe to drink.","zh":"如果没有其他安全水源，可以把烫得不能碰的自来水放凉，一般可以安全饮用。","kind":"narration","speaker":"旁白"},{"en":"Those planning a trip to remote areas, or intending to live in countries where drinking water is not readily available, should know about the various possible methods for making water safe.","zh":"计划去偏远地区旅行，或准备在不容易获得饮用水的国家居住的人，应该了解使水变得安全的各种可行方法。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"be due to","matchedForm":"is usually due to","meaning":"由于","note":"due to 后接名词性原因；usually 限定为通常情况。","example":"Contamination of water supplies is usually due to poor sanitation close to water sources, sewage disposal into the sources themselves, leakage of sewage into distribution systems or contamination with industrial or farm waste.","exampleZh":"供水受到污染，通常是因为水源附近卫生条件差、污水直接排入水源、污水渗漏进输配水系统，或被工业和农业废弃物污染。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"keep to","matchedForm":"keep to","meaning":"坚持只用；限于","note":"此处建议将饮品选择限制在列出的类别。","example":"It is best to keep to hot drinks, bottled or canned drinks of well-known brand names—international standards of water treatment are usually followed at bottling plants.","exampleZh":"最好只喝热饮和知名品牌的瓶装或罐装饮料，因为装瓶厂通常遵循国际水处理标准。","sourceParagraphIndex":1,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"in one’s presence","matchedForm":"in your presence","meaning":"当着……的面","note":"指有人在场并能看到事情发生。","example":"Make sure that all bottles are opened in your presence, and that their rims are clean and dry.","exampleZh":"要确保所有瓶子都当着你的面打开，而且瓶口清洁、干燥。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"on request","matchedForm":"on request","meaning":"应要求","note":"表示提出要求后即可提供服务，不表示自动供应。","example":"Some hotels supply boiled water on request and this can be used for drinking, or for brushing teeth.","exampleZh":"有些旅馆可应要求提供开水，这些水可用于饮用或刷牙。","sourceParagraphIndex":2,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"beware of","matchedForm":"Beware of","meaning":"当心；提防","note":"常用于提示危险，of 后接需警惕的事物。","example":"Beware of methylated alcohol, which is very poisonous, and should never be added to drinking water.","exampleZh":"要提防变性酒精，它毒性很强，绝不能加入饮用水中。","sourceParagraphIndex":4,"sourceSentenceIndex":3,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l039","book":4,"number":39,"title":"What every writer wants","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"I have known very few writers, but those I have known, and whom I respect, confess at once that they have little idea where they are going when they first set pen to paper.","zh":"我认识的作家很少，但那些我认识而且尊敬的作家，都会坦然承认：刚落笔时，他们几乎不知道自己将写向何处。","kind":"narration","speaker":"旁白"},{"en":"They have a character, perhaps two; they are in that condition of eager discomfort which passes for inspiration; all admit radical changes of destination once the journey has begun; one, to my certain knowledge, spent nine months on a novel about Kashmir, then reset the whole thing in the Scottish Highlands.","zh":"他们也许有一个人物，或两个人物；他们处于一种迫切而不安、被称作灵感的状态；他们都承认，开始创作之后，原定的方向会出现根本改变；其中一位，据我确切所知，花了九个月写一部以克什米尔为背景的小说，后来又把整部作品的背景改设在苏格兰高地。","kind":"narration","speaker":"旁白"},{"en":"I never heard of anyone making a ‘skeleton’, as we were taught at school.","zh":"我从没听说谁会像我们在学校里所学的那样，先列一个“骨架”。","kind":"narration","speaker":"旁白"},{"en":"In the breaking and remaking, in the timing, interweaving, beginning afresh, the writer comes to discern things in his material which were not consciously in his mind when he began.","zh":"在打破与重塑、安排节奏、穿插情节、重新开始的过程中，作家逐渐辨认出素材中一些起初并未清楚意识到的东西。","kind":"narration","speaker":"旁白"},{"en":"This organic process, often leading to moments of extraordinary self-discovery, is of an indescribable fascination.","zh":"这个有机发展的过程，常常使人获得非同寻常的自我发现，其魅力无法形容。","kind":"narration","speaker":"旁白"},{"en":"A blurred image appears; he adds a brushstroke and another, and it is gone; but something was there, and he will not rest till he has captured it.","zh":"一个模糊的形象浮现了；他添上一笔，再添一笔，它却消失了；可那里确实曾有过什么，而他不捕捉到它便不会罢休。","kind":"narration","speaker":"旁白"},{"en":"Sometimes the yeast within a writer outlives a book he has written.","zh":"有时，作家内心发酵的创作冲动，在一本书写完之后还会继续存在。","kind":"narration","speaker":"旁白"},{"en":"I have heard of writers who read nothing but their own books; like adolescents they stand before the mirror, and still cannot fathom the exact outline of the vision before them.","zh":"我听说过一些作家，他们除了自己的书什么也不读；他们像青少年一样站在镜前，却仍然摸不清眼前影像的准确轮廓。","kind":"narration","speaker":"旁白"},{"en":"For the same reason, writers talk interminably about their own books, winkling out hidden meanings, super-imposing new ones, begging response from those around them.","zh":"出于同样的原因，作家会没完没了地谈论自己的书，挖掘隐藏的意义，再叠加新的意义，恳求周围人给予回应。","kind":"narration","speaker":"旁白"},{"en":"Of course a writer doing this is misunderstood: he might as well try to explain a crime or a love affair.","zh":"当然，作家这样做会被人误解；他还不如试着去解释一桩罪行或一场恋情。","kind":"narration","speaker":"旁白"},{"en":"He is also, incidentally, an unforgivable bore.","zh":"顺便说一句，他也会变成一个让人无法原谅的讨厌鬼。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"This temptation to cover the distance between himself and the reader, to study his image in the sight of those who do not know him, can be his undoing: he has begun to write to please.","zh":"想要消除自己与读者之间的距离，想从那些不了解自己的人的眼中研究自己的形象，这种诱惑可能毁掉他：他已开始为了取悦别人而写作。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"A young English writer made the pertinent observation a year or two back that the talent goes into the first draft, and the art into the drafts that follow.","zh":"一两年前，一位年轻的英国作家作过一个贴切的观察：才华倾注在初稿里，艺术则体现在之后一遍遍的改稿中。","kind":"narration","speaker":"旁白"},{"en":"For this reason also the writer, like any other artist, has no resting place, no crowd or movement in which he may take comfort, no judgment from outside which can replace the judgment from within.","zh":"也是因为这个缘故，作家像任何其他艺术家一样，没有安歇之所，没有可从中寻得慰藉的人群或运动，也没有任何外来的判断能取代内心的判断。","kind":"narration","speaker":"旁白"},{"en":"A writer makes order out of the anarchy of his heart; he submits himself to a more ruthless discipline than any critic dreamed of, and when he flirts with fame, he is taking time off from living with himself, from the search for what his world contains at its inmost point.","zh":"作家从自己内心的混乱中创造秩序；他让自己服从比任何评论家所能想象的都更严酷的约束；而当他向名声调情时，不过是暂时离开与自己相处的生活，暂时放下对自己世界最深处究竟包含什么的探索。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"set pen to paper","matchedForm":"set pen to paper","meaning":"动笔；开始写作","note":"固定表达，常用于谈写作起点。","example":"I have known very few writers, but those I have known, and whom I respect, confess at once that they have little idea where they are going when they first set pen to paper.","exampleZh":"我认识的作家很少，但那些我认识而且尊敬的作家，都会坦然承认：刚落笔时，他们几乎不知道自己将写向何处。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"pass for","matchedForm":"passes for","meaning":"被当作；被认为是","note":"常暗示名不副实或说话者有所保留，此处形容所谓灵感。","example":"They have a character, perhaps two; they are in that condition of eager discomfort which passes for inspiration; all admit radical changes of destination once the journey has begun; one, to my certain knowledge, spent nine months on a novel about Kashmir, then reset the whole thing in the Scottish Highlands.","exampleZh":"他们也许有一个人物，或两个人物；他们处于一种迫切而不安、被称作灵感的状态；他们都承认，开始创作之后，原定的方向会出现根本改变；其中一位，据我确切所知，花了九个月写一部以克什米尔为背景的小说，后来又把整部作品的背景改设在苏格兰高地。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"might as well","matchedForm":"might as well","meaning":"还不如；倒不如","note":"后接动词原形，此处用另一个同样难以说清的事情作反讽。","example":"Of course a writer doing this is misunderstood: he might as well try to explain a crime or a love affair.","exampleZh":"当然，作家这样做会被人误解；他还不如试着去解释一桩罪行或一场恋情。","sourceParagraphIndex":0,"sourceSentenceIndex":9,"sourceType":"textbook-passage"},{"phrase":"take comfort","matchedForm":"take comfort","meaning":"得到慰藉","note":"常搭配 in 或 from，引出慰藉来源；原文用 in which。","example":"For this reason also the writer, like any other artist, has no resting place, no crowd or movement in which he may take comfort, no judgment from outside which can replace the judgment from within.","exampleZh":"也是因为这个缘故，作家像任何其他艺术家一样，没有安歇之所，没有可从中寻得慰藉的人群或运动，也没有任何外来的判断能取代内心的判断。","sourceParagraphIndex":2,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"take time off from","matchedForm":"taking time off from","meaning":"暂时中断","note":"from 后接名词或动名词，表示暂离平日持续进行的活动。","example":"A writer makes order out of the anarchy of his heart; he submits himself to a more ruthless discipline than any critic dreamed of, and when he flirts with fame, he is taking time off from living with himself, from the search for what his world contains at its inmost point.","exampleZh":"作家从自己内心的混乱中创造秩序；他让自己服从比任何评论家所能想象的都更严酷的约束；而当他向名声调情时，不过是暂时离开与自己相处的生活，暂时放下对自己世界最深处究竟包含什么的探索。","sourceParagraphIndex":2,"sourceSentenceIndex":2,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l040","book":4,"number":40,"title":"Waves","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Waves are the children of the struggle between ocean and atmosphere, the ongoing signatures of infinity.","zh":"波浪是海洋与大气搏斗的产物，是无穷世界不断写下的印记。","kind":"narration","speaker":"旁白"},{"en":"Rays from the sun excite and energize the atmosphere of the earth, awakening it to flow, to movement, to rhythm, to life.","zh":"太阳的光芒激发地球的大气，赋予它能量，使它苏醒，开始流动，开始运动，获得节奏，获得生命。","kind":"narration","speaker":"旁白"},{"en":"The wind then speaks the message of the sun to the sea and the sea transmits it on through waves—an ancient, exquisite, powerful message.","zh":"接着，风把太阳的信息诉说给大海，大海又通过波浪继续传递它——一个古老、精妙而强有力的信息。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"These ocean waves are among the earth’s most complicated natural phenomena.","zh":"这些海浪是地球上最复杂的自然现象之一。","kind":"narration","speaker":"旁白"},{"en":"The basic features include a crest (the highest point of the wave), a trough (the lowest point), a height (the vertical distance from the trough to the crest), a wave length (the horizontal distance between two wave crests), and a period (which is the time it takes a wave crest to travel one wave length).","zh":"它们的基本特征包括波峰（波浪的最高点）、波谷（最低点）、波高（波谷到波峰的垂直距离）、波长（两个波峰间的水平距离）以及周期（一个波峰前进一个波长所需的时间）。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"Although an ocean wave gives the impression of a wall of water moving in your direction, in actuality waves move through the water leaving the water about where it was.","zh":"海浪虽然给人一种水墙迎面移来的印象，但实际上，波是在水中传播，水却大致留在原处。","kind":"narration","speaker":"旁白"},{"en":"If the water was moving with the wave, the ocean and everything on it would be racing in to the shore with obviously catastrophic results.","zh":"如果水也随着波浪移动，那么海洋以及海上的一切都会向岸边狂奔，结果显然会是灾难性的。","kind":"narration","speaker":"旁白"}]},{"index":3,"rows":[{"en":"An ocean wave passing through deep water causes a particle on the surface to move in a roughly circular orbit, drawing the particle first towards the advancing wave, then up into the wave, then forward with it and then—as the wave leaves the particles behind—back to its starting point again.","zh":"海浪通过深水时，会使水面上的一个质点沿大致呈圆形的轨道运动：先把它拉向正在前进的波浪，再向上带入波中，接着让它随波向前，随后当波浪把质点留在身后时，又使它回到起点。","kind":"narration","speaker":"旁白"}]},{"index":4,"rows":[{"en":"From both maturity to death, a wave is subject to the same laws as any other ‘living’ thing.","zh":"从成熟到消亡，波浪与任何其他“活的”事物一样，都受同样的规律支配。","kind":"narration","speaker":"旁白"},{"en":"For a time it assumes a miraculous individuality that, in the end, is reabsorbed into the great ocean of life.","zh":"它暂时呈现出一种奇妙的个体性，最终这种个体性又被重新吸收到生命的大海之中。","kind":"narration","speaker":"旁白"}]},{"index":5,"rows":[{"en":"The undulating waves of the open sea are generated by three natural causes: wind, earth movements or tremors, and the gravitational pull of the moon and the sun.","zh":"外海起伏的波浪由三种自然原因产生：风、地球的运动或震颤，以及月球和太阳的引力。","kind":"narration","speaker":"旁白"},{"en":"Once waves have been generated, gravity is the force that drives them in a continual attempt to restore the ocean surface to a flat plain.","zh":"波浪一旦形成，重力便成为驱动它们的力量，不断试图把海面恢复成平坦的面。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"give the impression of","matchedForm":"gives the impression of","meaning":"给人……的印象","note":"of 后接名词性内容，也可用 give the impression that 接从句。","example":"Although an ocean wave gives the impression of a wall of water moving in your direction, in actuality waves move through the water leaving the water about where it was.","exampleZh":"海浪虽然给人一种水墙迎面移来的印象，但实际上，波是在水中传播，水却大致留在原处。","sourceParagraphIndex":2,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"in actuality","matchedForm":"in actuality","meaning":"实际上","note":"用于说明真实机制与外观印象的差别。","example":"Although an ocean wave gives the impression of a wall of water moving in your direction, in actuality waves move through the water leaving the water about where it was.","exampleZh":"海浪虽然给人一种水墙迎面移来的印象，但实际上，波是在水中传播，水却大致留在原处。","sourceParagraphIndex":2,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"leave behind","matchedForm":"leaves the particles behind","meaning":"把……留在后面","note":"可指在空间上经过并离开，代词或名词宾语可放在中间。","example":"An ocean wave passing through deep water causes a particle on the surface to move in a roughly circular orbit, drawing the particle first towards the advancing wave, then up into the wave, then forward with it and then—as the wave leaves the particles behind—back to its starting point again.","exampleZh":"海浪通过深水时，会使水面上的一个质点沿大致呈圆形的轨道运动：先把它拉向正在前进的波浪，再向上带入波中，接着让它随波向前，随后当波浪把质点留在身后时，又使它回到起点。","sourceParagraphIndex":3,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"be subject to","matchedForm":"is subject to","meaning":"受……支配","note":"to 后接规律、限制或变化，说明无法摆脱其作用。","example":"From both maturity to death, a wave is subject to the same laws as any other ‘living’ thing.","exampleZh":"从成熟到消亡，波浪与任何其他“活的”事物一样，都受同样的规律支配。","sourceParagraphIndex":4,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"for a time","matchedForm":"For a time","meaning":"暂时；一段时间","note":"表示状态持续一段时间，未说明具体长度。","example":"For a time it assumes a miraculous individuality that, in the end, is reabsorbed into the great ocean of life.","exampleZh":"它暂时呈现出一种奇妙的个体性，最终这种个体性又被重新吸收到生命的大海之中。","sourceParagraphIndex":4,"sourceSentenceIndex":1,"sourceType":"textbook-passage"}],"translationNotes":["英文“From both maturity to death”疑有讹字，保留原文；中文依本段关于波浪生命历程的语境理解为“从成熟到消亡”。"]},{"lessonId":"nce-nativeears-b4-l041","book":4,"number":41,"title":"Training elephants","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Two main techniques have been used for training elephants, which we may call respectively the tough and the gentle.","zh":"训练大象主要采用过两种方法，我们可以分别称为强硬法和温和法。","kind":"narration","speaker":"旁白"},{"en":"The former method simply consists of setting an elephant to work and beating him until he does what is expected of him.","zh":"前一种方法很简单，就是让大象干活，然后一直打，直到它按要求做。","kind":"narration","speaker":"旁白"},{"en":"Apart from any moral considerations this is a stupid method of training, for it produces a resentful animal who at a later stage may well turn man-killer.","zh":"即使不谈任何道德问题，这也是愚蠢的训练方法，因为这样训出的动物心怀怨恨，日后很可能变成杀人的凶手。","kind":"narration","speaker":"旁白"},{"en":"The gentle method requires more patience in the early stages, but produces a cheerful, good-tempered elephant who will give many years of loyal service.","zh":"温和法在初期需要更多耐心，却能训出性情愉快、脾气温顺的大象，多年忠实地为人服务。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"The first essential in elephant training is to assign to the animal a single mahout who will be entirely responsible for the job.","zh":"驯象的首要条件，是为每头象指定一名驯象人，由他全权负责这项工作。","kind":"narration","speaker":"旁白"},{"en":"Elephants like to have one master just as dogs do, and are capable of a considerable degree of personal affection.","zh":"大象和狗一样，喜欢只有一个主人，而且能产生相当深厚的个人感情。","kind":"narration","speaker":"旁白"},{"en":"There are even stories of half-trained elephant calves who have refused to feed and pined to death when by some unavoidable circumstance they have been deprived of their own trainer.","zh":"甚至还有这样的故事：有些只训了一半的幼象，因为某种无法避免的情况而失去自己的驯象人，便拒绝进食，憔悴而死。","kind":"narration","speaker":"旁白"},{"en":"Such extreme cases must probably be taken with a grain of salt, but they do underline the general principle that the relationship between elephant and mahout is the key to successful training.","zh":"这种极端的事例恐怕不可全信，但它们确实强调了一条普遍原则：大象和驯象人的关系，是成功训练的关键。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"The most economical age to capture an elephant for training is between fifteen and twenty years, for it is then almost ready to undertake heavy work and can begin to earn its keep straight away.","zh":"捕捉大象来训练，最经济的年龄是十五岁到二十岁，因为此时它几乎已能承担重活，马上就能开始干活抵偿饲养费用。","kind":"narration","speaker":"旁白"},{"en":"But animals of this age do not easily become subservient to man, and a very firm hand must be employed in the early stages.","zh":"不过，这个年龄的动物不容易顺从人，因此训练初期必须用十分坚决的手段。","kind":"narration","speaker":"旁白"},{"en":"The captive elephant, still roped to a tree, plunges and screams every time a man approaches, and for several days will probably refuse all food through anger and fear.","zh":"被捕的大象仍拴在树上，每当有人走近，就会猛冲尖叫，而且可能因愤怒和恐惧，连续几天拒绝一切食物。","kind":"narration","speaker":"旁白"},{"en":"Sometimes a tame elephant is tethered nearby to give the wild one confidence, and in most cases the captive gradually quietens down and begins to accept its food.","zh":"有时，人们会把一头驯熟的象拴在附近，让野象安心；多数情况下，被捕的大象会逐渐平静，开始接受食物。","kind":"narration","speaker":"旁白"},{"en":"The next stage is to get the elephant to the training establishment, a ticklish business which is achieved with the aid of two tame elephants roped to the captive on either side.","zh":"下一步是把大象带到训练场，这是一件棘手的事，须把两头驯象分别用绳子拴在它两侧，借助它们才办得到。","kind":"narration","speaker":"旁白"}]},{"index":3,"rows":[{"en":"When several elephants are being trained at one time, it is customary for the new arrival to be placed between the stalls of two captives whose training is already well advanced.","zh":"同时训练几头大象时，通常会把新来的象安置在两头训练已相当有进展的被捕大象的栏舍之间。","kind":"narration","speaker":"旁白"},{"en":"It is then left completely undisturbed with plenty of food and water so that it can absorb the atmosphere of its new home and see that nothing particularly alarming is happening to its companions.","zh":"然后给它充足的食物和水，完全不去打扰，让它慢慢适应新家的气氛，看到同伴并没有遇到什么特别可怕的事。","kind":"narration","speaker":"旁白"},{"en":"When it is eating normally, its own training begins.","zh":"等它能正常进食，就开始训练它。","kind":"narration","speaker":"旁白"},{"en":"The trainer stands in front of the elephant holding a long stick with a sharp metal point.","zh":"驯象人手持一根末端装着尖金属头的长棍，站到大象面前。","kind":"narration","speaker":"旁白"},{"en":"Two assistants, mounted on tame elephants, control the captive from either side, while others rub their hands over his skin to the accompaniment of a monotonous and soothing chant.","zh":"两名助手骑在驯象背上，从两侧控制被捕的大象，其他人则用手摩擦它的皮肤，并伴以单调而舒缓的吟唱。","kind":"narration","speaker":"旁白"},{"en":"This is supposed to induce pleasurable sensations in the elephant, and its effects are reinforced by the use of endearing epithets, such as ‘ho!","zh":"据说这样能使大象产生愉悦的感觉；人们还会用亲昵的称呼加强效果，例如：“嗬！","kind":"mixed","speaker":"旁白 / 驯象人"},{"en":"my son’, or ‘ho!","zh":"我的孩子”，或“嗬！","kind":"speech","speaker":"驯象人"},{"en":"my father’, or ‘my mother’, according to the age and sex of the captive.","zh":"我的父亲”，或“我的母亲”，具体称呼取决于被捕大象的年龄和性别。","kind":"mixed","speaker":"驯象人 / 旁白"},{"en":"The elephant is not immediately susceptible to such blandishments, however, and usually lashes fiercely with its trunk in all directions.","zh":"然而，大象并不会立刻接受这些甜言蜜语，通常会向各个方向猛烈甩动鼻子。","kind":"narration","speaker":"旁白"},{"en":"These movements are controlled by the trainer with the metal-pointed stick, and the trunk eventually becomes so sore that the elephant curls it up and seldom afterwards uses it for offensive purposes.","zh":"驯象人用那根带金属尖头的棍子制止这些动作，最后象鼻疼痛得厉害，大象便把它卷起来，往后也很少再用它攻击了。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"apart from","matchedForm":"Apart from","meaning":"撇开……不谈","note":"此处先排除道德角度，再从训练成效批评强硬方法。","example":"Apart from any moral considerations this is a stupid method of training, for it produces a resentful animal who at a later stage may well turn man-killer.","exampleZh":"即使不谈任何道德问题，这也是愚蠢的训练方法，因为这样训出的动物心怀怨恨，日后很可能变成杀人的凶手。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"pine to death","matchedForm":"pined to death","meaning":"因忧伤憔悴而死","note":"pine 表示因悲伤、思念而衰弱，常见 pine away。","example":"There are even stories of half-trained elephant calves who have refused to feed and pined to death when by some unavoidable circumstance they have been deprived of their own trainer.","exampleZh":"甚至还有这样的故事：有些只训了一半的幼象，因为某种无法避免的情况而失去自己的驯象人，便拒绝进食，憔悴而死。","sourceParagraphIndex":1,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"take with a grain of salt","matchedForm":"taken with a grain of salt","meaning":"有所保留地相信","note":"固定习语，表示不可照单全收，并不等于全盘否定。","example":"Such extreme cases must probably be taken with a grain of salt, but they do underline the general principle that the relationship between elephant and mahout is the key to successful training.","exampleZh":"这种极端的事例恐怕不可全信，但它们确实强调了一条普遍原则：大象和驯象人的关系，是成功训练的关键。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"earn one’s keep","matchedForm":"earn its keep","meaning":"挣得生活费用；抵偿饲养成本","note":"可用于人或动物，强调通过工作抵偿维持生活所需的开销。","example":"The most economical age to capture an elephant for training is between fifteen and twenty years, for it is then almost ready to undertake heavy work and can begin to earn its keep straight away.","exampleZh":"捕捉大象来训练，最经济的年龄是十五岁到二十岁，因为此时它几乎已能承担重活，马上就能开始干活抵偿饲养费用。","sourceParagraphIndex":2,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"with the aid of","matchedForm":"with the aid of","meaning":"在……帮助下","note":"较正式的表达，aid 可指人力或工具提供的帮助。","example":"The next stage is to get the elephant to the training establishment, a ticklish business which is achieved with the aid of two tame elephants roped to the captive on either side.","exampleZh":"下一步是把大象带到训练场，这是一件棘手的事，须把两头驯象分别用绳子拴在它两侧，借助它们才办得到。","sourceParagraphIndex":2,"sourceSentenceIndex":4,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l042","book":4,"number":42,"title":"Recording an earthquake","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"An earthquake comes like a thief in the night, without warning.","zh":"地震就像夜里的窃贼，毫无预警地到来。","kind":"narration","speaker":"旁白"},{"en":"It was necessary, therefore, to invent instruments that neither slumbered nor slept.","zh":"因此，有必要发明既不打盹、也不睡觉的仪器。","kind":"narration","speaker":"旁白"},{"en":"Some devices were quite simple.","zh":"有些装置很简单。","kind":"narration","speaker":"旁白"},{"en":"One, for instance, consisted of rods of various lengths and thicknesses which would stand up on end like ninepins.","zh":"例如有一种，是把长短、粗细不同的杆子，像九柱戏的木柱一样竖立起来。","kind":"narration","speaker":"旁白"},{"en":"When a shock came, it shook the rigid table upon which these stood.","zh":"震动到来时，便摇动这些杆子所立的坚硬桌面。","kind":"narration","speaker":"旁白"},{"en":"If it were gentle, only the more unstable rods fell.","zh":"如果震动轻微，只有较不稳定的杆子会倒。","kind":"narration","speaker":"旁白"},{"en":"If it were severe, they all fell.","zh":"如果震动强烈，杆子就全倒了。","kind":"narration","speaker":"旁白"},{"en":"Thus the rods, by falling, and by the direction in which they fell, recorded for the slumbering scientist the strength of a shock that was too weak to waken him, and the direction from which it came.","zh":"这样，杆子通过是否倒下以及倒下的方向，为熟睡中的科学家记录下那种不足以把他震醒的震动的强度和来向。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"But instruments far more delicate than that were needed if any really serious advance was to be made.","zh":"但若要取得真正重大的进展，就需要比这精密得多的仪器。","kind":"narration","speaker":"旁白"},{"en":"The ideal to be aimed at was to devise an instrument that could record with a pen on paper, the movements of the ground or of the table as the quake passed by.","zh":"应当追求的理想，是设计出一种仪器，能在地震经过时，用笔在纸上记录地面或桌面的运动。","kind":"narration","speaker":"旁白"},{"en":"While I write my pen moves, but the paper keeps still.","zh":"我写字时，笔在动，纸却静止不动。","kind":"narration","speaker":"旁白"},{"en":"With practice, no doubt, I could in time learn to write by holding the pen still while the paper moved.","zh":"只要练习，毫无疑问，我最终也能学会让笔保持不动、让纸移动来写字。","kind":"narration","speaker":"旁白"},{"en":"That sounds a silly suggestion, but that was precisely the idea adopted in some of the early instruments (seismometers) for recording earthquake waves.","zh":"这听起来是个愚蠢的建议，但早期某些记录地震波的仪器，也就是地震仪，采用的恰恰就是这个想法。","kind":"narration","speaker":"旁白"},{"en":"But when table, penholder and paper are all moving, how is it possible to write legibly?","zh":"可是，当桌子、笔架和纸都在移动时，怎么可能把字写清楚呢？","kind":"narration","speaker":"旁白"},{"en":"The key to a solution of that problem lay in an everyday observation.","zh":"解决这个问题的关键，藏在一个日常观察中。","kind":"narration","speaker":"旁白"},{"en":"Why does a person standing in a bus or train tend to fall when a sudden start is made?","zh":"为什么公共汽车或火车突然启动时，站在车上的人容易摔倒？","kind":"narration","speaker":"旁白"},{"en":"It is because his feet move on, but his head stays still.","zh":"因为他的脚向前移动了，头却仍停留在原处。","kind":"narration","speaker":"旁白"},{"en":"A simple experiment will help us a little further.","zh":"一个简单实验会帮助我们再理解得深入一点。","kind":"narration","speaker":"旁白"},{"en":"Tie a heavy weight at the end of a long piece of string.","zh":"在一根长绳的一端拴一个重物。","kind":"narration","speaker":"旁白"},{"en":"With the hand held high in the air, hold the string so that the weight nearly touches the ground.","zh":"把手高举在空中，握住绳子，使重物几乎碰到地面。","kind":"narration","speaker":"旁白"},{"en":"Now move the hand to and fro and around but not up and down.","zh":"现在让手来回移动或转圈，但不要上下移动。","kind":"narration","speaker":"旁白"},{"en":"It will be found that the weight moves but slightly or not at all.","zh":"你会发现，重物只动一点点，甚至完全不动。","kind":"narration","speaker":"旁白"},{"en":"Imagine a pen attached to the weight in such a way that its point rests upon a piece of paper on the floor.","zh":"想象把一支笔装在重物上，使笔尖搁在地面的一张纸上。","kind":"narration","speaker":"旁白"},{"en":"Imagine an earthquake shock shaking the floor, the paper, you and your hand.","zh":"再想象一阵地震震动了地板、纸、你和你的手。","kind":"narration","speaker":"旁白"},{"en":"In the midst of all this movement, the weight and the pen would be still.","zh":"在这一片运动之中，重物和笔却会静止不动。","kind":"narration","speaker":"旁白"},{"en":"But as the paper moved from side to side under the pen point, its movement would be recorded in ink upon its surface.","zh":"但当纸在笔尖下面左右移动时，它的运动就会被墨水记录在纸面上。","kind":"narration","speaker":"旁白"},{"en":"It was upon this principle that the first instruments were made, but the paper was wrapped round a drum which rotated slowly.","zh":"最早的仪器就是根据这一原理制造的，不过纸是包在一个缓慢转动的圆筒上的。","kind":"narration","speaker":"旁白"},{"en":"As long as all was still, the pen drew a straight line, but while the drum was being shaken, the line that the pen was drawing wriggled from side to side.","zh":"只要一切静止，笔就画出直线；而圆筒受到摇动时，笔正在画的线便会左右弯曲。","kind":"narration","speaker":"旁白"},{"en":"The apparatus thus described, however, records only the horizontal component of the wave movement, which is, in fact, much more complicated.","zh":"然而，上述仪器只能记录波动的水平分量；实际上，波动要复杂得多。","kind":"narration","speaker":"旁白"},{"en":"If we could actually see the path described by a particle, such as a sand grain in the rock, it would be more like that of a bluebottle buzzing round the room; it would be up and down, to and fro and from side to side.","zh":"如果真能看见一个质点，例如岩石中的一粒沙，所描绘的运动轨迹，它会更像一只在屋里嗡嗡乱飞的绿头苍蝇；它会上下、前后、左右地运动。","kind":"narration","speaker":"旁白"},{"en":"Instruments have been devised and can be so placed that all three elements can be recorded in different graphs.","zh":"人们已设计出仪器，并可通过适当安放，使这三个方向的分量都记录在不同的图线上。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"When the instrument is situated at more than 700 miles from the earthquake centre, the graphic record shows three waves arriving one after the other at short intervals.","zh":"仪器若位于距震中七百英里以外，图形记录会显示三种波以很短的间隔先后到达。","kind":"narration","speaker":"旁白"},{"en":"The first records the arrival of longitudinal vibrations.","zh":"第一种记录纵向振动的到达。","kind":"narration","speaker":"旁白"},{"en":"The second marks the arrival of transverse vibrations which travel more slowly and arrive several minutes after the first.","zh":"第二种标志着横向振动的到达；它传播较慢，比第一种晚几分钟到达。","kind":"narration","speaker":"旁白"},{"en":"These two have travelled through the earth.","zh":"这两种波都穿过了地球内部。","kind":"narration","speaker":"旁白"},{"en":"It was from the study of these that so much was learnt about the interior of the earth.","zh":"正是通过研究它们，人们才获得了许多关于地球内部的知识。","kind":"narration","speaker":"旁白"},{"en":"The third, or main wave, is the slowest and has travelled round the earth through the surface rocks.","zh":"第三种波，或者说主波，最慢，它沿地球表面的岩石传播，绕地球而行。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"like a thief in the night","matchedForm":"like a thief in the night","meaning":"像夜贼一样悄然而至","note":"比喻事情突然且无预警地发生。","example":"An earthquake comes like a thief in the night, without warning.","exampleZh":"地震就像夜里的窃贼，毫无预警地到来。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"in time","matchedForm":"in time","meaning":"最终；迟早","note":"此处强调经过练习终能学会，不是赶上截止时间。","example":"With practice, no doubt, I could in time learn to write by holding the pen still while the paper moved.","exampleZh":"只要练习，毫无疑问，我最终也能学会让笔保持不动、让纸移动来写字。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"to and fro","matchedForm":"to and fro","meaning":"来回地","note":"表示往返运动，常与 move、swing 等搭配。","example":"Now move the hand to and fro and around but not up and down.","exampleZh":"现在让手来回移动或转圈，但不要上下移动。","sourceParagraphIndex":1,"sourceSentenceIndex":12,"sourceType":"textbook-passage"},{"phrase":"in the midst of","matchedForm":"In the midst of","meaning":"在……之中","note":"midst 后可接活动、纷乱或一群事物，语体较正式。","example":"In the midst of all this movement, the weight and the pen would be still.","exampleZh":"在这一片运动之中，重物和笔却会静止不动。","sourceParagraphIndex":1,"sourceSentenceIndex":16,"sourceType":"textbook-passage"},{"phrase":"one after the other","matchedForm":"one after the other","meaning":"一个接一个地","note":"强调依次发生；原文说三种波先后到达。","example":"When the instrument is situated at more than 700 miles from the earthquake centre, the graphic record shows three waves arriving one after the other at short intervals.","exampleZh":"仪器若位于距震中七百英里以外，图形记录会显示三种波以很短的间隔先后到达。","sourceParagraphIndex":2,"sourceSentenceIndex":0,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l043","book":4,"number":43,"title":"Are there strangers in space?","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"We must conclude from the work of those who have studied the origin of life, that given a planet only approximately like our own, life is almost certain to start.","zh":"根据生命起源研究者的工作，我们必须得出这样的结论：只要有一颗与地球大致相似的行星，生命几乎肯定会萌生。","kind":"narration","speaker":"旁白"},{"en":"Of all the planets in our own solar system, we are now pretty certain the Earth is the only one on which life can survive.","zh":"在我们太阳系的所有行星中，如今我们相当确信，地球是唯一能让生命生存的星球。","kind":"narration","speaker":"旁白"},{"en":"Mars is too dry and poor in oxygen, Venus far too hot, and so is Mercury, and the outer planets have temperatures near absolute zero and hydrogen-dominated atmospheres.","zh":"火星太干燥，氧气也太少；金星过热，水星也是如此；外侧行星的温度接近绝对零度，大气则以氢为主。","kind":"narration","speaker":"旁白"},{"en":"But other suns, stars as the astronomers call them, are bound to have planets like our own, and as the number of stars in the universe is so vast, this possibility becomes virtual certainty.","zh":"但别的太阳，也就是天文学家所说的恒星，必然会有像地球这样的行星；宇宙中的恒星数量如此巨大，这种可能性实际上便成了必然。","kind":"narration","speaker":"旁白"},{"en":"There are one hundred thousand million stars in our own Milky Way alone, and then there are three thousand million other Milky Ways, or galaxies, in the universe.","zh":"仅我们自己的银河系中就有一千亿颗恒星，宇宙里还有另外三十亿个银河系那样的星系。","kind":"narration","speaker":"旁白"},{"en":"So the number of stars that we know exist is now estimated at about 300 million million million.","zh":"因此，我们如今估计，已知存在的恒星总数约为三乘以十的二十次方颗。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Although perhaps only 1 per cent of the life that has started somewhere will develop into highly complex and intelligent patterns, so vast is the number of planets, that intelligent life is bound to be a natural part of the universe.","zh":"在某处已经出现的生命中，虽然也许只有百分之一会发展成高度复杂而有智慧的形式，但行星数量如此庞大，智慧生命必然是宇宙中自然存在的一部分。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"If then we are so certain that other intelligent life exists in the universe, why have we had no visitors from outer space yet?","zh":"那么，既然我们如此确信宇宙中存在其他智慧生命，为什么至今还没有外太空的访客呢？","kind":"narration","speaker":"旁白"},{"en":"First of all, they may have come to this planet of ours thousands or millions of years ago, and found our then prevailing primitive state completely uninteresting to their own advanced knowledge.","zh":"首先，他们可能在几千年、几百万年前就来过我们这颗行星，却发现当时这里的原始状态，对于掌握着先进知识的他们来说，完全没有趣味。","kind":"narration","speaker":"旁白"},{"en":"Professor Ronald Bracewell, a leading American radio astronomer, argued in Nature that such a superior civilization, on a visit to our own solar system, may have left an automatic messenger behind to await the possible awakening of an advanced civilization.","zh":"美国杰出的射电天文学家罗纳德·布雷斯韦尔教授在《自然》杂志上论述过：这种先进文明造访我们的太阳系时，可能留下了一个自动信使，等待一个先进文明可能出现的觉醒。","kind":"narration","speaker":"旁白"},{"en":"Such a messenger, receiving our radio and television signals, might well re-transmit them back to its home-planet, although what impression any other civilization would thus get from us is best left unsaid.","zh":"这样的信使收到我们的广播和电视信号后，很可能把它们转发回自己的母星；不过，其他文明由此会对我们形成什么印象，还是不说为妙。","kind":"narration","speaker":"旁白"}]},{"index":3,"rows":[{"en":"But here we come up against the most difficult of all obstacles to contact with people on other planets —the astronomical distances which separate us.","zh":"然而，在这里我们遇到了与其他行星上的人接触的最大障碍：将我们分隔开来的天文距离。","kind":"narration","speaker":"旁白"},{"en":"As a reasonable guess, they might, on an average, be 100 light years away.","zh":"作一个合理估计，他们离我们平均可能有一百光年。","kind":"narration","speaker":"旁白"},{"en":"(A light year is the distance which light travels at 186,000 miles per second in one year, namely 6 million million miles.)","zh":"（一光年是光以每秒十八万六千英里的速度，在一年中所行进的距离，即六万亿英里。）","kind":"note","speaker":"说明"},{"en":"Radio waves also travel at the speed of light, and assuming such an automatic messenger picked up our first broadcasts of the 1920’s, the message to its home planet is barely halfway there.","zh":"无线电波也以光速传播；假定这样一个自动信使接收到了我们二十世纪二十年代最早的广播，那么传向它母星的信息，如今还勉强只走了一半路程。","kind":"narration","speaker":"旁白"},{"en":"Similarly, our own present primitive chemical rockets, though good enough to orbit men, have no chance of transporting us to the nearest other star, four light years away, let alone distances of tens or hundreds of light years.","zh":"同样，我们目前这种原始的化学火箭，虽然足以把人送入轨道，却根本不可能把我们运送到四光年外最近的另一颗恒星，更不用说几十或几百光年的距离了。","kind":"narration","speaker":"旁白"}]},{"index":4,"rows":[{"en":"Fortunately, there is a ‘uniquely rational way’ for us to communicate with other intelligent beings, as Walter Sullivan has put it in his excellent book, We Are not Alone.","zh":"幸运的是，正如沃尔特·沙利文在其出色的著作《我们并不孤独》中所说，我们与其他智慧生命交流，有一种“独一无二的合理方式”。","kind":"narration","speaker":"旁白"},{"en":"This depends on the precise radio frequency of the 21-cm wavelength, or 1420 megacycles per second.","zh":"这种方式依靠的是二十一厘米波长所对应的精确无线电频率，也就是每秒一千四百二十兆周。","kind":"narration","speaker":"旁白"},{"en":"It is the natural frequency of emission of the hydrogen atoms in space and was discovered by us in 1951; it must be known to any kind of radio astronomer in the universe.","zh":"这是太空中氢原子发射的自然频率，我们于一九五一年发现了它；宇宙中任何射电天文学家都必定知道它。","kind":"narration","speaker":"旁白"}]},{"index":5,"rows":[{"en":"Once the existence of this wave-length had been discovered, it was not long before its use as the uniquely recognizable broadcasting frequency for interstellar communication was suggested.","zh":"这种波长一经发现，没过多久就有人提出，把它用作星际通信中可被独一识别的广播频率。","kind":"narration","speaker":"旁白"},{"en":"Without something of this kind, searching for intelligences on other planets would be like trying to meet a friend in London without a pre-arranged rendezvous and absurdly wandering the streets in the hope of a chance encounter.","zh":"如果没有这类约定，搜寻其他行星上的智慧生命，就像想在伦敦见一个朋友，却不事先约定见面地点，只是荒唐地在街头游荡，盼着偶然相遇。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"be bound to","matchedForm":"are bound to","meaning":"必然会","note":"表达说话者对结果的高度确信，后接动词原形。","example":"But other suns, stars as the astronomers call them, are bound to have planets like our own, and as the number of stars in the universe is so vast, this possibility becomes virtual certainty.","exampleZh":"但别的太阳，也就是天文学家所说的恒星，必然会有像地球这样的行星；宇宙中的恒星数量如此巨大，这种可能性实际上便成了必然。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"be best left unsaid","matchedForm":"is best left unsaid","meaning":"最好不说","note":"leave something unsaid 表示不把话说出；此处有讽刺意味。","example":"Such a messenger, receiving our radio and television signals, might well re-transmit them back to its home-planet, although what impression any other civilization would thus get from us is best left unsaid.","exampleZh":"这样的信使收到我们的广播和电视信号后，很可能把它们转发回自己的母星；不过，其他文明由此会对我们形成什么印象，还是不说为妙。","sourceParagraphIndex":2,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"come up against","matchedForm":"come up against","meaning":"遇到；碰上","note":"常接困难、阻力或难以解决的问题。","example":"But here we come up against the most difficult of all obstacles to contact with people on other planets —the astronomical distances which separate us.","exampleZh":"然而，在这里我们遇到了与其他行星上的人接触的最大障碍：将我们分隔开来的天文距离。","sourceParagraphIndex":3,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"let alone","matchedForm":"let alone","meaning":"更不用说","note":"从较低要求都做不到，推到更高要求更无法做到。","example":"Similarly, our own present primitive chemical rockets, though good enough to orbit men, have no chance of transporting us to the nearest other star, four light years away, let alone distances of tens or hundreds of light years.","exampleZh":"同样，我们目前这种原始的化学火箭，虽然足以把人送入轨道，却根本不可能把我们运送到四光年外最近的另一颗恒星，更不用说几十或几百光年的距离了。","sourceParagraphIndex":3,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"in the hope of","matchedForm":"in the hope of","meaning":"希望；抱着……希望","note":"of 后接名词或动名词，说明做事时所盼望的结果。","example":"Without something of this kind, searching for intelligences on other planets would be like trying to meet a friend in London without a pre-arranged rendezvous and absurdly wandering the streets in the hope of a chance encounter.","exampleZh":"如果没有这类约定，搜寻其他行星上的智慧生命，就像想在伦敦见一个朋友，却不事先约定见面地点，只是荒唐地在街头游荡，盼着偶然相遇。","sourceParagraphIndex":5,"sourceSentenceIndex":1,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l044","book":4,"number":44,"title":"Patterns of culture","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Custom has not commonly been regarded as a subject of any great moment.","zh":"习俗通常并不被视为一个多么重要的研究课题。","kind":"narration","speaker":"旁白"},{"en":"The inner workings of our own brains we feel to be uniquely worthy of investigation, but custom, we have a way of thinking, is behaviour at its most commonplace.","zh":"我们觉得自己大脑的内部运作格外值得研究，却习惯认为习俗不过是最平常不过的行为。","kind":"narration","speaker":"旁白"},{"en":"As a matter of fact, it is the other way around.","zh":"事实上，情况恰恰相反。","kind":"narration","speaker":"旁白"},{"en":"Traditional custom, taken the world over, is a mass of detailed behaviour more astonishing than what any one person can ever evolve in individual actions, no matter how aberrant.","zh":"从全世界来看，传统习俗是一整套细致繁多的行为，比任何个人凭一己行动所能发展出的行为都更令人惊异，无论这个人的举动多么离经叛道。","kind":"narration","speaker":"旁白"},{"en":"Yet that is a rather trivial aspect of the matter.","zh":"然而，这还只是事情一个相当次要的方面。","kind":"narration","speaker":"旁白"},{"en":"The fact of first-rate importance is the predominant role that custom plays in experience and in belief, and the very great varieties it may manifest.","zh":"最为重要的事实，是习俗在经验和信念中所起的主导作用，以及它可能表现出的极其丰富的差异。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"No man ever looks at the world with pristine eyes.","zh":"从来没有人用毫无成见的眼光看世界。","kind":"narration","speaker":"旁白"},{"en":"He sees it edited by a definite set of customs and institutions and ways of thinking.","zh":"他所看到的世界，已经过一套特定的习俗、制度和思维方式的编排。","kind":"narration","speaker":"旁白"},{"en":"Even in his philosophical probings he cannot go behind these stereotypes: his very concepts of the true and the false will still have reference to his particular traditional customs.","zh":"即使进行哲学探索，他也无法越出这些定式：连他对真与假的概念，也仍然关联着他所属的特定传统习俗。","kind":"narration","speaker":"旁白"},{"en":"John Dewey has said in all seriousness that the part played by custom in shaping the behaviour of the individual, as against any way in which he can affect traditional custom, is as the proportion of the total vocabulary of his mother tongue against those words of his own baby talk that are taken up into the vernacular of his family.","zh":"约翰·杜威曾十分严肃地说，习俗对塑造个人行为的影响，与个人以任何方式改变传统习俗的影响相比，其比例就像他母语的全部词汇量，与他幼儿时期所说、后来被家人纳入口头用语的那些话的数量之比。","kind":"narration","speaker":"旁白"},{"en":"When one seriously studies the social orders that have had the opportunity to develop autonomously, the figure becomes no more than an exact and matter-of-fact observation.","zh":"认真研究那些有机会自主发展的社会秩序后，就会发现，这个比喻其实只是准确、实事求是的观察。","kind":"narration","speaker":"旁白"},{"en":"The life history of the individual is first and foremost an accommodation to the patterns and standards traditionally handed down in his community.","zh":"个人的生活史，首先而且最主要的，是不断适应其社区世代相传的模式和标准的过程。","kind":"narration","speaker":"旁白"},{"en":"From the moment of his birth, the customs into which he is born shape his experience and behaviour.","zh":"从出生那一刻起，他所处的习俗就塑造着他的经验和行为。","kind":"narration","speaker":"旁白"},{"en":"By the time he can talk, he is the little creature of his culture, and by the time he is grown and able to take part in its activities, its habits are his habits, its beliefs his beliefs, its impossibilities his impossibilities.","zh":"到能够说话时，他已成了自身文化塑造的小小产物；到长大并能参加其中活动时，这个文化的习惯就是他的习惯，它的信念就是他的信念，它认定不可能的事情，也就是他认定不可能的事情。","kind":"narration","speaker":"旁白"},{"en":"Every child that is born into his group will share them with him, and no child born into one on the opposite side of the globe can ever achieve the thousandth part.","zh":"每个生在他这个群体中的孩子，都会同他分享这些；而出生在地球另一端某个群体的孩子，连其中千分之一也不可能获得。","kind":"narration","speaker":"旁白"},{"en":"There is no social problem it is more incumbent upon us to understand than this of the role of custom.","zh":"没有哪个社会问题，比习俗的作用更是我们理应理解的。","kind":"narration","speaker":"旁白"},{"en":"Until we are intelligent as to its laws and varieties, the main complicating facts of human life must remain unintelligible.","zh":"在我们理解它的规律和差异之前，人类生活中那些使事情复杂化的主要事实，必然仍难以理解。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"The study of custom can be profitable only after certain preliminary propositions have been accepted, and some of these propositions have been violently opposed.","zh":"只有接受了某些前提，习俗研究才能有所收获；而其中一些前提曾遭到激烈反对。","kind":"narration","speaker":"旁白"},{"en":"In the first place, any scientific study requires that there be no preferential weighting of one or another of the items in the series it selects for its consideration.","zh":"首先，任何科学研究都要求，对所选择考察的一系列对象，不应偏袒其中任何一项。","kind":"narration","speaker":"旁白"},{"en":"In all the less controversial fields, like the study of cacti or termites or the nature of nebulae, the necessary method of study is to group the relevant material and to take note of all possible variant forms and conditions.","zh":"在所有争议较小的领域，例如研究仙人掌、白蚁或星云的性质时，必需的方法都是把有关材料归类，并留意一切可能的变异形式和条件。","kind":"narration","speaker":"旁白"},{"en":"In this way, we have learned all that we know of the laws of astronomy, or of the habits of the social insects, let us say.","zh":"我们关于天文学规律，或者比如社会性昆虫习性的全部知识，都是这样得来的。","kind":"narration","speaker":"旁白"},{"en":"It is only in the study of man himself that the major social sciences have substituted the study of one local variation, that of Western civilization.","zh":"只有在研究人类自身时，主要社会科学才把对某一种地方性变体——即西方文明——的研究，拿来代替对全体的研究。","kind":"narration","speaker":"旁白"}]},{"index":3,"rows":[{"en":"Anthropology was by definition impossible, as long as these distinctions between ourselves and the primitive, ourselves and the barbarian, ourselves and the pagan, held sway over people’s minds.","zh":"只要人们仍受这些区别支配，把我们与原始人、把我们与野蛮人、把我们与异教徒截然划开，那么从定义上说，人类学就不可能成立。","kind":"narration","speaker":"旁白"},{"en":"It was necessary first to arrive at that degree of sophistication where we no longer set our own belief against our neighbour’s superstition.","zh":"首先，认识必须成熟到不再把自己的观念当作信仰，却把邻人的观念贬作迷信。","kind":"narration","speaker":"旁白"},{"en":"It was necessary to recognize that these institutions which are based on the same premises, let us say the supernatural, must be considered together, our own among the rest.","zh":"必须承认，立足于相同前提——比如超自然观念——的各种制度，应放在一起考察，我们自己的制度也不例外。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"of great moment","matchedForm":"of any great moment","meaning":"有重大意义","note":"moment 在此指重要性，属较正式用法，而非一小段时间。","example":"Custom has not commonly been regarded as a subject of any great moment.","exampleZh":"习俗通常并不被视为一个多么重要的研究课题。","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"the other way around","matchedForm":"the other way around","meaning":"恰好相反","note":"表示实际关系与前述的方向或顺序相反。","example":"As a matter of fact, it is the other way around.","exampleZh":"事实上，情况恰恰相反。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"in all seriousness","matchedForm":"in all seriousness","meaning":"十分认真地","note":"强调并非玩笑或夸张，而是严肃提出的判断。","example":"John Dewey has said in all seriousness that the part played by custom in shaping the behaviour of the individual, as against any way in which he can affect traditional custom, is as the proportion of the total vocabulary of his mother tongue against those words of his own baby talk that are taken up into the vernacular of his family.","exampleZh":"约翰·杜威曾十分严肃地说，习俗对塑造个人行为的影响，与个人以任何方式改变传统习俗的影响相比，其比例就像他母语的全部词汇量，与他幼儿时期所说、后来被家人纳入口头用语的那些话的数量之比。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"first and foremost","matchedForm":"first and foremost","meaning":"首先且最重要的是","note":"不仅表示顺序靠前，更突出首要地位。","example":"The life history of the individual is first and foremost an accommodation to the patterns and standards traditionally handed down in his community.","exampleZh":"个人的生活史，首先而且最主要的，是不断适应其社区世代相传的模式和标准的过程。","sourceParagraphIndex":1,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"hold sway over","matchedForm":"held sway over","meaning":"支配；统治","note":"常用于观念、势力对人或地区的支配，sway 在此为名词。","example":"Anthropology was by definition impossible, as long as these distinctions between ourselves and the primitive, ourselves and the barbarian, ourselves and the pagan, held sway over people’s minds.","exampleZh":"只要人们仍受这些区别支配，把我们与原始人、把我们与野蛮人、把我们与异教徒截然划开，那么从定义上说，人类学就不可能成立。","sourceParagraphIndex":3,"sourceSentenceIndex":0,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l045","book":4,"number":45,"title":"Of men and galaxies","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"In man’s early days, competition with other creatures must have been critical.","zh":"在人类早期，与其他生物的竞争必定关系到生死存亡。","kind":"narration","speaker":"旁白"},{"en":"But this phase of our development is now finished.","zh":"但我们发展的这个阶段如今已经结束。","kind":"narration","speaker":"旁白"},{"en":"Indeed, we lack practice and experience nowadays in dealing with primitive conditions.","zh":"事实上，现在我们已缺乏应付原始环境的实践和经验。","kind":"narration","speaker":"旁白"},{"en":"I am sure that, without modern weapons, I would make a very poor show of disputing the ownership of a cave with a bear, and in this I do not think that I stand alone.","zh":"我确信，如果没有现代武器，要和一头熊争一个山洞的所有权，我会表现得十分狼狈；而在这一点上，我想绝不只是我一个人如此。","kind":"narration","speaker":"旁白"},{"en":"The last creature to compete with man was the mosquito.","zh":"最后一种与人类竞争的生物是蚊子。","kind":"narration","speaker":"旁白"},{"en":"But even the mosquito has been subdued by attention to drainage and by chemical sprays.","zh":"不过，即使是蚊子，也已通过重视排水和喷洒化学药剂而被制服。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Competition between ourselves, person against person, community against community, still persists, however; and it is as fierce as it ever was.","zh":"然而，我们人类内部的竞争——个人对个人、群体对群体——仍在继续，而且和以往一样激烈。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"But the competition of man against man is not the simple process envisioned in biology.","zh":"但是，人与人之间的竞争，并不是生物学所设想的那种简单过程。","kind":"narration","speaker":"旁白"},{"en":"It is not a simple competition for a fixed amount of food determined by the physical environment, because the environment that determines our evolution is no longer essentially physical.","zh":"它并非只是争夺由自然环境决定的固定数量的食物，因为决定我们演化的环境，已不再主要是物质环境。","kind":"narration","speaker":"旁白"},{"en":"Our environment is chiefly conditioned by the things we believe.","zh":"我们的环境主要受我们信奉的观念制约。","kind":"narration","speaker":"旁白"},{"en":"Morocco and California are bits of the Earth in very similar latitudes, both on the west coasts of continents with similar climates, and probably with rather similar natural resources.","zh":"摩洛哥和加利福尼亚位于地球上十分相近的纬度，都在大陆西岸，气候相似，自然资源可能也颇相近。","kind":"narration","speaker":"旁白"},{"en":"Yet their present development is wholly different, not so much because of different people even, but because of the different thoughts that exist in the minds of their inhabitants.","zh":"然而，两地目前的发展全然不同；这与其说是因为人群不同，甚至不如说是因为居民头脑中的思想不同。","kind":"narration","speaker":"旁白"},{"en":"This is the point I wish to emphasize.","zh":"这就是我想强调的一点。","kind":"narration","speaker":"旁白"},{"en":"The most important factor in our environment is the state of our own minds.","zh":"我们环境中最重要的因素，是我们自身的思想状态。","kind":"narration","speaker":"旁白"}]},{"index":3,"rows":[{"en":"It is well known that where the white man has invaded a primitive culture, the most destructive effects have come not from physical weapons but from ideas.","zh":"众所周知，在白人侵入原始文化的地方，破坏最强的影响并非来自物质武器，而是来自思想。","kind":"narration","speaker":"旁白"},{"en":"Ideas are dangerous.","zh":"思想是危险的。","kind":"narration","speaker":"旁白"},{"en":"The Holy Office knew this full well when it caused heretics to be burned in days gone by.","zh":"宗教裁判所昔日下令烧死异端者时，对这一点十分清楚。","kind":"narration","speaker":"旁白"},{"en":"Indeed, the concept of free speech only exists in our modern society because when you are inside a community, you are conditioned by the conventions of the community to such a degree that it is very difficult to conceive of anything really destructive.","zh":"事实上，言论自由这一观念之所以能在现代社会存在，只是因为当你身处一个社群内部时，会受到该社群惯例的深刻制约，以至于很难设想出任何真正具有破坏性的思想。","kind":"narration","speaker":"旁白"},{"en":"It is only someone looking on from outside that can inject the dangerous thoughts.","zh":"只有从外部观察的人，才能注入那些危险的思想。","kind":"narration","speaker":"旁白"},{"en":"I do not doubt that it would be possible to inject ideas into the modern world that would utterly destroy us.","zh":"我毫不怀疑，完全有可能向现代世界注入某些观念，将我们彻底毁灭。","kind":"narration","speaker":"旁白"},{"en":"I would like to give you an example, but fortunately I cannot do so.","zh":"我很想举个例子给各位听，但幸运的是，我举不出来。","kind":"narration","speaker":"旁白"},{"en":"Perhaps it will suffice to mention the nuclear bomb.","zh":"也许提到核弹就足够了。","kind":"narration","speaker":"旁白"},{"en":"Imagine the effect on a reasonably advanced technological society, one that still does not possess the bomb, of making it aware of the possibility, of supplying sufficient details to enable the thing to be constructed.","zh":"设想一下，对于一个技术相当先进、却还没有核弹的社会，如果让它知道核弹有可能制造出来，并提供足够的细节，使它能够造出来，会产生什么影响。","kind":"narration","speaker":"旁白"},{"en":"Twenty or thirty pages of information handed to any of the major world powers around the year 1925 would have been sufficient to change the course of world history.","zh":"在一九二五年前后，只要把二三十页资料交给任何一个世界主要强国，就足以改变世界历史的进程。","kind":"narration","speaker":"旁白"},{"en":"It is a strange thought, but I believe a correct one, that twenty or thirty pages of ideas and information would be capable of turning the present-day world upside down, or even destroying it.","zh":"二三十页思想和资料竟能够使当今世界天翻地覆，甚至毁灭它；这是个奇怪的想法，但我相信它是正确的。","kind":"narration","speaker":"旁白"},{"en":"I have often tried to conceive of what those pages might contain, but of course I cannot do so because I am a prisoner of the present-day world, just as all of you are.","zh":"我常常试图设想那些页上会写些什么，当然却想不出来，因为我和各位一样，都是当今世界的囚徒。","kind":"narration","speaker":"旁白"},{"en":"We cannot think outside the particular patterns that our brains are conditioned to, or, to be more accurate, we can think only a very little way outside, and then only if we are very original.","zh":"我们无法跳出大脑已经习惯的特定思维模式；或者更准确地说，我们只能向模式之外想一点点，而且即便这样，也只有极富独创性才办得到。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"deal with","matchedForm":"dealing with","meaning":"应付；处理","note":"后接问题或环境，表示采取行动去应对。","example":"Indeed, we lack practice and experience nowadays in dealing with primitive conditions.","exampleZh":"事实上，现在我们已缺乏应付原始环境的实践和经验。","sourceParagraphIndex":0,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"make a poor show of","matchedForm":"make a very poor show of","meaning":"表现得很差","note":"show 在此指表现，of 后接名词或动名词。","example":"I am sure that, without modern weapons, I would make a very poor show of disputing the ownership of a cave with a bear, and in this I do not think that I stand alone.","exampleZh":"我确信，如果没有现代武器，要和一头熊争一个山洞的所有权，我会表现得十分狼狈；而在这一点上，我想绝不只是我一个人如此。","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"not so much ... but","matchedForm":"not so much","meaning":"与其说……不如说……","note":"not so much ... but ... 将重点从前一解释移到后一解释；原句以 because of 引出两种原因，even 进一步弱化前一项。","example":"Yet their present development is wholly different, not so much because of different people even, but because of the different thoughts that exist in the minds of their inhabitants.","exampleZh":"然而，两地目前的发展全然不同；这与其说是因为人群不同，甚至不如说是因为居民头脑中的思想不同。","sourceParagraphIndex":2,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"in days gone by","matchedForm":"in days gone by","meaning":"在过去的日子里","note":"较有叙述色彩的过去时间表达。","example":"The Holy Office knew this full well when it caused heretics to be burned in days gone by.","exampleZh":"宗教裁判所昔日下令烧死异端者时，对这一点十分清楚。","sourceParagraphIndex":3,"sourceSentenceIndex":2,"sourceType":"textbook-passage"},{"phrase":"turn upside down","matchedForm":"turning the present-day world upside down","meaning":"使天翻地覆","note":"turn something upside down 除实际翻转外，也可比喻彻底打乱现状。","example":"It is a strange thought, but I believe a correct one, that twenty or thirty pages of ideas and information would be capable of turning the present-day world upside down, or even destroying it.","exampleZh":"二三十页思想和资料竟能够使当今世界天翻地覆，甚至毁灭它；这是个奇怪的想法，但我相信它是正确的。","sourceParagraphIndex":3,"sourceSentenceIndex":10,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l046","book":4,"number":46,"title":"Hobbies","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"A gifted American psychologist has said, ‘Worry is a spasm of the emotion; the mind catches hold of something and will not let it go.’","zh":"一位有才华的美国心理学家曾说：“忧虑是情感的痉挛；心灵抓住了某个东西，便不肯放手。”","kind":"mixed","speaker":"旁白 / 美国心理学家"},{"en":"It is useless to argue with the mind in this condition.","zh":"在这种状态下，与心灵争辩是徒劳的。","kind":"narration","speaker":"旁白"},{"en":"The stronger the will, the more futile the task.","zh":"意志越强，这样做就越没有用。","kind":"narration","speaker":"旁白"},{"en":"One can only gently insinuate something else into its convulsive grasp.","zh":"人只能轻轻把别的东西塞进它那痉挛般紧抓的手中。","kind":"narration","speaker":"旁白"},{"en":"And if this something else is rightly chosen, if it is really attended by the illumination of another field of interest, gradually, and often quite swiftly, the old undue grip relaxes and the process of recuperation and repair begins.","zh":"如果这别的东西选得恰当，如果它确实伴随着另一个兴趣领域带来的启迪，那么原先那种过度的紧抓就会渐渐松开，而且往往相当迅速，复原与修复的过程便开始了。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"The cultivation of a hobby and new forms of interest is therefore a policy of the first importance to a public man.","zh":"因此，对一个从事公共事务的人来说，培养一种业余爱好和新的兴趣形式，是头等重要的方针。","kind":"narration","speaker":"旁白"},{"en":"But this is not a business that can be undertaken in a day or swiftly improvised by a mere command of the will.","zh":"但这并不是一天之内就能办成的事，也不是光靠一道意志的命令就能迅速应付出来的。","kind":"narration","speaker":"旁白"},{"en":"The growth of alternative mental interests is a long process.","zh":"培养能替换原有心智活动的其他兴趣，是个漫长的过程。","kind":"narration","speaker":"旁白"},{"en":"The seeds must be carefully chosen; they must fall on good ground; they must be sedulously tended, if the vivifying fruits are to be at hand when needed.","zh":"种子必须仔细挑选，必须落在好土里，也必须悉心照料，才能在需要时，随手获得那些使人恢复活力的果实。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"To be really happy and really safe, one ought to have at least two or three hobbies, and they must all be real.","zh":"要真正幸福、真正安稳，人至少应有两三种爱好，而且都必须是真正的爱好。","kind":"narration","speaker":"旁白"},{"en":"It is no use starting late in life to say: ‘I will take an interest in this or that.’","zh":"到了晚年才开始说“我要对这个或那个感兴趣”，是没有用的。","kind":"mixed","speaker":"旁白 / 假想的自语"},{"en":"Such an attempt only aggravates the strain of mental effort.","zh":"这种尝试只会加重精神用力的紧张。","kind":"narration","speaker":"旁白"},{"en":"A man may acquire great knowledge of topics unconnected with his daily work, and yet get hardly any benefit or relief.","zh":"一个人也许对与日常工作毫不相关的话题获得了大量知识，却几乎得不到任何益处或解脱。","kind":"narration","speaker":"旁白"},{"en":"It is no use doing what you like; you have got to like what you do.","zh":"光做自己喜欢的事没有用；你必须喜欢自己正在做的事。","kind":"narration","speaker":"旁白"},{"en":"Broadly speaking, human beings may be divided into three classes: those who are toiled to death, those who are worried to death, and those who are bored to death.","zh":"大体说来，人可以分成三类：劳累致死的人、忧虑致死的人和无聊致死的人。","kind":"narration","speaker":"旁白"},{"en":"It is no use offering the manual labourer, tired out with a hard week's sweat and effort, the chance of playing a game of football or baseball on Saturday afternoon.","zh":"一个体力劳动者经过一周艰苦的流汗出力，已筋疲力尽，星期六下午再给他一次踢足球或打棒球的机会，是没有用的。","kind":"narration","speaker":"旁白"},{"en":"It is no use inviting the politician or the professional or business man, who has been working or worrying about serious things for six days, to work or worry about trifling things at the weekend.","zh":"一个政客、专业人士或商人，已连续六天为重要事情忙碌或忧虑，再请他周末为琐事忙碌或忧虑，也是没有用的。","kind":"narration","speaker":"旁白"}]},{"index":3,"rows":[{"en":"As for the unfortunate people who can command everything they want, who can gratify every caprice and lay their hands on almost every object of desire—for them a new pleasure, a new excitement is only an additional satiation.","zh":"至于那些不幸的人，他们能得到任何想要的东西，能满足每一时兴起的念头，几乎能把一切欲求之物拿到手；对他们来说，一种新乐趣、一番新刺激，只会再增添一层餍足与厌腻。","kind":"narration","speaker":"旁白"},{"en":"In vain they rush frantically round from place to place, trying to escape from avenging boredom by mere clatter and motion.","zh":"他们发狂般四处奔走，想仅凭喧闹和活动躲开报复般追来的无聊，却徒劳无功。","kind":"narration","speaker":"旁白"},{"en":"For them discipline in one form or another is the most hopeful path.","zh":"对他们来说，某种形式的自我约束，是最有希望的出路。","kind":"narration","speaker":"旁白"}]},{"index":4,"rows":[{"en":"It may also be said that rational, industrious, useful human beings are divided into two classes: first, those whose work is work and whose pleasure is pleasure; and secondly, those whose work and pleasure are one.","zh":"也可以说，理智、勤勉而有用的人分为两类：第一类是工作归工作、娱乐归娱乐的人；第二类是工作和娱乐融为一体的人。","kind":"narration","speaker":"旁白"},{"en":"Of these the former are the majority.","zh":"两者之中，前一类占多数。","kind":"narration","speaker":"旁白"},{"en":"They have their compensations.","zh":"他们也有自己的补偿。","kind":"narration","speaker":"旁白"},{"en":"The long hours in the office or the factory bring with them as their reward, not only the means of sustenance, but a keen appetite for pleasure even in its simplest and most modest forms.","zh":"在办公室或工厂里工作的漫长时光，带来的报偿不仅是维持生活的收入，也使人对娱乐产生强烈的渴望，哪怕那娱乐最简单、最朴素。","kind":"narration","speaker":"旁白"},{"en":"But Fortune's favoured children belong to the second class.","zh":"但幸运女神宠爱的孩子属于第二类。","kind":"narration","speaker":"旁白"},{"en":"Their life is a natural harmony.","zh":"他们的生活天然和谐。","kind":"narration","speaker":"旁白"},{"en":"For them the working hours are never long enough.","zh":"对他们来说，工作时间永远不够长。","kind":"narration","speaker":"旁白"},{"en":"Each day is a holiday, and ordinary holidays, when they come, are grudged as enforced interruptions in an absorbing vocation.","zh":"每天都是假日，而通常所谓的假期到来时，却被他们看作对引人入胜的事业的强行打断，心中不愿接受。","kind":"narration","speaker":"旁白"},{"en":"Yet to both classes, the need of an alternative outlook, of a change of atmosphere, of a diversion of effort, is essential.","zh":"然而，对这两类人来说，都必不可少的是换一种眼光、换一种氛围，把精力转投别处。","kind":"narration","speaker":"旁白"},{"en":"Indeed, it may well be that those whose work is their pleasure are those who most need the means of banishing it at intervals from their minds.","zh":"事实上，很可能恰恰是那些把工作当乐趣的人，最需要有办法时不时把工作从脑海里赶出去。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"catch hold of","matchedForm":"catches hold of","meaning":"抓住","note":"可以指实际抓取，也可以像此处一样比喻思想紧扣某事。","example":"A gifted American psychologist has said, ‘Worry is a spasm of the emotion; the mind catches hold of something and will not let it go.’","exampleZh":"一位有才华的美国心理学家曾说：“忧虑是情感的痉挛；心灵抓住了某个东西，便不肯放手。”","sourceParagraphIndex":0,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"of the first importance","matchedForm":"of the first importance","meaning":"极其重要的","note":"of 加抽象名词可表示性质，the first 强调首要程度。","example":"The cultivation of a hobby and new forms of interest is therefore a policy of the first importance to a public man.","exampleZh":"因此，对一个从事公共事务的人来说，培养一种业余爱好和新的兴趣形式，是头等重要的方针。","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"it is no use doing","matchedForm":"It is no use doing","meaning":"做……没有用","note":"常用 it 作形式主语，后面的动名词短语说明无益的行为。","example":"It is no use doing what you like; you have got to like what you do.","exampleZh":"光做自己喜欢的事没有用；你必须喜欢自己正在做的事。","sourceParagraphIndex":2,"sourceSentenceIndex":4,"sourceType":"textbook-passage"},{"phrase":"broadly speaking","matchedForm":"Broadly speaking","meaning":"大体说来","note":"提示后面的分类或判断是概括性的。","example":"Broadly speaking, human beings may be divided into three classes: those who are toiled to death, those who are worried to death, and those who are bored to death.","exampleZh":"大体说来，人可以分成三类：劳累致死的人、忧虑致死的人和无聊致死的人。","sourceParagraphIndex":2,"sourceSentenceIndex":5,"sourceType":"textbook-passage"},{"phrase":"in vain","matchedForm":"In vain","meaning":"徒劳地","note":"说明努力没有达到目的，可置于句首加强语气。","example":"In vain they rush frantically round from place to place, trying to escape from avenging boredom by mere clatter and motion.","exampleZh":"他们发狂般四处奔走，想仅凭喧闹和活动躲开报复般追来的无聊，却徒劳无功。","sourceParagraphIndex":3,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"at intervals","matchedForm":"at intervals","meaning":"每隔一段时间；时不时","note":"强调间歇发生，不一定指固定间隔。","example":"Indeed, it may well be that those whose work is their pleasure are those who most need the means of banishing it at intervals from their minds.","exampleZh":"事实上，很可能恰恰是那些把工作当乐趣的人，最需要有办法时不时把工作从脑海里赶出去。","sourceParagraphIndex":4,"sourceSentenceIndex":9,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l047","book":4,"number":47,"title":"The great escape","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"Economy is one powerful motive for camping, since after the initial outlay upon equipment, or through hiring it, the total expense can be far less than the cost of hotels.","zh":"节省开支是露营的一大动机，因为除去最初购置装备的花费，或通过租用装备，总费用可以远低于住旅馆。","kind":"narration","speaker":"旁白"},{"en":"But, contrary to a popular assumption, it is far from being the only one, or even the greatest.","zh":"但与流行的看法相反，省钱远非唯一动机，甚至并非最大动机。","kind":"narration","speaker":"旁白"},{"en":"The man who manoeuvres carelessly into his twenty pounds’ worth of space at one of Europe’s myriad permanent sites may find himself bumping a Bentley.","zh":"一个人若漫不经心地把车驶进欧洲无数固定营地之一、自己花二十英镑租来的那块地方，可能会发现自己撞上了一辆宾利。","kind":"narration","speaker":"旁白"},{"en":"More likely, Ford Escort will be hub to hub with Renault or Mercedes, but rarely with bicycles made for two.","zh":"更可能的情景是，福特 Escort 与雷诺或梅赛德斯的轮毂紧挨着轮毂，却很少与双人自行车并排。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"That the equipment of modern camping becomes yearly more sophisticated is an entertaining paradox for the cynic, a brighter promise for the hopeful traveller who has sworn to get away from it all.","zh":"现代露营装备一年比一年精巧；对愤世嫉俗者而言，这是个有趣的悖论，对发誓要远离一切烦扰、满怀期待的旅行者而言，却是更光明的许诺。","kind":"narration","speaker":"旁白"},{"en":"It also provides—and some student sociologist might care to base his thesis upon the phenomenon—an escape of another kind.","zh":"它也提供了另一种逃离——也许某个社会学学生会愿意以这一现象为基础写篇论文。","kind":"narration","speaker":"旁白"},{"en":"The modern traveller is often a man who dislikes the Splendide and the Bellavista, not because he cannot afford, or shuns their material comforts, but because he is afraid of them.","zh":"现代旅行者常常不喜欢住“华丽”或“美景”那样的大饭店，并非因为住不起或逃避它们的物质舒适，而是因为害怕它们。","kind":"narration","speaker":"旁白"},{"en":"Affluent he may be, but he is by no means sure what to tip the doorman or the chambermaid.","zh":"他或许富有，却完全拿不准该给门童或客房女服务员多少小费。","kind":"narration","speaker":"旁白"},{"en":"Master in his own house, he has little idea of when to say boo to a maître d’hôtel.","zh":"他在自己家里是主人，却不大知道该在什么时候对餐厅领班开口表示不满。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"From all such fears camping releases him.","zh":"露营使他摆脱所有这类恐惧。","kind":"narration","speaker":"旁白"},{"en":"Granted, a snobbery of camping itself, based upon equipment and techniques, already exists; but it is of a kind that, if he meets it, he can readily understand and deal with.","zh":"诚然，露营本身已经出现了以装备和技巧论高下的势利风气；但即使碰到，他也很容易理解并应付这种风气。","kind":"narration","speaker":"旁白"},{"en":"There is no superior ‘they’ in the shape of managements and hotel hierarchies to darken his holiday days.","zh":"那里没有由管理人员和饭店各级人员构成的、高高在上的“他们”，来给他的假日蒙上阴影。","kind":"narration","speaker":"旁白"}]},{"index":3,"rows":[{"en":"To such motives, yet another must be added.","zh":"除了这些动机，还必须再加上一个。","kind":"narration","speaker":"旁白"},{"en":"The contemporary phenomenon of car worship is to be explained not least by the sense of independence and freedom that ownership entails.","zh":"当代人对汽车的崇拜，至少有相当一部分原因，是拥有汽车带来的独立与自由感。","kind":"narration","speaker":"旁白"},{"en":"To this pleasure camping gives an exquisite refinement.","zh":"露营又使这种乐趣变得格外精妙。","kind":"narration","speaker":"旁白"}]},{"index":4,"rows":[{"en":"From one’s own front door to home or foreign hills or sands and back again, everything is to hand.","zh":"从自家前门出发，到国内或国外的山野、沙滩，再返回家中，一切都在手边。","kind":"narration","speaker":"旁白"},{"en":"Not only are the means of arriving at the holiday paradise entirely within one’s own command and keeping, but the means of escape from holiday hell (if the beach proves too crowded, the local weather too inclement) are there, outside—or, as likely, part of—the tent.","zh":"不仅到达度假天堂的交通工具完全由自己掌握和保管，逃离度假地狱的工具也随时在帐篷外面——或者很可能就是帐篷的一部分——等着自己，万一海滩太拥挤、当地天气太恶劣就能离开。","kind":"narration","speaker":"旁白"}]},{"index":5,"rows":[{"en":"Idealists have objected to the practice of camping, as to the package tour, that the traveller abroad thereby denies himself the opportunity of getting to know the people of the country visited.","zh":"理想主义者反对露营，也反对包价旅游，理由是出国的旅行者因此失去了了解所访国家人民的机会。","kind":"narration","speaker":"旁白"},{"en":"Insularity and self-containment, it is argued, go hand in hand.","zh":"有人认为，闭塞与自给自足总是相伴而行。","kind":"narration","speaker":"旁白"},{"en":"The opinion does not survive experience of a popular Continental camping place.","zh":"只要到欧洲大陆一个热门营地亲身体验，这种看法就站不住脚了。","kind":"narration","speaker":"旁白"},{"en":"Holiday hotels tend to cater for one nationality of visitors especially, sometimes exclusively.","zh":"度假旅馆往往主要迎合某一个国籍的客人，有时甚至只接待该国客人。","kind":"narration","speaker":"旁白"},{"en":"Camping sites, by contrast, are highly cosmopolitan.","zh":"相比之下，露营地却十分国际化。","kind":"narration","speaker":"旁白"},{"en":"Granted, a preponderance of Germans is a characteristic that seems common to most Mediterranean sites; but as yet there is no overwhelmingly specialized patronage.","zh":"诚然，德国人占多数似乎是大多数地中海营地共有的特点，但迄今还没有哪个营地的顾客压倒性地局限于某一国籍。","kind":"narration","speaker":"旁白"},{"en":"Notices forbidding the open-air drying of clothes, or the use of water points for car washing, or those inviting ‘our camping friends’ to a dance or a boat trip are printed not only in French or Italian or Spanish, but also in English, German and Dutch.","zh":"禁止露天晾衣、禁止用供水点洗车的告示，以及邀请“我们的露营朋友”参加舞会或乘船游览的通知，不仅用法语、意大利语或西班牙语印制，还用英语、德语和荷兰语印制。","kind":"narration","speaker":"旁白"},{"en":"At meal times the odour of sauerkraut vies with that of garlic.","zh":"用餐时，酸菜的气味与大蒜的气味争相飘散。","kind":"narration","speaker":"旁白"},{"en":"The Frenchman's breakfast coffee competes with the Englishman’s bacon and eggs.","zh":"法国人早餐咖啡的香气，又与英国人的培根煎蛋气味争相较量。","kind":"narration","speaker":"旁白"}]},{"index":6,"rows":[{"en":"Whether the remarkable growth of organized camping means the eventual death of the more independent kind is hard to say.","zh":"有组织露营的显著增长，是否意味着更加独立自主的露营方式最终会消亡，还很难说。","kind":"narration","speaker":"旁白"},{"en":"Municipalities naturally want to secure the campers’ site fees and other custom.","zh":"各市镇自然希望获得露营者的场地费和其他消费收入。","kind":"narration","speaker":"旁白"},{"en":"Police are wary of itinerants who cannot be traced to a recognized camp boundary or to four walls.","zh":"警察会提防那些无法追查到某个正式营地范围内或固定住处的流动人员。","kind":"narration","speaker":"旁白"},{"en":"But most probably it will all depend upon campers themselves: how many heath fires they cause; how much litter they leave; in short, whether or not they wholly alienate landowners and those who live in the countryside.","zh":"但最终情况多半还是取决于露营者自己：他们造成多少荒野火灾，丢下多少垃圾；总之，看他们是否把地主和乡村居民彻底惹恼。","kind":"narration","speaker":"旁白"},{"en":"Only good scouting is likely to preserve the freedoms so dear to the heart of the eternal Boy Scout.","zh":"只有良好的童子军式户外操守，才有可能保住那些为永远怀着童子军之心的人所珍爱的自由。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"far from","matchedForm":"far from","meaning":"远非；绝不是","note":"此处后接 being，强调与某种描述相距很远。","example":"But, contrary to a popular assumption, it is far from being the only one, or even the greatest.","exampleZh":"但与流行的看法相反，省钱远非唯一动机，甚至并非最大动机。","sourceParagraphIndex":0,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"get away from it all","matchedForm":"get away from it all","meaning":"远离日常烦扰","note":"常用于度假，it all 指平日的压力和事务。","example":"That the equipment of modern camping becomes yearly more sophisticated is an entertaining paradox for the cynic, a brighter promise for the hopeful traveller who has sworn to get away from it all.","exampleZh":"现代露营装备一年比一年精巧；对愤世嫉俗者而言，这是个有趣的悖论，对发誓要远离一切烦扰、满怀期待的旅行者而言，却是更光明的许诺。","sourceParagraphIndex":1,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"by no means","matchedForm":"by no means","meaning":"绝不；完全不","note":"强烈否定表达，置于句首时通常引起部分倒装。","example":"Affluent he may be, but he is by no means sure what to tip the doorman or the chambermaid.","exampleZh":"他或许富有，却完全拿不准该给门童或客房女服务员多少小费。","sourceParagraphIndex":1,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"not least","matchedForm":"not least","meaning":"尤其；至少在很大程度上","note":"引入不应被低估的重要原因，并非表示最不重要。","example":"The contemporary phenomenon of car worship is to be explained not least by the sense of independence and freedom that ownership entails.","exampleZh":"当代人对汽车的崇拜，至少有相当一部分原因，是拥有汽车带来的独立与自由感。","sourceParagraphIndex":3,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"go hand in hand","matchedForm":"go hand in hand","meaning":"相伴而行","note":"形容两种现象密切相关、同时出现。","example":"Insularity and self-containment, it is argued, go hand in hand.","exampleZh":"有人认为，闭塞与自给自足总是相伴而行。","sourceParagraphIndex":5,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"cater for","matchedForm":"cater for","meaning":"迎合；满足……需要","note":"后接服务对象或需求，不能一律理解为提供餐饮。","example":"Holiday hotels tend to cater for one nationality of visitors especially, sometimes exclusively.","exampleZh":"度假旅馆往往主要迎合某一个国籍的客人，有时甚至只接待该国客人。","sourceParagraphIndex":5,"sourceSentenceIndex":3,"sourceType":"textbook-passage"}]},{"lessonId":"nce-nativeears-b4-l048","book":4,"number":48,"title":"Planning a share portfolio","sourceSha256":"aed8a2a10c90ae46c51190798938f834bb9b7a673ed0ca9b4d1470bfa90735d7","paragraphs":[{"index":0,"rows":[{"en":"There is no shortage of tipsters around offering ‘get-rich-quick’ opportunities.","zh":"四周从来不缺提供“迅速发财”机会的荐股者。","kind":"narration","speaker":"旁白"},{"en":"But if you are a serious private investor, leave the Las Vegas mentality to those with money to fritter.","zh":"但如果你是个认真的个人投资者，就把拉斯维加斯式的赌博心态留给那些有钱挥霍的人。","kind":"narration","speaker":"旁白"},{"en":"The serious investor needs a proper ‘portfolio’—a well-planned selection of investments, with a definite structure and a clear aim.","zh":"认真的投资者需要一个恰当的“投资组合”——经过周密选择、结构明确、目标清楚的一组投资。","kind":"narration","speaker":"旁白"},{"en":"But exactly how does a newcomer to the stock market go about achieving that?","zh":"不过，一个刚进入股市的人，究竟该怎样着手做到这一点呢？","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"Well, if you go to five reputable stock brokers and ask them what you should do with your money, you're likely to get five different answers,—even if you give all the relevant information about your age, family, finances and what you want from your investments.","zh":"假如你找五家信誉良好的证券经纪商，问他们你的钱该怎么用，很可能会得到五种不同的答案，即使你已提供了关于年龄、家庭、财务状况和投资期望的全部相关信息。","kind":"narration","speaker":"旁白"},{"en":"Moral?","zh":"这里的启示是什么？","kind":"narration","speaker":"旁白"},{"en":"There is no one ‘right’ way to structure a portfolio.","zh":"安排投资组合，并没有唯一“正确”的方法。","kind":"narration","speaker":"旁白"},{"en":"However, there are undoubtedly some wrong ways, and you can be sure that none of our five advisers would have suggested sinking all (or perhaps any) of your money into Periwigs.","zh":"不过，错误的方法无疑还是有的；你可以肯定，这五位顾问没有一个会建议你把全部资金，甚至也许哪怕一部分资金，投进“佩里维格斯”公司。","kind":"narration","speaker":"旁白"}]},{"index":2,"rows":[{"en":"So what should you do?","zh":"那么，你该怎么办呢？","kind":"narration","speaker":"旁白"},{"en":"We’ll assume that you have sorted out the basics—like mortgages, pensions, insurance and access to sufficient cash reserves.","zh":"我们假定，你已经处理好基本事项，例如住房抵押贷款、养老金、保险，以及确保有足够的现金储备可供动用。","kind":"narration","speaker":"旁白"},{"en":"You should then establish your own individual aims.","zh":"接着，你应该确立自己个人的目标。","kind":"narration","speaker":"旁白"},{"en":"These are partly a matter of personal circumstances, partly a matter of psychology.","zh":"这些目标部分取决于个人处境，部分取决于心理因素。","kind":"narration","speaker":"旁白"}]},{"index":3,"rows":[{"en":"For instance, if you are older you have less time to recover from any major losses, and you may well wish to boost your pension income.","zh":"例如，如果你年纪较大，就没有那么多时间从重大损失中恢复，而且你很可能希望增加养老金收入。","kind":"narration","speaker":"旁白"},{"en":"So preserving your capital and generating extra income are your main priorities.","zh":"因此，保住本金并产生额外收入，是你的首要任务。","kind":"narration","speaker":"旁白"},{"en":"In this case, you'd probably construct a portfolio with some shares (but not high risk ones), along with gilts, cash deposits, and perhaps convertibles or the income shares of split capital investment trusts.","zh":"在这种情况下，你大概会构建这样的投资组合：包括一些股票，但不包括高风险股票，再配上英国国债、现金存款，也许还有可转换证券，或者分割资本投资信托的收益股。","kind":"narration","speaker":"旁白"}]},{"index":4,"rows":[{"en":"If you are younger, and in a solid financial position, you may decide to take an aggressive approach— but only if you're blessed with a sanguine disposition and won't suffer sleepless nights over share prices.","zh":"如果你较年轻，财务状况又稳健，或许会决定采取进取策略，但前提是你天性乐观，不会为股价辗转失眠。","kind":"narration","speaker":"旁白"},{"en":"If you recognize yourself in this description, you might include a couple of heady growth stocks in your portfolio, alongside your more pedestrian investments.","zh":"如果你觉得这正是在说自己，可以在比较平稳普通的投资之外，在组合中加入一两只增长势头强劲、令人兴奋的成长股。","kind":"narration","speaker":"旁白"},{"en":"Once you have decided on your investment aims, you can then decide where to put your money.","zh":"一旦确定了投资目标，你便可以决定把钱放到哪里。","kind":"narration","speaker":"旁白"},{"en":"The golden rule here is spread your risk—if you put all of your money into Periwigs International, you're setting yourself up as a hostage to fortune.","zh":"这里的金科玉律是分散风险；如果把所有钱都投进“佩里维格斯国际公司”，你就是在让自己听任命运摆布。","kind":"narration","speaker":"旁白"}]}],"usage":[{"phrase":"go about","matchedForm":"go about","meaning":"着手；设法进行","note":"后接动名词，询问完成事情的方法或步骤。","example":"But exactly how does a newcomer to the stock market go about achieving that?","exampleZh":"不过，一个刚进入股市的人，究竟该怎样着手做到这一点呢？","sourceParagraphIndex":0,"sourceSentenceIndex":3,"sourceType":"textbook-passage"},{"phrase":"sort out","matchedForm":"sorted out","meaning":"处理妥当；理清","note":"此处指先安排好投资之前的基本财务事项。","example":"We’ll assume that you have sorted out the basics—like mortgages, pensions, insurance and access to sufficient cash reserves.","exampleZh":"我们假定，你已经处理好基本事项，例如住房抵押贷款、养老金、保险，以及确保有足够的现金储备可供动用。","sourceParagraphIndex":2,"sourceSentenceIndex":1,"sourceType":"textbook-passage"},{"phrase":"recover from","matchedForm":"recover from","meaning":"从……中恢复","note":"可用于疾病、损失或打击，此处讲弥补重大投资损失。","example":"For instance, if you are older you have less time to recover from any major losses, and you may well wish to boost your pension income.","exampleZh":"例如，如果你年纪较大，就没有那么多时间从重大损失中恢复，而且你很可能希望增加养老金收入。","sourceParagraphIndex":3,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"be blessed with","matchedForm":"blessed with","meaning":"有幸拥有","note":"be blessed with 后接令人满意的品质或条件，表示有幸拥有；原文为 you’re blessed with，指天性乐观。","example":"If you are younger, and in a solid financial position, you may decide to take an aggressive approach— but only if you're blessed with a sanguine disposition and won't suffer sleepless nights over share prices.","exampleZh":"如果你较年轻，财务状况又稳健，或许会决定采取进取策略，但前提是你天性乐观，不会为股价辗转失眠。","sourceParagraphIndex":4,"sourceSentenceIndex":0,"sourceType":"textbook-passage"},{"phrase":"a hostage to fortune","matchedForm":"a hostage to fortune","meaning":"听任运气摆布的人；易受不测影响的处境","note":"固定比喻，表示把自己暴露在难以控制的风险中。","example":"The golden rule here is spread your risk—if you put all of your money into Periwigs International, you're setting yourself up as a hostage to fortune.","exampleZh":"这里的金科玉律是分散风险；如果把所有钱都投进“佩里维格斯国际公司”，你就是在让自己听任命运摆布。","sourceParagraphIndex":4,"sourceSentenceIndex":3,"sourceType":"textbook-passage"}]}]};
(function install(global,data,validate){
 const accepted=[],rejected=[],split=global.StudyReading.splitEnglish;
 for(const entry of data.lessons||[]){
  const lesson=(global.LESSONS||[]).find(l=>l.id===entry.lessonId);
  try{validate(entry,lesson,split);}catch{rejected.push({book:entry.book,number:entry.number,lessonId:entry.lessonId});continue;}
  for(const p of entry.paragraphs)lesson.paragraphs[p.index].zh=p.rows.map(r=>r.zh).join('');
  lesson.translation={label:data.label||'自编中文译文（非教材官方译文）',reviewStatus:data.reviewStatus||'self-reviewed',notes:entry.translationNotes||[]};
  lesson.textbook.translation=lesson.translation;
  const keys=new Set(entry.usage.map(u=>u.phrase.toLowerCase().trim()));
  const usage=entry.usage.map(u=>({...u,sourcePage:lesson.textbook.sourcePdfPage,sourceUrl:lesson.textbook.sourceUrl,sourceLabel:'教材正文中的表达 · 自编释义与用法说明',meaningSource:'本课语境释义（学习整理）'}));
  const original=lesson.sourceNoteUsage||lesson.usage||[];
  lesson.sourceNoteUsage=original;
  lesson.usage=[...usage,...original.filter(u=>u.needsContextReview!==true&&typeof u.meaning==='string'&&u.meaning.trim()&&!/未附(?:独立)?中文释义|未提供中文释义|暂无释义|待(?:补充|复核)|原笔记习惯表达/.test(u.meaning)&&!keys.has(String(u.phrase||'').toLowerCase().trim()))];
  accepted.push(entry);
 }
 global.BOOK34_READING_ALIGNMENT={version:1,label:data.label,lessons:accepted};
 global.BOOK34_LANGUAGE_STATUS={applied:accepted.length,rejected};
})(window,window.BOOK34_LANGUAGE_SUPPORT,function validateEntry(entry,source,split){
 const fail=reason=>{throw new Error('Advanced language source mismatch: '+entry?.book+':'+entry?.number+' '+reason);};
 const chinese=value=>typeof value==='string'&&/[\u3400-\u9fff]/.test(value)&&!/^\s*(?:待翻译|待补充|TODO|TBD)\s*$/i.test(value);
 if(!entry||!source||![3,4].includes(entry.book)||source.id!==entry.lessonId||source.book!==entry.book||source.number!==entry.number||source.textbook?.title!==entry.title||source.textbook?.sourceSha256!==entry.sourceSha256||!/^[a-f0-9]{64}$/.test(entry.sourceSha256||''))fail('identity');
 if(!Array.isArray(entry.paragraphs)||!Array.isArray(source.paragraphs)||entry.paragraphs.length!==source.paragraphs.length)fail('paragraph count');
 for(let pi=0;pi<entry.paragraphs.length;pi++){
  const p=entry.paragraphs[pi],expected=split(source.paragraphs[pi].en);
  if(p.index!==pi||!Array.isArray(p.rows)||p.rows.length!==expected.length)fail('sentence count '+pi);
  for(let ri=0;ri<p.rows.length;ri++){
   const row=p.rows[ri];
   if(row.en!==expected[ri]||!chinese(row.zh)||!['narration','speech','thought','note','mixed'].includes(row.kind)||typeof row.speaker!=='string'||!row.speaker.trim())fail('sentence '+pi+':'+ri);
  }
 }
 if(!Array.isArray(entry.usage))fail('usage list');
 const seen=new Set();
 for(const u of entry.usage){
  const p=entry.paragraphs[u.sourceParagraphIndex],row=p?.rows?.[u.sourceSentenceIndex],key=String(u.phrase||'').toLowerCase().trim();
  if(!Number.isSafeInteger(u.sourceParagraphIndex)||!Number.isSafeInteger(u.sourceSentenceIndex)||!row||u.example!==row.en||u.exampleZh!==row.zh||typeof u.matchedForm!=='string'||!u.matchedForm.trim()||!u.example.includes(u.matchedForm)||key.split(/\s+/).length<2||seen.has(key)||!chinese(u.meaning)||!chinese(u.note)||u.sourceType!=='textbook-passage')fail('usage evidence '+key);
  seen.add(key);
 }
 return true;
});
